    /// fixture snapshots without one fall back to the owner (the Init
    /// default, C4Object.cpp:162).
    pub fn controller(&self) -> i32 {
        self.controller.unwrap_or_else(|| {
            self.state
                .as_ref()
                .map(|state| state.controller)
                .unwrap_or(self.owner)
        })
    }

