fn build_host_sector_map<'a, I>(
    objects: I,
    definitions: &HashMap<DefinitionId, DefinitionMetadata>,
    landscape: &Landscape,
) -> SectorMap
where
    I: IntoIterator<Item = &'a HostWorldObject>,
{
    let width = i32::try_from(landscape.width()).unwrap_or(i32::MAX);
    let height = landscape.estimated_height();
    let mut sectors = SectorMap::new(width, height);
    sectors.rebuild(
        objects
            .into_iter()
            .filter_map(|object| host_sector_record(object, definitions)),
    );
    sectors
}

fn host_sector_record(
    object: &HostWorldObject,
    definitions: &HashMap<DefinitionId, DefinitionMetadata>,
) -> Option<SectorObject> {
    if !object.status().is_active() {
        return None;
    }
    Some(SectorObject {
        id: object.id,
        position: object.position(),
        shape_rect: sector_shape_rect(host_object_live_shape_rect(object, definitions)),
    })
}

/// Exact world-space `C4Object::Shape` rectangle at callback entry.
/// Engine-created host snapshots carry `Object::current_shape_rect()` in
/// `ObjectState::shape_override`; the derivation and vertex fallback keep
/// synthetic fixture contexts useful without overriding that authoritative
/// live value.
fn host_object_live_shape_rect(
    object: &HostWorldObject,
    definitions: &HashMap<DefinitionId, DefinitionMetadata>,
) -> DefinitionRect {
    let metadata = definitions.get(object.definition_id());
    object
        .full_state()
        .and_then(|state| state.shape_override)
        .or_else(|| {
            let metadata = metadata?;
            if metadata.line != 0 {
                return metadata.shape;
            }
            crate::transformed_shape_rect(
                metadata.shape,
                object.construction(),
                metadata.stretch_growth,
                metadata.rotateable,
                object.rotation,
            )
        })
        .map(|rect| {
            DefinitionRect::new(
                object.position().x.saturating_add(rect.x),
                object.position().y.saturating_add(rect.y),
                rect.width,
                rect.height,
            )
        })
        .or_else(|| host_vertex_bounds_rect(object.position(), object.vertices()))
        .unwrap_or_else(|| DefinitionRect::new(object.position().x, object.position().y, 1, 1))
}

/// `C4Object::Left/Top/Width/Height`, used by `C4LArea(Object)` and the
/// legacy `C4Object::At` query, expand short shapes upward to an 18-pixel
/// action area. Array Find predicates themselves use the raw shape above.
fn sector_shape_rect(mut rect: DefinitionRect) -> DefinitionRect {
    let add_top = (18 - rect.height).max(0);
    rect.y = rect.y.saturating_sub(add_top);
    rect.height = rect.height.saturating_add(add_top);
    rect
}

fn host_vertex_bounds_rect(position: Vector2, vertices: &[ObjectVertex]) -> Option<DefinitionRect> {
    let first = vertices.first()?;
    let mut min_x = first.x;
    let mut max_x = first.x;
    let mut min_y = first.y;
    let mut max_y = first.y;
    for vertex in &vertices[1..] {
        min_x = min_x.min(vertex.x);
        max_x = max_x.max(vertex.x);
        min_y = min_y.min(vertex.y);
        max_y = max_y.max(vertex.y);
    }
    Some(DefinitionRect::new(
        position.x.saturating_add(min_x),
        position.y.saturating_add(min_y),
        max_x.saturating_sub(min_x).saturating_add(1),
        max_y.saturating_sub(min_y).saturating_add(1),
    ))
}

trait WorldAccessor {
    fn get_object(&self, id: ObjectId) -> Option<HostWorldObject>;
    fn object_ids(&self) -> Vec<ObjectId>;
    fn master_object_ids(&self) -> Vec<ObjectId>;
    /// Exact world-space `C4Object::Shape`; no `C4Object::addtop` expansion.
    fn object_live_shape_rect(&self, object: &HostWorldObject) -> DefinitionRect;
    /// Sector/legacy-`At` bounds, including `C4Object::addtop`.
    fn object_shape_rect(&self, object: &HostWorldObject) -> DefinitionRect;
    fn object_sector_ids_in_rect(&self, rect: DefinitionRect) -> Option<Vec<ObjectId>>;
    fn shape_sector_ids_in_rect(&self, rect: DefinitionRect) -> Option<Vec<ObjectId>>;
    /// The bounded Find-with-sort walk needs the per-sector lists kept
    /// separate (C4FindObject.cpp:283-307); shape lists arrive without the
    /// Marker dedup the flat variants apply.
    fn object_sector_id_lists_in_rect(&self, rect: DefinitionRect) -> Option<Vec<Vec<ObjectId>>>;
    fn shape_sector_id_lists_in_rect(&self, rect: DefinitionRect) -> Option<Vec<Vec<ObjectId>>>;
    /// Definition mass/value for the C4SO_Mass/C4SO_Value sorts.
    fn definition_metadata(&self, id: &str) -> Option<DefinitionMetadata>;
    /// Whether any definition script (or host function) knows `name` —
    /// the `Game.ScriptEngine.GetFirstFunc` lookup C4FindObjectFunc does at
    /// construction (C4Aul.cpp:545-552).
    fn script_function_known(&self, name: &str) -> bool;
}

/// Snapshot fallback for C4Object::Mass. Live host calls use the scoped
/// variant below, while standalone Find fixtures still need the complete
/// cached-mass formula, including recursively contained objects.
fn world_object_mass(
    world: &impl WorldAccessor,
    target: ObjectId,
    visited: &mut HashSet<ObjectId>,
) -> i32 {
    if !visited.insert(target) {
        return 0;
    }
    let Some(object) = world.get_object(target) else {
        visited.remove(&target);
        return 0;
    };
    let Some(metadata) = world.definition_metadata(object.definition_id()) else {
        visited.remove(&target);
        return 1;
    };
    let state = object.full_state();
    let own_mass = state.map(|state| state.own_mass).unwrap_or(0);
    let mut mass = metadata
        .mass
        .saturating_add(own_mass)
        .saturating_mul(object.construction())
        / FULL_CON;
    mass = mass.max(1);
    if !metadata.no_component_mass {
        for child in object.contents() {
            if world
                .get_object(*child)
                .is_some_and(|child| child.is_present())
            {
                mass = mass.saturating_add(world_object_mass(world, *child, visited));
            }
        }
    }
    visited.remove(&target);
    mass
}

/// C4SO_Mass reads the live cached `pFor->Mass`. Prefer the current host scope
/// so contents and own-mass changes made by an earlier Find_Func or Sort_Func
/// callback in the same search are reflected in the key.
fn sort_object_mass(world: &impl WorldAccessor, target: ObjectId) -> i32 {
    let live = HOST_CONTEXT.with(|cell| {
        let borrow = cell.try_borrow().ok()?;
        let context = borrow.as_ref()?;
        context.get_world_object(target)?;
        Some(reflected_object_mass(context, target, &mut HashSet::new()))
    });
    live.unwrap_or_else(|| world_object_mass(world, target, &mut HashSet::new()))
}

impl WorldAccessor for HostWorldContext {
    fn get_object(&self, id: ObjectId) -> Option<HostWorldObject> {
        self.get(id)
    }

    fn object_ids(&self) -> Vec<ObjectId> {
        self.object_ids()
    }

    fn master_object_ids(&self) -> Vec<ObjectId> {
        HostWorldContext::master_object_ids(self).to_vec()
    }

    fn object_live_shape_rect(&self, object: &HostWorldObject) -> DefinitionRect {
        self.object_live_shape_rect(object)
    }

    fn object_shape_rect(&self, object: &HostWorldObject) -> DefinitionRect {
        self.object_shape_rect(object)
    }

    fn object_sector_ids_in_rect(&self, rect: DefinitionRect) -> Option<Vec<ObjectId>> {
        self.object_sector_ids_in_rect(rect)
    }

    fn shape_sector_ids_in_rect(&self, rect: DefinitionRect) -> Option<Vec<ObjectId>> {
        self.shape_sector_ids_in_rect(rect)
    }

    fn object_sector_id_lists_in_rect(&self, rect: DefinitionRect) -> Option<Vec<Vec<ObjectId>>> {
        self.object_sector_id_lists_in_rect(rect)
    }

    fn shape_sector_id_lists_in_rect(&self, rect: DefinitionRect) -> Option<Vec<Vec<ObjectId>>> {
        self.shape_sector_id_lists_in_rect(rect)
    }

    fn definition_metadata(&self, id: &str) -> Option<DefinitionMetadata> {
        HostWorldContext::definition_metadata(self, id).cloned()
    }

    fn script_function_known(&self, name: &str) -> bool {
        HostWorldContext::script_function_known(self, name)
    }
}

/// Borrow-free handle for callback-backed Find/Sort evaluation. Every method
/// takes and releases one short immutable HOST_CONTEXT borrow and returns an
/// owned value; nested script dispatch therefore remains free to take the
/// mutable borrow while all later observations see its completed scope.
#[derive(Clone, Copy)]
struct LiveFuncFindView;

impl LiveFuncFindView {
    fn new() -> Option<Self> {
        HOST_CONTEXT.with(|cell| cell.borrow().as_ref().map(|_| Self))
    }

    fn read<T>(&self, f: impl FnOnce(&EffectHostContext) -> T) -> T {
        HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let context = borrow
                .as_ref()
                .expect("live Func-find view outlived its host context");
            f(context)
        })
    }
}

impl WorldAccessor for LiveFuncFindView {
    fn get_object(&self, id: ObjectId) -> Option<HostWorldObject> {
        self.read(|context| context.get_world_object(id))
    }

    fn object_ids(&self) -> Vec<ObjectId> {
        self.read(EffectHostContext::world_object_ids)
    }

    fn master_object_ids(&self) -> Vec<ObjectId> {
        self.read(EffectHostContext::master_object_ids)
    }

    fn object_live_shape_rect(&self, object: &HostWorldObject) -> DefinitionRect {
        self.read(|context| match context.get_world_object(object.id) {
            Some(live) => effect_object_live_shape_rect(context, &live),
            None => effect_object_live_shape_rect(context, object),
        })
    }

    fn object_shape_rect(&self, object: &HostWorldObject) -> DefinitionRect {
        sector_shape_rect(self.object_live_shape_rect(object))
    }

    fn object_sector_ids_in_rect(&self, rect: DefinitionRect) -> Option<Vec<ObjectId>> {
        self.read(|context| {
            <EffectHostContext as WorldAccessor>::object_sector_ids_in_rect(context, rect)
        })
    }

    fn shape_sector_ids_in_rect(&self, rect: DefinitionRect) -> Option<Vec<ObjectId>> {
        self.read(|context| {
            <EffectHostContext as WorldAccessor>::shape_sector_ids_in_rect(context, rect)
        })
    }

    fn object_sector_id_lists_in_rect(&self, rect: DefinitionRect) -> Option<Vec<Vec<ObjectId>>> {
        self.read(|context| {
            <EffectHostContext as WorldAccessor>::object_sector_id_lists_in_rect(context, rect)
        })
    }

    fn shape_sector_id_lists_in_rect(&self, rect: DefinitionRect) -> Option<Vec<Vec<ObjectId>>> {
        self.read(|context| {
            <EffectHostContext as WorldAccessor>::shape_sector_id_lists_in_rect(context, rect)
        })
    }

    fn definition_metadata(&self, id: &str) -> Option<DefinitionMetadata> {
        self.read(|context| <EffectHostContext as WorldAccessor>::definition_metadata(context, id))
    }

    fn script_function_known(&self, name: &str) -> bool {
        self.read(|context| {
            <EffectHostContext as WorldAccessor>::script_function_known(context, name)
        })
    }
}

/// `CheckObjectStatus` erases only `Status == 0`; an object deactivated by a
/// callback has nonzero C4OS_INACTIVE and remains in a result already being
/// built even though it has left the active master list.
fn object_present_after_callback(world: &impl WorldAccessor, id: ObjectId) -> bool {
    world
        .get_object(id)
        .is_some_and(|object| object.status() != ObjectStatus::Deleted)
}

fn retain_present_after_callback(world: &impl WorldAccessor, ids: &mut Vec<ObjectId>) {
    ids.retain(|id| object_present_after_callback(world, *id));
}

impl WorldAccessor for EffectHostContext {
    fn get_object(&self, id: ObjectId) -> Option<HostWorldObject> {
        self.get_world_object(id)
    }

    fn object_ids(&self) -> Vec<ObjectId> {
        self.world_object_ids()
    }

    fn master_object_ids(&self) -> Vec<ObjectId> {
        EffectHostContext::master_object_ids(self)
    }

    fn script_function_known(&self, name: &str) -> bool {
        self.world.script_function_known(name)
    }

    fn object_live_shape_rect(&self, object: &HostWorldObject) -> DefinitionRect {
        effect_object_live_shape_rect(self, object)
    }

    fn object_shape_rect(&self, object: &HostWorldObject) -> DefinitionRect {
        sector_shape_rect(self.object_live_shape_rect(object))
    }

    fn definition_metadata(&self, id: &str) -> Option<DefinitionMetadata> {
        EffectHostContext::definition_metadata(self, id).cloned()
    }

    fn object_sector_ids_in_rect(&self, rect: DefinitionRect) -> Option<Vec<ObjectId>> {
        let mut ids = self.world.object_sector_ids_in_rect(rect)?;
        let mut seen = ids.iter().copied().collect::<HashSet<_>>();
        for &id in &self.pending_order {
            let Some(object) = self.pending_objects.get(&id) else {
                continue;
            };
            if rect.contains_point(object.position.x, object.position.y) && seen.insert(id) {
                ids.push(id);
            }
        }
        Some(ids)
    }

    fn shape_sector_ids_in_rect(&self, rect: DefinitionRect) -> Option<Vec<ObjectId>> {
        let mut ids = self.world.shape_sector_ids_in_rect(rect)?;
        let mut seen = ids.iter().copied().collect::<HashSet<_>>();
        for &id in &self.pending_order {
            let Some(object) = self.pending_objects.get(&id) else {
                continue;
            };
            if self.object_shape_rect(object).overlaps(&rect) && seen.insert(id) {
                ids.push(id);
            }
        }
        Some(ids)
    }

    fn object_sector_id_lists_in_rect(&self, rect: DefinitionRect) -> Option<Vec<Vec<ObjectId>>> {
        let mut lists = self.world.object_sector_id_lists_in_rect(rect)?;
        let mut seen = lists.iter().flatten().copied().collect::<HashSet<_>>();
        let pending: Vec<ObjectId> =
            self.pending_order
                .iter()
                .copied()
                .filter(|&id| {
                    self.pending_objects.get(&id).is_some_and(|object| {
                        rect.contains_point(object.position.x, object.position.y)
                    }) && seen.insert(id)
                })
                .collect();
        if !pending.is_empty() {
            lists.push(pending);
        }
        Some(lists)
    }

    fn shape_sector_id_lists_in_rect(&self, rect: DefinitionRect) -> Option<Vec<Vec<ObjectId>>> {
        let mut lists = self.world.shape_sector_id_lists_in_rect(rect)?;
        let mut seen = lists.iter().flatten().copied().collect::<HashSet<_>>();
        let pending: Vec<ObjectId> = self
            .pending_order
            .iter()
            .copied()
            .filter(|&id| {
                self.pending_objects
                    .get(&id)
                    .is_some_and(|object| self.object_shape_rect(object).overlaps(&rect))
                    && seen.insert(id)
            })
            .collect();
        if !pending.is_empty() {
            lists.push(pending);
        }
        Some(lists)
    }
}

fn truncate_to_i32(value: u64) -> i32 {
    if value > i32::MAX as u64 {
        i32::MAX
    } else {
        value as i32
    }
}

fn invert_rgba_alpha(color: u32) -> u32 {
    let alpha = (color >> 24) & 0xff;
    let rgb = color & 0x00ff_ffff;
    ((255 - alpha) << 24) | rgb
}

fn ensure_single_flag(flags: u32, mask: u32, error: &str) -> Result<(), RuntimeError> {
    let masked = flags & mask;
    if masked != 0 && (masked & (masked - 1)) != 0 {
        return Err(RuntimeError::new(error));
    }
    Ok(())
}

pub fn object_reference_value(id: ObjectId) -> Value {
    Value::Object(id.as_u64())
}

fn object_id_from_value(value: &Value) -> Option<ObjectId> {
    match value {
        Value::Object(id) if *id != 0 => Some(ObjectId::new(*id)),
        Value::Proplist(map) => match map.get("id") {
            Some(Value::Int(id)) if *id > 0 => Some(ObjectId::new(*id as u64)),
            _ => None,
        },
        _ => None,
    }
}

fn parse_object_reference_argument(
    value: &Value,
    function: &str,
    parameter: &str,
) -> Result<Option<ObjectId>, RuntimeError> {
    match value {
        Value::Object(_) | Value::Proplist(_) => Ok(object_id_from_value(value)),
        Value::Nil => Ok(None),
        Value::Int(id) if *id == 0 => Ok(None),
        other => Err(RuntimeError::new(format!(
            "{}: expected object, proplist, nil, or 0 for {}, got {}",
            function,
            parameter,
            other.type_name()
        ))),
    }
}

/// Apply native `C4Object *` parameter conversion. Before strict 3, C4Aul
/// eagerly resets raw-falsy values to nil; strict-3 callers retain typed
/// integer/bool zero and therefore fail the object typecheck. Canonical null
/// object and raw-zero C4ID values remain nil in either mode.
fn parse_native_object_argument(
    value: Option<&Value>,
    function: &str,
    parameter: &str,
) -> Result<Option<ObjectId>, RuntimeError> {
    let value = value.unwrap_or(&Value::Nil);
    let canonical_nil = matches!(value, Value::Nil | Value::Object(0))
        || matches!(value, Value::C4Id(id) if cast_c4id_payload(id) == 0);
    let eager_falsy_conversion = !matches!(
        clonk_script::caller_origin_strictness(),
        clonk_script::HostCallerStrictness::Strict(level) if level >= 3
    );
    if canonical_nil || (eager_falsy_conversion && !value.as_bool()) {
        return Ok(None);
    }
    match value {
        Value::Object(_) | Value::Proplist(_) => Ok(object_id_from_value(value)),
        other => Err(RuntimeError::new(format!(
            "{function}: expected object for {parameter}, got {}",
            other.type_name()
        ))),
    }
}

fn consume_optional_object_reference_argument(
    args: &[Value],
    index: &mut usize,
    function: &str,
    parameter: &str,
) -> Result<Option<ObjectId>, RuntimeError> {
    let Some(value) = args.get(*index) else {
        return Ok(None);
    };
    if !matches!(
        value,
        Value::Object(_) | Value::Proplist(_) | Value::Nil | Value::Int(0)
    ) {
        return Ok(None);
    }
    let object_id = parse_object_reference_argument(value, function, parameter)?;
    *index += 1;
    Ok(object_id)
}

fn value_to_i32(value: &Value, function: &str, parameter: &str) -> Result<i32, RuntimeError> {
    match value {
        Value::Int(int) => Ok(*int),
        // Unfilled parameter slots are nil and convert to 0; bools convert
        // directly (C4AulExec.cpp:1364-1396 CheckConvertFunctionParameters,
        // C4Value.cpp FnCnvGuess / Bool->Int CnvOK).
        Value::Nil => Ok(0),
        Value::Bool(flag) => Ok(i32::from(*flag)),
        Value::RawBool(raw) => Ok(*raw as u32 as i32),
        other => Err(RuntimeError::new(format!(
            "{}: expected integer for {}, got {}",
            function,
            parameter,
            other.type_name()
        ))),
    }
}

/// Which post-name script argument layout a command function uses.
#[derive(Clone, Copy)]
enum CommandArgLayout {
    /// FnSetCommand: (name, target, Tx, Ty, target2, data, retries) — no
    /// update-interval slot, and the resulting command is always pushed
    /// with C4CMD_Mode_Base (C4Script.cpp:840-867, C4Object.cpp:3949).
    Set,
    /// FnAddCommand/FnAppendCommand: (name, target, Tx, Ty, target2,
    /// interval, data, retries, base_mode); an unfilled base_mode is int 0
    /// = C4CMD_Mode_SilentSub (C4Script.cpp:870-916, C4Command.h:62).
    Add,
}

fn parse_command_request(
    id: CommandId,
    args: &[Value],
    layout: CommandArgLayout,
    function: &str,
) -> Result<CommandRequest, RuntimeError> {
    let target = if args.len() > 1 {
        parse_object_reference_argument(&args[1], function, "target")?
    } else {
        None
    };

    let (tx, tx_definition, tx_value) = if args.len() > 2 {
        match &args[2] {
            Value::Nil => (None, None, (id == CommandId::Call).then_some(Value::Nil)),
            // Tx is a C4Value rather than C4ValueInt in all three C++
            // wrappers. Call uniquely skips ConvertTo(C4V_Int) and forwards
            // arbitrary tagged values to its script callback. Legacy
            // conversion also leaves a C4ID's tag intact.
            Value::C4Id(id) => {
                let raw = cast_c4id_payload(id);
                (
                    Some(raw as i32),
                    (raw != 0).then(|| clonk_script::c4_id_from_raw(raw)),
                    Some(Value::C4Id(id.clone())),
                )
            }
            other if id == CommandId::Call => (
                match other {
                    Value::Int(value) => Some(*value),
                    _ => None,
                },
                None,
                Some(other.clone()),
            ),
            other => {
                let value = value_to_i32(other, function, "Tx")?;
                (Some(value), None, Some(Value::Int(value)))
            }
        }
    } else {
        (None, None, (id == CommandId::Call).then_some(Value::Nil))
    };

    let ty = if args.len() > 3 {
        match &args[3] {
            Value::Nil => None,
            other => Some(value_to_i32(other, function, "Ty")?),
        }
    } else {
        None
    };

    let target2 = if args.len() > 4 {
        parse_object_reference_argument(&args[4], function, "target2")?
    } else {
        None
    };

    let (interval_slot, data_slot, retries_slot, mode_slot) = match layout {
        CommandArgLayout::Set => (None, 5usize, 6usize, None),
        CommandArgLayout::Add => (Some(5usize), 6, 7, Some(8usize)),
    };

    let update_interval = interval_slot
        .and_then(|slot| args.get(slot))
        .map(|value| value_to_i32(value, function, "update_interval"))
        .transpose()?
        .unwrap_or(0);

    let data_value = args.get(data_slot).unwrap_or(&Value::Nil);
    let data = match (id, data_value) {
        (CommandId::Call, Value::String(text)) => {
            let text = text.as_ref();
            let nul = text.as_bytes().iter().position(|byte| *byte == 0);
            CommandData::Text(text[..nul.unwrap_or(text.len())].to_owned())
        }
        // C4Value::getStr() returns null for every failed strict conversion,
        // and FnStringPar maps that null to an empty function name. Native
        // still queues the Call; C4Command::Call fails it during execution.
        (CommandId::Call, _) => CommandData::Text(String::new()),
        (_, Value::Nil) => CommandData::Integer(0),
        (_, Value::C4Id(id)) => CommandData::Integer(cast_c4id_payload(id) as i32),
        (_, other) => CommandData::Integer(value_to_i32(other, function, "data")?),
    };

    let retries = args
        .get(retries_slot)
        .map(|value| value_to_i32(value, function, "retries"))
        .transpose()?
        .unwrap_or(0);

    let mode = mode_slot
        .and_then(|slot| args.get(slot))
        .map(|value| value_to_i32(value, function, "mode"))
        .transpose()?
        .map(|raw| CommandMode::from_i32(raw).unwrap_or(CommandMode::Base))
        .unwrap_or(match layout {
            CommandArgLayout::Set => CommandMode::Base,
            CommandArgLayout::Add => CommandMode::SilentSub,
        });

    let mut request = CommandRequest::new(id)
        .with_target(target)
        .with_target2(target2)
        .with_tx(tx)
        .with_ty(ty)
        .with_data(data)
        .with_update_interval(update_interval)
        .with_retries(retries)
        .with_mode(mode);
    request.tx_definition = tx_definition;
    request.tx_value = tx_value;
    Ok(request)
}

fn parse_player_type_filter(value: Option<&Value>, function: &str) -> Result<i32, RuntimeError> {
    match value {
        Some(Value::Int(filter)) => Ok(*filter),
        Some(Value::Nil) | None => Ok(0),
        Some(other) => Err(RuntimeError::new(format!(
            "{}: expected int or nil for type filter, got {}",
            function,
            other.type_name()
        ))),
    }
}

fn player_type(player: &PlayerState) -> i32 {
    i32::from(if player.script_player {
        crate::PLAYER_INFO_TYPE_SCRIPT
    } else {
        crate::PLAYER_INFO_TYPE_USER
    })
}

fn player_type_matches(player: &PlayerState, filter: i32) -> bool {
    filter == 0 || filter == player_type(player)
}

fn script_player_extra_data(value: Option<&Value>) -> Result<[u8; 4], RuntimeError> {
    let Some(id) = parse_native_c4id_argument(value, "CreateScriptPlayer")? else {
        return Ok(*b"NONE");
    };
    let text = clonk_script::c4_id_text(&id);
    let bytes = clonk_script::c4_string_bytes(&text);
    if bytes.len() < 4 {
        return Ok(*b"NONE");
    }
    let mut extra = [0; 4];
    extra.copy_from_slice(&bytes[..4]);
    Ok(extra)
}

/// FnCreateScriptPlayer (C4Script.cpp:2877-2903): validate the name on
/// every peer, but only the control host emits the additive PlayerInfo
/// request. The actual join remains delayed in the control pipeline.
fn create_script_player(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 5 {
        return Err(RuntimeError::new(
            "CreateScriptPlayer expects at most 5 arguments: name, color, team, flags and extra data",
        ));
    }
    let name = match args.first().unwrap_or(&Value::Nil) {
        Value::String(name) if !name.is_empty() => Some(name),
        Value::String(_) | Value::Nil => None,
        other => {
            return Err(RuntimeError::new(format!(
                "CreateScriptPlayer: expected string for name, got {}",
                other.type_name()
            )));
        }
    };
    let color = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "CreateScriptPlayer",
        "color",
    )? as u32
        & 0x00ff_ffff;
    let team = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "CreateScriptPlayer",
        "team",
    )?;
    let source_flags = value_to_i32(
        args.get(3).unwrap_or(&Value::Nil),
        "CreateScriptPlayer",
        "flags",
    )?;
    let extra_data = script_player_extra_data(args.get(4))?;
    let Some(name) = name else {
        return Ok(Value::Bool(false));
    };

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Bool(true));
        };
        if !context.world.control_host {
            return Ok(Value::Bool(true));
        }
        let mut flags = 0;
        if source_flags & 1 != 0 {
            flags |= crate::PLAYER_INFO_FLAG_ATTRIBUTES_FIXED;
        }
        if source_flags & 2 != 0 {
            flags |= crate::PLAYER_INFO_FLAG_NO_SCENARIO_INIT;
        }
        if source_flags & 4 != 0 {
            flags |= crate::PLAYER_INFO_FLAG_NO_ELIMINATION_CHECK;
        }
        if source_flags & 8 != 0 {
            flags |= crate::PLAYER_INFO_FLAG_INVISIBLE;
        }
        let name = crate::LegacyCString::from_bytes(clonk_script::c4_string_bytes(name)).ok_or_else(
            || RuntimeError::new("CreateScriptPlayer: name contains an interior NUL"),
        )?;
        context
            .world
            .player_info_updates
            .borrow_mut()
            .push(crate::PlayerInfoUpdateRequest {
                client_id: 0,
                flags: crate::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS,
                players: vec![crate::ControlPlayerInfoEntry {
                    name,
                    flags,
                    player_type: crate::PLAYER_INFO_TYPE_SCRIPT,
                    color,
                    original_color: color,
                    team,
                    extra_data,
                    ..Default::default()
                }],
            });
        Ok(Value::Bool(true))
    })
}

fn get_player_count(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "GetPlayerCount expects at most 1 argument: type",
        ));
    }
    let filter = parse_player_type_filter(args.first(), "GetPlayerCount")?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Int(0));
        };
        let count = context
            .player_ids()
            .iter()
            .filter(|id| {
                context
                    .player_state(**id)
                    .map(|player| player_type_matches(player, filter))
                    .unwrap_or(false)
            })
            .count();
        Ok(Value::Int(truncate_to_i32(count as u64)))
    })
}

/// `FnIsNetwork` reads `Game.Parameters.IsNetworkGame`
/// (C4Script.cpp:3554). Parameter setup copies that flag from the active
/// `Game.NetworkActive` session (C4GameParameters.cpp:429-434).
fn is_network(_args: &[Value]) -> Result<Value, RuntimeError> {
    HOST_CONTEXT.with(|cell| {
        Ok(Value::Bool(
            cell.borrow()
                .as_ref()
                .is_some_and(|context| context.world.network_game()),
        ))
    })
}

/// `FnGetMaxPlayer` (C4Script.cpp:3693-3696): return the exact live
/// `Game.Parameters.MaxPlayers` integer, including a successful setter
/// earlier in the same VM call.
fn get_max_player(_args: &[Value]) -> Result<Value, RuntimeError> {
    HOST_CONTEXT.with(|cell| {
        Ok(Value::Int(
            cell.borrow()
                .as_ref()
                .map_or(0, |context| context.world.max_players()),
        ))
    })
}

/// `FnSetMaxPlayer` (C4Script.cpp:3698-3706): nonnegative values directly
/// replace `Game.Parameters.MaxPlayers`; negative values fail without a
/// write. The C++ host function returns `C4ValueInt`, not a script bool.
fn set_max_player(args: &[Value]) -> Result<Value, RuntimeError> {
    let max_players = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "SetMaxPlayer",
        "maximum player count",
    )?;
    if max_players < 0 {
        return Ok(Value::Int(0));
    }

    HOST_CONTEXT.with(|cell| {
        if let Some(context) = cell.borrow_mut().as_mut() {
            context.world.set_max_players(max_players);
            context.record_player_command(PlayerCommand::SetMaxPlayer { max_players });
        }
    });
    Ok(Value::Int(1))
}

/// `FnTestMessageBoard` (C4Script.cpp:3564-3573): invalid players return
/// nil. The ordinary multi-query availability probe is always true for a
/// valid player; the explicit in-use form reports whether any query node is
/// retained, including an answered query awaiting its control packet.
fn test_message_board(args: &[Value]) -> Result<Value, RuntimeError> {
    let player_id = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "TestMessageBoard",
        "player",
    )?;
    let test_if_in_use = value_to_bool(
        args.get(1).unwrap_or(&Value::Nil),
        "TestMessageBoard",
        "test if in use",
    )?;

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let player = borrow
            .as_ref()
            .and_then(|context| context.player_state(player_id));
        let Some(player) = player else {
            return Ok(Value::Nil);
        };
        Ok(Value::Bool(
            !test_if_in_use || !player.message_board_queries.is_empty(),
        ))
    })
}

/// `FnCallMessageBoard` (C4Script.cpp:3575-3585): register one player query,
/// replacing the first query for the same callback object and appending the
/// replacement at the list tail.
fn call_message_board(args: &[Value]) -> Result<Value, RuntimeError> {
    let explicit_target = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "CallMessageBoard",
        "callback object",
    )?;
    let uppercase = value_to_bool(
        args.get(1).unwrap_or(&Value::Nil),
        "CallMessageBoard",
        "uppercase",
    )?;
    let prompt =
        parse_optional_string(args.get(2), "CallMessageBoard", "query")?.unwrap_or_default();
    let player_id = value_to_i32(
        args.get(3).unwrap_or(&Value::Nil),
        "CallMessageBoard",
        "player",
    )?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let target = explicit_target.or(context.script_object_context);
        if target.is_some_and(|target| !context.object_status_present(target)) {
            return Ok(Value::Bool(false));
        }
        let query = crate::MessageBoardQuery::new(target, prompt, uppercase);
        let Some(player) = context.player_state_mut(player_id) else {
            return Ok(Value::Bool(false));
        };
        player.call_message_board(query.clone());
        context.record_player_command(PlayerCommand::CallMessageBoard { player_id, query });
        Ok(Value::Bool(true))
    })
}

/// `FnAbortMessageBoard` (C4Script.cpp:3587-3597). Local non-network
/// cancellation synchronously executes an empty answer before the outer
/// Remove call, so an active query closes/removes but the builtin returns
/// false; network cancellation defers that answer and returns the Remove
/// result.
fn abort_message_board(args: &[Value]) -> Result<Value, RuntimeError> {
    let explicit_target = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "AbortMessageBoard",
        "callback object",
    )?;
    let player_id = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "AbortMessageBoard",
        "player",
    )?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let target = explicit_target.or(context.script_object_context);
        if context.player_state(player_id).is_none() {
            return Ok(Value::Bool(false));
        }
        let active_local_cancel = !context.world.network_game()
            && context
                .world
                .active_message_board_input()
                .is_some_and(|input| input.player == player_id && input.target == target);
        let removed = context
            .player_state_mut(player_id)
            .is_some_and(|player| player.remove_message_board_query(target));
        context.record_player_command(PlayerCommand::AbortMessageBoard { player_id, target });
        Ok(Value::Bool(removed && !active_local_cancel))
    })
}

/// `FnOnMessageBoardAnswer` (C4Script.cpp:3599-3613): consume exactly one
/// query before dispatching `InputCallback(answer, player)`. An omitted/null
/// answer only clears the query, while an explicit empty string is delivered.
fn on_message_board_answer(args: &[Value]) -> Result<Value, RuntimeError> {
    let target = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "OnMessageBoardAnswer",
        "callback object",
    )?;
    let player_id = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "OnMessageBoardAnswer",
        "player",
    )?;
    let answer = parse_optional_string_value(args.get(2), "OnMessageBoardAnswer", "answer")?;

    let removed = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        let removed = context
            .player_state_mut(player_id)
            .is_some_and(|player| player.remove_message_board_query(target));
        if removed {
            context.record_player_command(PlayerCommand::RemoveMessageBoardQuery {
                player_id,
                target,
            });
        }
        removed
    });
    if !removed {
        return Ok(Value::Bool(false));
    }
    let Some(answer) = answer else {
        return Ok(Value::Bool(true));
    };

    let callback_args = [Value::String(answer), Value::Int(player_id)];
    let callback = match target {
        Some(target) => call_world_object_own_function(target, "InputCallback", &callback_args),
        None => {
            let script = HOST_CONTEXT.with(|cell| {
                cell.borrow()
                    .as_ref()
                    .and_then(|context| context.world.scenario_script().cloned())
            });
            script.and_then(|script| {
                call_scoped_script_function(script, "InputCallback", &callback_args)
            })
        }
    };
    match callback {
        Some(Ok(value)) => Ok(Value::Bool(value_raw_truthy(&value))),
        Some(Err(error)) => Err(error),
        None => Ok(Value::Bool(false)),
    }
}

/// `FnAddMsgBoardCmd` (C4Script.cpp:5198-5217): register a first-wins custom
/// chat command. Unnamed DirectExec/eval callers may only install the
/// Identifier-restricted form; ordinary named functions may install all
/// three restriction variants.
fn add_msg_board_cmd(args: &[Value]) -> Result<Value, RuntimeError> {
    // Native parameter conversion happens before the function body, so
    // validate all three slots before applying either early-return gate.
    let command = parse_optional_string(args.first(), "AddMsgBoardCmd", "command")?;
    let script = parse_optional_string(args.get(1), "AddMsgBoardCmd", "script")?;
    let raw_restriction = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "AddMsgBoardCmd",
        "restriction",
    )?;

    let (Some(command), Some(script)) = (command, script) else {
        return Ok(Value::Bool(false));
    };
    if raw_restriction != 2 && clonk_script::caller_is_temporary_script() != Some(false) {
        return Ok(Value::Bool(false));
    }
    let restriction = match raw_restriction {
        0 => crate::MessageBoardCommandRestriction::Escaped,
        1 => crate::MessageBoardCommandRestriction::Plain,
        2 => crate::MessageBoardCommandRestriction::Identifier,
        _ => return Ok(Value::Bool(false)),
    };

    HOST_CONTEXT.with(|cell| {
        if let Some(context) = cell.borrow_mut().as_mut() {
            context.record_player_command(PlayerCommand::AddMessageBoardCommand {
                command: crate::InitialNetworkMessageBoardCommand {
                    name: command,
                    script,
                    restriction,
                },
            });
        }
    });
    Ok(Value::Bool(true))
}

fn get_player_by_index(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "GetPlayerByIndex expects at most 2 arguments: index and type",
        ));
    }
    // C++ pads missing script args with zero: GetPlayerByIndex() is the
    // first player (GoldRush Script1's intro camera).
    let index = match args.first() {
        None | Some(Value::Nil) => 0,
        Some(value) => value_to_i32(value, "GetPlayerByIndex", "index")?,
    };
    let filter = parse_player_type_filter(args.get(1), "GetPlayerByIndex")?;
    if index < 0 {
        return Ok(Value::Int(OWNER_NONE));
    }
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Int(OWNER_NONE));
        };
        let matching: Vec<i32> = context
            .player_ids()
            .iter()
            .filter_map(|id| {
                context
                    .player_state(*id)
                    .filter(|player| player_type_matches(player, filter))
                    .map(|_| *id)
            })
            .collect();
        let idx = index as usize;
        if idx >= matching.len() {
            Ok(Value::Int(OWNER_NONE))
        } else {
            Ok(Value::Int(matching[idx]))
        }
    })
}

/// `FnInitScenarioPlayer` (C4Script.cpp:5827-5832): run
/// `C4Player::ScenarioAndTeamInit` for any live C4PlayerInfo-backed player.
/// The copied host context predicts its team-validation result; the ordered
/// player command runs the authoritative initialization path when this VM
/// call folds back into the engine.
fn init_scenario_player(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "InitScenarioPlayer expects at most 2 arguments: player and team",
        ));
    }
    let player_id = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "InitScenarioPlayer",
        "player",
    )?;
    let requested_team = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "InitScenarioPlayer",
        "team",
    )?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let Some((player_info_id, current_team)) = context
            .player_state(player_id)
            .map(|player| (player.player_info_id, player.team))
        else {
            return Ok(Value::Bool(false));
        };
        // C4Player::ScenarioAndTeamInit gates only on GetInfo(). A fully
        // initialized player may run it again; status is not consulted.
        if player_info_id == 0 {
            return Ok(Value::Bool(false));
        }

        let accepted = match requested_team {
            -1 => {
                context.world.auto_generate_teams()
                    && context
                        .teams()
                        .iter()
                        .map(|team| team.id)
                        .fold(0, i32::max)
                        .checked_add(1)
                        .is_some()
            }
            0 => true,
            team => {
                context.teams().iter().any(|candidate| candidate.id == team)
                    && (current_team == Some(team) || !context.team_is_full(team))
            }
        };

        // Rejected choices still run ScenarioAndTeamInit: its
        // OnTeamSelectionFailed arm changes Pending back to TeamSelection.
        context.record_player_command(PlayerCommand::InitScenarioPlayer {
            player_id,
            team: requested_team,
        });
        Ok(Value::Bool(accepted))
    })
}

/// FnEliminatePlayer (C4Script.cpp:2823-2842): missing players and already
/// eliminated regular players fail; the direct flag removes through the
/// player-control path, while regular elimination starts the retire delay.
fn eliminate_player(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "EliminatePlayer expects at most 2 arguments: player and direct removal flag",
        ));
    }
    let player_id = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "EliminatePlayer",
        "player",
    )?;
    let remove_direct = value_to_bool(
        args.get(1).unwrap_or(&Value::Nil),
        "EliminatePlayer",
        "direct removal flag",
    )?;
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Int(0));
        };
        let Some(player) = context.player_state(player_id) else {
            return Ok(Value::Int(0));
        };
        if remove_direct {
            // Every peer reports success for a valid player, but only the
            // control host appends CID_RemovePlr to Game.Input
            // (C4Script.cpp:2823-2833).
            if context.world.control_host {
                context.record_player_command(PlayerCommand::Remove { player_id });
            }
            return Ok(Value::Int(1));
        }
        if matches!(
            player.status,
            crate::PlayerStatus::Eliminated | crate::PlayerStatus::Surrendered
        ) || player.surrendered
        {
            return Ok(Value::Int(0));
        }
        if let Some(player) = context.player_state_mut(player_id) {
            player.status = crate::PlayerStatus::Eliminated;
            player.surrendered = false;
        }
        context.record_player_command(PlayerCommand::Eliminate { player_id });
        Ok(Value::Int(1))
    })
}

/// FnActivateGameGoalMenu (C4Script.cpp:5953-5960): a missing player fails;
/// every valid peer evaluates the goals, while the embedding runtime decides
/// whether its locally controlled player may build the actual menu.
fn activate_game_goal_menu(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "ActivateGameGoalMenu expects at most 1 argument: player",
        ));
    }
    let player_id = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "ActivateGameGoalMenu",
        "player",
    )?;
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Int(0));
        };
        if context.player_state(player_id).is_none() {
            return Ok(Value::Int(0));
        }
        let open_menu = context.world.local_players.contains(&player_id);
        context.record_player_command(PlayerCommand::ActivateGameGoalMenu {
            player_id,
            open_menu,
        });
        Ok(Value::Int(1))
    })
}

/// `FnSurrenderPlayer` (C4Script.cpp:2843-2850): resolve any live player,
/// reject one whose eliminated flag is already set, then run the ordinary
/// surrender transition without the network control's client authorization.
fn surrender_player(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "SurrenderPlayer expects at most 1 argument: player",
        ));
    }
    let player_id = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "SurrenderPlayer",
        "player",
    )?;
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let can_surrender = context.player_state(player_id).is_some_and(|player| {
            !matches!(
                player.status,
                crate::PlayerStatus::Eliminated | crate::PlayerStatus::Surrendered
            ) && !player.surrendered
        });
        if !can_surrender {
            return Ok(Value::Bool(false));
        }

        // C++ changes both flags synchronously. Mirror that in the copied
        // host state so another call in this same VM invocation sees the
        // player as eliminated before the deferred command is folded back.
        if let Some(player) = context.player_state_mut(player_id) {
            player.status = crate::PlayerStatus::Surrendered;
            player.surrendered = true;
        }
        context.record_player_command(PlayerCommand::Surrender { player_id });
        Ok(Value::Bool(true))
    })
}

fn get_player_name(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "GetPlayerName expects at most 1 argument: player",
        ));
    }
    // An unfilled iPlr slot is nil -> 0 (C4AulExec parameter filling).
    let player_id = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "GetPlayerName",
        "player",
    )?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let Some(player) = context.player_state(player_id) else {
            return Ok(Value::Nil);
        };
        Ok(Value::String(player.name.clone().into()))
    })
}

/// `FnGetTaggedPlayerName` colors a valid player's name with their 24-bit
/// display color after `C4GUI::MakeColorReadableOnBlack` has raised dark
/// colors to the legacy lightness floor (C4Script.cpp:1084-1091;
/// C4Gui.cpp:71-87).
fn get_tagged_player_name(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "GetTaggedPlayerName expects at most 1 argument: player",
        ));
    }
    let player_id = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "GetTaggedPlayerName",
        "player",
    )?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let Some(player) = context.player_state(player_id) else {
            return Ok(Value::Nil);
        };
        let mut color = player
            .color
            .map(|color| {
                (u32::from(color.r) << 16) | (u32::from(color.g) << 8) | u32::from(color.b)
            })
            .unwrap_or(0);
        let red = (color >> 16) & 0xff;
        let green = (color >> 8) & 0xff;
        let blue = color & 0xff;
        let lightness = red * 50 + green * 87 + blue * 27;
        if lightness < 16_575 {
            let increment = (16_575 - lightness) / 164;
            color = ((red + increment).min(255) << 16)
                | ((green + increment).min(255) << 8)
                | (blue + increment).min(255);
        }
        Ok(Value::String(
            format!("<c {color:x}>{}</c>", player.name).into(),
        ))
    })
}

/// FnGetPlayerVal reflects the named C4Player fields serialized by
/// C4Player::CompileFunc (C4Script.cpp:4252-4263). The standard
/// GetPlrViewX/GetPlrViewY wrappers use the ViewX/ViewY entries
/// (planet/System.c4g/GetXVal.c:99-100; C4Player.cpp:1576-1577).
fn get_player_val(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some(entry) = parse_optional_string(args.first(), "GetPlayerVal", "entry")? else {
        return Ok(Value::Nil);
    };
    let section = parse_optional_string(args.get(1), "GetPlayerVal", "section")?;
    let player_id = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "GetPlayerVal", "player")?;
    let entry_index = value_to_i32(
        args.get(3).unwrap_or(&Value::Nil),
        "GetPlayerVal",
        "entry_nr",
    )?;
    if entry_index < 0 || !matches!(section.as_deref(), None | Some("") | Some("Player")) {
        return Ok(Value::Nil);
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let Some(player) = context.player_state(player_id) else {
            return Ok(Value::Nil);
        };
        let index = entry_index as usize;
        let indexed_id_list = |entries: Vec<(DefinitionId, i32)>| {
            entries
                .get(index / 2)
                .map(|(id, count)| {
                    if index % 2 == 0 {
                        Value::C4Id(id.clone())
                    } else {
                        Value::Int(*count)
                    }
                })
                .unwrap_or(Value::Nil)
        };
        let indexed_value = match entry.as_str() {
            "Hostile" => player
                .exact_hostility_entries()
                .get(index / 2)
                .map(|(raw_id, count)| {
                    if index % 2 == 0 {
                        Value::C4Id(render_cast_c4id(*raw_id))
                    } else {
                        Value::Int(*count)
                    }
                })
                .unwrap_or(Value::Nil),
            "HomeBaseMaterial" => indexed_id_list(player.exact_home_base_material_entries()),
            "HomeBaseProduction" => indexed_id_list(player.exact_home_base_production_entries()),
            "Knowledge" => indexed_id_list(player.exact_knowledge_entries()),
            "Magic" => indexed_id_list(player.exact_magic_entries()),
            "Crew" => player
                .crew
                .iter()
                .filter(|object_id| {
                    context
                        .get_world_object(**object_id)
                        .is_some_and(|object| object.status != ObjectStatus::Deleted)
                })
                .nth(index)
                .map(|object_id| Value::Int(truncate_to_i32(object_id.as_u64())))
                .unwrap_or(Value::Nil),
            _ => Value::Nil,
        };
        if !matches!(&indexed_value, Value::Nil)
            || matches!(
                entry.as_str(),
                "Hostile"
                    | "HomeBaseMaterial"
                    | "HomeBaseProduction"
                    | "Knowledge"
                    | "Magic"
                    | "Crew"
            )
        {
            return Ok(indexed_value);
        }
        if entry_index != 0 {
            return Ok(Value::Nil);
        }
        let view_center = player
            .view_center
            .or_else(|| player.viewports.first().map(|viewport| viewport.center))
            .or_else(|| {
                player
                    .cursor
                    .and_then(|cursor| context.get_world_object(cursor))
                    .map(|cursor| cursor.position())
            })
            .unwrap_or(Vector2::ZERO);
        let player_status = match player.status {
            crate::PlayerStatus::Inactive => 0,
            crate::PlayerStatus::TeamSelection => 2,
            crate::PlayerStatus::TeamSelectionPending => 3,
            crate::PlayerStatus::Active
            | crate::PlayerStatus::Eliminated
            | crate::PlayerStatus::Surrendered => 1,
        };
        let object_number =
            |object: Option<ObjectId>| object.map(|id| truncate_to_i32(id.as_u64())).unwrap_or(0);
        Ok(match entry.as_str() {
            "Status" => Value::Int(player_status),
            "AtClient" => Value::Int(player.at_client.get()),
            "AtClientName" => Value::String(
                player
                    .at_client_name
                    .clone()
                    .unwrap_or_else(|| "Local".to_string())
                    .into(),
            ),
            "Index" => Value::Int(player.id),
            "ID" => Value::Int(player.player_info_id),
            "Eliminated" => Value::Int(i32::from(matches!(
                player.status,
                crate::PlayerStatus::Eliminated | crate::PlayerStatus::Surrendered
            ) || player.surrendered)),
            "Surrendered" => Value::Int(i32::from(
                player.surrendered || matches!(player.status, crate::PlayerStatus::Surrendered),
            )),
            "Evaluated" => Value::Bool(player.evaluated),
            "Color" => Value::Int(player.color_index.unwrap_or(-1)),
            "ColorDw" => Value::Int(player.exact_color_dw() as i32),
            "Control" => Value::Int(player.control_set),
            "MouseControl" => Value::Int(player.mouse_control),
            "AutoContextMenu" => Value::Int(i32::from(player.control.auto_context_menu)),
            "AutoStopControl" => Value::Int(i32::from(player.control.control_style)),
            "Position" => Value::Int(player.position_index.unwrap_or(-1)),
            "ViewMode" => Value::Int(player.view_mode),
            "ViewX" => Value::Int(view_center.x),
            "ViewY" => Value::Int(view_center.y),
            "ViewWealth" => Value::Int(player.view_wealth),
            "ViewValue" => Value::Int(player.view_value),
            "FogOfWar" => Value::Bool(player.fog_of_war),
            "ForceFogOfWar" => Value::Bool(player.force_fog_of_war),
            "ShowStartup" => Value::Bool(player.show_startup),
            "ShowControl" => Value::Int(player.show_control),
            "ShowControlPos" => Value::Int(player.show_control_position),
            "Wealth" => Value::Int(player.wealth),
            "Points" => Value::Int(player.points),
            "Value" => Value::Int(player.value),
            "InitialValue" => Value::Int(player.initial_value),
            "ValueGain" => Value::Int(player.value_gain),
            "ObjectsOwned" => Value::Int(player.objects_owned as i32),
            "ProductionDelay" => Value::Int(player.production_delay as i32),
            "ProductionUnit" => Value::Int(player.production_unit as i32),
            "SelectCount" => Value::Int(player.select_count),
            "SelectFlash" => Value::Int(player.control.select_flash),
            "CursorFlash" => Value::Int(player.control.cursor_flash),
            "Cursor" => Value::Int(object_number(player.cursor)),
            "ViewCursor" => Value::Int(object_number(player.view_cursor)),
            "Captain" => Value::Int(object_number(player.captain)),
            "LastCom" => Value::Int(player.control.last_com),
            "LastComDel" => Value::Int(player.control.last_com_delay),
            "PressedComs" => Value::Int(player.control.pressed_coms),
            "LastComDownDouble" => Value::Int(player.control.last_com_down_double),
            "CursorSelection" => Value::Int(player.control.cursor_selection),
            "CursorToggled" => Value::Int(player.control.cursor_toggled),
            "MessageStatus" => Value::Int(player.message_status),
            "MessageBuf" => Value::String(player.message_buf.clone().into()),
            "CrewCreated" => Value::Int(player.crew_created),
            _ => Value::Nil,
        })
    })
}

/// FnGetPlayerInfoCoreVal (C4Script.cpp:4266-4280): reflect a saved
/// C4PlayerInfoCore field. Only the control-style preference is represented
/// in PlayerState today; it is the path used by Hazard's weapon recharge.
fn get_player_info_core_val(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some(entry) = parse_optional_string(args.first(), "GetPlayerInfoCoreVal", "entry")? else {
        return Ok(Value::Nil);
    };
    let section = parse_optional_string(args.get(1), "GetPlayerInfoCoreVal", "section")?
        .filter(|section| !section.is_empty());
    let player_id = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "GetPlayerInfoCoreVal",
        "player",
    )?;
    let entry_index = value_to_i32(
        args.get(3).unwrap_or(&Value::Nil),
        "GetPlayerInfoCoreVal",
        "entry_nr",
    )?;
    if entry_index != 0
        || entry != "AutoStopControl"
        || !matches!(section.as_deref(), None | Some("Preferences"))
    {
        return Ok(Value::Nil);
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        Ok(borrow
            .as_ref()
            .and_then(|context| context.player_state(player_id))
            .map(|player| Value::Int(i32::from(player.control.control_style)))
            .unwrap_or(Value::Nil))
    })
}

