/// Run one creatorless engine-side object creation while preserving the
/// calling script object's live scope. `Game.CreateObject(id, nullptr)` does
/// not inherit the script caller's position, owner, layer, or controller.
fn with_creatorless_object_context<T>(callback: impl FnOnce() -> T) -> Result<T, RuntimeError> {
    let calling_object = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut().ok_or_else(|| {
            RuntimeError::new("creatorless object creation requires an active engine context")
        })?;
        Ok(context.object.take())
    })?;

    let result = callback();

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut().ok_or_else(|| {
            RuntimeError::new("host context disappeared during creatorless object creation")
        })?;
        debug_assert!(
            context.object.is_none(),
            "creatorless nested creation must restore its empty active scope"
        );
        context.object = calling_object;
        Ok(())
    })?;
    Ok(result)
}

/// FnLaunchLightning (C4Script.cpp:3081-3084) forwards all six integer
/// parameters and the normalized gamma flag to C4Weather::LaunchLightning.
/// Weather creates creatorless FXL1 at C4Game::CreateObject's native default
/// position (50,50), fail-safe-calls Activate, and returns true even when the
/// definition is absent or Activate errors (C4Weather.cpp:153-165;
/// C4Game.h:229-231).
fn launch_lightning(args: &[Value]) -> Result<Value, RuntimeError> {
    let integer = |index: usize, name: &str| {
        value_to_i32(
            args.get(index).unwrap_or(&Value::Nil),
            "LaunchLightning",
            name,
        )
    };
    let x = integer(0, "x")?;
    let y = integer(1, "y")?;
    let xdir = integer(2, "xdir")?;
    let xrange = integer(3, "xrange")?;
    let ydir = integer(4, "ydir")?;
    let yrange = integer(5, "yrange")?;
    let gamma = args.get(6).is_some_and(value_raw_truthy);

    let created = with_creatorless_object_context(|| {
        create_object(&[
            Value::C4Id("FXL1".to_string()),
            Value::Int(50),
            Value::Int(50),
            Value::Int(OWNER_NONE),
        ])
    })??;
    if let Some(target) = object_id_from_value(&created) {
        let activate_args = [
            Value::Int(x),
            Value::Int(y),
            Value::Int(xdir),
            Value::Int(xrange),
            Value::Int(ydir),
            Value::Int(yrange),
            Value::Bool(gamma),
        ];
        if let Some(Err(error)) = call_world_object_own_function(target, "Activate", &activate_args)
        {
            tracing::warn!(
                id = target.as_u64(),
                definition = "FXL1",
                function = "Activate",
                %error,
                "lightning activation failed; continuing like C++ fail-safe Call"
            );
        }
    }
    Ok(Value::Int(1))
}

/// FnLaunchVolcano (C4Script.cpp:3086-3093): the native signature consumes
/// only x (System.c4g may shadow it with a four-argument compatibility
/// wrapper). C4Weather then creates creatorless FXV1 at native position
/// (50,50) and fail-safe-calls Activate with `(x, GBackHgt - 1, bounded random size,
/// Material("Lava"))`, returning true even when FXV1 is absent or Activate
/// fails (C4Weather.cpp:178-184).
fn launch_volcano(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "LaunchVolcano", "x")?;
    let (height, lava) = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow
            .as_ref()
            .ok_or_else(|| RuntimeError::new("LaunchVolcano requires an active engine context"))?;
        let height = context
            .landscape_ref()
            .map(Landscape::estimated_height)
            .unwrap_or(0);
        let lava = context
            .world
            .materials()
            .and_then(|materials| materials.id_of("Lava"))
            .map(|material| material.index() as i32)
            .unwrap_or(MATERIAL_NONE);
        Ok((height, lava))
    })?;
    let size = (15 * height / 500 + draw_context_random(10)?).clamp(10, 60);

    let created = with_creatorless_object_context(|| {
        create_object(&[
            Value::C4Id("FXV1".to_string()),
            Value::Int(50),
            Value::Int(50),
            Value::Int(OWNER_NONE),
        ])
    })??;
    if let Some(target) = object_id_from_value(&created) {
        let args = [
            Value::Int(x),
            Value::Int(height - 1),
            Value::Int(size),
            Value::Int(lava),
        ];
        if let Some(Err(error)) = call_world_object_own_function(target, "Activate", &args) {
            tracing::warn!(
                id = target.as_u64(),
                definition = "FXV1",
                function = "Activate",
                %error,
                "volcano activation failed; continuing like C++ fail-safe Call"
            );
        }
    }
    Ok(Value::Int(1))
}

/// FnLaunchEarthquake (C4Script.cpp:3094-3097) discards
/// C4Weather::LaunchEarthquake's success value. Weather creates creatorless
/// FXQ1 at the exact requested position and fail-safe-calls Activate with no
/// arguments (C4Weather.cpp:196-203).
fn launch_earthquake(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "LaunchEarthquake", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "LaunchEarthquake", "y")?;

    let created = with_creatorless_object_context(|| {
        create_object(&[
            Value::C4Id("FXQ1".to_string()),
            Value::Int(x),
            Value::Int(y),
            Value::Int(OWNER_NONE),
        ])
    })??;
    if let Some(target) = object_id_from_value(&created) {
        call_object_own_fail_safe(target, "Activate", &[]);
    }
    Ok(Value::Nil)
}

/// FnFrameCounter (C4Script.cpp): Game.FrameCounter — the current
/// simulation frame.
fn frame_counter(_args: &[Value]) -> Result<Value, RuntimeError> {
    ENVIRONMENT_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let frame = borrow
            .as_ref()
            .map(|context| context.frame as i32)
            .unwrap_or(0);
        Ok(Value::Int(frame))
    })
}

/// `FnGetSystemTime` (C4Script.cpp:4654-4684): expose one local wall-clock
/// field only outside network, replay, and recording synchronization modes.
fn get_system_time(args: &[Value]) -> Result<Value, RuntimeError> {
    let field = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "GetSystemTime",
        "field",
    )?;
    let sync_mode = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .is_some_and(|context| context.world.control_sync_mode)
    });
    if sync_mode || !(0..=7).contains(&field) {
        return Ok(Value::Nil);
    }

    let now = Local::now();
    let value = match field {
        0 => now.year(),
        1 => now.month() as i32,
        2 => now.weekday().num_days_from_sunday() as i32,
        3 => now.day() as i32,
        4 => now.hour() as i32,
        5 => now.minute() as i32,
        6 => now.second() as i32,
        7 => (now.nanosecond() / 1_000_000) as i32,
        _ => unreachable!("field range checked above"),
    };
    Ok(Value::Int(value))
}

/// FnGetTime (C4Script.cpp:4647-4652): expose the process-local
/// `timeGetTime()` clock only in local, non-recording control mode. A missing
/// host context corresponds to C4GameControl::CM_None and is synchronized.
fn get_time(_args: &[Value]) -> Result<Value, RuntimeError> {
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        if context.world.control_sync_mode {
            return Ok(Value::Nil);
        }
        Ok(Value::Int(clonk_core::chrono_util::time_get_time() as i32))
    })
}

/// The active object of the executing call (`cthr->Obj`).
fn active_object_id() -> Option<ObjectId> {
    HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_context().map(|object| object.id()))
    })
}

/// C4IdText (C4Id.cpp:26-45) over a script value: C4ID_None -> "NONE",
/// numerical ids 0..9999 -> "%04u", literal ids stay as-is.
fn c4id_text_of(value: &Value) -> String {
    match value {
        Value::C4Id(id) => clonk_script::c4_id_text(id),
        Value::String(id) if !id.is_empty() => id.as_ref().to_owned(),
        Value::Int(raw) => c4id_to_definition(*raw).unwrap_or_else(|| "NONE".to_string()),
        _ => "NONE".to_string(),
    }
}

thread_local! {
    /// C4ObjectMenu::CloseQuerying (C4ObjectMenu.h:64): the per-menu
    /// recursion check for the MenuQueryCancel callback — shared between
    /// the host-fn close path and the engine-side close hooks.
    static CLOSE_QUERYING: RefCell<std::collections::HashSet<ObjectId>> =
        RefCell::new(std::collections::HashSet::new());
}

/// Marks `menu_object`'s menu as close-querying; false when a query is
/// already running (the C4ObjectMenu::CloseQuerying recursion check).
pub(crate) fn begin_menu_close_query(menu_object: ObjectId) -> bool {
    CLOSE_QUERYING.with(|cell| cell.borrow_mut().insert(menu_object))
}

pub(crate) fn end_menu_close_query(menu_object: ObjectId) {
    CLOSE_QUERYING.with(|cell| {
        cell.borrow_mut().remove(&menu_object);
    });
}

/// C4ObjectMenu::IsCloseDenied (C4ObjectMenu.cpp:56-75): a USER menu asks
/// MenuQueryCancel(Selection, ParentObject) on the command object
/// (CB_Object) or the scenario script (CB_Scenario); a truthy answer keeps
/// the menu open. The CloseQuerying flag stops recursive queries.
fn menu_close_denied(menu_object: ObjectId, menu: &crate::ObjectMenuState) -> bool {
    if !menu.user_menu {
        return false;
    }
    if !begin_menu_close_query(menu_object) {
        return false;
    }
    let pars = [
        Value::Int(menu.selection),
        object_reference_value(menu_object),
    ];
    // A missing function is a silent miss (the "~" in PSF_MenuQueryCancel);
    // callee errors fall back to close-OK (C4Object::Call, fPassErrors
    // defaults false — the error logs and the call yields C4VNull).
    let denied = if menu.scenario_callbacks {
        HOST_CONTEXT
            .with(|cell| {
                cell.borrow()
                    .as_ref()
                    .and_then(|context| context.world.scenario_script().cloned())
            })
            .filter(|script| script.has_local_function("MenuQueryCancel"))
            .and_then(|script| call_scoped_script_function(script, "MenuQueryCancel", &pars))
    } else if let Some(command_object) = menu.command_object {
        call_world_object_own_function(command_object, "MenuQueryCancel", &pars)
    } else {
        None
    }
    .map(|result| result.map(|value| value.as_bool()).unwrap_or(false))
    .unwrap_or(false);
    end_menu_close_query(menu_object);
    denied
}

/// C4Object::CloseMenu (C4Object.cpp:2009-2017): force skips the
/// MenuQueryCancel query (C4Menu::TryClose, C4Menu.cpp:317-320); a denied
/// soft close keeps the menu and fails.
fn close_object_menu(target: ObjectId, force: bool) -> bool {
    let menu = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_menu(target))
    });
    let Some(menu) = menu else {
        return true; // no menu -> close OK
    };
    if !force && menu_close_denied(target, &menu) {
        return false;
    }
    HOST_CONTEXT.with(|cell| {
        cell.borrow_mut()
            .as_mut()
            .map(|context| context.set_object_menu(target, None))
            .unwrap_or(false)
    })
}

/// FnCreateMenu (C4Script.cpp:1426-1459) → C4ObjectMenu::Init
/// (C4ObjectMenu.cpp:86-91): closes any old menu (soft — MenuQueryCancel
/// may deny), then installs a fresh user menu with Identification =
/// idMenuID ? idMenuID : iSymbol, the given style, and permanence.
fn create_menu(args: &[Value]) -> Result<Value, RuntimeError> {
    let symbol = parse_native_c4id_argument(args.first(), "CreateMenu")?
        .map(Value::C4Id)
        .unwrap_or(Value::Nil);
    let symbol_id = c4id_text_of(&symbol);
    let menu_target = parse_object_reference_argument(
        args.get(1).unwrap_or(&Value::Nil),
        "CreateMenu",
        "menu object",
    )?;
    let explicit_command = parse_object_reference_argument(
        args.get(2).unwrap_or(&Value::Nil),
        "CreateMenu",
        "command object",
    )?;
    let extra = parse_optional_i32(args.get(3), "CreateMenu", "extra")?.unwrap_or(0);
    let caption = parse_optional_string(args.get(4), "CreateMenu", "caption")?.unwrap_or_default();
    let extra_data = parse_optional_i32(args.get(5), "CreateMenu", "extra data")?.unwrap_or(0);
    let raw_style = parse_optional_i32(args.get(6), "CreateMenu", "style")?.unwrap_or(0);
    let style = raw_style & 127;
    let permanent = args.get(7).map(value_raw_truthy).unwrap_or(false);
    let menu_id = parse_native_c4id_argument(args.get(8), "CreateMenu")?
        .map(Value::C4Id)
        .unwrap_or(Value::Nil);

    let active = active_object_id();
    let Some(target) = menu_target.or(active) else {
        return Ok(Value::Bool(false)); // !pMenuObj && !cthr->Obj
    };
    let command_object = explicit_command.or(active);
    let scenario_callbacks = command_object.is_none();
    // Object menu: validate the command object (C4Script.cpp:1433-1436);
    // no command object is the scenario-script-callback form.
    if let Some(command_object) = command_object {
        let command_present = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .map(|context| context.object_status_present(command_object))
                .unwrap_or(false)
        });
        if !command_present {
            return Ok(Value::Bool(false));
        }
    }
    // Clear any old menu (C4Script.cpp:1447): a MenuQueryCancel denial
    // aborts the new menu.
    if !close_object_menu(target, false) {
        return Ok(Value::Bool(false));
    }
    let identification = if value_raw_truthy(&menu_id) {
        menu_id
    } else {
        symbol
    };
    let menu = crate::ObjectMenuState {
        caption,
        symbol_id,
        title_symbol: crate::ObjectMenuSymbol::default(),
        identification,
        // Style & C4MN_Style_BaseMask (C4Menu::InitMenu, C4Menu.cpp:359).
        style,
        equal_item_height: raw_style & 128 != 0,
        permanent,
        location: None,
        runtime_id: crate::direct_com::next_object_menu_runtime_id(),
        extra: crate::ObjectMenuExtra::from_legacy(extra),
        extra_data,
        internal_refill_token: 0,
        selection: -1,
        user_menu: true,
        command_object,
        scenario_callbacks,
        refill_object: None,
        refill_object_contents_count: 0,
        items: Vec::new(),
        // InitMenu immediately chooses five columns for Normal and one
        // for every other style (C4Menu.cpp:359-365); Lines stays at its
        // C4Menu::Default zero until layout/SetMenuSize.
        columns: if style == 0 { 5 } else { 1 },
        lines: 0,
        text_progressing: false,
        decoration: None,
    };
    let stored = HOST_CONTEXT.with(|cell| {
        cell.borrow_mut()
            .as_mut()
            .map(|context| context.set_object_menu(target, Some(menu)))
            .unwrap_or(false)
    });
    Ok(Value::Bool(stored))
}

/// FnGetMenu (C4Script.cpp:1418-1424): the active menu's Identification;
/// C4MN_None (0) without one; C4ID(-1) without an object.
fn get_menu(args: &[Value]) -> Result<Value, RuntimeError> {
    let target =
        parse_object_reference_argument(args.first().unwrap_or(&Value::Nil), "GetMenu", "obj")?;
    let Some(target) = target.or(active_object_id()) else {
        return Ok(Value::Int(-1));
    };
    let menu = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_menu(target))
    });
    Ok(menu
        .map(|menu| menu.identification)
        .unwrap_or(Value::Int(0)))
}

/// FnShowInfo (C4Script.cpp:3332-3336): open C4MN_Info on the calling
/// object, using the explicit object or the caller itself as target.
fn show_info(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some(command_object) = active_object_id() else {
        return Ok(Value::Bool(false));
    };
    let explicit =
        parse_object_reference_argument(args.first().unwrap_or(&Value::Nil), "ShowInfo", "object")?;
    let target = explicit.unwrap_or(command_object);
    let queued = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        if context.get_world_object(target).is_none() {
            return false;
        }
        let owner = context
            .get_world_object(command_object)
            .map(|object| object.owner)
            .unwrap_or(OWNER_NONE);
        context.pending_menu_requests.push(MenuRequest {
            crew_id: command_object,
            owner,
            kind: MenuRequestKind::Info { target },
        });
        true
    });
    Ok(Value::Bool(queued))
}

/// FnGetMenuSelection (C4Script.cpp:4310-4316): -1 without an object or an
/// active menu, else C4Menu::GetSelection() — the raw Selection index
/// (C4Menu.cpp:612-615; -1 while nothing is selected).
fn get_menu_selection(args: &[Value]) -> Result<Value, RuntimeError> {
    let target = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "GetMenuSelection",
        "obj",
    )?;
    let Some(target) = target.or(active_object_id()) else {
        return Ok(Value::Int(-1));
    };
    let menu = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_menu(target))
    });
    Ok(Value::Int(menu.map(|menu| menu.selection).unwrap_or(-1)))
}

/// FnKill (C4Script.cpp:335-345): default a null target to `cthr->Obj`,
/// reject missing/dead objects, trace a valid calling controller through
/// UpdatLastEnergyLossCause, and run the complete AssignDeath path.
fn kill(args: &[Value]) -> Result<Value, RuntimeError> {
    let target_id =
        parse_object_reference_argument(args.first().unwrap_or(&Value::Nil), "Kill", "target")?;
    let forced = value_to_bool(args.get(1).unwrap_or(&Value::Nil), "Kill", "forced")?;
    // C4Aul's typed two-parameter dispatch discards surplus values after
    // evaluating them (C4AulExec.cpp:1364-1396).

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        // `cthr->Obj`, not the mutable effect carrier: definition-owned
        // callbacks may carry pForObj state while executing with Obj=null.
        let caller = context.script_object_context;
        let Some(target) = target_id.or(caller) else {
            return Ok(Value::Bool(false));
        };
        if !context.ensure_object_scope(target)
            || !context
                .object_scope(target)
                .is_some_and(ObjectScopeContext::alive)
        {
            return Ok(Value::Bool(false));
        }

        let caller_controller = caller.and_then(|caller| {
            context
                .object_scope(caller)
                .map(ObjectScopeContext::controller)
                .or_else(|| {
                    context
                        .get_world_object(caller)
                        .map(|object| object.controller())
                })
        });
        let valid_controller =
            caller_controller.filter(|controller| context.player_state(*controller).is_some());
        if let Some(controller) = valid_controller {
            stage_energy_loss_cause(context, target, -1, crate::C4FX_CALL_ENG_SCRIPT, controller);
        }
        // C++ flips Alive before clearing death effects. Keep that state
        // visible to later host calls in this VM session without emitting a
        // bare Alive delta: AssignDeath owns the authoritative final value,
        // including non-forced revival by an effect.
        if let Some(scope) = context.object_scope_mut(target) {
            scope.request_assign_death(forced);
        }
        Ok(Value::Bool(true))
    })
}

/// FnPunch (C4Script.cpp:328-332) → ObjectComPunch (C4ObjectCom.cpp:
/// 735-767): a zero punch derives from the Fight physicals
/// (BoundBy(5*attacker/target, 0, 10)); QueryCatchBlow on the target
/// halves punch > 1 and stops the blow; the target loses punch% energy
/// (DoEnergy with the ATTACKER's controller as caused-by, kill-trace
/// marked) and its ComDir stops either way; a stopped blow returns false
/// without a fling; punch >= 10 tries the Tumble action (xdir
/// FIXED100(150)*tdir, ydir -2), the regular path GetPunched (xdir
/// FIXED100(250)*tdir, ydir 0) — each re-writing
/// LastEnergyLossCausePlayer unguarded and firing
/// CatchBlow(punch, attacker) on success.
fn punch(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some(target) =
        parse_object_reference_argument(args.first().unwrap_or(&Value::Nil), "Punch", "target")?
    else {
        return Ok(Value::Bool(false)); // !pTarget (C4ObjectCom.cpp:737)
    };
    let mut punch = parse_optional_i32(args.get(1), "Punch", "punch")?.unwrap_or(0);

    // Resolve only the physicals the native zero-punch branch actually
    // touches, in native order: target guard, attacker numerator, target
    // denominator (C4ObjectCom.cpp:738-740).
    let attacker = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_context().map(ObjectScopeContext::id))
    });
    let Some(attacker) = attacker else {
        return Ok(Value::Bool(false));
    };
    let target_exists = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        borrow
            .as_mut()
            .is_some_and(|context| context.ensure_object_scope(target))
    });
    if !target_exists {
        return Ok(Value::Bool(false)); // !cthr->Obj / unknown target
    }
    if punch == 0 {
        let Some(target_guard) =
            resolve_object_physical(target, false).map(|physical| physical.fight)
        else {
            return Ok(Value::Bool(false));
        };
        if target_guard != 0 {
            let Some(attacker_fight) =
                resolve_object_physical(attacker, false).map(|physical| physical.fight)
            else {
                return Ok(Value::Bool(false));
            };
            let Some(target_fight) =
                resolve_object_physical(target, false).map(|physical| physical.fight)
            else {
                return Ok(Value::Bool(false));
            };
            if target_fight != 0 {
                punch = (5 * attacker_fight / target_fight).clamp(0, 10);
            }
        }
    }
    if punch == 0 {
        return Ok(Value::Bool(true)); // nothing to do (C4ObjectCom.cpp:741)
    }

    // PSF_QueryCatchBlow (fail-safe; callee errors log and read as false,
    // C4Object::Call fPassErrors=false).
    let blow_stopped = match call_world_object_own_function(
        target,
        "QueryCatchBlow",
        &[object_reference_value(attacker)],
    ) {
        Some(Ok(value)) => value.as_bool(),
        Some(Err(error)) => {
            tracing::warn!(
                %error,
                "script error in QueryCatchBlow; continuing like the C++ fail-safe exec"
            );
            false
        }
        None => false,
    };
    if blow_stopped && punch > 1 {
        punch /= 2; // caught blow halves damage (C4ObjectCom.cpp:743)
    }

    // DoEnergy(-punch, false, C4FxCall_EngGetPunched, cObj->Controller)
    // reads the attacker controller after QueryCatchBlow. The target's
    // physical Energy lookup may itself run the first fair-crew fill.
    let attacker_controller = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_scope(attacker))
            .map(ObjectScopeContext::controller)
            .unwrap_or(OWNER_NONE)
    });
    let staged = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        stage_energy_loss_cause(
            context,
            target,
            -punch,
            crate::C4FX_CALL_ENG_GET_PUNCHED,
            attacker_controller,
        );
        context.object_scope(target).is_some()
    });
    if !staged {
        return Ok(Value::Bool(false));
    }
    let Some(max_energy) = resolve_object_physical(target, false).map(|physical| physical.energy)
    else {
        return Ok(Value::Bool(false));
    };
    let written = HOST_CONTEXT.with(|cell| {
        cell.borrow_mut()
            .as_mut()
            .and_then(|context| context.object_scope_mut(target))
            .map(|scope| {
                scope.adjust_energy(-punch, false, max_energy);
            })
            .is_some()
    });
    if !written {
        return Ok(Value::Bool(false));
    }
    // Native reads the attacker's facing only after DoEnergy returned, then
    // stops the target's command direction (C4ObjectCom.cpp:744-746).
    let tdir_set = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return None;
        };
        let tdir = match context.object_scope(attacker)?.direction() {
            Direction::Left => -1,
            _ => 1,
        };
        context
            .object_scope_mut(target)?
            .set_command_direction(CommandDirection::Stop);
        Some(tdir)
    });
    let Some(tdir) = tdir_set else {
        return Ok(Value::Bool(false));
    };
    if blow_stopped {
        return Ok(Value::Bool(false)); // no tumbles for caught blows
    }

    let try_fling = |action: &str, velocity: FixedVec2| -> bool {
        let action_set = matches!(
            call_world_object_function(
                target,
                "SetAction",
                &[Value::String(action.to_string().into())],
            ),
            Some(Ok(value)) if value.as_bool()
        );
        if !action_set {
            return false;
        }
        HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(context) = borrow.as_mut() else {
                return false;
            };
            context
                .object_scope_mut(target)
                .map(|scope| scope.set_fixed_velocity(velocity))
                .is_some()
        })
    };
    let flung = (punch >= 10
        && try_fling("Tumble", FixedVec2::new(fixed100(150) * tdir, itofix(-2))))
        || try_fling(
            "GetPunched",
            FixedVec2::new(fixed100(250) * tdir, C4Fixed::ZERO),
        );
    if !flung {
        return Ok(Value::Bool(false));
    }
    // A successful fling writes the kill trace DIRECTLY — no
    // UpdatLastEnergyLossCause guard ("for kill tracing when pushing
    // enemies off a cliff", C4ObjectCom.cpp:755,762).
    let attacker_controller = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_scope(attacker))
            .map(ObjectScopeContext::controller)
            .unwrap_or(OWNER_NONE)
    });
    HOST_CONTEXT.with(|cell| {
        if let Some(context) = cell.borrow_mut().as_mut() {
            if let Some(scope) = context.object_scope_mut(target) {
                scope.pending_update.energy_loss_cause = Some(attacker_controller);
            }
        }
    });
    // PSF_CatchBlow after a successful fling (C4ObjectCom.cpp:754,762).
    if let Some(Err(error)) = call_world_object_own_function(
        target,
        "CatchBlow",
        &[Value::Int(punch), object_reference_value(attacker)],
    ) {
        tracing::warn!(
            %error,
            "script error in CatchBlow; continuing like the C++ fail-safe exec"
        );
    }
    Ok(Value::Bool(true))
}

/// The literal-text half of the FnAddMenuItem sprintf (C4Script.cpp:
/// 1567-1570, fmt::sprintf(dummy, parameter, 0/1)): specifiers consume the
/// two arguments positionally — the parameter text first (its slot was
/// rewritten "%d" -> "%s"), then the left/right-click flag.
fn sprintf_menu_command(format: &str, parameter: &str, click: i32) -> String {
    let click_text = click.to_string();
    let mut arguments = [parameter, click_text.as_str()].into_iter();
    let mut out = String::with_capacity(format.len());
    let mut chars = format.chars().peekable();
    while let Some(current) = chars.next() {
        if current != '%' {
            out.push(current);
            continue;
        }
        match chars.peek().copied() {
            Some('%') => {
                chars.next();
                out.push('%');
            }
            Some('s') | Some('d') => {
                chars.next();
                out.push_str(arguments.next().unwrap_or(""));
            }
            _ => out.push('%'),
        }
    }
    out
}

fn menu_components_from_custom(values: Vec<Value>) -> Vec<crate::ObjectMenuComponent> {
    let mut components = Vec::<crate::ObjectMenuComponent>::new();
    let mut current_id: Option<String> = None;
    let mut current_count = 0_i32;
    let store = |components: &mut Vec<crate::ObjectMenuComponent>, id: String, count: i32| {
        if let Some(component) = components
            .iter_mut()
            .find(|component| component.definition_id == id)
        {
            component.count = count;
        } else {
            components.push(crate::ObjectMenuComponent {
                definition_id: id,
                count,
            });
        }
    };

    for value in values {
        let Value::C4Id(id) = value else {
            continue;
        };
        let raw = cast_c4id_payload(&id);
        if raw == 0 {
            continue;
        }
        let id = clonk_script::c4_id_from_raw(raw);
        if current_id.as_deref().is_some_and(|current| current != id) {
            store(
                &mut components,
                current_id.take().unwrap_or_default(),
                current_count,
            );
            current_count = 0;
        }
        current_id = Some(id);
        current_count = current_count.saturating_add(1);
    }
    if let Some(id) = current_id {
        store(&mut components, id, current_count);
    }
    components
}

/// `C4Def::GetComponents`' array-to-`C4IDList` conversion
/// (C4Def.cpp:1322-1355). The engine expects equal ids to be contiguous;
/// a later non-contiguous run overwrites the earlier count while retaining
/// the id's original list position through `SetIDCount(..., true)`.
pub(crate) fn component_list_from_custom_array(values: &[Value]) -> Vec<(String, i32)> {
    let mut components = Vec::<(String, i32)>::new();
    let mut last_id = String::new();
    let mut count = 0_i32;

    let store = |components: &mut Vec<(String, i32)>, id: &str, count: i32| {
        if id.is_empty() || count == 0 {
            return;
        }
        if let Some((_, stored_count)) = components.iter_mut().find(|(stored, _)| stored == id) {
            *stored_count = count;
        } else {
            components.push((id.to_owned(), count));
        }
    };

    for (index, value) in values.iter().enumerate() {
        let current_id = match value {
            Value::C4Id(id) if cast_c4id_payload(id) != 0 => {
                clonk_script::c4_id_from_raw(cast_c4id_payload(id))
            }
            Value::Int(raw @ 1..=9999) => format!("{raw:04}"),
            _ => continue,
        };
        // C4Def::GetComponents keys this flush off the ORIGINAL array
        // index. If the first valid ID follows an invalid slot it inserts a
        // leading C4ID_None entry; GetNeededMatStr/ComposeContents/Split then
        // stop at that sentinel before observing any later requirements.
        if index != 0 && last_id.is_empty() && count == 0 {
            return Vec::new();
        }
        if index != 0 && current_id != last_id {
            store(&mut components, &last_id, count);
            count = 0;
        }
        last_id = current_id;
        count = count.saturating_add(1);
    }
    store(&mut components, &last_id, count);
    components
}

/// FnAddMenuItem (C4Script.cpp:1471-1734): appends one item to the menu
/// object's OPEN menu. Sim-observable pieces ported: the composed
/// left/right-click commands (new-style %d sprintf vs old-style
/// "Fn(ID,param[,click][,value])"), the caption's %s -> def-name splice,
/// count/no-count, C4MN_Add_PassValue, selectability, and the
/// first-selectable selection grab (C4Menu::AddItem, C4Menu.cpp:424).
/// Symbols are presentation, but their argument CHECKS still gate the
/// return value (:1626,1679,1690-1693,1705-1709).
fn text_spec_image_known(context: &EffectHostContext, spec: &str) -> bool {
    match parse_text_spec(spec) {
        Some(TextSpec::Definition { id, .. }) => context.definition_metadata(id).is_some(),
        Some(TextSpec::Portrait {
            definition_id,
            portrait_name,
            ..
        }) => context
            .definition_metadata(definition_id)
            .is_some_and(|metadata| {
                metadata
                    .portrait_names
                    .iter()
                    .any(|name| name.eq_ignore_ascii_case(portrait_name))
            }),
        Some(TextSpec::Icon(_)) => true,
        None => false,
    }
}

fn add_menu_item(args: &[Value]) -> Result<Value, RuntimeError> {
    let caption_arg = parse_optional_string(args.first(), "AddMenuItem", "caption")?;
    let command_arg =
        parse_optional_string(args.get(1), "AddMenuItem", "command")?.unwrap_or_default();
    let item_id = parse_native_c4id_argument(args.get(2), "AddMenuItem")?;
    let item_id_raw = item_id
        .as_deref()
        .map(cast_c4id_payload)
        .unwrap_or_default();
    // C4MenuItem stores the typed C4ID payload. C4IdText is only used below
    // while composing executable source; using it for storage aliases e.g.
    // packed b"1111" with the distinct numeric C4ID 1111.
    let stored_item_id = clonk_script::c4_id_from_raw(item_id_raw);
    let menu_target = parse_object_reference_argument(
        args.get(3).unwrap_or(&Value::Nil),
        "AddMenuItem",
        "menu object",
    )?;
    let mut count = parse_optional_i32(args.get(4), "AddMenuItem", "count")?.unwrap_or(0);
    let parameter = args.get(5).cloned().unwrap_or(Value::Nil);
    let mut info_caption =
        parse_optional_string(args.get(6), "AddMenuItem", "info caption")?.unwrap_or_default();
    let extra = parse_optional_i32(args.get(7), "AddMenuItem", "extra")?.unwrap_or(0);
    let xpar = args.get(8).cloned().unwrap_or(Value::Nil);
    let xpar2 = args.get(9).cloned().unwrap_or(Value::Nil);

    let Some(target) = menu_target.or(active_object_id()) else {
        return Ok(Value::Bool(false)); // !pMenuObj (C4Script.cpp:1474)
    };
    let (
        menu,
        presentation_definition_id,
        def_name,
        def_description,
        static_components,
        component_script,
    ) = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return (None, None, String::new(), String::new(), Vec::new(), None);
        };
        // pDef = C4Id2Def(idItem), falling back to the menu object's own
        // def (C4Script.cpp:1488-1489).
        let item_definition_id = (item_id_raw != 0).then(|| stored_item_id.clone());
        let item_metadata = item_definition_id
            .as_deref()
            .and_then(|id| context.definition_metadata(id));
        let presentation_definition_id = item_metadata
            .and(item_definition_id.clone())
            .or_else(|| context.object_effective_definition_id(target));
        let def_name = presentation_definition_id
            .as_deref()
            .and_then(|id| context.definition_metadata(id))
            .map(|metadata| metadata.name.clone())
            .unwrap_or_default();
        let def_description = presentation_definition_id
            .as_deref()
            .and_then(|id| context.world.definition_description(id))
            .unwrap_or_default()
            .to_string();
        let static_components = item_metadata
            .map(|metadata| {
                metadata
                    .components
                    .iter()
                    .map(|(definition_id, count)| crate::ObjectMenuComponent {
                        definition_id: definition_id.clone(),
                        count: *count,
                    })
                    .collect()
            })
            .unwrap_or_default();
        let component_script = item_definition_id
            .as_deref()
            .filter(|_| item_metadata.is_some())
            .and_then(|id| context.world.definition_script(id))
            .cloned();
        (
            context.object_menu(target),
            presentation_definition_id,
            def_name,
            def_description,
            static_components,
            component_script,
        )
    });
    let Some(mut menu) = menu else {
        return Ok(Value::Bool(false)); // !pMenuObj->Menu (C4Script.cpp:1475)
    };
    let picture_symbol_size = if menu.style == 3 { 64 } else { 35 };

    // Compose the caption with the def name (C4Script.cpp:1492-1510).
    let mut caption = caption_arg
        .as_deref()
        .map(|text| text.replacen("%s", &def_name, 1))
        .unwrap_or_default();
    if info_caption.is_empty() && extra & 512 == 0 {
        info_caption = def_description;
    }
    info_caption = crate::normalize_menu_info_caption(info_caption);

    // Typed parameter -> command text (C4Script.cpp:1513-1546).
    let parameter_text = match &parameter {
        Value::Int(value) => value.to_string(),
        Value::Bool(flag) => if *flag { "true" } else { "false" }.to_string(),
        Value::RawBool(raw) => ((*raw as u32 as i32) != 0).to_string(),
        Value::C4Id(_) => c4id_text_of(&parameter),
        Value::Object(number) => format!("Object({number})"),
        Value::String(text) => format!("\"{text}\""),
        Value::Nil => "CastAny(0)".to_string(), // C4V_Any raw 0
        Value::Array(_) => {
            return Err(RuntimeError::new("array as parameter to AddMenuItem"));
        }
        Value::Proplist(_) => {
            return Err(RuntimeError::new("map as parameter to AddMenuItem"));
        }
    };

    // C4MN_Add_PassValue payload (C4Script.cpp:1549-1554).
    let own_value = (extra & 128 != 0).then(|| xpar2.as_c4_int().unwrap_or(0));

    // New style (any non-IsIdentifier char, C4Strings.cpp:36-45) vs old
    // style command composition (C4Script.cpp:1556-1597).
    let is_identifier = |c: char| c.is_ascii_alphanumeric() || matches!(c, '_' | '~' | '+' | '-');
    let (command, command2) = if command_arg.chars().any(|c| !is_identifier(c)) {
        let dummy = command_arg.replacen("%d", "%s", 1);
        (
            sprintf_menu_command(&dummy, &parameter_text, 0),
            sprintf_menu_command(&dummy, &parameter_text, 1),
        )
    } else if !command_arg.is_empty() {
        let id_text = clonk_script::c4_id_text(&stored_item_id);
        match own_value {
            Some(value) => (
                format!("{command_arg}({id_text},{parameter_text},0,{value})"),
                format!("{command_arg}({id_text},{parameter_text},1,{value})"),
            ),
            None => (
                format!("{command_arg}({id_text},{parameter_text})"),
                format!("{command_arg}({id_text},{parameter_text},1)"),
            ),
        }
    } else {
        (String::new(), String::new())
    };

    // Preserve the exact C4MN_Add_Img* recipe. Dialog portraits depend on
    // the pre-clear TextSpec caption surviving as an image source.
    let image = match extra & 127 {
        1 => {
            let rank = count;
            count = 0;
            crate::ObjectMenuImage::Rank { rank }
        }
        2 => crate::ObjectMenuImage::Indexed {
            index: xpar.as_c4_int().unwrap_or(0),
        },
        3 | 4 => {
            let Value::Object(number) = xpar else {
                return Ok(Value::Bool(false));
            };
            let object = ObjectId::new(number);
            if extra & 127 == 3 {
                crate::ObjectMenuImage::ObjectRank { object }
            } else {
                crate::ObjectMenuImage::Object { object }
            }
        }
        5 => {
            let Some(_) = caption_arg else {
                return Ok(Value::Bool(false));
            };
            let spec = caption.clone();
            let known = HOST_CONTEXT.with(|cell| {
                cell.borrow()
                    .as_ref()
                    .is_some_and(|context| text_spec_image_known(context, &spec))
            });
            if !known {
                return Ok(Value::Bool(false));
            }
            caption.clear();
            let raw_color = xpar.as_c4_int().unwrap_or(0) as u32;
            crate::ObjectMenuImage::TextSpec {
                spec,
                color: if raw_color == 0 { 0xff } else { raw_color },
            }
        }
        6 => crate::ObjectMenuImage::Color {
            color: xpar.as_c4_int().unwrap_or(0) as u32,
        },
        7 => {
            if extra & 128 != 0 {
                return Err(RuntimeError::new(
                    "AddMenuItem: C4MN_Add_ImgIndexedColor can not be used together with C4MN_Add_PassValue!",
                ));
            }
            crate::ObjectMenuImage::IndexedColor {
                index: xpar.as_c4_int().unwrap_or(0),
                color: xpar2.as_c4_int().unwrap_or(0) as u32,
            }
        }
        _ if item_id_raw == 0 => crate::ObjectMenuImage::None,
        _ => crate::ObjectMenuImage::Definition,
    };
    let picture_snapshot = match &image {
        crate::ObjectMenuImage::ObjectRank { object } => HOST_CONTEXT.with(|cell| {
            cell.borrow().as_ref().and_then(|context| {
                context.object_menu_picture_snapshot(*object, true, picture_symbol_size)
            })
        }),
        crate::ObjectMenuImage::Object { object } => HOST_CONTEXT.with(|cell| {
            cell.borrow().as_ref().and_then(|context| {
                context.object_menu_picture_snapshot(*object, false, picture_symbol_size)
            })
        }),
        _ => None,
    };

    // Zero count -> no count unless C4MN_Add_ForceCount (C4Script.cpp:1726).
    if count == 0 && extra & 256 == 0 {
        count = 12_345_678; // C4MN_Item_NoCount
    }
    let selectable = !command.is_empty();
    let components = match component_script.and_then(|script| {
        call_scoped_script_function(
            script,
            "GetCustomComponents",
            &[object_reference_value(target)],
        )
    }) {
        Some(result) => match result? {
            Value::Array(values) => menu_components_from_custom(values),
            _ => static_components,
        },
        None => static_components,
    };
    // First selectable item takes the selection, WITHOUT callbacks
    // (C4Menu::AddItem -> SetSelection(ItemCount-1, false, false)).
    if menu.internal_refill_token == 0 && menu.selection == -1 && selectable {
        menu.selection = menu.items.len() as i32;
    }
    menu.items.push(crate::ObjectMenuItem {
        caption,
        info_caption,
        command,
        command2,
        count,
        item_id: stored_item_id,
        symbol: crate::ObjectMenuSymbol::default(),
        image,
        presentation_definition_id,
        picture_snapshot,
        picture_object: None,
        components,
        selectable,
        value: own_value,
        text_display_progress: if menu.text_progressing { 0 } else { -1 },
    });
    let stored = HOST_CONTEXT.with(|cell| {
        cell.borrow_mut()
            .as_mut()
            .map(|context| context.set_object_menu(target, Some(menu)))
            .unwrap_or(false)
    });
    Ok(Value::Bool(stored))
}

/// C4ObjectMenu::OnSelectionChanged (C4ObjectMenu.cpp:93-104): user menus
/// fire OnMenuSelection(iNewSelection, ParentObject) on the command object
/// (CB_Object) or the scenario script (CB_Scenario); the result is
/// discarded, a missing function is a silent miss (PSF_MenuSelection is
/// "~"-prefixed), and callee errors log-and-continue (fPassErrors=false).
fn menu_selection_changed(menu_object: ObjectId, menu: &crate::ObjectMenuState) {
    if !menu.user_menu {
        return;
    }
    let pars = [
        Value::Int(menu.selection),
        object_reference_value(menu_object),
    ];
    let result = if menu.scenario_callbacks {
        HOST_CONTEXT
            .with(|cell| {
                cell.borrow()
                    .as_ref()
                    .and_then(|context| context.world.scenario_script().cloned())
            })
            .filter(|script| script.has_local_function("OnMenuSelection"))
            .and_then(|script| call_scoped_script_function(script, "OnMenuSelection", &pars))
    } else if let Some(command_object) = menu.command_object {
        call_world_object_own_function(command_object, "OnMenuSelection", &pars)
    } else {
        None
    };
    if let Some(Err(error)) = result {
        tracing::warn!(
            %error,
            "script error in OnMenuSelection; continuing like the C++ fail-safe exec"
        );
    }
}

/// FnSelectMenuItem (C4Script.cpp:1736-1741) → C4Menu::SetSelection
/// (C4Menu.cpp:557-594): moves the selection only onto SELECTABLE items
/// (or clears it on -1 in an empty menu), returns true whenever a menu is
/// active, and always runs the selection callback with the FINAL selection
/// (fDoCalls=true).
fn select_menu_item(args: &[Value]) -> Result<Value, RuntimeError> {
    let item = parse_optional_i32(args.first(), "SelectMenuItem", "item")?.unwrap_or(0);
    let target = parse_object_reference_argument(
        args.get(1).unwrap_or(&Value::Nil),
        "SelectMenuItem",
        "menu object",
    )?;
    let Some(target) = target.or(active_object_id()) else {
        return Ok(Value::Bool(false)); // !pMenuObj (C4Script.cpp:1738)
    };
    let menu = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_menu(target))
    });
    let Some(mut menu) = menu else {
        return Ok(Value::Bool(false)); // !pMenuObj->Menu (C4Script.cpp:1739)
    };
    let selectable = usize::try_from(item)
        .ok()
        .and_then(|index| menu.items.get(index))
        .map(|entry| entry.selectable)
        .unwrap_or(false);
    if (item == -1 && menu.items.is_empty()) || selectable {
        menu.selection = item;
    }
    let stored = HOST_CONTEXT.with(|cell| {
        cell.borrow_mut()
            .as_mut()
            .map(|context| context.set_object_menu(target, Some(menu.clone())))
            .unwrap_or(false)
    });
    if stored {
        menu_selection_changed(target, &menu);
    }
    Ok(Value::Bool(true))
}

/// FnClearMenuItems (C4Script.cpp:5149-5159) -> C4Menu::ClearItems(true)
/// (C4Menu.cpp:975-988): delete every item, reset the selection, and keep
/// the menu open. The `true` is fResetSelection; SetSelection receives
/// fDoCalls=false, so OnMenuSelection deliberately does not run.
fn clear_menu_items(args: &[Value]) -> Result<Value, RuntimeError> {
    let target = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "ClearMenuItems",
        "obj",
    )?;
    let Some(target) = target.or(active_object_id()) else {
        return Ok(Value::Bool(false));
    };
    let menu = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_menu(target))
    });
    let Some(mut menu) = menu else {
        return Ok(Value::Bool(false));
    };
    menu.items.clear();
    menu.selection = -1;
    let stored = HOST_CONTEXT.with(|cell| {
        cell.borrow_mut()
            .as_mut()
            .map(|context| context.set_object_menu(target, Some(menu)))
            .unwrap_or(false)
    });
    Ok(Value::Bool(stored))
}

/// FnCloseMenu (C4Script.cpp:4309-4314): pObj->CloseMenu(true) — the
/// forced close never asks MenuQueryCancel and always reports success.
fn close_menu(args: &[Value]) -> Result<Value, RuntimeError> {
    let target =
        parse_object_reference_argument(args.first().unwrap_or(&Value::Nil), "CloseMenu", "obj")?;
    let Some(target) = target.or(active_object_id()) else {
        return Ok(Value::Bool(false));
    };
    Ok(Value::Bool(close_object_menu(target, true)))
}

/// FnSetMenuSize (C4Script.cpp:4483-4492): false without an active menu;
/// cols/rows clamp through BoundBy(0..50) into C4Menu::SetSize
/// (C4Menu.cpp:635-640), where a ZERO axis keeps the previous value. The
/// stored Columns/Lines drive the menu layout (presentation) — the
/// sim-observable pieces are this state and the bool return.
fn set_menu_size(args: &[Value]) -> Result<Value, RuntimeError> {
    let cols = parse_optional_i32(args.first(), "SetMenuSize", "cols")?.unwrap_or(0);
    let rows = parse_optional_i32(args.get(1), "SetMenuSize", "rows")?.unwrap_or(0);
    let target =
        parse_object_reference_argument(args.get(2).unwrap_or(&Value::Nil), "SetMenuSize", "obj")?;
    let Some(target) = target.or(active_object_id()) else {
        return Ok(Value::Bool(false)); // !pObj (C4Script.cpp:4486)
    };
    let menu = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_menu(target))
    });
    let Some(mut menu) = menu else {
        return Ok(Value::Bool(false)); // !pMnu || !IsActive (C4Script.cpp:4489)
    };
    let cols = cols.clamp(0, 50);
    let rows = rows.clamp(0, 50);
    if cols != 0 {
        menu.columns = cols;
    }
    if rows != 0 {
        menu.lines = rows;
    }
    HOST_CONTEXT.with(|cell| {
        cell.borrow_mut()
            .as_mut()
            .map(|context| context.set_object_menu(target, Some(menu)))
    });
    Ok(Value::Bool(true))
}

/// FnSetMenuDecoration (C4Script.cpp:1737-1748): NO cthr->Obj fallback —
/// a nil menu object fails even with a scope object. The deco def must be
/// known (FrameDecoration::SetByDef fails on C4Id2Def null,
/// C4GuiDialogs.cpp:113-114). SetByDef snapshots five definition callbacks
/// and eight ActMap facets immediately.
fn build_frame_decoration_snapshot(deco_id: &str) -> Option<crate::ObjectMenuFrameDecoration> {
    let (metadata, script) = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        Some((
            context.definition_metadata(deco_id).cloned()?,
            context.world.definition_script(deco_id).cloned()?,
        ))
    })?;
    let query = |suffix: &str| {
        let function = format!("FrameDecoration{suffix}");
        match call_scoped_script_function(Arc::clone(&script), &function, &[]) {
            Some(Ok(value)) => value.as_c4_int().unwrap_or(0),
            Some(Err(error)) => {
                tracing::warn!(%error, function, "frame-decoration callback failed; using zero");
                0
            }
            None => 0,
        }
    };
    let facet = |suffix: &str| {
        metadata
            .action_graphics
            .get(&format!("FrameDeco{suffix}"))
            .and_then(|graphics| graphics.facet.clone())
    };
    Some(crate::ObjectMenuFrameDecoration {
        source_definition: deco_id.to_string(),
        background_color: query("BackClr") as u32,
        border_top: query("BorderTop"),
        border_left: query("BorderLeft"),
        border_right: query("BorderRight"),
        border_bottom: query("BorderBottom"),
        top: facet("Top"),
        top_right: facet("TopRight"),
        right: facet("Right"),
        bottom_right: facet("BottomRight"),
        bottom: facet("Bottom"),
        bottom_left: facet("BottomLeft"),
        left: facet("Left"),
        top_left: facet("TopLeft"),
    })
}

fn set_menu_decoration(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some(deco_id) = parse_custom_message_decoration(args.first(), "SetMenuDecoration")? else {
        return Ok(Value::Bool(false));
    };
    let target = parse_object_reference_argument(
        args.get(1).unwrap_or(&Value::Nil),
        "SetMenuDecoration",
        "menu object",
    )?;
    let Some(target) = target else {
        return Ok(Value::Bool(false)); // !pMenuObj (C4Script.cpp:1739)
    };
    let menu = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return None;
        };
        context.object_menu(target)
    });
    let Some(mut menu) = menu else {
        return Ok(Value::Bool(false)); // !pMenuObj->Menu (C4Script.cpp:1739)
    };
    let Some(decoration) = build_frame_decoration_snapshot(&deco_id) else {
        return Ok(Value::Bool(false)); // SetByDef failed (C4Script.cpp:1741-1745)
    };
    menu.decoration = Some(decoration);
    HOST_CONTEXT.with(|cell| {
        cell.borrow_mut()
            .as_mut()
            .map(|context| context.set_object_menu(target, Some(menu)))
    });
    Ok(Value::Bool(true))
}

/// FnSetMenuTextProgress (C4Script.cpp:1750-1754): NO cthr->Obj fallback —
/// a nil menu object fails even with a scope object. With an active menu
/// C4Menu::SetTextProgress(n, fAdd=false) (C4Menu.cpp:1079-1111)
/// distributes the shared byte budget across each non-portrait row.
fn set_menu_text_progress(args: &[Value]) -> Result<Value, RuntimeError> {
    let progress =
        parse_optional_i32(args.first(), "SetMenuTextProgress", "progress")?.unwrap_or(0);
    let target = parse_object_reference_argument(
        args.get(1).unwrap_or(&Value::Nil),
        "SetMenuTextProgress",
        "menu object",
    )?;
    let Some(target) = target else {
        return Ok(Value::Bool(false)); // !pMenuObj (C4Script.cpp:1752)
    };
    let menu = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_menu(target))
    });
    let Some(mut menu) = menu else {
        return Ok(Value::Bool(false)); // !pMenuObj->Menu / !IsActive
    };
    let _ = menu.set_text_progress(progress, false);
    HOST_CONTEXT.with(|cell| {
        cell.borrow_mut()
            .as_mut()
            .map(|context| context.set_object_menu(target, Some(menu)))
    });
    Ok(Value::Bool(true))
}

/// FnSetPlrView (C4Script.cpp:2545-2550): switch a valid player to
/// C4PVM_Target and follow the supplied ViewTarget. C4Player::ViewCursor and
/// viewport HUD focus remain independent; the later player phase copies the
/// target position into the modeled viewport center.
fn set_plr_view(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "SetPlrView expects at most 2 arguments: player and target",
        ));
    }
    let player_id = value_to_i32(args.first().unwrap_or(&Value::Nil), "SetPlrView", "player")?;
    let object = args
        .get(1)
        .map(|value| parse_object_reference_argument(value, "SetPlrView", "target"))
        .transpose()?
        .flatten();
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let Some(player) = context.player_state_mut(player_id) else {
            return Ok(Value::Bool(false));
        };
        player.set_view_target(object);
        context.record_player_command(PlayerCommand::SetPlrView { player_id, object });
        Ok(Value::Bool(true))
    })
}

/// FnGetPlrViewMode (C4Script.cpp:2579-2584): local, non-recording games
/// expose C4Player::ViewMode; synchronized control and invalid players return
/// -1 because the process-local mode must not affect synchronized scripts.
fn get_plr_view_mode(args: &[Value]) -> Result<Value, RuntimeError> {
    let player_id = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "GetPlrViewMode",
        "player",
    )?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let mode = borrow
            .as_ref()
            .filter(|context| !context.world.control_sync_mode)
            .and_then(|context| context.player_state(player_id))
            .map_or(-1, |player| player.view_mode);
        Ok(Value::Int(mode))
    })
}

/// FnGetPlrView (C4Script.cpp:2586-2591): expose ViewTarget only while the
/// valid player is in C4PVM_Target. Unlike GetPlrViewMode, C++ does not hide
/// this pointer during synchronized execution.
fn get_plr_view(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "GetPlrView expects at most 1 argument: player",
        ));
    }
    let player_id = value_to_i32(args.first().unwrap_or(&Value::Nil), "GetPlrView", "player")?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let target = borrow
            .as_ref()
            .and_then(|context| context.player_state(player_id))
            .filter(|player| player.view_mode == crate::PLAYER_VIEW_MODE_TARGET)
            .and_then(|player| player.view_target);
        Ok(target.map(object_reference_value).unwrap_or(Value::Nil))
    })
}

/// FnSetFilmView (C4Script.cpp:5134-5148): validate the target even in live
/// games, where the call is a no-op. Replay execution hands the temporary
/// first-viewport player assignment to the embedding app.
fn set_film_view(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "SetFilmView expects at most 1 argument: player",
        ));
    }
    let player = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "SetFilmView",
        "player",
    )?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref();
        if player != OWNER_NONE
            && context.is_none_or(|context| context.player_state(player).is_none())
        {
            return Ok(Value::Bool(false));
        }
        if let Some(context) = context.filter(|context| {
            context.world.replay_control && context.world.film_viewport_available
        }) {
            context
                .world
                .viewport_presentation_requests
                .borrow_mut()
                .push(crate::ViewportPresentationRequest::SetFilmView { player });
        }
        Ok(Value::Bool(true))
    })
}

/// FnSetPlrViewRange (C4Script.cpp:3681-3691): persist the object's FoW
/// range, including the legacy low-range clamp unless `exact` is true.
fn set_plr_view_range(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut range = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "SetPlrViewRange",
        "range",
    )?;
    let target = parse_object_reference_argument(
        args.get(1).unwrap_or(&Value::Nil),
        "SetPlrViewRange",
        "obj",
    )?;
    let exact = value_to_bool(
        args.get(2).unwrap_or(&Value::Nil),
        "SetPlrViewRange",
        "exact",
    )?;
    if !exact && range > 0 && range < 128 {
        range = 128;
    }
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Int(0));
        };
        let target = target.or_else(|| context.object_context().map(ObjectScopeContext::id));
        let Some(target) = target else {
            return Ok(Value::Int(0));
        };
        if !context.ensure_object_scope(target) {
            return Ok(Value::Int(0));
        }
        if let Some(scope) = context.object_scope_mut(target) {
            scope.set_plr_view_range(range);
            Ok(Value::Int(1))
        } else {
            Ok(Value::Int(0))
        }
    })
}

/// FnSetSolidMask (C4Script.cpp:271-278): sets the object's SolidMask
/// rect (x,y,wdt,hgt,tx,ty); a zero-area rect disables the mask (gates
/// open/close through this from UpdateTransferZone handlers).
fn set_solid_mask(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut values = [0i32; 6];
    for (i, slot) in values.iter_mut().enumerate() {
        *slot = parse_optional_i32(args.get(i), "SetSolidMask", "rect")?.unwrap_or(0);
    }
    let target =
        parse_object_reference_argument(args.get(6).unwrap_or(&Value::Nil), "SetSolidMask", "obj")?;
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let active = context.object_context().map(|object| object.id());
        let Some(target) = target.or(active) else {
            return Ok(Value::Bool(false));
        };
        let rect = crate::DefinitionTargetRect::new(
            values[0], values[1], values[2], values[3], values[4], values[5],
        );
        if context.object_scope(target).is_none() && !context.ensure_object_scope(target) {
            tracing::debug!(
                target = target.as_u64(),
                "SetSolidMask: unknown target; skipped"
            );
            return Ok(Value::Bool(false));
        }
        let rect = context
            .check_solid_mask_rect_for_object(target, rect)
            .unwrap_or(rect);
        let Some(object) = context.object_scope_mut(target) else {
            return Ok(Value::Bool(false));
        };
        object.set_solid_mask_rect(rect);
        context.update_live_solid_mask(target, true);
        Ok(Value::Bool(true))
    })
}

/// FnChangeDef (C4Script.cpp) -> C4Object::ChangeDef. The lifecycle is
/// synchronous: a contained object silently exits at (0,0), the old action
/// resets, the new definition becomes callback-visible, and RejectEntrance
/// decides whether a no-calls Enter restores the saved container.
fn change_def(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some(new_id) = parse_native_c4id_argument(args.first(), "ChangeDef")? else {
        return Ok(Value::Bool(false));
    };
    let target =
        parse_object_reference_argument(args.get(1).unwrap_or(&Value::Nil), "ChangeDef", "obj")?;
    let active = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.script_object_context)
    });
    // The optional object argument selects the native receiver; it does not
    // perform a second script lookup on that object's definition. A script
    // function also named ChangeDef therefore cannot shadow FnChangeDef.
    let target = target.or(active);
    let Some(target) = target else {
        return Ok(Value::Bool(false));
    };
    Ok(Value::Bool(change_def_live(target, &new_id)?))
}

/// Native host-side C4Object::ChangeDef used both by FnChangeDef and
/// BurnTurnTo. It bypasses script function resolution but keeps every
/// callback that the C++ object method itself performs.
fn change_def_live(target: ObjectId, new_id: &str) -> Result<bool, RuntimeError> {
    let known = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        context.definition_metadata(new_id).is_some() && context.ensure_object_scope(target)
    });
    if !known {
        return Ok(false);
    }
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        if let Some(scope) = borrow
            .as_mut()
            .and_then(|context| context.object_scope_mut(target))
        {
            // This marker describes the most recent ChangeDef lifecycle,
            // not merely an initial Exit. A later failed re-entry must clear
            // an earlier successful marker in the same staged update.
            scope.pending_update.change_def_reinsert = false;
            scope.pending_update.change_def_contents_sort = None;
            scope.pending_update.change_def_reset_action_time = false;
        }
    });

    let previous_container = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(target))
            .and_then(|object| object.container())
    });
    if let Some(previous) = previous_container {
        let _ = exit_object_at_position_with_calls(target, Vector2::ZERO, false)?;
        HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(context) = borrow.as_mut() else {
                return;
            };
            context.relink_content_after_exit(previous, target);
        });
    }

    // SetAction(ActIdle) runs on the OLD definition, including its ordinary
    // Start/Abort callbacks. NoOtherAction may reject it, but ChangeDef then
    // forcibly stores ActIdle before swapping Def.
    let action_was_idle = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_scope(target))
            .is_some_and(|object| {
                object.action_library.is_idle_entry(
                    object.effective_action_name(),
                    object.effective_action_index(),
                )
            })
    });
    let action_applied = native_set_action_by_name(target, "Idle")?;

    let staged = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        let Some(metadata) = context.definition_metadata(new_id).cloned() else {
            return false;
        };
        let world = context.world.clone();
        let current_color = context
            .object_scope(target)
            .and_then(|object| object.pending_update.color)
            .or_else(|| {
                context
                    .get_world_object(target)
                    .and_then(|object| object.full_state().map(|state| state.color))
            })
            .unwrap_or(0);
        let owner = context.object_scope(target).map(ObjectScopeContext::owner);
        let changed_color = if !context.world.definition_color_by_owner(new_id) {
            Some(0)
        } else if current_color == 0 {
            owner.and_then(|owner| {
                context.world.player(owner).and_then(|player| {
                    player.color.map(|color| {
                        u32::from(color.r) << 16 | u32::from(color.g) << 8 | u32::from(color.b)
                    })
                })
            })
        } else {
            None
        };
        let follows_definition = context
            .object_blit_mode(target)
            .is_none_or(|mode| mode & GFX_BLIT_CUSTOM == 0);
        let had_pending_blit = context
            .object_scope(target)
            .is_some_and(|object| object.pending_update.blit_mode.is_some());
        let pre_swap_contents_sort = context.get_world_object(target).and_then(|object| {
            object.container().map(|container| ChangeDefContentsSort {
                container,
                category: object.category,
                definition_id: object.definition_id().to_string(),
                unsorted: object.unsorted,
            })
        });
        let Some(object) = context.object_scope_mut(target) else {
            return false;
        };

        if let Some(sort) = pre_swap_contents_sort {
            object.pending_update.change_def_reinsert = true;
            object.pending_update.change_def_contents_sort = Some(sort);
        }
        // SetAction resets Time only when Act actually changes. Its boolean
        // return means success, not change; ChangeDef while already Idle
        // preserves a nonzero saved/reentrant Time like C++.
        object.pending_update.change_def_reset_action_time = action_applied && !action_was_idle;

        // C++ writes Action.Act=ActIdle unconditionally after SetAction and
        // all of its callbacks. If an AbortCall selected another action, its
        // Time/Data/Phase/targets remain, but the action slot becomes Idle.
        let action = object
            .pending_update
            .action
            .get_or_insert_with(ActionUpdate::default);
        action.set_name("Idle".to_string());
        action.set_force(true);
        action.callbacks_dispatched = true;
        object.update_effective_action("Idle");

        // Earlier graphics/mask writes are overwritten at the exact swap
        // point; later statements can stage new overrides normally.
        object.pending_update.solid_mask_override = None;
        object.set_base_graphics(None);
        if let Some(color) = changed_color {
            object.pending_update.color = Some(color);
        }
        if follows_definition && had_pending_blit {
            object.pending_update.blit_mode = Some(metadata.blit_mode);
        }
        object.install_definition_preview(new_id, &metadata);
        object.configure_fair_crew(&world);
        true
    });
    if !staged {
        return Ok(false);
    }
    HOST_CONTEXT.with(|cell| {
        if let Some(context) = cell.borrow_mut().as_mut() {
            context.update_live_solid_mask(target, true);
            let _ = refresh_live_object_ocf(context, target);
        }
    });

    if let Some(previous) = previous_container {
        // Return value intentionally ignored: C4Object::ChangeDef succeeds
        // even when new-def RejectEntrance or later Enter checks veto.
        if enter_object_live_with_calls(target, previous, false)? {
            HOST_CONTEXT.with(|cell| {
                let mut borrow = cell.borrow_mut();
                if let Some(scope) = borrow
                    .as_mut()
                    .and_then(|context| context.object_scope_mut(target))
                {
                    scope.pending_update.change_def_reinsert = true;
                    scope.pending_update.change_def_contents_sort = None;
                }
            });
        }
    }
    Ok(true)
}

/// FnGetPlrDownDouble (C4Script.cpp:2618-2622): the player's live
/// double-Down countdown. A missing player returns nil.
fn get_plr_down_double(args: &[Value]) -> Result<Value, RuntimeError> {
    let player_id = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "GetPlrDownDouble",
        "player",
    )?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let Some(player) = context.player_state(player_id) else {
            return Ok(Value::Nil);
        };
        Ok(Value::Int(player.control.last_com_down_double))
    })
}

/// FnClearLastPlrCom (C4Script.cpp:2624-2635): clear only LastCom and
/// LastComDownDouble. C++ deliberately leaves LastComDelay and PressedComs.
fn clear_last_plr_com(args: &[Value]) -> Result<Value, RuntimeError> {
    let player_id = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "ClearLastPlrCom",
        "player",
    )?;
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let Some(player) = context.player_state_mut(player_id) else {
            return Ok(Value::Bool(false));
        };
        player.control.last_com = 0;
        player.control.last_com_down_double = 0;
        context.record_player_command(PlayerCommand::ClearLastPlrCom { player_id });
        Ok(Value::Bool(true))
    })
}

/// FnSetVisibility (C4Script.cpp:3860-3869): write the target object's raw
/// VIS_* bitmask; a null target defaults to the calling object.
fn set_visibility(args: &[Value]) -> Result<Value, RuntimeError> {
    let visibility = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "SetVisibility",
        "visibility",
    )?;
    let target = args
        .get(1)
        .map(|value| parse_object_reference_argument(value, "SetVisibility", "object"))
        .transpose()?
        .flatten();
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let Some(target) = target.or_else(|| context.object_context().map(|object| object.id()))
        else {
            return Ok(Value::Bool(false));
        };
        Ok(Value::Bool(
            context.set_object_visibility(target, visibility),
        ))
    })
}

/// FnSetClrModulation (C4Script.cpp:3880-3901): set either the object's
/// `ColorMod` or one existing overlay's modulation. A null object defaults
/// to the calling object; an unknown overlay fails without creating it.
fn set_clr_modulation(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 3 {
        return Err(RuntimeError::new(
            "SetClrModulation expects at most 3 arguments: color, object and overlay id",
        ));
    }
    let color = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "SetClrModulation",
        "clr",
    )? as u32;
    let target = args
        .get(1)
        .map(|value| parse_object_reference_argument(value, "SetClrModulation", "object"))
        .transpose()?
        .flatten();
    let overlay_id = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "SetClrModulation",
        "overlay id",
    )?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let Some(target) = target.or_else(|| context.object_context().map(|object| object.id()))
        else {
            return Ok(Value::Bool(false));
        };
        let changed = if overlay_id == 0 {
            context.set_object_color_modulation(target, color)
        } else {
            context.set_object_overlay_color_modulation(target, overlay_id, color)
        };
        Ok(Value::Bool(changed))
    })
}

/// FnGetClrModulation (C4Script.cpp:3904-3921): return the raw object or
/// overlay modulation; a missing object/overlay is nil.
fn get_clr_modulation(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "GetClrModulation expects at most 2 arguments: object and overlay id",
        ));
    }
    let target = args
        .first()
        .map(|value| parse_object_reference_argument(value, "GetClrModulation", "object"))
        .transpose()?
        .flatten();
    let overlay_id = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "GetClrModulation",
        "overlay id",
    )?;

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let Some(target) = target.or_else(|| context.object_context().map(|object| object.id()))
        else {
            return Ok(Value::Nil);
        };
        let color = if overlay_id == 0 {
            context.object_color_modulation(target)
        } else {
            context.object_overlay_color_modulation(target, overlay_id)
        };
        Ok(color
            .map(|color| Value::Int(color as i32))
            .unwrap_or(Value::Nil))
    })
}

/// FnModulateColor (C4Script.cpp:5597-5612): multiply packed RGB channels
/// with the engine's `/ 256` rule and combine inverted alpha upwards.
fn modulate_color(args: &[Value]) -> Result<Value, RuntimeError> {
    let color1 = parse_native_optional_i32(args.first(), "ModulateColor", "color 1")?
        .unwrap_or(0x00ff_ffff) as u32;
    let color2 = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "ModulateColor",
        "color 2",
    )? as u32;
    let channel = |shift: u32| -> u32 {
        ((((color1 >> shift) & 0xff_u32) * ((color2 >> shift) & 0xff_u32)) >> 8) << shift
    };
    let alpha1 = color1 >> 24;
    let alpha2 = color2 >> 24;
    let alpha = (alpha1 + alpha2 - ((alpha1 * alpha2) >> 8)).min(0xff);
    Ok(Value::Int(
        (channel(0) | channel(8) | channel(16) | (alpha << 24)) as i32,
    ))
}

fn call_object_own_fail_safe(target: ObjectId, function: &str, args: &[Value]) -> Value {
    match call_world_object_own_function(target, function, args) {
        Some(Ok(value)) => value,
        Some(Err(error)) => {
            tracing::warn!(
                %error,
                object = target.as_u64(),
                callback = function,
                "script error in object callback; continuing like C++ fail-safe Call"
            );
            Value::Nil
        }
        None => Value::Nil,
    }
}

/// Fail-safe own-script call that also accepts an already-active object
/// scope which has not joined the world list yet. Plain Engine spawns run
/// Construction/Initialize in exactly that pre-insertion state.
fn call_inflight_object_own_fail_safe(target: ObjectId, function: &str, args: &[Value]) -> Value {
    match call_world_object_own_function_inflight(target, function, args) {
        Some(Ok(value)) => value,
        Some(Err(error)) => {
            tracing::warn!(
                %error,
                object = target.as_u64(),
                callback = function,
                "script error in object callback; continuing like C++ fail-safe Call"
            );
            Value::Nil
        }
        None => Value::Nil,
    }
}

fn object_is_present(target: ObjectId) -> bool {
    HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .is_some_and(|context| context.object_status_present(target))
    })
}

fn first_retained_content(context: &EffectHostContext, target: ObjectId) -> Option<ObjectId> {
    context
        .get_world_object(target)?
        .contents()
        .iter()
        .copied()
        .find(|content| context.object_status_present(*content))
}

fn retained_contents_count(context: &EffectHostContext, target: ObjectId) -> usize {
    context
        .get_world_object(target)
        .map(|object| {
            object
                .contents()
                .iter()
                .filter(|content| context.object_status_present(**content))
                .count()
        })
        .unwrap_or_default()
}

/// C++ truthiness of a raw object Status. Inactive objects still receive
/// callbacks; only Deleted/status-zero objects are suppressed.
fn object_has_status(target: ObjectId) -> bool {
    HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .is_some_and(|context| context.object_status_present(target))
    })
}

fn live_collection_eligible(
    context: &EffectHostContext,
    target: ObjectId,
    ignore_no_collect_delay: bool,
) -> bool {
    let Some(scope) = context.object_scope(target) else {
        return false;
    };
    let Some(definition_id) = context.object_effective_definition_id(target) else {
        return false;
    };
    let Some(metadata) = context.definition_metadata(&definition_id) else {
        return false;
    };
    let construction_ready = scope.construction() >= FULL_CON || metadata.fire.incomplete_activity;
    let positive_rect = metadata
        .fire
        .collection_rect
        .is_some_and(|rect| rect.width > 0 && rect.height > 0);
    let below_limit = !crate::collection_limit_reached(
        metadata.collection_limit,
        retained_contents_count(context, target),
    );
    construction_ready
        && positive_rect
        && below_limit
        && !scope
            .action_library
            .disables_object_for_entry(
                scope.effective_action_name(),
                scope.effective_action_index(),
            )
        && (ignore_no_collect_delay || scope.no_collect_delay() == 0)
}

/// Presence check for ordered command previews: once a same-call scope
/// exists, its removal state supersedes the immutable frame snapshot.
fn preview_object_is_present(target: ObjectId) -> bool {
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        match context.object_scope(target) {
            Some(scope) => !scope.destroy && scope.status() != ObjectStatus::Deleted,
            None => context
                .get_world_object(target)
                .is_some_and(|object| object.is_present()),
        }
    })
}

/// Synchronous host-side portion of C4Object::SetOCF that depends on live
/// motion/containment/terrain. Definition-static bits remain in the cached
/// seed; every field this helper rebuilds is cleared first like C++.
fn refresh_live_object_ocf(context: &mut EffectHostContext, target: ObjectId) -> bool {
    if !context.ensure_object_scope(target) {
        return false;
    }
    let Some(definition_id) = context.object_effective_definition_id(target) else {
        return false;
    };
    let Some(metadata) = context.definition_metadata(&definition_id).cloned() else {
        return false;
    };
    let Some((
        position,
        container,
        construction,
        rotation,
        energy,
        on_fire,
        alive,
        category,
        action_disabled,
    )) = context.object_scope(target).map(|scope| {
        (
            scope.effective_position(),
            scope.container(),
            scope.construction(),
            scope.rotation(),
            scope.energy(),
            scope.ocf() & ocf::ON_FIRE != 0,
            scope.alive(),
            scope.category(),
            scope
                .action_library
                .disables_object_for_entry(
                    scope.effective_action_name(),
                    scope.effective_action_index(),
                ),
        )
    })
    else {
        return false;
    };
    let collection = live_collection_eligible(context, target, false);
    let solid_center = context
        .landscape_ref()
        .is_some_and(|landscape| landscape.is_solid_at(position.x, position.y));
    let semi_above = context.landscape_ref().is_some_and(|landscape| {
        landscape.is_semi_solid_at(position.x, position.y.saturating_sub(1))
    });
    let solid_above = context
        .landscape_ref()
        .is_some_and(|landscape| landscape.is_solid_at(position.x, position.y.saturating_sub(1)));
    let semi_high = context.landscape_ref().is_some_and(|landscape| {
        landscape.is_semi_solid_at(position.x, position.y.saturating_sub(8))
    });
    let container_allows_get = container.is_some_and(|container| {
        let grab_get = context
            .object_effective_definition_id(container)
            .and_then(|id| context.definition_metadata(&id))
            .is_some_and(|metadata| metadata.grab_put_get & 2 != 0);
        let entrance = context
            .object_scope(container)
            .map(ObjectScopeContext::ocf)
            .or_else(|| {
                context
                    .get_world_object(container)
                    .map(|object| object.ocf())
            })
            .is_some_and(|mask| mask & ocf::ENTRANCE != 0);
        grab_get || entrance
    });

    let Some(scope) = context.object_scope_mut(target) else {
        return false;
    };
    scope.refresh_cached_ocf();
    let mut mask = scope.cached_ocf.unwrap_or(ocf::NORMAL);
    // Every bit whose SetOCF predicate depends directly or indirectly on
    // Con is rebuilt from the live definition/scope. DoCon calls SetOCF
    // before UpdateFace and before any lifecycle callback.
    mask &= !(ocf::CONSTRUCT
        | ocf::FULL_CON
        | ocf::ROTATE
        | ocf::ENTRANCE
        | ocf::COLLECTION
        | ocf::LINE_CONSTRUCT
        | ocf::ATTRACT_LIGHTNING
        | ocf::POWER_CONSUMER
        | ocf::POWER_SUPPLY
        | ocf::CONTAINER
        | ocf::FIGHT_READY);
    if metadata.constructable && construction < FULL_CON && rotation == 0 && !on_fire {
        mask |= ocf::CONSTRUCT;
    }
    if construction >= FULL_CON {
        mask |= ocf::FULL_CON;
    }
    if metadata.rotateable != 0 && construction > 100 {
        mask |= ocf::ROTATE;
    }
    if metadata
        .fire
        .entrance_rect
        .is_some_and(|rect| rect.width > 0 && rect.height > 0)
        && mask & ocf::FULL_CON != 0
        && (metadata.fire.rotated_entrance == 1 || rotation <= metadata.fire.rotated_entrance)
    {
        mask |= ocf::ENTRANCE;
    }
    if collection {
        mask |= ocf::COLLECTION;
    }
    if mask & ocf::FULL_CON != 0 && metadata.line_connect & !crate::LINE_CONNECT_ENERGY_HOLDER != 0
    {
        mask |= ocf::LINE_CONSTRUCT;
    }
    if metadata.fire.attract_lightning && mask & ocf::FULL_CON != 0 {
        mask |= ocf::ATTRACT_LIGHTNING;
    }
    if metadata.line_connect & crate::LINE_CONNECT_POWER_CONSUMER != 0 && mask & ocf::FULL_CON != 0
    {
        mask |= ocf::POWER_CONSUMER;
    }
    if (metadata.line_connect & crate::LINE_CONNECT_POWER_GENERATOR != 0
        || (metadata.line_connect & crate::LINE_CONNECT_POWER_OUTPUT != 0 && energy > 0))
        && mask & ocf::FULL_CON != 0
    {
        mask |= ocf::POWER_SUPPLY;
    }
    if metadata.grab_put_get & 3 != 0 || mask & ocf::ENTRANCE != 0 {
        mask |= ocf::CONTAINER;
    }
    if alive
        && category & crate::CATEGORY_LIVING != 0
        && !action_disabled
        && !metadata.fire.no_fight
    {
        mask |= ocf::FIGHT_READY;
    }
    mask &= !(ocf::IN_SOLID | ocf::IN_FREE | ocf::AVAILABLE);
    if container.is_none() {
        if solid_center {
            mask |= ocf::IN_SOLID;
        }
        if !semi_above {
            mask |= ocf::IN_FREE;
        }
    }
    if (container.is_none() || container_allows_get)
        && (!semi_above || (!solid_above && !semi_high))
    {
        mask |= ocf::AVAILABLE;
    }
    scope.cached_ocf = Some(mask);
    true
}

fn refresh_container_collection_ocf(context: &mut EffectHostContext, container: ObjectId) {
    let _ = refresh_live_object_ocf(context, container);
}

/// Direct `C4Object::Exit(x, y)` with absolute coordinates. Unlike the
/// script `Exit` wrapper, these receive no caller-relative or Shape.y
/// adjustment.
fn exit_object_at_position(target: ObjectId, position: Vector2) -> Result<bool, RuntimeError> {
    exit_object_at_position_with_calls(target, position, true)
}

fn live_object_bounds_shape(
    context: &EffectHostContext,
    target: ObjectId,
) -> Option<DefinitionRect> {
    if let Some(shape) = live_object_shape(context, target) {
        return Some(shape);
    }
    let object = context.get_world_object(target)?;
    let vertices = context
        .object_scope(target)
        .map(|scope| scope.vertices().to_vec())
        .unwrap_or_else(|| object.vertices.clone());
    host_vertex_bounds_rect(Vector2::ZERO, &vertices)
}

/// Exact world-space shape for a callback-live object. This is deliberately
/// separate from `WorldAccessor::object_shape_rect`, whose sector/legacy-At
/// contract includes `C4Object::addtop`.
fn effect_object_live_shape_rect(
    context: &EffectHostContext,
    object: &HostWorldObject,
) -> DefinitionRect {
    live_object_bounds_shape(context, object.id)
        .map(|shape| {
            DefinitionRect::new(
                object.position().x.saturating_add(shape.x),
                object.position().y.saturating_add(shape.y),
                shape.width,
                shape.height,
            )
        })
        .unwrap_or_else(|| DefinitionRect::new(object.position().x, object.position().y, 1, 1))
}

fn live_exit_layer_bounds(
    context: &EffectHostContext,
    target: ObjectId,
    horizontal: bool,
) -> Option<(i32, i32)> {
    let object = context.get_world_object(target)?;
    let definition_id = context.object_effective_definition_id(target)?;
    let metadata = context.definition_metadata(&definition_id)?;
    let (action_name, action_index) = context
        .object_scope(target)
        .map(|scope| (scope.effective_action_name(), scope.effective_action_index()))
        .unwrap_or((object.action_name.as_str(), object.action_index));
    let procedure = metadata
        .action_library
        .procedure_for_entry(action_name, action_index);
    if !metadata
        .action_library
        .is_idle_entry(action_name, action_index)
        && matches!(procedure, ActionProcedure::Attach)
    {
        return None;
    }

    let layer_id = context.object_layer(target)?;
    let layer = context.get_world_object(layer_id)?;
    let layer_definition_id = context.object_effective_definition_id(layer_id)?;
    let layer_metadata = context.definition_metadata(&layer_definition_id)?;
    if layer_metadata.border_bound & C4D_BORDER_LAYER == 0 {
        return None;
    }
    let object_shape = live_object_bounds_shape(context, target).unwrap_or_default();
    let layer_shape = live_object_bounds_shape(context, layer_id).unwrap_or_default();
    let is_static = object.category & crate::CATEGORY_STATIC_BACK != 0;
    let (layer_origin, layer_size, shape_offset) = if horizontal {
        (
            layer.position.x.saturating_add(layer_shape.x),
            layer_shape.width,
            object_shape.x,
        )
    } else {
        (
            layer.position.y.saturating_add(layer_shape.y),
            layer_shape.height,
            object_shape.y,
        )
    };
    let low = if is_static {
        layer_origin
    } else {
        layer_origin.saturating_sub(shape_offset)
    };
    let high = if is_static {
        layer_origin.saturating_add(layer_size)
    } else {
        layer_origin
            .saturating_add(layer_size)
            .saturating_add(shape_offset)
    };
    Some((low, high))
}

fn run_live_exit_bound_contact(target: ObjectId, cnat: u32) {
    let calls_enabled = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        let definition_id = context.object_effective_definition_id(target);
        let calls_enabled = definition_id
            .as_deref()
            .and_then(|id| context.definition_metadata(id))
            .is_some_and(|metadata| metadata.contact_function_calls);
        if !context.ensure_object_scope(target) {
            return false;
        }
        if let Some(scope) = context.object_scope_mut(target) {
            let component = if cnat == CNAT_LEFT || cnat == CNAT_RIGHT {
                VelocityComponent::X
            } else {
                VelocityComponent::Y
            };
            scope.set_fixed_velocity_component(component, C4Fixed::ZERO);
            return calls_enabled && scope.status() != ObjectStatus::Deleted;
        }
        false
    });
    if calls_enabled {
        if let Some(function) = crate::contact_callback_name(cnat) {
            let _ = call_object_own_fail_safe(target, function, &[]);
        }
    }
}

fn apply_live_exit_target_bounds(
    target: ObjectId,
    coordinate: &mut i32,
    low: i32,
    high: i32,
    low_cnat: u32,
    high_cnat: u32,
) {
    // These are deliberately independent, matching C4Object::TargetBounds.
    if *coordinate < low {
        *coordinate = low;
        run_live_exit_bound_contact(target, low_cnat);
    }
    if *coordinate > high {
        *coordinate = high;
        run_live_exit_bound_contact(target, high_cnat);
    }
}

fn bounds_check_live_exit(target: ObjectId, position: &mut Vector2) {
    let layer_side = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| live_exit_layer_bounds(context, target, true))
    });
    if let Some((low, high)) = layer_side {
        apply_live_exit_target_bounds(target, &mut position.x, low, high, CNAT_LEFT, CNAT_RIGHT);
    }

    let landscape_side = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let definition_id = context.object_effective_definition_id(target)?;
        let metadata = context.definition_metadata(&definition_id)?;
        if metadata.border_bound & C4D_BORDER_SIDES == 0 {
            return None;
        }
        let shape_x = live_object_bounds_shape(context, target)
            .map(|shape| shape.x)
            .unwrap_or(0);
        let width = i32::try_from(context.landscape_ref()?.width()).ok()?;
        Some((-shape_x, width.saturating_add(shape_x)))
    });
    if let Some((low, high)) = landscape_side {
        apply_live_exit_target_bounds(target, &mut position.x, low, high, CNAT_LEFT, CNAT_RIGHT);
    }

    let layer_vertical = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| live_exit_layer_bounds(context, target, false))
    });
    if let Some((low, high)) = layer_vertical {
        apply_live_exit_target_bounds(target, &mut position.y, low, high, CNAT_TOP, CNAT_BOTTOM);
    }

    let top = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let definition_id = context.object_effective_definition_id(target)?;
        let metadata = context.definition_metadata(&definition_id)?;
        if metadata.border_bound & C4D_BORDER_TOP == 0 {
            return None;
        }
        let shape_y = live_object_bounds_shape(context, target)
            .map(|shape| shape.y)
            .unwrap_or(0);
        Some((-shape_y, 1_000_000))
    });
    if let Some((low, high)) = top {
        apply_live_exit_target_bounds(target, &mut position.y, low, high, CNAT_TOP, CNAT_BOTTOM);
    }

    let bottom = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let definition_id = context.object_effective_definition_id(target)?;
        let metadata = context.definition_metadata(&definition_id)?;
        if metadata.border_bound & C4D_BORDER_BOTTOM == 0 {
            return None;
        }
        let shape_y = live_object_bounds_shape(context, target)
            .map(|shape| shape.y)
            .unwrap_or(0);
        let height = context.landscape_ref()?.estimated_height();
        Some((-1_000_000, height.saturating_add(shape_y)))
    });
    if let Some((low, high)) = bottom {
        apply_live_exit_target_bounds(target, &mut position.y, low, high, CNAT_TOP, CNAT_BOTTOM);
    }
}

fn exit_object_at_position_with_calls(
    target: ObjectId,
    position: Vector2,
    f_calls: bool,
) -> Result<bool, RuntimeError> {
    exit_object_at_position_with_motion_and_calls(
        target,
        position,
        FixedVec2::ZERO,
        C4Fixed::ZERO,
        f_calls,
    )
}

fn exit_object_at_position_with_motion_and_calls(
    target: ObjectId,
    position: Vector2,
    velocity: FixedVec2,
    rotation_velocity: C4Fixed,
    f_calls: bool,
) -> Result<bool, RuntimeError> {
    exit_object_at_position_with_full_motion_and_calls(
        target,
        position,
        0,
        velocity,
        rotation_velocity,
        f_calls,
    )
}

fn exit_object_at_position_with_full_motion_and_calls(
    target: ObjectId,
    mut position: Vector2,
    rotation: i32,
    velocity: FixedVec2,
    rotation_velocity: C4Fixed,
    f_calls: bool,
) -> Result<bool, RuntimeError> {
    let previous = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return None;
        };
        if !context.ensure_object_scope(target) {
            return None;
        }
        let previous = context.object_scope(target)?.container()?;
        context.track_contents_link_removal(previous, target);
        let scope = context.object_scope_mut(target)?;
        // Raw unlink first. Contained is null for BoundsCheck, but C++ does
        // not close the menu or refresh this object's OCF until afterward.
        scope.removed_contents_links.insert(previous);
        scope.current_container = None;
        scope.pending_update.container = Some(None);
        scope.reset_contained_compiler_cache();
        scope.pending_update.construction_preserves_fixed_position = false;
        scope.exit_bounds_in_progress = true;
        context.relink_content_after_exit(previous, target);
        refresh_container_collection_ocf(context, previous);
        Some(previous)
    });
    let Some(previous) = previous else {
        return Ok(false);
    };

    bounds_check_live_exit(target, &mut position);

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        let definition_metadata = context
            .object_effective_definition_id(target)
            .and_then(|id| context.definition_metadata(&id).cloned())
            .unwrap_or_default();
        let Some(scope) = context.object_scope_mut(target) else {
            return;
        };
        scope.exit_bounds_in_progress = false;
        // Exit assigns x/y even when unchanged and thereby snaps fix_x/y.
        scope.current_position = position;
        scope.current_fixed_position = FixedVec2::from_ints(position.x, position.y);
        scope.pending_update.position = Some(position);
        scope.pending_update.construction_preserves_fixed_position = false;
        scope.current_rotation = rotation;
        scope.current_fixed_rotation = itofix(rotation);
        scope.pending_update.rotation = Some(rotation);
        scope.set_fixed_velocity(velocity);
        scope.set_rotation_velocity(rotation_velocity);
        scope.set_mobile(true);
        scope.current_in_liquid = false;
        // Bounds callbacks may have opened a menu; Exit closes it afterward.
        scope.pending_update.menu = Some(None);
        // UpdateFace(true) rebuilds an ordinary C4Shape from Def after the
        // BoundsCheck callbacks consumed the old live SetShape rectangle.
        // Line shapes keep their independent geometry.
        if definition_metadata.line == 0 {
            scope.pending_update.shape_override = Some(None);
        }
        scope.refresh_shape_preview(&definition_metadata);
        // Pending native creations are already real objects to C++. Keep the
        // deferred SpawnConfig in the same post-Exit state so it can
        // materialize even when its likewise-pending container is removed
        // later in this call. The nested update still carries callback writes
        // that happen after this point.
        if let Some(spawn) = context
            .pending_spawns
            .iter_mut()
            .find(|spawn| spawn.id == Some(target))
        {
            spawn.container = None;
            spawn.position = position;
            spawn.fixed_position = None;
            spawn.rotation = rotation;
            spawn.fixed_rotation = None;
            spawn.velocity = Vector2::new(velocity.int_x(), velocity.int_y());
            spawn.fixed_velocity = Some(velocity);
            spawn.rotation_velocity = Some(rotation_velocity);
            spawn.mobile = Some(true);
            spawn.in_liquid = Some(false);
        }
    });
    HOST_CONTEXT.with(|cell| {
        if let Some(context) = cell.borrow_mut().as_mut() {
            // Exit's UpdateFace(true) updates the shape/solid mask before
            // SetOCF derives the final outside-container flags.
            context.update_live_solid_mask(target, false);
            let _ = refresh_live_object_ocf(context, target);
        }
    });

    if f_calls && object_has_status(previous) {
        call_object_own_fail_safe(previous, "Ejection", &[object_reference_value(target)]);
    }
    if f_calls && object_has_status(target) {
        call_object_own_fail_safe(target, "Departure", &[object_reference_value(previous)]);
    }
    Ok(HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(target))
            .is_some_and(|object| object.container().is_none())
    }))
}

/// C4Object::ClearContentsAndContained. C4ObjectList::Remove advances every
/// registered iterator that points at the removed link, and the C++ for-loop
/// then advances it once more. Track link generations so callback-driven
/// re-entry cannot make a new link alias the removed iterator position.
fn clear_contents_and_contained_live(target: ObjectId, f_calls: bool) -> Result<(), RuntimeError> {
    let initial_links = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Vec::new();
        };
        let Some(object) = context.get_world_object(target) else {
            return Vec::new();
        };
        object
            .contents()
            .iter()
            .copied()
            .map(|child| (child, context.contents_link_generation(child)))
            .collect::<Vec<_>>()
    });
    let mut iterator =
        crate::direct_com::RemovalSafeContentsIterator::new(target, &initial_links);
    loop {
        let links_and_position = HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let context = borrow.as_ref()?;
            let object = context.get_world_object(target)?;
            let links = object
                .contents()
                .iter()
                .copied()
                .map(|child| (child, context.contents_link_generation(child)))
                .collect::<Vec<_>>();
            Some((links, object.position))
        });
        let Some((links, position)) = links_and_position else {
            break;
        };
        let Some(child) = iterator.next(&links) else {
            break;
        };
        let _ = exit_object_at_position_with_calls(child, position, f_calls)?;
    }

    // C++ re-reads x/y after all content callbacks, so an Ejection or
    // Departure callback that moves the object affects its own later Exit.
    let contained_position = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let object = context.get_world_object(target)?;
        object.container().map(|_| object.position)
    });
    if let Some(position) = contained_position {
        let _ = exit_object_at_position_with_calls(target, position, f_calls)?;
    }
    Ok(())
}

/// Engine-internal exits normally retain the object's current coordinates.
fn exit_object_at_current_position(target: ObjectId) -> Result<bool, RuntimeError> {
    let position = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(target))
            .map(|object| object.position)
    });
    let Some(position) = position else {
        return Ok(false);
    };
    exit_object_at_position(target, position)
}

/// Live `C4Object::Enter(target)` without Collect's RejectCollect,
/// Collection and Hit tail. This is the path used by CreateContents and
/// Split2Components and must finish its callbacks before their next step.
fn enter_object_live(target: ObjectId, container: ObjectId) -> Result<bool, RuntimeError> {
    enter_object_live_with_calls(target, container, true)
}

/// C4Object::Enter's `fCalls` controls only Collection2/Entrance. The
/// RejectEntrance query, a transfer's ordinary callback-enabled Exit,
/// CopyMotion and base auto-sale all run in both modes.
fn enter_object_live_with_calls(
    target: ObjectId,
    container: ObjectId,
    f_calls: bool,
) -> Result<bool, RuntimeError> {
    enter_object_live_internal(target, container, f_calls, false, true)
}

/// ObjectComPut's Enter form supplies a non-null RejectCollect result
/// pointer. It shares the ordinary callback/copy-motion tail but inserts the
/// target query after cycle detection and before Exit (C4Object.cpp:1566-1636).
fn enter_object_live_with_reject_collect(
    target: ObjectId,
    container: ObjectId,
) -> Result<bool, RuntimeError> {
    enter_object_live_internal(target, container, true, true, true)
}

/// C4Object::Collect supplies RejectCollect but defers CopyMotion until after
/// Collection and Hit. All other C4Object::Enter state and callbacks are the
/// ordinary live path.
fn enter_object_live_for_collect(
    target: ObjectId,
    container: ObjectId,
) -> Result<bool, RuntimeError> {
    enter_object_live_internal(target, container, true, true, false)
}

fn enter_object_live_internal(
    target: ObjectId,
    container: ObjectId,
    f_calls: bool,
    reject_collect: bool,
    f_copy_motion: bool,
) -> Result<bool, RuntimeError> {
    // C4Object::Enter rejects null/self up front, but delays raw Status gates
    // until after RejectEntrance/RejectCollect and any old-container Exit.
    if target == container {
        return Ok(false);
    }
    if call_object_own_fail_safe(
        target,
        "RejectEntrance",
        &[object_reference_value(container)],
    )
    .as_bool()
    {
        return Ok(false);
    }

    let would_cycle = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return true;
        };
        let mut cursor = Some(container);
        let mut seen = HashSet::new();
        while let Some(current) = cursor {
            if current == target || !seen.insert(current) {
                return true;
            }
            cursor = context
                .get_world_object(current)
                .and_then(|object| object.container());
        }
        false
    });
    if would_cycle {
        return Ok(false);
    }

    if reject_collect {
        let definition_id = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.object_effective_definition_id(target))
        });
        let Some(definition_id) = definition_id else {
            return Ok(false);
        };
        if call_object_own_fail_safe(
            container,
            "RejectCollect",
            &[
                Value::C4Id(definition_id.to_string()),
                object_reference_value(target),
            ],
        )
        .as_bool()
        {
            return Ok(false);
        }
    }

    let contained = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(target))
            .and_then(|object| object.container())
            .is_some()
    });
    if contained && !exit_object_at_current_position(target)? {
        return Ok(false);
    }

    let entered = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        let definition_metadata = context
            .object_effective_definition_id(target)
            .and_then(|definition_id| context.definition_metadata(&definition_id).cloned())
            .unwrap_or_default();
        let target_ready = context.object_scope(target).is_some_and(|scope| {
            !scope.destroy
                && scope.status() != ObjectStatus::Deleted
                && scope.container().is_none()
        }) || context
            .get_world_object(target)
            .is_some_and(|object| object.is_present() && object.container().is_none());
        let container_motion = context
            .object_scope(container)
            .filter(|scope| !scope.destroy && scope.status() != ObjectStatus::Deleted)
            .map(|scope| {
                (
                    scope.effective_position(),
                    scope.fixed_velocity(),
                    scope.controller(),
                )
            })
            .or_else(|| {
                context
                    .get_world_object(container)
                    .filter(|object| object.is_present())
                    .map(|object| (object.position, object.fixed_velocity, object.controller()))
            });
        let Some((position, velocity, controller)) = container_motion else {
            return false;
        };
        if !target_ready || !context.ensure_object_scope(target) {
            return false;
        }
        let Some(scope) = context.object_scope_mut(target) else {
            return false;
        };
        // Enter closes an uncontained object's menu before linking it. A
        // transfer's Exit already did so, but the repeated close is harmless.
        scope.pending_update.menu = Some(None);
        scope.set_container(Some(container));
        if !(scope.alive() && scope.category() & crate::CATEGORY_LIVING != 0) {
            scope.set_controller(controller);
        }
        if f_copy_motion {
            let was_mobile = scope.mobile();
            // CopyMotion writes integer position/fix position and x/y dirs;
            // it intentionally leaves r/rdir untouched.
            scope.current_position = position;
            scope.current_fixed_position = FixedVec2::from_ints(position.x, position.y);
            scope.pending_update.position = Some(position);
            scope.pending_update.construction_preserves_fixed_position = false;
            scope.set_fixed_velocity(velocity);
            // CopyMotion does not mobilize; the generic fixed-dir update does,
            // so carry the pre-Enter native flag explicitly over that fold.
            scope.set_mobile(was_mobile);
        }
        let nonliving = !(scope.alive() && scope.category() & crate::CATEGORY_LIVING != 0);
        if let Some(spawn) = context
            .pending_spawns
            .iter_mut()
            .find(|spawn| spawn.id == Some(target))
        {
            spawn.container = Some(container);
            if f_copy_motion {
                spawn.position = position;
                spawn.fixed_position = None;
                spawn.fixed_velocity = Some(velocity);
            }
            if nonliving {
                spawn.controller = Some(controller);
            }
        }
        if f_copy_motion {
            // Native Enter removes the outside solid mask before CopyMotion,
            // so SetOCF at the destination cannot sample the object's own
            // old bake. No callback occurs during CopyMotion; removing here,
            // immediately before SetOCF, has the same observable ordering.
            context.update_live_solid_mask(target, false);
        }
        let _ = refresh_live_object_ocf(context, target);
        if let Some(scope) = context.object_scope_mut(target) {
            if definition_metadata.line == 0 {
                scope.pending_update.shape_override = Some(None);
            }
            scope.refresh_shape_preview(&definition_metadata);
        }
        context.update_live_solid_mask(target, false);
        refresh_container_collection_ocf(context, container);
        true
    });
    if !entered {
        return Ok(false);
    }

    if f_calls {
        call_object_own_fail_safe(container, "Collection2", &[object_reference_value(target)]);
        let entrance_container = HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let context = borrow.as_ref()?;
            let current = context.get_world_object(target)?.container()?;
            let current_live = context
                .get_world_object(current)
                .is_some_and(|object| object.is_present());
            let original_live = context
                .get_world_object(container)
                .is_some_and(|object| object.is_present());
            (current_live && original_live).then_some(current)
        });
        if let Some(current) = entrance_container {
            call_object_own_fail_safe(target, "Entrance", &[object_reference_value(current)]);
        }
    }
    auto_sell_after_enter(target, container)?;
    Ok(true)
}

/// `C4Effect::ClearAll(..., C4FxCall_RemoveClear)` for AssignRemoval.
/// Stop callbacks run from the tail of the effect list while the object is
/// still live; effects added by those callbacks are deleted afterwards
/// without receiving a Stop callback (C4Effect.cpp:407-425).
fn clear_effects_for_assign_removal(target: ObjectId) -> Result<bool, RuntimeError> {
    let effects = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Vec::new();
        };
        if !context.ensure_object_scope(target) {
            return Vec::new();
        }
        context
            .object_scope(target)
            .map(|scope| {
                scope
                    .effects
                    .snapshot()
                    .into_iter()
                    .filter(|effect| effect.priority != 0)
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default()
    });
    for effect in effects.into_iter().rev() {
        let marked_dead = HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(scope) = borrow
                .as_mut()
                .and_then(|context| context.object_scope_mut(target))
            else {
                return false;
            };
            let Some(live) = scope
                .effects
                .effects
                .iter_mut()
                .find(|live| live.number == effect.number && live.priority != 0)
            else {
                return false;
            };
            live.priority = 0;
            true
        });
        if marked_dead {
            let function = format!("Fx{}Stop", effect.name);
            let stop_result = dispatch_effect_fx_callback_fail_safe(
                &effect,
                &function,
                &[
                    object_reference_value(target),
                    Value::Int(effect.number),
                    Value::Int(3),
                ],
            );
            if !object_is_present(target) {
                return Ok(false);
            }
            if stop_result == -1 {
                HOST_CONTEXT.with(|cell| {
                    let mut borrow = cell.borrow_mut();
                    let Some(scope) = borrow
                        .as_mut()
                        .and_then(|context| context.object_scope_mut(target))
                    else {
                        return;
                    };
                    if let Some(live) = scope
                        .effects
                        .effects
                        .iter_mut()
                        .find(|live| live.number == effect.number && live.priority == 0)
                    {
                        live.priority = effect.priority;
                    }
                });
            }
        }
    }

    loop {
        let removed = HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(scope) = borrow
                .as_mut()
                .and_then(|context| context.object_scope_mut(target))
            else {
                return false;
            };
            let Some(number) = scope.effects.effects.first().map(|effect| effect.number) else {
                return false;
            };
            scope.effects.unlink_effect_by_number(number)
        });
        if !removed {
            break;
        }
    }
    Ok(true)
}

/// `C4Object::AssignRemoval` sets Status=0 before killing contents, but it
/// deliberately keeps Info, object references and the solid mask alive until
/// after contents and containment have been cleaned up (C4Object.cpp:276-313).
fn mark_object_status_deleted(context: &mut EffectHostContext, target: ObjectId) -> bool {
    if !context.ensure_object_scope(target) {
        return false;
    }
    if let Some(scope) = context.object_scope_mut(target) {
        scope.mark_destroy_status();
        true
    } else {
        false
    }
}

fn retire_object_info_and_clear_references(
    context: &mut EffectHostContext,
    target: ObjectId,
    last_position: Option<Vector2>,
) {
    let link = context
        .object_scope(target)
        .and_then(ObjectScopeContext::info_link);
    if let Some(link) = link {
        if retire_host_crew_info(context, link) {
            context.record_player_command(PlayerCommand::RetireCrewInfo {
                object_id: target,
                link,
            });
        }
    }
    if let Some(scope) = context.object_scope_mut(target) {
        scope.clear_info_for_removal();
    }
    context.clear_non_player_script_object_references(target, last_position);
}

fn assign_removal_live(target: ObjectId, exit_contents: bool) -> Result<bool, RuntimeError> {
    // C4Object::AssignRemoval gates on raw Status truthiness. Inactive is a
    // live nonzero status and is activated internally before deletion.
    if !object_has_status(target) {
        return Ok(false);
    }
    let container = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(target))
            .and_then(|object| object.container())
    });
    if let Some(container) = container.filter(|container| object_has_status(*container)) {
        call_object_own_fail_safe(
            container,
            "ContentsDestruction",
            &[object_reference_value(target)],
        );
        if !object_has_status(target) {
            return Ok(true);
        }
    }
    call_object_own_fail_safe(target, "Destruction", &[]);
    if !object_has_status(target) {
        return Ok(true);
    }
    if !clear_effects_for_assign_removal(target)? {
        return Ok(true);
    }

    // Particle lists are cleared before SetAction(ActIdle), while the object
    // is still live (C4Object.cpp:268-274).
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        if let Some(context) = borrow.as_mut() {
            context.register_particle(ParticleCommand::Clear {
                definition_id: None,
                scope: ParticleScope::Object(target),
            });
        }
    });
    let _ = native_set_action_by_name(target, "Idle")?;
    if !object_has_status(target) {
        return Ok(true);
    }

    // AssignRemoval(true) passes the removed container's x/y to every
    // direct child's Exit (C4Object.cpp:285-288).
    let exit_position = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| {
                context
                    .object_scope(target)
                    .map(|scope| scope.current_position)
                    .or_else(|| {
                        context
                            .get_world_object(target)
                            .map(|object| object.position)
                    })
            })
    });

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        mark_object_status_deleted(context, target);
    });

    loop {
        let child = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.get_world_object(target))
                .and_then(|object| object.contents().first().copied())
        });
        let Some(child) = child else { break };
        if exit_contents {
            let Some(position) = exit_position else { break };
            if !exit_object_at_position(child, position)? {
                break;
            }
            continue;
        }
        HOST_CONTEXT.with(|cell| {
            if let Some(context) = cell.borrow_mut().as_mut() {
                context.unlink_content_for_removal(target, child);
            }
        });
        // AssignRemoval's default `fExitContents=false` unlinks and
        // recursively removes contents without Ejection/Departure calls.
        // The child's Contained pointer remains observable during its own
        // Destruction callback even though the parent is already dead.
        let _ = assign_removal_live(child, false)?;
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        let removed_from = context
            .object_scope(target)
            .and_then(ObjectScopeContext::container);
        context.set_object_container_tracked(target, None);
        if let Some(container) = removed_from {
            // AssignRemoval removes the child's link, then UpdateMass and
            // SetOCF on the surviving parent (C4Object.cpp:297-305).
            refresh_container_collection_ocf(context, container);
        }
        retire_object_info_and_clear_references(context, target, exit_position);
    });
    clear_player_object_pointers_host(target);
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        if let Some(context) = borrow.as_mut() {
            // pSolidMaskData->Remove is the last modeled AssignRemoval side
            // arm, after Game.ClearPointers (C4Object.cpp:309-313).
            context.update_live_solid_mask(target, false);
        }
    });
    Ok(true)
}

fn can_sell_object_live(target: ObjectId, player: i32) -> bool {
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        let player_active = context
            .player_state(player)
            .is_some_and(|state| {
                !matches!(
                    state.status,
                    crate::PlayerStatus::Eliminated | crate::PlayerStatus::Surrendered
                ) && !state.surrendered
            });
        player_active
            && context
                .get_world_object(target)
                .is_some_and(|object| object.is_present() && object.ocf() & ocf::CREW_MEMBER == 0)
    })
}

fn sync_homebase_material_to_team_live(player: i32) {
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        if !context.team_home_base_rule() {
            return;
        }
        let Some((team, material)) = context.player_state(player).and_then(|state| {
            state
                .team
                .map(|team| (team, state.exact_home_base_material_entries()))
        }) else {
            return;
        };
        let teammates = context
            .player_ids()
            .iter()
            .copied()
            .filter(|candidate| {
                *candidate != player
                    && context.player_state(*candidate).and_then(|state| state.team) == Some(team)
            })
            .collect::<Vec<_>>();
        for teammate in teammates {
            if let Some(state) = context.player_state_mut(teammate) {
                state.set_home_base_material_entries(material.clone());
            }
        }
        context.record_player_command(PlayerCommand::SyncHomeBaseMaterialToTeam {
            player_id: player,
        });
    });
}

pub(super) fn sell_object_to_home_live(
    target: ObjectId,
    player: i32,
) -> Result<bool, RuntimeError> {
    if !can_sell_object_live(target, player) {
        return Ok(false);
    }

    loop {
        let child = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| first_retained_content(context, target))
        });
        let Some(child) = child else { break };
        let container = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.get_world_object(target))
                .and_then(|object| object.container())
        });
        let _ = match container {
            Some(container) => enter_object_live(child, container)?,
            None => exit_object_at_current_position(child)?,
        };
        let _ = sell_object_to_home_live(child, player)?;
    }

    // Sell2Home prices the object against its live containing base. Direct
    // Sell calls reach this path before Exit, unlike the base-auto-sell path.
    let base = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(target))
            .and_then(|object| object.container())
    });
    let value = match get_value(&[
        object_reference_value(target),
        Value::Nil,
        base.map(object_reference_value).unwrap_or(Value::Nil),
        Value::Int(player),
    ]) {
        Ok(Value::Int(value)) => value,
        Ok(_) => 0,
        Err(error) => {
            tracing::warn!(%error, "CalcValue failed during home-base sale; using zero");
            0
        }
    };
    // C4Player::DoWealth clamps adjustments to 0..=10000; FnSetWealth's
    // wider 100000 ceiling does not apply to a home-base sale.
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        let updated = {
            let Some(state) = context.player_state_mut(player) else {
                return;
            };
            let updated = (i64::from(state.wealth) + i64::from(value)).clamp(0, 10_000) as i32;
            state.wealth = updated;
            state.view_wealth = 100;
            updated
        };
        context.record_player_command(PlayerCommand::SetWealth {
            player_id: player,
            value: updated,
            show_change: true,
        });
    });

    let original_definition = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_effective_definition_id(target))
    });
    let stock_definition =
        match call_world_object_own_function(target, "SellTo", &[Value::Int(player)]) {
            Some(Ok(Value::C4Id(id))) => {
                definition_id_for_c4id(&id).map(|id| DefinitionId::from(id.as_str()))
            }
            Some(Ok(Value::Int(raw @ 1..=9999))) => {
                Some(DefinitionId::from(format!("{raw:04}").as_str()))
            }
            Some(Ok(_)) => None,
            None => original_definition,
            Some(Err(error)) => {
                tracing::warn!(%error, "SellTo failed during home-base sale; omitting stock");
                None
            }
        };
    if let Some(definition) = stock_definition {
        let (valid_definition, should_stock) = HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let Some(context) = borrow.as_ref() else {
                return (false, false);
            };
            let valid_definition =
                context.world.definition_known(definition.as_str()) != Some(false);
            let should_stock = valid_definition
                && (context.world.definition_rebuyable(definition.as_str())
                    || context
                        .player_state(player)
                        .is_some_and(|state| state.home_base_material.contains_key(&definition)));
            (valid_definition, should_stock)
        });
        if should_stock {
            let _ = do_homebase_material(&[
                Value::Int(player),
                Value::C4Id(definition.as_str().to_owned()),
                Value::Int(1),
            ])?;
        } else if valid_definition {
            sync_homebase_material_to_team_live(player);
        }
    }

    let contained = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(target))
            .is_some_and(|object| object.container().is_some())
    });
    if contained && object_is_present(target) {
        let _ = exit_object_at_position(target, Vector2::ZERO)?;
    }
    if object_is_present(target) {
        call_object_own_fail_safe(target, "Sale", &[Value::Int(player)]);
    }
    if object_is_present(target) {
        let _ = assign_removal_live(target, true)?;
    }
    Ok(true)
}

fn report_buy_error(
    player: i32,
    message: String,
    target: Option<ObjectId>,
) -> Result<(), RuntimeError> {
    let _ = player_message(&[Value::Int(player), Value::String(message.into())])?;
    HOST_CONTEXT.with(|cell| {
        if let Some(context) = cell.borrow_mut().as_mut() {
            context
                .audio_mut()
                .play_sound("Error", target, 100, false, false, None);
        }
    });
    Ok(())
}

/// FnBuy (C4Script.cpp:3732-3751) plus C4Player::Buy
/// (C4Player.cpp:826-864): synchronously consume the paying player's base
/// stock and wealth, create the item for another player, call Purchase, then
/// enter an explicit target or force-position at the calling object.
pub(super) fn buy(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 5 {
        return Err(RuntimeError::new(
            "Buy expects at most 5 arguments: definition, for_player, pay_player, target, show_errors",
        ));
    }
    let Some(definition) = parse_native_c4id_argument(args.first(), "Buy")? else {
        return Ok(Value::Nil);
    };
    let for_player = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "Buy", "for_player")?;
    let pay_player = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "Buy", "pay_player")?;
    let to_base =
        parse_object_reference_argument(args.get(3).unwrap_or(&Value::Nil), "Buy", "target")?;
    let show_errors = value_to_bool(args.get(4).unwrap_or(&Value::Nil), "Buy", "show_errors")?;
    let caller = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.script_object_context)
    });
    let creator = to_base.or(caller);
    let definition_id = DefinitionId::from(definition.as_str());

    let initial = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return None;
        };
        // ValidPlr accepts eliminated players; C4Player::Buy reports that
        // state separately below.
        context.player_state(for_player)?;
        let payer = context.player_state(pay_player)?;
        let eliminated = matches!(
            payer.status,
            crate::PlayerStatus::Eliminated | crate::PlayerStatus::Surrendered
        ) || payer.surrendered;
        let available = payer
            .exact_home_base_material_entries()
            .into_iter()
            .find_map(|(id, count)| (id == definition_id).then_some(count))
            .unwrap_or(0);
        let crew_member = context
            .definition_metadata(&definition)
            .map(|metadata| metadata.crew_member);
        Some((eliminated, payer.name.clone(), available, crew_member))
    });
    let Some((eliminated, payer_name, available, crew_member)) = initial else {
        return Ok(Value::Nil);
    };
    if eliminated {
        if show_errors {
            report_buy_error(
                pay_player,
                format!("Player {payer_name}|eliminated."),
                creator,
            )?;
        }
        return Ok(Value::Nil);
    }
    // C4Player::Buy checks stock before resolving the definition. Neither an
    // unavailable item nor an unknown definition produces an error message.
    if available <= 0 {
        return Ok(Value::Nil);
    }
    let Some(crew_member) = crew_member else {
        return Ok(Value::Nil);
    };

    let Some(price) = calculated_definition_value(&definition, creator, pay_player)? else {
        return Ok(Value::Nil);
    };

    // CalcDefValue/CalcBuyValue callbacks above can mutate both wealth and
    // stock. C++ compares/decrements the live values after those callbacks,
    // while retaining only the initial availability decision.
    let charged = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        let Some(current_wealth) = context.player_state(pay_player).map(|payer| payer.wealth)
        else {
            return false;
        };
        if price > current_wealth {
            return false;
        }

        let (team, updated_material, updated_wealth) = {
            let Some(payer) = context.player_state_mut(pay_player) else {
                return false;
            };
            payer.adjust_home_base_material_entry(definition_id.clone(), -1);
            let updated_wealth =
                (i64::from(payer.wealth) - i64::from(price)).clamp(0, 10_000) as i32;
            payer.wealth = updated_wealth;
            payer.view_wealth = 100;
            (
                payer.team,
                payer.exact_home_base_material_entries(),
                updated_wealth,
            )
        };

        if context.team_home_base_rule() {
            if let Some(team) = team {
                let teammates: Vec<i32> = context
                    .player_ids()
                    .iter()
                    .copied()
                    .filter(|other| {
                        *other != pay_player
                            && context.player_state(*other).and_then(|player| player.team)
                                == Some(team)
                    })
                    .collect();
                for teammate in teammates {
                    if let Some(player) = context.player_state_mut(teammate) {
                        player.set_home_base_material_entries(updated_material.clone());
                    }
                }
            }
        }
        context.record_player_command(PlayerCommand::AdjustHomeBaseMaterial {
            player_id: pay_player,
            definition_id: definition_id.clone(),
            delta: -1,
        });
        context.record_player_command(PlayerCommand::SetWealth {
            player_id: pay_player,
            value: updated_wealth,
            show_change: true,
        });
        true
    });
    if !charged {
        if show_errors {
            report_buy_error(pay_player, "Not enough money!".to_string(), creator)?;
        }
        return Ok(Value::Nil);
    }

    let Some(created) = create_native_object(NativeObjectCreation {
        definition: definition.clone(),
        creator,
        owner: for_player,
        controller: for_player,
        construction: FULL_CON,
        position: Vector2::new(50, 50),
        rotation: 0,
        velocity: FixedVec2::ZERO,
        rotation_velocity: C4Fixed::ZERO,
    })?
    else {
        return Ok(Value::Nil);
    };

    if crew_member {
        let _ = make_crew_member_live(created, for_player)?;
    }
    if !object_is_present(created) {
        return Ok(Value::Nil);
    }
    call_object_own_fail_safe(
        created,
        "Purchase",
        &[
            Value::Int(pay_player),
            creator.map(object_reference_value).unwrap_or(Value::Nil),
        ],
    );
    if !object_is_present(created) {
        return Ok(Value::Nil);
    }

    if let Some(to_base) = to_base {
        let _ = enter_object_live(created, to_base)?;
    } else if let Some(caller) = caller {
        let caller_position = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.get_world_object(caller))
                .map(|object| object.position())
        });
        if let Some(position) = caller_position {
            let _ = set_position(&[
                Value::Int(position.x),
                Value::Int(position.y),
                object_reference_value(created),
            ])?;
        }
    }
    Ok(object_reference_value(created))
}

/// FnSell (C4Script.cpp:3753-3760): a nil object means the executing
/// script object; a valid player then runs the complete Sell2Home path.
fn sell(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "Sell expects at most 2 arguments: player, object",
        ));
    }
    let player = value_to_i32(args.first().unwrap_or(&Value::Nil), "Sell", "player")?;
    let explicit =
        parse_object_reference_argument(args.get(1).unwrap_or(&Value::Nil), "Sell", "object")?;
    let target = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| explicit.or(context.script_object_context))
    });
    let Some(target) = target else {
        return Ok(Value::Bool(false));
    };
    Ok(Value::Bool(sell_object_to_home_live(target, player)?))
}

fn auto_sell_after_enter(
    entering: ObjectId,
    original_target: ObjectId,
) -> Result<(), RuntimeError> {
    let sale = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        if !context.world.base_auto_sell_enabled
            || !context
                .get_world_object(original_target)
                .is_some_and(|object| object.is_present())
        {
            return None;
        }
        let container = context.get_world_object(entering)?.container()?;
        let container_state = context.get_world_object(container)?;
        if !container_state.is_present() {
            return None;
        }
        let base = container_state.full_state()?.base;
        context.player_state(base).map(|_| (container, base))
    });
    let Some((container, player)) = sale else {
        return Ok(());
    };
    let outer = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(container))
            .map(|object| object.contents().to_vec())
            .unwrap_or_default()
    });
    for object in outer {
        let nested = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.get_world_object(object))
                .map(|object| object.contents().to_vec())
                .unwrap_or_default()
        });
        for child in nested {
            let auto_sell = HOST_CONTEXT.with(|cell| {
                let borrow = cell.borrow();
                let Some(context) = borrow.as_ref() else {
                    return false;
                };
                context
                    .object_effective_definition_id(child)
                    .is_some_and(|id| context.world.definition_base_auto_sell(id.as_str()))
            });
            if auto_sell && can_sell_object_live(child, player) {
                let _ = exit_object_at_current_position(child)?;
                let _ = sell_object_to_home_live(child, player)?;
            }
        }
        let auto_sell = HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let Some(context) = borrow.as_ref() else {
                return false;
            };
            context
                .object_effective_definition_id(object)
                .is_some_and(|id| context.world.definition_base_auto_sell(id.as_str()))
        });
        if auto_sell && can_sell_object_live(object, player) {
            let _ = exit_object_at_current_position(object)?;
            let _ = sell_object_to_home_live(object, player)?;
        }
    }
    Ok(())
}

/// FnEnter (C4Script.cpp:365-370): pObj (or the scope object) enters the
/// container pTarget through the synchronous C4Object::Enter pipeline.
fn enter(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some(target) =
        parse_object_reference_argument(args.first().unwrap_or(&Value::Nil), "Enter", "target")?
    else {
        return Ok(Value::Bool(false)); // C4Object::Enter(nullptr)
    };
    let subject =
        parse_object_reference_argument(args.get(1).unwrap_or(&Value::Nil), "Enter", "obj")?;
    let active = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_context().map(|object| object.id()))
    });
    let Some(subject) = subject.or(active) else {
        return Ok(Value::Bool(false));
    };
    Ok(Value::Bool(enter_object_live(subject, target)?))
}

/// FnCollect (C4Script.cpp:391-415) routes through C4Object::Collect:
/// validate the collector's cached OCF, run Enter's two vetoes and callback
/// tail synchronously, then Collection/Hit before the final CopyMotion
/// (C4Object.cpp:1566-1636,5693-5714). This must stay a live host operation,
/// rather than a deferred container assignment: MFBL collects a same-call
/// freshly-created FRBL and branches on the boolean result.
pub(crate) fn flag_collection_blocked(
    definition_id: &str,
    action_name: &str,
    flag_removeable: bool,
) -> bool {
    !flag_removeable && definition_id == "FLAG" && action_name == "FlyBase"
}

struct CollectDelayRestore {
    collector: ObjectId,
    old_delay: i32,
}

impl Drop for CollectDelayRestore {
    fn drop(&mut self) {
        if self.old_delay == 0 {
            return;
        }
        HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(scope) = borrow
                .as_mut()
                .and_then(|context| context.object_scope_mut(self.collector))
            else {
                return;
            };
            scope.restore_no_collect_delay(self.old_delay);
        });
    }
}

fn collect(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some(item) =
        parse_object_reference_argument(args.first().unwrap_or(&Value::Nil), "Collect", "item")?
    else {
        return Ok(Value::Bool(false));
    };
    let explicit_collector = parse_object_reference_argument(
        args.get(1).unwrap_or(&Value::Nil),
        "Collect",
        "collector",
    )?;
    let active = active_object_id();
    let Some(collector) = explicit_collector.or(active) else {
        return Ok(Value::Bool(false));
    };
    if item == collector {
        return Ok(Value::Bool(false));
    }

    let (ready, old_no_collect_delay) = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return (false, 0);
        };
        let item_ready = context
            .get_world_object(item)
            .is_some_and(|object| object.is_present());
        let collector_state = context.get_world_object(collector);
        let collector_present = collector_state
            .as_ref()
            .is_some_and(HostWorldObject::is_present);
        if !collector_present || !context.ensure_object_scope(collector) {
            return (false, 0);
        }
        let old_no_collect_delay = context
            .object_scope(collector)
            .map(ObjectScopeContext::no_collect_delay)
            .unwrap_or(0);
        // FnCollect trusts the existing cached OCF when the delay is already
        // zero. Only a nonzero delay is cleared and followed by UpdateOCF.
        if old_no_collect_delay != 0 {
            if let Some(scope) = context.object_scope_mut(collector) {
                scope.set_no_collect_delay(0);
            }
            let _ = refresh_live_object_ocf(context, collector);
        }
        let collector_ready = collector_present
            && context
                .object_scope(collector)
                .is_some_and(|scope| scope.ocf() & ocf::COLLECTION != 0);
        (item_ready && collector_ready, old_no_collect_delay)
    });
    // Restore on every success, veto, error and early return after the
    // temporary clear. C++ performs this after Collect returns, even when it
    // failed (C4Script.cpp:410-413).
    let _delay_restore = CollectDelayRestore {
        collector,
        old_delay: old_no_collect_delay,
    };
    if !ready {
        return Ok(Value::Bool(false));
    }

    // C4Object::Collect's first operation: an attached base flag is not
    // collectable without cached C4RULE_FlagRemoveable. FnCollect's
    // temporary NoCollectDelay/OCF work above deliberately precedes this
    // native gate (C4Script.cpp:391-413; C4Object.cpp:5693-5700).
    let blocked_flag = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        context.get_world_object(item).is_some_and(|item| {
            flag_collection_blocked(
                item.definition_id(),
                item.action_name(),
                context.world.flag_removeable(),
            )
        })
    });
    if blocked_flag {
        return Ok(Value::Bool(false));
    }

    let call_fail_safe = |target, function: &str, pars: &[Value]| -> Value {
        match call_world_object_own_function(target, function, pars) {
            Some(Ok(value)) => value,
            Some(Err(error)) => {
                tracing::warn!(
                    %error,
                    object = target.as_u64(),
                    callback = function,
                    "script error in Collect callback; continuing like C++ fail-safe Call"
                );
                Value::Nil
            }
            None => Value::Nil,
        }
    };

    // Collect uses the ordinary Enter lifecycle and RejectCollect query, but
    // passes fCopyMotion=false so Collection2/Entrance/Collection/Hit observe
    // the item's post-Exit motion. Its own tail copies collector motion later.
    if !enter_object_live_for_collect(item, collector)? {
        return Ok(Value::Bool(false));
    }

    // C4Object::Collect cancels an ATTACH procedure before Collection. Use
    // ObjectSetAction so Start/Abort calls remain synchronous like C++
    // ObjectComCancelAttach -> SetAction(ActIdle) (C4ObjectCom.cpp:769-774).
    let attached = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        context
            .object_scope(item)
            .map(ObjectScopeContext::effective_action_procedure)
            .or_else(|| {
                context
                    .get_world_object(item)
                    .and_then(|object| object.procedure_name().map(ActionProcedure::from_name))
            })
            == Some(ActionProcedure::Attach)
    });
    if attached {
        let _ = object_set_action(&[
            object_reference_value(item),
            Value::String("Idle".into()),
        ])?;
    }

    call_fail_safe(collector, "Collection", &[object_reference_value(item)]);
    for (flag, function) in [
        (ocf::HIT_SPEED1, "Hit"),
        (ocf::HIT_SPEED2, "Hit2"),
        (ocf::HIT_SPEED3, "Hit3"),
    ] {
        // Native rereads both Status and OCF before every callback; an
        // earlier Hit may delete the item or synchronously change later
        // hit-speed flags.
        let should_call = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.get_world_object(item))
                .is_some_and(|object| object.is_present() && object.ocf() & flag != 0)
        });
        if should_call {
            call_fail_safe(item, function, &[]);
        }
    }

    // Hit observes the pre-copy item motion. Only afterwards, and only if
    // callbacks left it in this collector, CopyMotion snaps position and
    // fixed dirs to the collector (C4Object.cpp:5711-5713;
    // C4Movement.cpp:518-529).
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        let still_collected = context
            .get_world_object(item)
            .is_some_and(|object| object.is_present() && object.container() == Some(collector));
        if !still_collected {
            return;
        }
        let Some(collector_state) = context.get_world_object(collector) else {
            return;
        };
        let position = context
            .object_scope(collector)
            .map(ObjectScopeContext::effective_position)
            .unwrap_or(collector_state.position);
        let velocity = context
            .object_scope(collector)
            .map(ObjectScopeContext::fixed_velocity)
            .unwrap_or(collector_state.fixed_velocity);
        let Some(scope) = context.object_scope_mut(item) else {
            return;
        };
        let was_mobile = scope.mobile();
        scope.set_position(position);
        scope.set_fixed_velocity(velocity);
        // Native CopyMotion writes x/y and xdir/ydir without changing Mobile.
        scope.set_mobile(was_mobile);
    });

    // FnCollect restores the old positive NoCollectDelay but deliberately
    // does not call UpdateOCF again (:412-413). Preserve the cache left by
    // the temporary recompute/Enter callbacks after the deferred outcome
    // fold performs its ordinary container refresh.
    if old_no_collect_delay != 0 {
        HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(context) = borrow.as_mut() else {
                return;
            };
            if context.ensure_object_scope(collector) {
                if let Some(scope) = context.object_scope_mut(collector) {
                    let ocf = scope.ocf();
                    scope.pending_update.ocf_override = Some(ocf);
                }
            }
        });
    }

    Ok(Value::Bool(true))
}

/// FnGrabContents (C4Script.cpp:320-327) and C4Object::GrabContents
/// (C4Object.cpp:6162-6171): pTo defaults to the calling object, the source
/// list is copied before any moves, and every still-live entry attempts a
/// regular Enter(pTo). Individual failures do not change the true return.
fn grab_contents(args: &[Value]) -> Result<Value, RuntimeError> {
    let from = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "GrabContents",
        "from",
    )?;
    let Some(from) = from else {
        return Ok(Value::Bool(false));
    };
    let explicit_to =
        parse_object_reference_argument(args.get(1).unwrap_or(&Value::Nil), "GrabContents", "to")?;
    let active = active_object_id();
    let Some(to) = explicit_to.or(active) else {
        return Ok(Value::Bool(false));
    };
    if to == from {
        return Ok(Value::Bool(false));
    }

    // An explicit foreign destination becomes the call context just like
    // FnGrabContents' pTo default would have been that object. This also
    // lets object-arrow calls operate on freshly created pending objects.
    if Some(to) != active {
        return match call_world_object_function(to, "GrabContents", &[object_reference_value(from)])
        {
            Some(result) => result,
            None => Ok(Value::Bool(false)),
        };
    }

    let contents = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return None;
        };
        // A C4Value object reference can only supply live engine objects.
        context.get_world_object(to)?;
        context
            .get_world_object(from)
            .map(|source| source.contents().to_vec())
    });
    let Some(contents) = contents else {
        return Ok(Value::Bool(false));
    };

    // C4Object::GrabContents snapshots the list, then invokes the ordinary
    // C4Object::Enter path for every still-live link. Reuse the live Enter
    // seam so transfers receive their complete Exit/CopyMotion/OCF/face and
    // callback lifecycle instead of maintaining another partial duplicate.
    for child in contents {
        // GrabContents' copied-list loop owns this raw Status check. Enter
        // itself deliberately performs its status gates only after callbacks
        // and an old-container Exit.
        if object_has_status(child) {
            let _ = enter_object_live(child, to)?;
        }
    }

    Ok(Value::Bool(true))
}

/// FnExit (C4Script.cpp:372-388): pObj (or the scope object) leaves its
/// container via C4Object::Exit. The optional tx/ty are CALLER-relative
/// (`tx += cthr->Obj->x`, :377-381), tr == -1 draws Random(360) (:382),
/// and Exit writes position/rotation/dirs unconditionally — bare Exit()
/// re-places the object at the caller's position with r = 0 and zeroed
/// dirs (C4Object.cpp:1549-1553), the y target offset by the SUBJECT's
/// Shape.y (:385) and rdir scaled `itofix(trdir) / 10` (:388).
/// ObjectComCancelAttach changes an ATTACH action to Idle (including its
/// AbortCall) before Exit checks containment. Exit unlinks, runs BoundsCheck,
/// installs final state, dispatches Ejection then Departure synchronously and
/// returns the live post-callback `!Contained` state (C4Object.cpp:1532-1563).
fn exit_container(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 7 {
        return Err(RuntimeError::new(
            "Exit expects at most 7 arguments: obj, x, y, r, xdir, ydir, rdir",
        ));
    }
    let subject =
        parse_object_reference_argument(args.first().unwrap_or(&Value::Nil), "Exit", "obj")?;
    let tx = parse_optional_i32(args.get(1), "Exit", "x")?.unwrap_or(0);
    let ty = parse_optional_i32(args.get(2), "Exit", "y")?.unwrap_or(0);
    let tr = parse_optional_i32(args.get(3), "Exit", "r")?.unwrap_or(0);
    let txdir = parse_optional_i32(args.get(4), "Exit", "xdir")?.unwrap_or(0);
    let tydir = parse_optional_i32(args.get(5), "Exit", "ydir")?.unwrap_or(0);
    let trdir = parse_optional_i32(args.get(6), "Exit", "rdir")?.unwrap_or(0);
    let prepared = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(None);
        };
        let active = context.object_context().map(|object| object.id());
        let Some(target) = subject.or(active) else {
            return Ok(None); // no pObj and no scope object
        };
        // Caller-relative offset: the CALLING object, also for foreign
        // subjects (C4Script.cpp:377-381).
        let (mut abs_x, mut abs_y) = (tx, ty);
        if let Some(caller) = context.object_context() {
            let position = caller.effective_position();
            abs_x = abs_x.saturating_add(position.x);
            abs_y = abs_y.saturating_add(position.y);
        }
        // The Random(360) draw happens before the contained check — it
        // runs even when Exit then fails (C4Script.cpp:382).
        let rotation = if tr == -1 {
            draw_context_random(360)?
        } else {
            tr
        };
        Ok(Some((target, abs_x, abs_y, rotation)))
    })?;
    let Some((target, abs_x, abs_y, rotation)) = prepared else {
        return Ok(Value::Bool(false));
    };

    // ObjectComCancelAttach runs after the optional rotation draw but before
    // C4Object::Exit checks Contained. SetAction(ActIdle) is a native call:
    // a script function named SetAction may not intercept it, and the old
    // ATTACH action's AbortCall observes the pre-Exit position/container.
    let attached = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        context
            .object_scope(target)
            .map(ObjectScopeContext::effective_action_procedure)
            .or_else(|| {
                context
                    .get_world_object(target)
                    .and_then(|object| object.procedure_name().map(ActionProcedure::from_name))
            })
            == Some(ActionProcedure::Attach)
    });
    if attached {
        let _ = native_set_action_by_name(target, "Idle")?;
    }

    // The SUBJECT's live Shape.y (C4Script.cpp:385): a same-call SetShape
    // override wins over the def shape. Read it only after the attach
    // AbortCall, which may change the shape or definition.
    let shape_y = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        Some(
            live_object_shape(context, target)
                .map(|shape| shape.y)
                .unwrap_or(0),
        )
    });
    let Some(shape_y) = shape_y else {
        return Ok(Value::Bool(false));
    };
    let exited = exit_object_at_position_with_full_motion_and_calls(
        target,
        Vector2::new(abs_x, abs_y.saturating_add(shape_y)),
        rotation,
        FixedVec2::new(itofix(txdir), itofix(tydir)),
        itofix(trdir) / 10,
        true,
    )?;
    Ok(Value::Bool(exited))
}

/// FnSetComponent (C4Script.cpp:2659-2663): sets the component count on
/// pObj or the scope object (C4IDList::SetIDCount with fAddNewID — the
/// entry persists even at zero). Foreign subjects route through the seam.
fn set_component(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some(component) = parse_native_c4id_argument(args.first(), "SetComponent")? else {
        return Ok(Value::Bool(false));
    };
    let count = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "SetComponent", "count")?;
    let target =
        parse_object_reference_argument(args.get(2).unwrap_or(&Value::Nil), "SetComponent", "obj")?;
    let active = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_context().map(|object| object.id()))
    });
    if let Some(target) = target {
        if Some(target) != active {
            return match call_world_object_function(
                target,
                "SetComponent",
                &args[..2.min(args.len())],
            ) {
                Some(result) => result,
                None => Ok(Value::Bool(false)),
            };
        }
    }
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let Some(self_id) = context.object_context().map(|object| object.id()) else {
            return Ok(Value::Bool(false));
        };
        // Read-modify-write: the update replaces the whole map, so seed
        // from pending writes or the object's current components.
        let current = context
            .object_context()
            .and_then(|object| object.pending_update.components.clone())
            .or_else(|| {
                context
                    .get_world_object(self_id)
                    .and_then(|object| object.full_state().map(|state| state.components.clone()))
            })
            .unwrap_or_default();
        let mut order = context
            .object_context()
            .and_then(|object| object.pending_update.component_order.clone())
            .or_else(|| {
                context.get_world_object(self_id).and_then(|object| {
                    object
                        .full_state()
                        .map(|state| state.component_order.clone())
                })
            })
            .unwrap_or_default();
        let Some(object) = context.object_context_mut() else {
            return Ok(Value::Bool(false));
        };
        let mut map = current;
        let component = DefinitionId::from(component.as_str());
        if !order.contains(&component) {
            order.push(component.clone());
        }
        map.insert(component, count);
        object.pending_update.components = Some(map);
        object.pending_update.component_order = Some(order);
        Ok(Value::Bool(true))
    })
}

/// FnGetDefinition (C4Script.cpp:2668-2677) indexes runtime `Game.Defs` order;
/// C4DefList::GetDef optionally filters by overlapping category bits without
/// reordering the surviving definitions (C4Def.cpp:1141-1158).
fn get_definition(args: &[Value]) -> Result<Value, RuntimeError> {
    let index = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "GetDefinition",
        "index",
    )?;
    let category = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "GetDefinition",
        "category",
    )?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        Ok(borrow
            .as_ref()
            .and_then(|context| context.world.definition_id_by_index(index, category))
            .map(|id| Value::C4Id(id.as_str().to_string()))
            .unwrap_or(Value::Nil))
    })
}

/// FnValue (C4Script.cpp:1385-1389): the raw DefCore `Value` of a loaded
/// definition. Unlike GetValue this does not run CalcDefValue/CalcBuyValue;
/// an unloaded or zero ID returns null.
fn definition_value(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "Value expects at most 1 argument: definition",
        ));
    }
    let Some(definition) = parse_native_c4id_argument(args.first(), "Value")? else {
        return Ok(Value::Nil);
    };
    HOST_CONTEXT.with(|cell| {
        Ok(cell
            .borrow()
            .as_ref()
            .and_then(|context| {
                context
                    .world
                    .definition_metadata(&DefinitionId::from(definition.as_str()))
            })
            .map_or(Value::Nil, |metadata| Value::Int(metadata.value)))
    })
}

/// `C4Def::GetValue` (C4Def.cpp:839-858): run the definition-owned
/// `CalcDefValue(base, player)` override, then the optional base-owned
/// `CalcBuyValue(definition, value)` adjustment. `None` means the definition
/// is not loaded, matching FnGetValue's null return for an unknown id.
pub(super) fn calculated_definition_value(
    definition: &str,
    base: Option<ObjectId>,
    player: i32,
) -> Result<Option<i32>, RuntimeError> {
    let (metadata, script) = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return (None, None);
        };
        (
            context.definition_metadata(definition).cloned(),
            context.world.definition_script(definition).cloned(),
        )
    });
    let Some(metadata) = metadata else {
        return Ok(None);
    };
    let callback_args = [
        base.map(object_reference_value).unwrap_or(Value::Nil),
        Value::Int(player),
    ];
    let mut value = match script.and_then(|script| {
        call_scoped_definition_function(script, definition, "CalcDefValue", &callback_args)
    }) {
        Some(result) => result?.as_c4_int().unwrap_or(0),
        None => metadata.value,
    };
    if let Some(base) = base {
        if let Some(result) = call_world_object_own_function(
            base,
            "CalcBuyValue",
            &[Value::C4Id(definition.to_string()), Value::Int(value)],
        ) {
            value = result?.as_c4_int().unwrap_or(0);
        }
    }
    Ok(Some(value))
}

/// FnGetValue (C4Script.cpp:1366-1375): with a nonzero definition id, use
/// `C4Def::GetValue`; otherwise use the explicit object or `cthr->Obj` and
/// `C4Object::GetValue` (CalcValue/CalcDefValue, construction percentage,
/// then the containing base's CalcSellValue adjustment).
pub(super) fn get_value(args: &[Value]) -> Result<Value, RuntimeError> {
    let target =
        parse_object_reference_argument(args.first().unwrap_or(&Value::Nil), "GetValue", "object")?;
    let definition = parse_native_c4id_argument(args.get(1), "GetValue")?;
    let base =
        parse_object_reference_argument(args.get(2).unwrap_or(&Value::Nil), "GetValue", "base")?;
    let player = value_to_i32(args.get(3).unwrap_or(&Value::Nil), "GetValue", "player")?;

    if let Some(definition) = definition.filter(|id| !id.is_empty()) {
        return Ok(calculated_definition_value(&definition, base, player)?
            .map(Value::Int)
            .unwrap_or(Value::Nil));
    }

    let target = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        target.or_else(|| context.object_context().map(ObjectScopeContext::id))
    });
    let Some(target) = target else {
        return Ok(Value::Nil);
    };
    let Some(definition) = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| effective_definition_id(context, target))
    }) else {
        return Ok(Value::Nil);
    };

    let callback_args = [
        base.map(object_reference_value).unwrap_or(Value::Nil),
        Value::Int(player),
    ];
    let mut value = match call_world_object_own_function(target, "CalcValue", &callback_args) {
        Some(result) => result?.as_c4_int().unwrap_or(0),
        None => calculated_definition_value(&definition, None, player)?.unwrap_or(0),
    };
    let construction = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        context
            .object_scope(target)
            .map(ObjectScopeContext::construction)
            .or_else(|| {
                context
                    .get_world_object(target)
                    .map(|object| object.construction())
            })
    });
    let Some(construction) = construction else {
        return Ok(Value::Nil);
    };
    value = value.wrapping_mul(construction) / crate::FULL_CON;

    if let Some(base) = base {
        if let Some(result) = call_world_object_own_function(
            base,
            "CalcSellValue",
            &[object_reference_value(target), Value::Int(value)],
        ) {
            value = result?.as_c4_int().unwrap_or(0);
        }
    }
    Ok(Value::Int(value))
}

/// FnGetDefCoreVal (C4Script.cpp:4170-4183): compiler-shaped reflection over
/// the complete DefCore/Shape surface and sibling Physical section.
fn get_def_core_val(args: &[Value]) -> Result<Value, RuntimeError> {
    let entry = parse_optional_string(args.first(), "GetDefCoreVal", "entry")?;
    let section = parse_optional_string(args.get(1), "GetDefCoreVal", "section")?
        .filter(|section| !section.is_empty());
    let requested = parse_native_c4id_argument(args.get(2), "GetDefCoreVal")?;
    let entry_index = parse_optional_i32(args.get(3), "GetDefCoreVal", "entry_nr")?.unwrap_or(0);
    let Some(entry) = entry else {
        return Ok(Value::Nil);
    };
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let definition_id = match requested {
            Some(id) => Some(id),
            // `if (!idDef && cthr->Def) idDef = cthr->Def->id` — the
            // executing function's definition, even without an object.
            None => context
                .current_definition_id()
                .map(|definition| definition.to_string()),
        };
        let Some(definition_id) = definition_id else {
            return Ok(Value::Nil);
        };
        let Some(metadata) = context.definition_metadata(definition_id.as_str()) else {
            return Ok(Value::Nil);
        };
        if !metadata.fire.def_core_values.is_empty() {
            return Ok(metadata
                .fire
                .def_core_values
                .get(entry.as_str(), section.as_deref(), entry_index)
                .unwrap_or(Value::Nil));
        }
        // Snapshot-only and synthetic host fixtures predating the complete
        // reflection store retain the small modeled fallback below.
        if section
            .as_deref()
            .is_some_and(|section| section != "DefCore")
        {
            return Ok(Value::Nil);
        }
        let shape = metadata.shape.unwrap_or(DefinitionRect::new(0, 0, 0, 0));
        if entry == "Offset" {
            return Ok(match entry_index {
                0 => Value::Int(shape.x),
                1 => Value::Int(shape.y),
                _ => Value::Nil,
            });
        }
        if entry_index != 0 {
            return Ok(Value::Nil);
        }
        Ok(match entry.as_str() {
            "Width" => Value::Int(shape.width),
            "Height" => Value::Int(shape.height),
            "CollectionLimit" => Value::Int(metadata.collection_limit),
            "GrabPutGet" => Value::Int(metadata.grab_put_get),
            "FireTop" => Value::Int(metadata.fire.fire_top),
            "LiftTop" => Value::Int(metadata.fire.lift_top),
            "Value" => Value::Int(metadata.value),
            "Mass" => Value::Int(metadata.mass),
            // C4Def::CompileFunc's line bitfields (C4Def.cpp:333-351).
            "Line" => Value::Int(metadata.line),
            "LineConnect" => Value::Int(metadata.line_connect as i32),
            // The blast-chain entries System.c4g reads through the GetXVal
            // wrappers (GetDefGrab/GetDefHorizontalFix/GetDefContainBlast,
            // BlastObjectsShockwaveCheck + DoExplosion).
            "Grab" => Value::Int(metadata.fire.grab),
            "NoPushEnter" => Value::Int(metadata.fire.no_push_enter),
            "HorizontalFix" => Value::Int(metadata.fire.no_horizontal_move),
            "ContainBlast" => Value::Int(metadata.fire.contain_blast),
            "ClosedContainer" => Value::Int(metadata.fire.closed_container),
            "BlastIncinerate" => Value::Int(metadata.fire.blast_incinerate),
            "ContactIncinerate" => Value::Int(metadata.fire.contact_incinerate),
            other => {
                tracing::debug!(entry = other, "GetDefCoreVal entry not modeled; nil");
                Value::Nil
            }
        })
    })
}

/// FnGetLeague (C4Script.cpp:3556-3561): the indexed semicolon-delimited
/// section of the exact Game.Parameters.League byte buffer.
fn get_league(args: &[Value]) -> Result<Value, RuntimeError> {
    let index = value_to_i32(args.first().unwrap_or(&Value::Nil), "GetLeague", "index")?;
    let Ok(index) = usize::try_from(index) else {
        return Ok(Value::Nil);
    };
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let Some(section) = context
            .world
            .league_name
            .split(|byte| *byte == b';')
            .nth(index)
        else {
            return Ok(Value::Nil);
        };
        if section.is_empty() {
            Ok(Value::Nil)
        } else {
            Ok(Value::String(
                clonk_script::c4_string_from_bytes(section).into(),
            ))
        }
    })
}

