/// Apply native `C4String *` conversion without collapsing an explicit empty
/// string into a null pointer. Pre-strict-3 callers eagerly reset raw-falsy
/// values to nil; strict-3 callers retain their type, so typed `0`/`false`
/// fail conversion while nil remains a valid null string pointer.
fn parse_native_c4_string_argument(
    value: Option<&Value>,
    function: &str,
    parameter: &str,
) -> Result<Option<String>, RuntimeError> {
    let value = value.unwrap_or(&Value::Nil);
    let eager_falsy_conversion = !matches!(
        clonk_script::caller_origin_strictness(),
        clonk_script::HostCallerStrictness::Strict(level) if level >= 3
    );
    if eager_falsy_conversion && !value.as_bool() {
        return Ok(None);
    }
    match value {
        Value::Nil => Ok(None),
        Value::String(text) => Ok(Some(text.as_ref().to_owned())),
        other => Err(RuntimeError::new(format!(
            "{function}: expected string for {parameter}, got {}",
            other.type_name()
        ))),
    }
}

/// `FnSetLeagueProgressData` (C4Script.cpp:2860-2866): update the exact
/// retained C4PlayerInfo buffer when the display league name is configured.
fn set_league_progress_data(args: &[Value]) -> Result<Value, RuntimeError> {
    // Native parameter conversion is complete before either function gate.
    let data =
        parse_native_c4_string_argument(args.first(), "SetLeagueProgressData", "progress data")?
            .map(|text| clonk_script::c4_string_bytes(&text));
    let player_info_id = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "SetLeagueProgressData",
        "player info ID",
    )?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        if !context.world.league_name_configured()
            || !context.world.player_info_id_known(player_info_id)
        {
            return Ok(Value::Bool(false));
        }
        // The C++ mutation is synchronous: a getter later in this same VM
        // call must already observe it before the deferred Engine fold.
        let updated = context
            .world
            .set_player_info_league_progress_data(player_info_id, data.clone());
        debug_assert!(updated, "validated player-info ID must update");
        context.record_player_command(PlayerCommand::SetLeagueProgressData {
            player_info_id,
            data,
        });
        Ok(Value::Bool(true))
    })
}

/// FnGetScenarioVal (C4Script.cpp:4244-4250): exact StdCompiler reflection
/// over the retained, post-load `Game.C4S`. `entry_nr` counts primitive
/// callbacks inside the matched named value: C4SVal is Std/Rnd/Min/Max and
/// ID lists are ID/count pairs (C4Script.cpp:3997-4006).
fn get_scenario_val(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some(entry) = parse_optional_string(args.first(), "GetScenarioVal", "entry")? else {
        return Ok(Value::Nil);
    };
    let section = parse_optional_string(args.get(1), "GetScenarioVal", "section")?
        .filter(|section| !section.is_empty());
    let entry_index = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "GetScenarioVal",
        "entry_nr",
    )?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        if let Some(value) =
            context
                .world
                .scenario_value(entry.as_str(), section.as_deref(), entry_index)
        {
            return Ok(match value {
                ScenarioValue::Int(value) => Value::Int(*value),
                ScenarioValue::Bool(value) => Value::Bool(*value),
                ScenarioValue::String(value) => Value::from(value.clone()),
                // C4Value(C4ID_None) has C4V_Any type, i.e. nil rather than
                // a typed zero ID (C4Value.h:113,306).
                ScenarioValue::C4Id(value) if value.is_empty() => Value::Nil,
                ScenarioValue::C4Id(value) => {
                    let raw = clonk_script::c4_id_parse(value);
                    if raw == 0 {
                        Value::Nil
                    } else {
                        Value::C4Id(clonk_script::c4_id_from_raw(raw))
                    }
                }
            });
        }
        tracing::debug!(
            entry = entry.as_str(),
            section = section.as_deref().unwrap_or(""),
            entry_index,
            "GetScenarioVal entry not found; nil"
        );
        Ok(Value::Nil)
    })
}

/// `FnLoadScenarioSection` (C4Script.cpp:5401-5408): reject a null/empty
/// name, resolve the section case-insensitively, and hand the engine an
/// ordered request. C++ removes every active object but deliberately keeps
/// inactive objects, so their effective identities travel with the request.
fn load_scenario_section(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "LoadScenarioSection expects at most 2 arguments: name, flags",
        ));
    }
    let Some(name) = parse_optional_string(args.first(), "LoadScenarioSection", "name")? else {
        return Ok(Value::Int(0));
    };
    if name.is_empty() {
        return Ok(Value::Int(0));
    }
    let flags = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "LoadScenarioSection",
        "flags",
    )?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Int(0));
        };
        if !context.world.scenario_section_known(&name) {
            return Ok(Value::Int(0));
        }
        let preserve_ids = context
            .all_world_object_ids()
            .into_iter()
            .filter(|id| {
                context
                    .get_world_object(*id)
                    .is_some_and(|object| object.status() == ObjectStatus::Inactive)
            })
            .collect();
        context.record_player_command(PlayerCommand::LoadScenarioSection {
            name,
            flags,
            preserve_ids,
        });
        Ok(Value::Int(1))
    })
}

fn get_hi_rank(args: &[Value]) -> Result<Value, RuntimeError> {
    // FnGetHiRank (C4Script.cpp:2792-2796) ->
    // C4Player::GetHiRankActiveCrew(false) (C4Player.cpp:1003-1020): walk
    // the crew in order, rank from the linked Info (no info = -1); only a
    // strictly higher rank replaces, so the first of equal ranks wins.
    let player_id = value_to_i32(args.first().unwrap_or(&Value::Nil), "GetHiRank", "player")?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let Some(player) = context.player_state(player_id) else {
            return Ok(Value::Nil);
        };
        let mut best: Option<(u64, i32)> = None;
        for crew_id in &player.crew {
            if context.object_crew_disabled(*crew_id).unwrap_or(false) {
                continue;
            }
            let rank = match context.object_scope(*crew_id) {
                Some(scope) => scope.info_rank(),
                None => context.world.crew_rank(crew_id.as_u64()),
            }
            .unwrap_or(-1);
            match best {
                Some((_, best_rank)) if best_rank >= rank => {}
                _ => best = Some((crew_id.as_u64(), rank)),
            }
        }
        Ok(best
            .map(|(id, _)| object_reference_value(ObjectId::new(id)))
            .unwrap_or(Value::Nil))
    })
}

/// FnGetRank (C4Script.cpp:1378-1383): read the linked C4ObjectInfo rank.
/// A null object defaults to the executing object; objects without Info and
/// global calls without an object return nil.
fn get_rank(args: &[Value]) -> Result<Value, RuntimeError> {
    let target = args
        .first()
        .map(|value| parse_object_reference_argument(value, "GetRank", "obj"))
        .transpose()?
        .flatten();
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let Some(target) = target.or_else(|| context.object_context().map(|object| object.id()))
        else {
            return Ok(Value::Nil);
        };
        let rank = match context.object_scope(target) {
            Some(scope) => scope.info_rank(),
            None => context.world.crew_rank(target.as_u64()),
        };
        Ok(rank.map(Value::Int).unwrap_or(Value::Nil))
    })
}

fn get_crew(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "GetCrew expects at most 2 arguments: player and index",
        ));
    }
    // Unfilled iPlr/index slots are nil -> 0 (FnGetCrew, C4Script.cpp:2798);
    // SkiesOfFire's InitializePlayer calls GetCrew(iPlr) with no index.
    let player_id = value_to_i32(args.first().unwrap_or(&Value::Nil), "GetCrew", "player")?;
    let index = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "GetCrew", "index")?;
    if index < 0 {
        return Ok(Value::Nil);
    }
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let Some(player) = context.player_state(player_id) else {
            return Ok(Value::Nil);
        };
        let idx = index as usize;
        let Some(crew_id) = player.crew.get(idx) else {
            return Ok(Value::Nil);
        };
        Ok(object_reference_value(ObjectId::new(crew_id.as_u64())))
    })
}

