/// FnSimFlight (C4Script.cpp:5309-5330) and SimFlight
/// (C4Movement.cpp:623-653). The first four native C4Value* arguments are
/// nullable references; simulation runs on local fixed-point copies so a
/// bounds/iteration failure leaves every caller variable untouched.
fn sim_flight(args: &[HostCallArg]) -> Result<Value, RuntimeError> {
    if (0..4).any(|index| !args.get(index).is_some_and(HostCallArg::is_reference)) {
        return Err(RuntimeError::new(
            "SimFlight: first four arguments must be variable references",
        ));
    }

    let values = args
        .iter()
        .map(HostCallArg::read)
        .collect::<Result<Vec<_>, _>>()?;
    // FnSimFlight calls getInt() on the referenced C4Values after native
    // dispatch has validated only that they are references. getInt() returns
    // zero when the referenced value cannot convert to Int.
    let read_int = |index: usize| values.get(index).and_then(Value::as_c4_int).unwrap_or(0);
    let optional_int = |index: usize, parameter: &str| {
        parse_native_optional_i32(values.get(index), "SimFlight", parameter)
    };
    let density_min = optional_int(4, "density_min")?.unwrap_or(50);
    let density_max = optional_int(5, "density_max")?.unwrap_or(100);
    let mut iterations = optional_int(6, "iterations")?.unwrap_or(-1);
    let precision = optional_int(7, "precision")?.unwrap_or(10);
    if precision == 0 {
        return Err(RuntimeError::new("SimFlight: precision must not be zero"));
    }

    let mut x = itofix(read_int(0));
    let mut y = itofix(read_int(1));
    let xdir = itofix_prec(read_int(2), precision);
    let mut ydir = itofix_prec(read_int(3), precision);
    let gravity = PHYSICS_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .map(|context| fixed100(context.gravity()) / 5)
            .ok_or_else(|| RuntimeError::new("SimFlight requires an active physics context"))
    })?;

    let succeeded = HOST_CONTEXT.with(|cell| -> Result<bool, RuntimeError> {
        let borrow = cell.borrow();
        let context = borrow
            .as_ref()
            .ok_or_else(|| RuntimeError::new("SimFlight requires an active engine context"))?;
        let landscape = context
            .world
            .landscape_ref()
            .ok_or_else(|| RuntimeError::new("SimFlight requires an active landscape"))?;
        let width = landscape.width() as i32;
        let height = landscape.estimated_height();
        let mut cx = fixtoi(x);
        let mut cy = fixtoi(y);

        loop {
            if iterations == 0 {
                return Ok(false);
            }
            iterations = iterations.wrapping_sub(1);
            x += xdir;
            y += ydir;
            let target_x = fixtoi(x);
            let target_y = fixtoi(y);
            // Inside(target_x, 0, GBackWdt) is inclusive in both bounds;
            // C++ only rejects the lower landscape vertically.
            if !(0..=width).contains(&target_x) || target_y >= height {
                return Ok(false);
            }

            let contact = loop {
                cx += (target_x - cx).signum();
                cy += (target_y - cy).signum();
                let density = context.world.movement_density_at(cx, cy).unwrap_or(0);
                if (density_min..=density_max).contains(&density) {
                    break true;
                }
                if cx == target_x && cy == target_y {
                    break false;
                }
            };
            // GravAccel is adjusted for every completed movement frame,
            // including the frame that first contacts the density.
            ydir += gravity;
            if contact {
                x = itofix(cx);
                y = itofix(cy);
                return Ok(true);
            }
        }
    })?;

    if !succeeded {
        return Ok(Value::Bool(false));
    }
    let output = [
        Value::Int(fixtoi(x)),
        Value::Int(fixtoi(y)),
        Value::Int(fixtoi(xdir * precision)),
        Value::Int(fixtoi(ydir * precision)),
    ];
    for (index, value) in output.into_iter().enumerate() {
        let wrote = args[index].write(value)?;
        debug_assert!(wrote, "validated SimFlight reference disappeared");
    }
    Ok(Value::Bool(true))
}

fn set_wind(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.is_empty() {
        return Err(RuntimeError::new("SetWind expects 1 argument: wind"));
    }

    let wind = match &args[0] {
        Value::Int(value) => *value,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "SetWind: expected int or nil for wind, got {}",
                other.type_name()
            )));
        }
    };

    ENVIRONMENT_CONTEXT.with(|cell| {
        let context = cell
            .borrow()
            .as_ref()
            .ok_or_else(|| RuntimeError::new("SetWind requires an active engine context"))?
            .clone();
        context.set_wind(wind);
        Ok(Value::Nil)
    })
}

fn get_wind(args: &[Value]) -> Result<Value, RuntimeError> {
    for (index, arg) in args.iter().take(3).enumerate() {
        match arg {
            Value::Int(_) | Value::Nil => {}
            Value::Bool(_) if index == 2 => {}
            other => {
                return Err(RuntimeError::new(format!(
                    "GetWind: unexpected argument type {} at position {}",
                    other.type_name(),
                    index + 1
                )));
            }
        }
    }

    let wind = ENVIRONMENT_CONTEXT.with(|cell| {
        let context = cell
            .borrow()
            .as_ref()
            .ok_or_else(|| RuntimeError::new("GetWind requires an active engine context"))?
            .clone();
        Ok::<i32, RuntimeError>(context.wind_force())
    })?;

    // Global form (FnGetWind, C4Script.cpp:3001-3004).
    let global = match args.get(2) {
        Some(Value::Bool(flag)) => *flag,
        Some(Value::Int(value)) => *value != 0,
        _ => false,
    };
    if global {
        return Ok(Value::Int(wind));
    }

    // Positional form: object-relative GBackWind — zero on tunnel
    // background (C4Script.cpp:3005-3007; C4Wrappers.h:189-192).
    let local_x = match args.first() {
        Some(Value::Int(value)) => *value,
        _ => 0,
    };
    let local_y = match args.get(1) {
        Some(Value::Int(value)) => *value,
        _ => 0,
    };
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Int(wind));
        };
        let mut global_x = local_x;
        let mut global_y = local_y;
        if let Some(object) = context.object_context() {
            let position = object.effective_position();
            global_x = global_x.saturating_add(position.x);
            global_y = global_y.saturating_add(position.y);
        }
        let in_tunnel = context
            .landscape_ref()
            .map(|landscape| landscape.is_tunnel_at(global_x, global_y))
            .unwrap_or(false);
        Ok(Value::Int(if in_tunnel { 0 } else { wind }))
    })
}

// Mathematical host functions

fn abs_func(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() != 1 {
        return Err(RuntimeError::new("Abs expects 1 argument: value"));
    }

    match &args[0] {
        Value::Int(value) => Ok(Value::Int(value.abs())),
        Value::Nil => Ok(Value::Int(0)),
        other => Err(RuntimeError::new(format!(
            "Abs: expected int, got {}",
            other.type_name()
        ))),
    }
}

fn min_func(args: &[Value]) -> Result<Value, RuntimeError> {
    let val1 = value_to_i32(args.first().unwrap_or(&Value::Nil), "Min", "first argument")?;
    let val2 = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "Min", "second argument")?;

    Ok(Value::Int(val1.min(val2)))
}

fn max_func(args: &[Value]) -> Result<Value, RuntimeError> {
    let val1 = value_to_i32(args.first().unwrap_or(&Value::Nil), "Max", "first argument")?;
    let val2 = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "Max", "second argument")?;

    Ok(Value::Int(val1.max(val2)))
}

fn sqrt_func(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() != 1 {
        return Err(RuntimeError::new("Sqrt expects 1 argument: value"));
    }

    let value = match &args[0] {
        Value::Int(v) => *v,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "Sqrt: expected int, got {}",
                other.type_name()
            )));
        }
    };

    // C++ returns 0 for negative values
    if value < 0 {
        return Ok(Value::Int(0));
    }

    // C++ implementation does: sqrt, then adjusts for rounding
    let result = (value as f64).sqrt() as i32;
    Ok(Value::Int(result))
}

fn inverse_trig_func(
    args: &[Value],
    function: &str,
    inverse: fn(f64) -> f64,
) -> Result<Value, RuntimeError> {
    let value = value_to_i32(args.first().unwrap_or(&Value::Nil), function, "value")?;
    let radius = value_to_i32(args.get(1).unwrap_or(&Value::Nil), function, "radius")?;
    // FnArcSin/FnArcCos (C4Script.cpp:3276-3298): the comparison is
    // deliberately signed (negative values within the domain remain
    // valid), followed by double-precision libm in degrees and
    // floor(angle + 0.5).
    if radius == 0 || value > radius {
        return Ok(Value::Int(0));
    }
    let angle = inverse(f64::from(value) / f64::from(radius)) * 180.0 * std::f64::consts::FRAC_1_PI;
    Ok(Value::Int(round_inverse_angle(angle)))
}

fn round_inverse_angle(angle: f64) -> i32 {
    (angle + 0.5).floor() as i32
}

fn arc_sin_func(args: &[Value]) -> Result<Value, RuntimeError> {
    inverse_trig_func(args, "ArcSin", f64::asin)
}

fn arc_cos_func(args: &[Value]) -> Result<Value, RuntimeError> {
    inverse_trig_func(args, "ArcCos", f64::acos)
}

/// FnAngle (C4Script.cpp:3255-3280): the position-to-position angle in
/// Clonk orientation (0 = up, 90 = right), `iPrec` scaling (default 1).
/// Axis-aligned deltas take the exact shortcuts; the general case is
/// `trunc(180 * prec * atan2(|dy|, |dx|) / pi)` folded into the quadrant.
fn angle_func(args: &[Value]) -> Result<Value, RuntimeError> {
    let x1 = value_to_i32(args.first().unwrap_or(&Value::Nil), "Angle", "x1")?;
    let y1 = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "Angle", "y1")?;
    let x2 = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "Angle", "x2")?;
    let y2 = value_to_i32(args.get(3).unwrap_or(&Value::Nil), "Angle", "y2")?;
    let mut prec = value_to_i32(args.get(4).unwrap_or(&Value::Nil), "Angle", "precision")?;
    if prec == 0 {
        prec = 1;
    }

    let dx = x2.wrapping_sub(x1);
    let dy = y2.wrapping_sub(y1);
    if dx == 0 {
        return Ok(Value::Int(if dy > 0 { 180 * prec } else { 0 }));
    }
    if dy == 0 {
        return Ok(Value::Int(if dx > 0 { 90 * prec } else { 270 * prec }));
    }

    let angle = (180.0
        * f64::from(prec)
        * f64::from(dy.abs()).atan2(f64::from(dx.abs()))
        * std::f64::consts::FRAC_1_PI) as i32;

    Ok(Value::Int(if x2 > x1 {
        if y2 < y1 {
            90 * prec - angle
        } else {
            90 * prec + angle
        }
    } else if y2 < y1 {
        270 * prec + angle
    } else {
        270 * prec - angle
    }))
}

/// FnGetMass (C4Script.cpp:1148-1158): with an id, the DEF mass; else the
/// object's Mass = max(Def->Mass * Con / FullCon, 1)
/// (C4Object.cpp:188; OwnMass/contents mass unmodeled). Nil without both.
fn get_mass(args: &[Value]) -> Result<Value, RuntimeError> {
    if std::env::var("LC_MASSDBG").is_ok() {
        let peek = parse_native_c4id_argument(args.get(1), "GetMass")
            .ok()
            .flatten();
        let mass = peek.as_ref().and_then(|d| {
            HOST_CONTEXT.with(|cell| {
                cell.borrow()
                    .as_ref()
                    .and_then(|c| c.world.definition_metadata(d).map(|m| m.mass))
            })
        });
        eprintln!("MASSDBG GetMass args={args:?} -> {mass:?}");
    }
    let definition = parse_native_c4id_argument(args.get(1), "GetMass")?;
    if let Some(definition) = definition {
        return HOST_CONTEXT.with(|cell| {
            Ok(cell
                .borrow()
                .as_ref()
                .and_then(|context| context.world.definition_metadata(&definition))
                .map(|metadata| Value::Int(metadata.mass))
                .unwrap_or(Value::Nil))
        });
    }
    let target =
        parse_object_reference_argument(args.first().unwrap_or(&Value::Nil), "GetMass", "obj")?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let id = target.or_else(|| context.object_context().map(|object| object.id()));
        let Some(id) = id else {
            return Ok(Value::Nil);
        };
        // UpdateMass: Mass = max((Def->Mass + OwnMass) * Con / FullCon, 1)
        // (C4Object.cpp:497-500); the active scope has the freshest OwnMass.
        if context.get_world_object(id).is_none() {
            return Ok(Value::Nil);
        }
        Ok(Value::Int(reflected_object_mass(
            context,
            id,
            &mut HashSet::new(),
        )))
    })
}

/// FnGrabObjectInfo (C4Script.cpp:2170-2176) -> C4Object::GrabInfo
/// (C4Object.cpp:5696-5726): `pTo` (default: the caller) takes pFrom's
/// exact info pointer, after both objects are removed from every player crew,
/// then registers the receiver with its unchanged Owner.
fn grab_object_info(args: &[Value]) -> Result<Value, RuntimeError> {
    let from = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "GrabObjectInfo",
        "from",
    )?;
    let Some(from) = from else {
        return Ok(Value::Bool(false));
    };
    let to = parse_object_reference_argument(
        args.get(1).unwrap_or(&Value::Nil),
        "GrabObjectInfo",
        "to",
    )?;
    let result = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return None;
        };
        let active = context.object_context().map(|object| object.id());
        let Some(to) = to.or(active) else {
            return None;
        };
        if !context.ensure_object_scope(from) || !context.ensure_object_scope(to) {
            return None;
        }
        if !context.object_status_present(from) || !context.object_status_present(to) {
            return None;
        }
        if from == to {
            return Some((to, None));
        }
        let donor_has_info = context
            .object_scope(from)
            .is_some_and(|scope| scope.info_core().is_some() || scope.info_rank().is_some());
        if !donor_has_info {
            return None;
        }

        // Retire and clear the receiver's old Info before either global
        // ClearPointers call.
        let receiver_link = context
            .object_scope(to)
            .and_then(ObjectScopeContext::info_link);
        if let Some(link) = receiver_link {
            if retire_host_crew_info(context, link) {
                context.record_player_command(PlayerCommand::RetireCrewInfo {
                    object_id: to,
                    link,
                });
            }
        }
        if let Some(scope) = context.object_scope_mut(to) {
            scope.set_info_rank(None);
            scope.set_info_link(None);
            scope.set_info_core(None);
            scope.info_physical = None;
            scope.record_physicals();
        }

        // ClearPointers may synchronously run CrewSelection through cursor
        // replacement. Release the host borrow so those nested callbacks see
        // and mutate the same live context, then re-read donor Info.
        drop(borrow);
        clear_player_object_pointers_host(from);
        clear_player_object_pointers_host(to);
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut()?;
        if !context.ensure_object_scope(from) || !context.ensure_object_scope(to) {
            return None;
        }
        let (donor_core, donor_link, donor_physical, donor_definition_physical) = context
            .object_scope(from)
            .map(|scope| {
                (
                    scope.info_core().cloned().or_else(|| {
                        let rank = scope.info_rank()?;
                        let definition = scope.definition_id.as_deref()?;
                        let definition_id = DefinitionId::from(definition);
                        let rank_names = context.world.definition_rank_names.get(&definition_id);
                        let mut rank_name =
                            default_rank_name(&context.world.default_rank_names, rank)
                                .unwrap_or("Clonk")
                                .to_string();
                        let mut core = CrewInfoCoreFields {
                            type_name: context
                                .definition_metadata(definition)
                                .map(|metadata| crate::bounded_crew_type_name(&metadata.name))
                                .unwrap_or_else(|| "Clonk".to_string()),
                            ..CrewInfoCoreFields::default()
                        };
                        crate::update_custom_rank_fields(
                            &mut rank_name,
                            &mut core,
                            rank,
                            rank_names,
                            context.world.definition_rank_base(definition),
                        );
                        Some(CrewObjectInfo {
                            definition_id,
                            name: context
                                .definition_metadata(definition)
                                .map(|metadata| metadata.name.clone())
                                .unwrap_or_else(|| "Clonk".to_string()),
                            death_message: String::new(),
                            core,
                            rank,
                            rank_name,
                            experience: 0,
                            participation: 1,
                            rounds: 0,
                            death_count: 0,
                            total_playing_time: 0,
                            birthday: 0,
                            age: 0,
                            in_action_time: 0,
                            extra_data: Vec::new(),
                            portraits: CrewPortraitState::default(),
                        })
                    }),
                    scope.info_link(),
                    scope.info_physical,
                    scope.info_definition_physical,
                )
            })
            .unwrap_or((None, None, None, None));
        let mut donor_core = donor_core?;
        if let Some(scope) = context.object_scope_mut(from) {
            scope.set_crew_status_member(false);
            scope.set_info_rank(None);
            scope.set_info_link(None);
            scope.set_info_core(None);
            scope.info_physical = None;
            scope.record_physicals();
        }
        context.refresh_scope_fair_crew(from);

        let target_alive = context
            .object_scope(to)
            .is_some_and(ObjectScopeContext::alive);
        if target_alive {
            donor_core.rank_name = recruited_rank_name(
                &context.world,
                &donor_core.definition_id,
                donor_core.rank,
                &donor_core.rank_name,
            );
        }
        let linked = donor_link.filter(|link| {
            let valid = retire_host_crew_info(context, *link);
            if valid {
                context.record_player_command(PlayerCommand::RetireCrewInfo {
                    object_id: from,
                    link: *link,
                });
                relink_host_crew_info(context, *link, target_alive, !target_alive);
            }
            valid
        });
        if let Some(scope) = context.object_scope_mut(to) {
            scope.set_info_rank(Some(donor_core.rank));
            scope.set_info_link(linked);
            scope.set_info_core(Some(donor_core.clone()));
            scope.info_physical = donor_physical;
            scope.info_definition_physical = donor_definition_physical;
            scope.record_physicals();
        }
        context.refresh_scope_fair_crew(to);
        context.record_player_command(PlayerCommand::LinkCrewInfo {
            object_id: to,
            link: linked,
            info: donor_core,
            created_entry: None,
            recruit: target_alive,
            has_died: !target_alive,
        });

        let owner = context.object_scope(to).map(ObjectScopeContext::owner);
        let callback_owner = owner.filter(|owner| {
            context.player_state(*owner).is_some()
                && context.object_status_present(to)
                && context
                    .object_effective_definition_id(to)
                    .and_then(|definition| context.definition_metadata(&definition))
                    .is_some_and(|metadata| metadata.crew_member)
        });
        if let Some(owner) = callback_owner {
            context.insert_player_crew(owner, to);
            if let Some(scope) = context.object_scope_mut(to) {
                scope.set_controller(owner);
                if scope.plr_view_range() == 0 {
                    scope.set_plr_view_range(500);
                }
            }
        }
        let donor_member = context.object_in_any_crew(from);
        let receiver_member = context.object_in_any_crew(to);
        if let Some(scope) = context.object_scope_mut(from) {
            scope.set_crew_status_member(donor_member);
        }
        if let Some(scope) = context.object_scope_mut(to) {
            scope.set_crew_status_member(receiver_member);
        }
        context.record_crew_rosters();
        Some((to, callback_owner))
    });

    let Some((to, callback_owner)) = result else {
        return Ok(Value::Bool(false));
    };
    if let Some(owner) = callback_owner {
        call_recruitment_callback(to, owner);
        HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(context) = borrow.as_mut() else {
                return;
            };
            let donor_member = context.object_in_any_crew(from);
            let receiver_member = context.object_in_any_crew(to);
            if let Some(scope) = context.object_scope_mut(from) {
                scope.set_crew_status_member(donor_member);
            }
            if let Some(scope) = context.object_scope_mut(to) {
                scope.set_crew_status_member(receiver_member);
            }
            context.record_crew_rosters();
        });
    }
    Ok(Value::Bool(true))
}

/// FnMakeCrewMember (C4Script.cpp:2164-2168) -> C4Player::MakeCrewMember
/// (C4Player.cpp:1167-1215): valid player + CrewMember def required; assigns
/// an exact idle/new info, joins the independent roster and calls Recruitment.

/// `pObj->Call(PSF_OnJoinCrew)` where PSF_OnJoinCrew is the fail-safe
/// `~Recruitment` name and C4Object::Call uses fPassError=false.
fn call_recruitment_callback(target: ObjectId, player: i32) {
    if let Some(Err(error)) =
        call_world_object_own_function(target, "Recruitment", &[Value::Int(player)])
    {
        tracing::warn!(
            object = %target,
            error = %error,
            "script error in Recruitment callback; continuing like C++"
        );
    }
}

fn retire_host_crew_info(context: &mut EffectHostContext, link: CrewInfoLink) -> bool {
    let (entry, order) = {
        let mut state = context.world.crew_info_state.borrow_mut();
        let Some(entry) = state.entries.get_mut(&link) else {
            return false;
        };
        entry.in_action = false;
        (
            entry.clone(),
            state
                .order
                .get(&link.player_id)
                .cloned()
                .unwrap_or_default(),
        )
    };
    let key = (link.player_id, entry.id.clone());
    let mut state = context.world.crew_info_state.borrow_mut();
    if context.world.definition_metadata(&entry.id).is_none() {
        state.idle.remove(&key);
        return true;
    }
    let rebuilt: Vec<_> = order
        .into_iter()
        .filter_map(|candidate| {
            let info = state.entries.get(&candidate)?;
            (info.id == entry.id && info.participation != 0 && !info.in_action && !info.has_died)
                .then(|| (candidate, info.clone()))
        })
        .collect();
    if rebuilt.is_empty() {
        state.idle.remove(&key);
    } else {
        state.idle.insert(key, rebuilt);
    }
    true
}

fn relink_host_crew_info(
    context: &mut EffectHostContext,
    link: CrewInfoLink,
    recruit: bool,
    has_died: bool,
) -> bool {
    let recruited_name = if recruit {
        let state = context.world.crew_info_state.borrow();
        state.entries.get(&link).map(|entry| {
            recruited_rank_name(
                &context.world,
                &DefinitionId::from(entry.id.as_str()),
                entry.rank,
                &entry.rank_name,
            )
        })
    } else {
        None
    };
    let mut state = context.world.crew_info_state.borrow_mut();
    let Some(entry) = state.entries.get_mut(&link) else {
        return false;
    };
    entry.has_died = has_died;
    if recruit && !entry.in_action {
        if let Some(rank_name) = recruited_name {
            entry.rank_name = rank_name;
        }
    }
    entry.in_action = recruit;
    entry.was_in_action |= recruit;
    let key = (link.player_id, entry.id.clone());
    if let Some(pool) = state.idle.get_mut(&key) {
        pool.retain(|(candidate, _)| *candidate != link);
    }
    true
}

fn recruited_rank_name(
    world: &HostWorldContext,
    definition_id: &DefinitionId,
    rank: i32,
    stored_rank_name: &str,
) -> String {
    world
        .definition_rank_names
        .get(definition_id)
        .filter(|names| !names.is_empty())
        .and_then(|names| {
            usize::try_from(rank)
                .ok()
                .and_then(|rank| names.get_or_last(rank))
                .map(|name| name.into_owned())
        })
        .unwrap_or_else(|| stored_rank_name.to_string())
}

fn recruit_or_create_crew_info(
    context: &mut EffectHostContext,
    player: i32,
    definition_id: &str,
) -> Result<
    Option<(
        CrewInfoLink,
        CrewObjectInfo,
        Option<crate::player_file::CrewInfo>,
        PhysicalInfo,
    )>,
    RuntimeError,
> {
    let key = (player, definition_id.to_string());
    let idle = {
        let mut state = context.world.crew_info_state.borrow_mut();
        let picked = state.idle.get_mut(&key).and_then(|pool| {
            let best = pool
                .iter()
                .enumerate()
                .fold(
                    None,
                    |best: Option<(usize, i32)>, (index, (_, info))| match best {
                        Some((_, best_exp)) if best_exp >= info.experience => best,
                        _ => Some((index, info.experience)),
                    },
                )
                .map(|(index, _)| index)?;
            Some(pool.remove(best))
        });
        if let Some((link, _)) = picked.as_ref() {
            if let Some(entry) = state.entries.get_mut(link) {
                entry.in_action = true;
                entry.was_in_action = true;
            }
        }
        picked
    };
    if let Some((link, mut entry)) = idle {
        entry.rank_name = recruited_rank_name(
            &context.world,
            &DefinitionId::from(entry.id.as_str()),
            entry.rank,
            &entry.rank_name,
        );
        if let Some(stored) = context
            .world
            .crew_info_state
            .borrow_mut()
            .entries
            .get_mut(&link)
        {
            stored.rank_name = entry.rank_name.clone();
        }
        let info = CrewObjectInfo {
            definition_id: DefinitionId::from(entry.id.as_str()),
            name: entry.name.clone(),
            death_message: entry.death_message.clone(),
            core: entry.core.clone(),
            rank: entry.rank,
            rank_name: entry.rank_name.clone(),
            experience: entry.experience,
            participation: entry.participation,
            rounds: entry.rounds,
            death_count: entry.death_count,
            total_playing_time: entry.total_playing_time,
            birthday: entry.birthday,
            age: entry.age,
            in_action_time: entry.in_action_time,
            extra_data: entry.extra_data.clone(),
            portraits: entry.portraits.clone(),
        };
        return Ok(Some((link, info, None, entry.physical)));
    }

    let names_source = context
        .world
        .definition_crew_names
        .get(definition_id)
        .cloned()
        .or_else(|| context.world.standard_crew_names.clone());
    const C4_MAX_NAME: usize = 30;
    let mut name = match names_source {
        Some(names) if names.to_ascii_lowercase().contains("names.txt") => {
            draw_context_random(1000)?;
            "Clonk".to_string()
        }
        Some(names) => {
            let newline_count = names.bytes().filter(|&byte| byte == b'\n').count() as i32;
            let segment_index = draw_context_random(newline_count)? as usize;
            let segment = names
                .split('\n')
                .nth(segment_index)
                .unwrap_or_default()
                .replace('\r', "");
            let cleaned: String = segment.trim().chars().take(C4_MAX_NAME).collect();
            if cleaned.is_empty() {
                "Clonk".to_string()
            } else {
                cleaned
            }
        }
        None => "Clonk".to_string(),
    };

    let physical = context
        .definition_metadata(definition_id)
        .map(|metadata| crate::crew_info_physical(metadata.physical, 0))
        .unwrap_or_default();
    let definition_id_key = DefinitionId::from(definition_id);
    let rank_names = context.world.definition_rank_names.get(&definition_id_key);
    let mut rank_name = "Clonk".to_string();
    let mut core = CrewInfoCoreFields {
        type_name: context
            .definition_metadata(definition_id)
            .map(|metadata| crate::bounded_crew_type_name(&metadata.name))
            .unwrap_or_else(|| "Clonk".to_string()),
        ..CrewInfoCoreFields::default()
    };
    crate::update_custom_rank_fields(
        &mut rank_name,
        &mut core,
        0,
        rank_names,
        context.world.definition_rank_base(definition_id),
    );
    let (link, entry) = {
        let mut state = context.world.crew_info_state.borrow_mut();
        {
            let names = state.roster_names.entry(player).or_default();
            let base = name.clone();
            let mut next_number = 2;
            while names.iter().any(|existing| {
                c4_bytes_equal_no_case(
                    &clonk_script::c4_string_bytes(existing),
                    &clonk_script::c4_string_bytes(&name),
                )
            }) {
                let digits = next_number.to_string();
                let keep = base
                    .chars()
                    .count()
                    .min(C4_MAX_NAME.saturating_sub(digits.len()));
                name = base.chars().take(keep).collect::<String>() + &digits;
                next_number += 1;
            }
            names.push(name.clone());
        }
        let roster_index = *state.next_indices.entry(player).or_insert(0);
        state.next_indices.insert(player, roster_index + 1);
        let link = CrewInfoLink {
            player_id: player,
            roster_index,
        };
        let entry = crate::player_file::CrewInfo {
            id: definition_id.to_string(),
            name,
            death_message: String::new(),
            core,
            rank: 0,
            rank_name,
            experience: 0,
            rounds: 0,
            physical,
            death_count: 0,
            total_playing_time: 0,
            birthday: 0,
            age: 0,
            participation: 1,
            in_action: false,
            was_in_action: false,
            in_action_time: 0,
            has_died: false,
            extra_data: Vec::new(),
            portraits: CrewPortraitState::default(),
        };
        state.entries.insert(link, entry.clone());
        state.order.entry(player).or_default().insert(0, link);
        (link, entry)
    };
    let info = CrewObjectInfo {
        definition_id: DefinitionId::from(entry.id.as_str()),
        name: entry.name.clone(),
        death_message: entry.death_message.clone(),
        core: entry.core.clone(),
        rank: entry.rank,
        rank_name: entry.rank_name.clone(),
        experience: entry.experience,
        participation: entry.participation,
        rounds: entry.rounds,
        death_count: entry.death_count,
        total_playing_time: entry.total_playing_time,
        birthday: entry.birthday,
        age: entry.age,
        in_action_time: entry.in_action_time,
        extra_data: entry.extra_data.clone(),
        portraits: entry.portraits.clone(),
    };
    if let Some(player) = context.player_state_mut(player) {
        player.crew_created = player.crew_created.wrapping_add(1);
    }
    Ok(Some((link, info, Some(entry), physical)))
}

/// Direct C4Player::MakeCrewMember mutation. Native callers such as Buy must
/// not dispatch a definition function named MakeCrewMember on the target.
fn make_crew_member_live(target: ObjectId, player: i32) -> Result<bool, RuntimeError> {
    let joined = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(false);
        };
        if context.player_state(player).is_none() {
            return Ok(false); // ValidPlr (C4Script.cpp:2166)
        }
        if !context.object_status_present(target) || !context.ensure_object_scope(target) {
            return Ok(false); // !pObj->Status (C4Player.cpp:1169)
        }
        let crew_def = context
            .object_effective_definition_id(target)
            .and_then(|definition| context.world.definition_metadata(&definition))
            .map(|metadata| metadata.crew_member)
            .unwrap_or(false);
        if !crew_def {
            return Ok(false); // Def->CrewMember required (C4Player.cpp:1170)
        }
        // C4Player::MakeCrewMember info selection (C4Player.cpp:1180-1199):
        // the gate is `!pObj->Info` — an object that already carries a crew
        // info skips; an idle info skips the New; otherwise
        // C4ObjectInfoList::New draws the name Random over the def's
        // ClonkNames (or the game standard names) — a synced ledger draw
        // that must fire INSIDE this call.
        let already_has_info = context
            .object_scope(target)
            .is_some_and(|object| object.info_rank().is_some());
        let assignment = if already_has_info {
            None
        } else {
            let Some(definition_id) = context.object_effective_definition_id(target) else {
                return Ok(false);
            };
            recruit_or_create_crew_info(context, player, definition_id.as_str())?
        };
        {
            let Some(object) = context.object_scope_mut(target) else {
                return Ok(false);
            };
            object.set_crew_member(true);
            if object.plr_view_range() == 0 {
                object.set_plr_view_range(500);
            }
            if let Some((link, info, _, info_physical)) = assignment.as_ref() {
                object.set_info_rank(Some(info.rank));
                object.set_info_link(Some(*link));
                object.set_info_core(Some(info.clone()));
                object.info_physical = Some(*info_physical);
                object.info_definition_physical = Some(object.definition_physical);
                object.record_physicals();
            }
            // C4Player::MakeCrewMember changes Controller, never Owner
            // (C4Player.cpp:1202-1204).
            object.set_controller(player);
        }
        context.refresh_scope_fair_crew(target);
        if let Some((link, info, created_entry, _)) = assignment {
            context.record_player_command(PlayerCommand::LinkCrewInfo {
                object_id: target,
                link: Some(link),
                info,
                created_entry,
                recruit: true,
                has_died: false,
            });
        }
        // C4Player::MakeCrewMember inserts into the LIVE C4Player::Crew
        // before Recruitment returns (C4Player.cpp:1194-1209). Later calls
        // in the same scenario callback must therefore see the member via
        // SelectCrew/GetCrew. Crew-member definitions take stMain's ordinary
        // category/id branch: prefer the first equal category+id link, then
        // the first link whose relative category is <= the new one
        // (C4ObjectList.cpp:110-195).
        if !context.insert_player_crew(player, target) {
            return Ok(false);
        }
        context.record_crew_rosters();
        Ok(true)
    })?;
    if joined {
        // PSF_OnJoinCrew resolves to the script function "Recruitment"
        // (C4Script.h:107 `#define PSF_OnJoinCrew "~Recruitment"`), fired
        // inside MakeCrewMember (C4Player.cpp:1206-1209). C4Object::Call's
        // default fPassError=false makes it fail-safe.
        call_recruitment_callback(target, player);
    }
    Ok(joined)
}

fn make_crew_member(args: &[Value]) -> Result<Value, RuntimeError> {
    let explicit = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "MakeCrewMember",
        "obj",
    )?;
    let player = parse_optional_i32(args.get(1), "MakeCrewMember", "player")?.unwrap_or(0);
    // FnMakeCrewMember passes pObj through unchanged; unlike several local
    // natives it never substitutes cthr->Obj for nil. AB_CALL only changes
    // the call context and likewise does not inject its receiver into pObj.
    let Some(target) = explicit else {
        return Ok(Value::Bool(false));
    };
    Ok(Value::Bool(make_crew_member_live(target, player)?))
}

/// FnSetMass (C4Script.cpp:3620-3626): OwnMass = value - Def->Mass, then
/// UpdateMass; foreign targets mutate in their own scope.
fn set_mass(args: &[Value]) -> Result<Value, RuntimeError> {
    let value = parse_optional_i32(args.first(), "SetMass", "mass")?.unwrap_or(0);
    let target =
        parse_object_reference_argument(args.get(1).unwrap_or(&Value::Nil), "SetMass", "obj")?;
    let active = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_context().map(|object| object.id()))
    });
    if let Some(target) = target {
        if Some(target) != active {
            return match call_world_object_function(target, "SetMass", &[Value::Int(value)]) {
                Some(result) => result,
                None => Ok(Value::Bool(false)),
            };
        }
    }
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let Some(id) = context.object_context().map(|object| object.id()) else {
            return Ok(Value::Bool(false));
        };
        // The scope's own definition id — a synchronous Initialize (the
        // ArrowPack UpdateMass at CreateContents) runs before the object
        // reaches the world/pending views, so get_world_object misses it
        // and OwnMass = iValue - Def->Mass (C4Script.cpp:3627-3631)
        // silently lost the Def->Mass term.
        let def_mass = context
            .object_context()
            .and_then(|object| object.definition_id.clone())
            .and_then(|definition_id| {
                context
                    .world
                    .definition_metadata(&definition_id)
                    .map(|metadata| metadata.mass)
            })
            .or_else(|| {
                context
                    .get_world_object(id)
                    .and_then(|object| context.world.definition_metadata(object.definition_id()))
                    .map(|metadata| metadata.mass)
            })
            .unwrap_or(0);
        let Some(object) = context.object_context_mut() else {
            return Ok(Value::Bool(false));
        };
        object.set_own_mass(value - def_mass);
        Ok(Value::Bool(true))
    })
}

/// FnMod (C4Script.cpp:3219-3223): truncated `%`, zero divisor yields 0.
fn modulo(args: &[Value]) -> Result<Value, RuntimeError> {
    let value = parse_optional_i32(args.first(), "Mod", "value")?.unwrap_or(0);
    let divisor = parse_optional_i32(args.get(1), "Mod", "divisor")?.unwrap_or(0);
    Ok(Value::Int(if divisor == 0 {
        0
    } else {
        value.wrapping_rem(divisor)
    }))
}

/// FnC4Id (C4Script.cpp:2396-2399): string to C4ID; empty/nil is C4ID_None
/// (0 — falsy, like C4Id("") in C++).
fn c4_id(args: &[Value]) -> Result<Value, RuntimeError> {
    let name = parse_optional_string(args.first(), "C4Id", "id")?;
    Ok(match name {
        Some(name) if clonk_script::c4_id_parse(&name) != 0 => {
            Value::C4Id(clonk_script::c4_id_from_raw(clonk_script::c4_id_parse(&name)))
        }
        _ => Value::Nil,
    })
}

/// `C4AulDefCastFunc<C4V_C4ID,C4V_Int>` (C4Script.cpp:6184-6195,
/// :7042): preserve the four-byte C4ID payload and change only its type tag.
fn scoreboard_col(args: &[Value]) -> Result<Value, RuntimeError> {
    let raw = parse_native_c4id_argument(args.first(), "ScoreboardCol")?
        .as_deref()
        .map(cast_c4id_payload)
        .unwrap_or(0) as i32;
    Ok(Value::Int(raw))
}

fn pow_func(args: &[Value]) -> Result<Value, RuntimeError> {
    let base = value_to_i32(args.first().unwrap_or(&Value::Nil), "Pow", "base")?;
    let exponent = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "Pow",
        "exponent",
    )?;

    if exponent < 0 {
        return Ok(Value::Int(0)); // Match C++ behavior for negative exponents
    }

    Ok(Value::Int(base.wrapping_pow(exponent as u32)))
}

fn bound_by_func(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() != 3 {
        return Err(RuntimeError::new(
            "BoundBy expects 3 arguments: value, min, max",
        ));
    }

    let value = match &args[0] {
        Value::Int(v) => *v,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "BoundBy: expected int for value, got {}",
                other.type_name()
            )));
        }
    };

    let range1 = match &args[1] {
        Value::Int(v) => *v,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "BoundBy: expected int for range1, got {}",
                other.type_name()
            )));
        }
    };

    let range2 = match &args[2] {
        Value::Int(v) => *v,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "BoundBy: expected int for range2, got {}",
                other.type_name()
            )));
        }
    };

    // BoundBy clamps value between range1 and range2 (order doesn't matter)
    let min = range1.min(range2);
    let max = range1.max(range2);
    Ok(Value::Int(value.clamp(min, max)))
}

pub(crate) fn sin_func(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.is_empty() || args.len() > 3 {
        return Err(RuntimeError::new(
            "Sin expects 1-3 arguments: angle, radius, precision",
        ));
    }

    let angle = match &args[0] {
        Value::Int(v) => *v,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "Sin: expected int for angle, got {}",
                other.type_name()
            )));
        }
    };

    let radius = if args.len() > 1 {
        match &args[1] {
            Value::Int(v) => *v,
            Value::Nil => 0,
            other => {
                return Err(RuntimeError::new(format!(
                    "Sin: expected int for radius, got {}",
                    other.type_name()
                )));
            }
        }
    } else {
        0
    };

    let precision = if args.len() > 2 {
        match &args[2] {
            Value::Int(v) => {
                if *v == 0 {
                    1
                } else {
                    *v
                }
            }
            Value::Nil => 1,
            other => {
                return Err(RuntimeError::new(format!(
                    "Sin: expected int for precision, got {}",
                    other.type_name()
                )));
            }
        }
    } else {
        1
    };

    // FnSin uses C4Fixed's shared SineTable; no floating-point arithmetic is
    // allowed on this lockstep path (C4Script.cpp:3224-3231; Fixed.h:188-202).
    let angle_mod = angle % (360 * precision);
    let result = fixtoi_prec(itofix_prec(angle_mod, precision).sin_deg(), radius);
    Ok(Value::Int(result))
}

pub(crate) fn cos_func(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.is_empty() || args.len() > 3 {
        return Err(RuntimeError::new(
            "Cos expects 1-3 arguments: angle, radius, precision",
        ));
    }

    let angle = match &args[0] {
        Value::Int(v) => *v,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "Cos: expected int for angle, got {}",
                other.type_name()
            )));
        }
    };

    let radius = if args.len() > 1 {
        match &args[1] {
            Value::Int(v) => *v,
            Value::Nil => 0,
            other => {
                return Err(RuntimeError::new(format!(
                    "Cos: expected int for radius, got {}",
                    other.type_name()
                )));
            }
        }
    } else {
        0
    };

    let precision = if args.len() > 2 {
        match &args[2] {
            Value::Int(v) => {
                if *v == 0 {
                    1
                } else {
                    *v
                }
            }
            Value::Nil => 1,
            other => {
                return Err(RuntimeError::new(format!(
                    "Cos: expected int for precision, got {}",
                    other.type_name()
                )));
            }
        }
    } else {
        1
    };

    // FnCos uses the same fixed-point table and scaling path
    // (C4Script.cpp:3233-3238; Fixed.h:204-218).
    let angle_mod = angle % (360 * precision);
    let result = fixtoi_prec(itofix_prec(angle_mod, precision).cos_deg(), radius);
    Ok(Value::Int(result))
}

