fn get_energy(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "GetEnergy expects at most 1 argument: target",
        ));
    }

    let mut target_id: Option<ObjectId> = None;
    if let Some(arg) = args.first() {
        target_id = parse_object_reference_argument(arg, "GetEnergy", "target")?;
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        if let Some(target) = target_id {
            if let Some(object) = context.object_context() {
                if object.id() == target {
                    return Ok(Value::Int(energy_to_script_value(object.energy())));
                }
            }
            if let Some(other) = context.get_world_object(target) {
                return Ok(Value::Int(energy_to_script_value(other.energy())));
            }
            return Ok(Value::Nil);
        }

        let object = match context.object_context() {
            Some(object) => object,
            None => return Ok(Value::Nil),
        };

        Ok(Value::Int(energy_to_script_value(object.energy())))
    })
}

/// FnDoBreath (C4Script.cpp:502-506) and C4Object::DoBreath
/// (C4Object.cpp:1406-1413): default the target to the calling object,
/// scale script points by C4MaxPhysical/100, then clamp the live raw value
/// into 0..GetPhysical()->Breath.
fn do_breath(args: &[Value]) -> Result<Value, RuntimeError> {
    let change = value_to_i32(args.first().unwrap_or(&Value::Nil), "DoBreath", "change")?;
    let target_id =
        parse_object_reference_argument(args.get(1).unwrap_or(&Value::Nil), "DoBreath", "target")?;
    let target = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("DoBreath requires an active engine context"))?;
        let Some(target) = target_id.or_else(|| context.object_context().map(|object| object.id()))
        else {
            return Ok(None);
        };
        if !context.ensure_object_scope(target) {
            return Ok(None);
        }
        Ok(Some(target))
    })?;
    let Some(target) = target else {
        return Ok(Value::Bool(false));
    };
    let Some(capacity) =
        resolve_object_physical(target, false).map(|physical| physical.breath.max(0))
    else {
        return Ok(Value::Bool(false));
    };
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("DoBreath requires an active engine context"))?;
        let Some(scope) = context.object_scope_mut(target) else {
            return Ok(Value::Bool(false));
        };
        let scaled = change.saturating_mul(LEGACY_MAX_PHYSICAL / 100);
        let breath = scope.breath().saturating_add(scaled).clamp(0, capacity);
        scope.set_breath(breath);
        Ok(Value::Bool(true))
    })
}

/// FnGetBreath (C4Script.cpp:1143-1146): `100 * Breath / C4MaxPhysical`.
/// A scope-local staged write wins over the frame-start world snapshot, as
/// C++ mutates C4Object::Breath synchronously.
fn get_breath(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut index = 0;
    let target_id =
        consume_optional_object_reference_argument(args, &mut index, "GetBreath", "target")?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };
        let target = target_id.or_else(|| context.object_context().map(|object| object.id()));
        let Some(target) = target else {
            return Ok(Value::Nil);
        };
        let breath = context
            .object_scope(target)
            .map(ObjectScopeContext::breath)
            .or_else(|| {
                context
                    .get_world_object(target)
                    .and_then(|object| object.full_state().map(|state| state.breath))
            });
        match breath {
            Some(breath) => Ok(Value::Int(
                (100i64 * i64::from(breath) / i64::from(LEGACY_MAX_PHYSICAL)) as i32,
            )),
            None => Ok(Value::Nil),
        }
    })
}

/// FnGetName (C4Script.cpp:992-1005): the definition Name for an id
/// argument; otherwise CustomName, live Info name, then definition name.
fn get_name(args: &[Value]) -> Result<Value, RuntimeError> {
    let target_id = args
        .first()
        .map(|value| parse_object_reference_argument(value, "GetName", "target"))
        .transpose()?
        .flatten();
    let def_id = parse_native_c4id_argument(args.get(1), "GetName")?.filter(|id| !id.is_empty());
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        if let Some(definition) = def_id {
            return Ok(context
                .definition_metadata(&definition)
                .map(|metadata| Value::String(metadata.name.clone().into()))
                .unwrap_or(Value::Nil));
        }
        let Some(target) = target_id.or_else(|| context.object_context().map(|object| object.id()))
        else {
            return Ok(Value::Nil);
        };
        Ok(context
            .object_effective_name(target)
            .map(|name| Value::String(name.into()))
            .unwrap_or(Value::Nil))
    })
}

/// FnGetDesc (C4Script.cpp:1063-1076): an explicit object wins over the
/// definition argument. The caller object is used only when both slots are
/// nil/zero; definition-only script contexts do not supply a fallback.
fn get_desc(args: &[Value]) -> Result<Value, RuntimeError> {
    let target =
        parse_object_reference_argument(args.first().unwrap_or(&Value::Nil), "GetDesc", "object")?;
    let definition =
        parse_native_c4id_argument(args.get(1), "GetDesc")?.filter(|id| !id.is_empty());
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let definition = match (target, definition) {
            (Some(target), _) => context.object_effective_definition_id(target),
            (None, Some(definition)) => Some(definition),
            (None, None) => context
                .script_object_context
                .and_then(|target| context.object_effective_definition_id(target)),
        };
        Ok(definition
            .as_deref()
            .and_then(|id| context.world.definition_description(id))
            .map(|description| Value::String(description.to_owned().into()))
            .unwrap_or(Value::Nil))
    })
}

const C4_MAX_NAME_BYTES: usize = 30;

/// `C4ObjectInfoList::MakeValidName` (C4ObjectInfoList.cpp:93-101): keep the
/// requested name as the fixed base, replace its tail with 2, 3, ... and
/// choose the first case-insensitively unused candidate.
fn make_valid_crew_name(requested: &str, existing: &[String]) -> String {
    let requested_bytes = clonk_script::c4_string_bytes(requested);
    let mut candidate = requested.to_owned();
    let mut suffix = 2u64;
    while existing.iter().any(|name| {
        c4_bytes_equal_no_case(
            &clonk_script::c4_string_bytes(name),
            &clonk_script::c4_string_bytes(&candidate),
        )
    }) {
        let suffix_text = suffix.to_string();
        let keep = requested_bytes
            .len()
            .min(C4_MAX_NAME_BYTES.saturating_sub(suffix_text.len()));
        candidate = clonk_script::c4_string_from_bytes(&requested_bytes[..keep]);
        candidate.push_str(&suffix_text);
        suffix += 1;
    }
    candidate
}

/// FnSetName (C4Script.cpp:1008-1061): rename a definition, persist a crew
/// info name with owner-list duplicate handling, or set an object's transient
/// CustomName. A missing object defaults to the calling object.
fn set_name(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 5 {
        return Err(RuntimeError::new(
            "SetName expects at most 5 arguments: name, object, definition, set-in-info, make-valid",
        ));
    }
    let requested_name = parse_optional_string(args.first(), "SetName", "name")?;
    let target_id = args
        .get(1)
        .map(|value| parse_object_reference_argument(value, "SetName", "target"))
        .transpose()?
        .flatten();
    let definition =
        parse_native_c4id_argument(args.get(2), "SetName")?.filter(|id| !id.is_empty());
    let set_in_info = args
        .get(3)
        .map(|value| value_to_bool(value, "SetName", "set-in-info"))
        .transpose()?
        .unwrap_or(false);
    let make_valid = args
        .get(4)
        .map(|value| value_to_bool(value, "SetName", "make-valid"))
        .transpose()?
        .unwrap_or(false);

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        if set_in_info && definition.is_some() {
            return Ok(Value::Bool(false));
        }
        if let Some(definition) = definition {
            return Ok(Value::Bool(context.set_definition_name(
                definition,
                requested_name.unwrap_or_default(),
            )));
        }
        let Some(target) = target_id.or_else(|| context.object_context().map(|object| object.id()))
        else {
            return Ok(Value::Bool(false));
        };

        if set_in_info {
            if !context.ensure_object_scope(target) {
                return Ok(Value::Bool(false));
            }
            let Some((owner, link, old_name)) = context.object_scope(target).and_then(|scope| {
                Some((
                    scope.owner(),
                    scope.info_link(),
                    scope.info_core()?.name.clone(),
                ))
            }) else {
                return Ok(Value::Bool(false));
            };
            let Some(requested_name) = requested_name else {
                return Ok(Value::Bool(false));
            };
            if requested_name.is_empty()
                || clonk_script::c4_string_byte_len(&requested_name) > C4_MAX_NAME_BYTES
            {
                return Ok(Value::Bool(false));
            }
            if clonk_script::c4_strings_equal(&requested_name, &old_name) {
                return Ok(Value::Bool(true));
            }

            let owner_names = if context.player_state(owner).is_some() {
                context
                    .world
                    .crew_info_state
                    .borrow()
                    .roster_names
                    .get(&owner)
                    .cloned()
                    .unwrap_or_default()
            } else {
                Vec::new()
            };
            let duplicate = owner_names.iter().any(|name| {
                c4_bytes_equal_no_case(
                    &clonk_script::c4_string_bytes(name),
                    &clonk_script::c4_string_bytes(&requested_name),
                )
            });
            if duplicate && !make_valid {
                return Ok(Value::Bool(false));
            }
            let final_name = if duplicate {
                make_valid_crew_name(&requested_name, &owner_names)
            } else {
                requested_name
            };

            let Some(scope) = context.object_scope_mut(target) else {
                return Ok(Value::Bool(false));
            };
            let Some(mut info) = scope.info_core().cloned() else {
                return Ok(Value::Bool(false));
            };
            info.name = final_name.clone();
            scope.set_info_core(Some(info));
            // pObj->SetName() with no argument adopts Info->Name by clearing
            // any transient CustomName override.
            scope.pending_update.custom_name = Some(None);
            if let Some(link) = link {
                let mut state = context.world.crew_info_state.borrow_mut();
                if let Some(entry) = state.entries.get_mut(&link) {
                    entry.name = final_name.clone();
                }
                if let Some(name) = state
                    .roster_names
                    .get_mut(&link.player_id)
                    .and_then(|names| names.get_mut(link.roster_index))
                {
                    *name = final_name.clone();
                }
                for entries in state.idle.values_mut() {
                    for (candidate, entry) in entries {
                        if *candidate == link {
                            entry.name = final_name.clone();
                        }
                    }
                }
            }
            context.record_player_command(PlayerCommand::SetCrewInfoName {
                object_id: target,
                link,
                name: final_name,
            });
            return Ok(Value::Bool(true));
        }

        let custom_name = requested_name.filter(|name| !name.is_empty());
        Ok(Value::Bool(
            context.set_object_custom_name(target, custom_name),
        ))
    })
}

fn get_con(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "GetCon expects at most 1 argument: target",
        ));
    }

    let mut target_id: Option<ObjectId> = None;
    if let Some(arg) = args.first() {
        target_id = parse_object_reference_argument(arg, "GetCon", "target")?;
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        if let Some(target) = target_id {
            if let Some(object) = context.object_scope(target) {
                return Ok(Value::Int(construction_to_script_value(
                    object.construction(),
                )));
            }
            if let Some(other) = context.get_world_object(target) {
                return Ok(Value::Int(construction_to_script_value(
                    other.construction(),
                )));
            }
            return Ok(Value::Nil);
        }

        let object = match context.object_context() {
            Some(object) => object,
            None => return Ok(Value::Nil),
        };

        Ok(Value::Int(construction_to_script_value(
            object.construction(),
        )))
    })
}

/// A physical name argument (`FnStringPar`): None for Nil/absent/empty.
fn physical_name_argument(
    args: &[Value],
    index: usize,
    fn_name: &str,
) -> Result<Option<String>, RuntimeError> {
    match args.get(index) {
        Some(Value::String(name)) if !name.is_empty() => {
            Ok(Some(name.as_ref().to_owned()))
        }
        Some(Value::String(_)) | Some(Value::Nil) | None => Ok(None),
        Some(other) => Err(RuntimeError::new(format!(
            "{fn_name}: expected string for physical name, got {}",
            other.type_name()
        ))),
    }
}

fn int_argument(args: &[Value], index: usize, fn_name: &str) -> Result<i32, RuntimeError> {
    match args.get(index) {
        Some(Value::Int(value)) => Ok(*value),
        Some(Value::Nil) | None => Ok(0),
        Some(other) => Err(RuntimeError::new(format!(
            "{fn_name}: expected int, got {}",
            other.type_name()
        ))),
    }
}

/// Resolve a live object's physicals without retaining a borrow of the host
/// TLS across a possible first-fill definition callback.
fn resolve_object_physical(target: ObjectId, permanent: bool) -> Option<PhysicalInfo> {
    let resolution = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.prepare_object_physical(target, permanent))
    });
    resolution.map(PhysicalResolution::resolve)
}

/// `FnGetPhysical` (C4Script.cpp:638-688): `GetPhysical(name, mode, obj,
/// id)`. The def form reads the definition's `[Physical]` section; object
/// reads resolve against the explicitly targeted live object.
fn get_physical(args: &[Value]) -> Result<Value, RuntimeError> {
    let name = physical_name_argument(args, 0, "GetPhysical")?;
    let mode = int_argument(args, 1, "GetPhysical")?;
    let target_id = args
        .get(2)
        .map(|arg| parse_object_reference_argument(arg, "GetPhysical", "target"))
        .transpose()?
        .flatten();
    let definition_id =
        parse_native_c4id_argument(args.get(3), "GetPhysical")?.filter(|id| !id.is_empty());
    let Some(name) = name else {
        return Ok(Value::Nil);
    };
    // No object given: a def id reads the definition physicals
    // (C4Script.cpp:644-653). This path cannot enter fair-crew projection.
    if target_id.is_none() {
        if let Some(definition_id) = definition_id.as_deref() {
            return Ok(HOST_CONTEXT.with(|cell| {
                cell.borrow()
                    .as_ref()
                    .and_then(|context| context.world.definition_metadata(definition_id))
                    .and_then(|metadata| metadata.physical.value_by_name(&name))
                    .map(Value::Int)
                    .unwrap_or(Value::Nil)
            }));
        }
    }

    let resolution = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let target = target_id.or_else(|| context.object_context().map(ObjectScopeContext::id));
        let target = target?;
        if let Some(object) = context.object_scope(target) {
            return object.prepare_get_physical(mode);
        }
        // An explicit pObj is not constrained to cthr->Obj: FnGetPhysical
        // dereferences that live object directly (C4Script.cpp:638-688).
        // Build the same read-only scope used for nested object calls so
        // crew info and temporary physicals retain their normal precedence.
        context
            .get_world_object(target)
            .and_then(|object| context.nested_scope_for(&object))
            .and_then(|(object, _)| object.prepare_get_physical(mode))
    });
    Ok(resolution
        .map(PhysicalResolution::resolve)
        .and_then(|physical| physical.value_by_name(&name))
        .map(Value::Int)
        .unwrap_or(Value::Nil))
}

/// `FnSetPhysical` (C4Script.cpp:557-601): `SetPhysical(name, value, mode,
/// obj)`.
fn set_physical(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some(name) = physical_name_argument(args, 0, "SetPhysical")? else {
        return Ok(Value::Bool(false));
    };
    if PhysicalInfo::default().value_mut_by_name(&name).is_none() {
        return Ok(Value::Bool(false));
    }
    let value = int_argument(args, 1, "SetPhysical")?;
    let mode = int_argument(args, 2, "SetPhysical")?;
    let target_id = args
        .get(3)
        .map(|arg| parse_object_reference_argument(arg, "SetPhysical", "target"))
        .transpose()?
        .flatten();

    let prepared = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetPhysical requires an active engine context"))?;
        let target = target_id.or_else(|| context.object_context().map(ObjectScopeContext::id));
        let Some(target) = target else {
            return Ok(None);
        };
        if context.object_scope(target).is_none() && !context.ensure_object_scope(target) {
            return Ok(None);
        }
        let Some(object) = context.object_scope_mut(target) else {
            return Ok(None);
        };
        let base = matches!(mode, PHYS_TEMPORARY | PHYS_STACK_TEMPORARY)
            .then(|| {
                object
                    .temporary_physical
                    .is_none()
                    .then(|| object.prepare_resolved_physical(false))
            })
            .flatten();
        Ok(Some((target, base)))
    })?;
    let Some((target, base)) = prepared else {
        return Ok(Value::Bool(false));
    };
    let base = base.map(PhysicalResolution::resolve);
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetPhysical requires an active engine context"))?;
        Ok(Value::Bool(context.object_scope_mut(target).is_some_and(
            |object| object.set_physical(&name, value, mode, base),
        )))
    })
}

/// `FnTrainPhysical` (C4Script.cpp:603-611): `TrainPhysical(name, by, max,
/// obj)`.
fn train_physical(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some(name) = physical_name_argument(args, 0, "TrainPhysical")? else {
        return Ok(Value::Bool(false));
    };
    let train_by = int_argument(args, 1, "TrainPhysical")?;
    let max_train = int_argument(args, 2, "TrainPhysical")?;
    let target_id = args
        .get(3)
        .map(|arg| parse_object_reference_argument(arg, "TrainPhysical", "target"))
        .transpose()?
        .flatten();

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("TrainPhysical requires an active engine context"))?;
        let target = target_id.or_else(|| context.object_context().map(ObjectScopeContext::id));
        let Some(target) = target else {
            return Ok(Value::Bool(false));
        };
        if context.object_scope(target).is_none() && !context.ensure_object_scope(target) {
            return Ok(Value::Bool(false));
        }
        let (trained, info_writeback) = {
            let Some(object) = context.object_scope_mut(target) else {
                return Ok(Value::Bool(false));
            };
            let has_info = object.has_physical_info();
            let trained = object.train_physical(&name, train_by, max_train);
            let info_writeback = (has_info && trained)
                .then(|| object.info_link().zip(object.info_physical))
                .flatten();
            (trained, info_writeback)
        };
        if let Some((link, physical)) = info_writeback {
            // The host mirrors the exact roster node so a later Retire,
            // GrabObjectInfo or MakeCrewMember in this same VM call sees the
            // trained values before the copied outcome reaches Engine.
            let mut state = context.world.crew_info_state.borrow_mut();
            if let Some(entry) = state.entries.get_mut(&link) {
                entry.physical = physical;
            }
            for entries in state.idle.values_mut() {
                for (candidate, entry) in entries {
                    if *candidate == link {
                        entry.physical = physical;
                    }
                }
            }
            drop(state);
            context.record_player_command(PlayerCommand::SetCrewInfoPhysical { link, physical });
        }
        Ok(Value::Bool(trained))
    })
}

/// `FnResetPhysical` (C4Script.cpp:613-636): `ResetPhysical(obj, name)` —
/// the object comes FIRST in this one.
fn reset_physical(args: &[Value]) -> Result<Value, RuntimeError> {
    let target_id = args
        .first()
        .map(|arg| parse_object_reference_argument(arg, "ResetPhysical", "target"))
        .transpose()?
        .flatten();
    let name = physical_name_argument(args, 1, "ResetPhysical")?;

    let prepared = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("ResetPhysical requires an active engine context"))?;
        let target = target_id.or_else(|| context.object_context().map(ObjectScopeContext::id));
        let Some(target) = target else {
            return Ok(None);
        };
        if context.object_scope(target).is_none() && !context.ensure_object_scope(target) {
            return Ok(None);
        }
        Ok(context
            .object_scope_mut(target)
            .map(|object| (target, object.begin_reset_physical(name.as_deref()))))
    })?;
    let Some((target, step)) = prepared else {
        return Ok(Value::Bool(false));
    };
    match step {
        ResetPhysicalBegin::Complete(result) => return Ok(Value::Bool(result)),
        ResetPhysicalBegin::ComparePermanent => {}
    }
    let Some(reference) = resolve_object_physical(target, true) else {
        return Ok(Value::Bool(false));
    };
    Ok(Value::Bool(HOST_CONTEXT.with(|cell| {
        cell.borrow_mut()
            .as_mut()
            .and_then(|context| context.object_scope_mut(target))
            .is_some_and(|object| object.finish_reset_physical(reference))
    })))
}

fn do_energy(args: &[Value]) -> Result<Value, RuntimeError> {
    do_energy_with_cause_override(args, None)
}

/// Internal engine callers already have the decoded player number and must
/// be able to pass explicit NO_OWNER; the public script ABI reserves encoded
/// zero for its caller-controller default.
fn do_energy_with_cause_override(
    args: &[Value],
    caused_by_override: Option<i32>,
) -> Result<Value, RuntimeError> {
    let change = match args.first().unwrap_or(&Value::Nil) {
        Value::Int(value) => *value,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "DoEnergy: expected int or nil for change, got {}",
                other.type_name()
            )));
        }
    };

    let mut index = 1;
    let mut target_id: Option<ObjectId> = None;

    if let Some(arg) = args.get(index) {
        match arg {
            Value::Object(_) | Value::Proplist(_) => {
                target_id = object_id_from_value(arg);
                index += 1;
            }
            Value::Nil => {
                index += 1;
            }
            Value::Int(value) if *value == 0 => {
                index += 1;
            }
            Value::Int(value) if *value > 0 => {
                target_id = Some(ObjectId::new(*value as u64));
                index += 1;
            }
            _ => {}
        }
    }

    let mut exact = false;
    if let Some(arg) = args.get(index) {
        match arg {
            Value::Bool(flag) => {
                exact = *flag;
                index += 1;
            }
            Value::Int(value) => {
                exact = *value != 0;
                index += 1;
            }
            Value::Nil => {
                index += 1;
            }
            other => {
                return Err(RuntimeError::new(format!(
                    "DoEnergy: expected bool, int, or nil for exact flag, got {}",
                    other.type_name()
                )));
            }
        }
    }

    let mut eng_type = 0;
    if let Some(arg) = args.get(index) {
        match arg {
            Value::Int(value) => {
                eng_type = *value;
                index += 1;
            }
            Value::Nil => {
                index += 1;
            }
            other => {
                return Err(RuntimeError::new(format!(
                    "DoEnergy: expected int or nil for cause, got {}",
                    other.type_name()
                )));
            }
        }
    }
    // C4FxCall_EngScript default (C4Script.cpp:495).
    if eng_type == 0 {
        eng_type = crate::C4FX_CALL_ENG_SCRIPT;
    }

    let mut caused_by_plus_one = 0;
    if let Some(arg) = args.get(index) {
        match arg {
            Value::Int(value) => {
                caused_by_plus_one = *value;
                index += 1;
            }
            Value::Nil => {
                index += 1;
            }
            other => {
                return Err(RuntimeError::new(format!(
                    "DoEnergy: expected int or nil for caused by, got {}",
                    other.type_name()
                )));
            }
        }
    }

    if index < args.len() {
        return Err(RuntimeError::new(
            "DoEnergy: additional arguments are not supported",
        ));
    }

    let staged = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("DoEnergy requires an active engine context"))?;
        // iCausedBy = iCausedByPlusOne - 1, else the CALLER's controller
        // (C4Script.cpp:496-497) — resolved in the caller's scope.
        let caused_by = caused_by_override.unwrap_or_else(|| {
            if caused_by_plus_one != 0 {
                caused_by_plus_one - 1
            } else {
                context
                    .object_context()
                    .map(|object| object.controller())
                    .unwrap_or(OWNER_NONE)
            }
        });
        // `if (!pObj) pObj = cthr->Obj` is only the local-call default
        // (C4Script.cpp:494) — a named target may be FOREIGN.
        let Some(target) = target_id.or_else(|| context.object_context().map(|o| o.id())) else {
            return Ok(None);
        };
        if !context.ensure_object_scope(target) {
            return Ok(None);
        }
        // Kill-trace mark before the effects hook (C4Object.cpp:1351-1353).
        stage_energy_loss_cause(context, target, change, eng_type, caused_by);
        let Some(scope) = context.object_scope(target) else {
            return Ok(None);
        };
        Ok(Some((target, caused_by, scope.alive())))
    })?;
    let Some((target, caused_by, alive)) = staged else {
        return Ok(Value::Bool(false));
    };
    // The percent scale precedes the effects hook (C4Object.cpp:1347 vs
    // :1355): living targets' hooks see the SCALED change, and a zero
    // chain outcome returns before the energy write (:1358).
    let scaled = if exact {
        change
    } else {
        change.saturating_mul(LEGACY_MAX_PHYSICAL / 100)
    };
    let scaled = match alive
        .then(|| dispatch_effects_do_damage(target, scaled, eng_type, caused_by))
        .flatten()
    {
        Some(0) => return Ok(Value::Bool(true)),
        Some(modified) => modified,
        None => scaled,
    };
    let Some(max_energy) = resolve_object_physical(target, false).map(|physical| physical.energy)
    else {
        return Ok(Value::Bool(false));
    };
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        if let Some(scope) = context.object_scope_mut(target) {
            scope.adjust_energy(scaled, true, max_energy);
        }
    });
    Ok(Value::Bool(true))
}

/// `MagicPhysicalFactor` (C4Object.h:81): raw MagicEnergy units per
/// script-visible magic point.
const MAGIC_PHYSICAL_FACTOR: i32 = 1000;

/// Reads DoMagicEnergy/GetMagicEnergy's optional object slot: object
/// references, positive ints (object numbers), or nil/0 for the
/// caller-object default.
fn magic_energy_target(
    arg: Option<&Value>,
    function: &str,
) -> Result<Option<ObjectId>, RuntimeError> {
    match arg.unwrap_or(&Value::Nil) {
        value @ (Value::Object(_) | Value::Proplist(_)) => Ok(object_id_from_value(value)),
        Value::Nil | Value::Int(0) => Ok(None),
        Value::Int(value) if *value > 0 => Ok(Some(ObjectId::new(*value as u64))),
        other => Err(RuntimeError::new(format!(
            "{function}: expected object or nil for target, got {}",
            other.type_name()
        ))),
    }
}

/// `FnDoMagicEnergy` (C4Script.cpp:517-544): the change scales by
/// MagicPhysicalFactor; an overload (change > 0 past GetPhysical()->Magic)
/// or underload (change < 0 past zero) fails the call unless
/// fAllowPartial clamps it to the remaining headroom — a zero remainder
/// still fails. The result bounds into 0..GetPhysical()->Magic
/// (BoundBy, :541). ViewEnergy = C4ViewDelay (:542) is the magic-bar
/// display flash — presentation-only, not modeled.
fn do_magic_energy(args: &[Value]) -> Result<Value, RuntimeError> {
    let change = match args.first().unwrap_or(&Value::Nil) {
        Value::Int(value) => *value,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "DoMagicEnergy: expected int or nil for change, got {}",
                other.type_name()
            )));
        }
    };
    let target_id = magic_energy_target(args.get(1), "DoMagicEnergy")?;
    let allow_partial = match args.get(2).unwrap_or(&Value::Nil) {
        Value::Bool(flag) => *flag,
        Value::Int(value) => *value != 0,
        Value::Nil => false,
        other => {
            return Err(RuntimeError::new(format!(
                "DoMagicEnergy: expected bool or nil for allow-partial flag, got {}",
                other.type_name()
            )));
        }
    };

    let target = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("DoMagicEnergy requires an active engine context"))?;
        // `if (!pObj) pObj = cthr->Obj; if (!pObj) return false` (:519).
        let Some(target) = target_id.or_else(|| context.object_context().map(|o| o.id())) else {
            return Ok(None);
        };
        if !context.ensure_object_scope(target) {
            return Ok(None);
        }
        Ok(Some(target))
    })?;
    let Some(target) = target else {
        return Ok(Value::Bool(false));
    };
    // C++ arithmetic is plain i32 (wrapping on x86) — keep it exact.
    let mut change = change.wrapping_mul(MAGIC_PHYSICAL_FACTOR);

    // The positive overload expression is the first physical read. A failed
    // negative underload returns before GetPhysical entirely
    // (C4Script.cpp:523-540), which is observable for a lazy fair cache.
    if change > 0 {
        let current = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.object_scope(target))
                .map(ObjectScopeContext::magic_energy)
        });
        let Some(current) = current else {
            return Ok(Value::Bool(false));
        };
        let Some(cap) = resolve_object_physical(target, false).map(|physical| physical.magic)
        else {
            return Ok(Value::Bool(false));
        };
        if current.wrapping_add(change) > cap {
            if !allow_partial {
                return Ok(Value::Bool(false));
            }
            // The partial branch calls GetPhysical a second time, then reads
            // the live MagicEnergy again (C4Script.cpp:528).
            let Some(cap) = resolve_object_physical(target, false).map(|physical| physical.magic)
            else {
                return Ok(Value::Bool(false));
            };
            let current = HOST_CONTEXT.with(|cell| {
                cell.borrow()
                    .as_ref()
                    .and_then(|context| context.object_scope(target))
                    .map(ObjectScopeContext::magic_energy)
            });
            let Some(current) = current else {
                return Ok(Value::Bool(false));
            };
            change = cap.wrapping_sub(current);
            if change == 0 {
                return Ok(Value::Bool(false));
            }
        }
    }

    if change < 0 {
        let current = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.object_scope(target))
                .map(ObjectScopeContext::magic_energy)
        });
        let Some(current) = current else {
            return Ok(Value::Bool(false));
        };
        if current.wrapping_add(change) < 0 {
            if !allow_partial {
                return Ok(Value::Bool(false));
            }
            change = current.wrapping_neg();
            if change == 0 {
                return Ok(Value::Bool(false));
            }
        }
    }

    // BoundBy performs the final GetPhysical even for a zero change. Re-read
    // MagicEnergy afterward so side effects from that first fill are live.
    let Some(cap) = resolve_object_physical(target, false).map(|physical| physical.magic) else {
        return Ok(Value::Bool(false));
    };
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("DoMagicEnergy requires an active engine context"))?;
        let Some(scope) = context.object_scope_mut(target) else {
            return Ok(Value::Bool(false));
        };
        let sum = scope.magic_energy().wrapping_add(change);
        scope.set_magic_energy(if sum < 0 {
            0
        } else if sum > cap {
            cap
        } else {
            sum
        });
        Ok(Value::Bool(true))
    })
}

/// `FnGetMagicEnergy` (C4Script.cpp:546-550): MagicEnergy /
/// MagicPhysicalFactor; 0 without an object (`return false`).
fn get_magic_energy(args: &[Value]) -> Result<Value, RuntimeError> {
    let target_id = magic_energy_target(args.first(), "GetMagicEnergy")?;
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("GetMagicEnergy requires an active engine context"))?;
        let Some(target) = target_id.or_else(|| context.object_context().map(|o| o.id())) else {
            return Ok(Value::Int(0));
        };
        if !context.ensure_object_scope(target) {
            return Ok(Value::Int(0));
        }
        let Some(scope) = context.object_scope(target) else {
            return Ok(Value::Int(0));
        };
        Ok(Value::Int(scope.magic_energy() / MAGIC_PHYSICAL_FACTOR))
    })
}

/// The kill-trace mark of C4Object::DoEnergy (C4Object.cpp:1351-1353):
/// negative changes (and object hits even at zero) record the causing
/// player, with the UpdatLastEnergyLossCause guard (:1369-1378) applied
/// at call time against the freshest tracked value.
fn stage_energy_loss_cause(
    context: &mut EffectHostContext,
    target: ObjectId,
    change: i32,
    eng_type: i32,
    caused_by: i32,
) {
    if change >= 0 && eng_type != crate::C4FX_CALL_ENG_OBJ_HIT {
        return;
    }
    let tracked = context
        .object_scope(target)
        .and_then(|scope| scope.pending_update.energy_loss_cause)
        .or_else(|| {
            context
                .get_world_object(target)
                .map(|object| object.last_energy_loss_cause)
        })
        .unwrap_or(OWNER_NONE);
    let controller = context
        .object_scope(target)
        .map(|scope| scope.controller())
        .unwrap_or(OWNER_NONE);
    if caused_by != controller || tracked < 0 {
        if let Some(scope) = context.object_scope_mut(target) {
            scope.pending_update.energy_loss_cause = Some(caused_by);
        }
    }
}

fn do_con(args: &[Value]) -> Result<Value, RuntimeError> {
    let change_percent = match args.first().unwrap_or(&Value::Nil) {
        Value::Int(value) => *value,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "DoCon: expected int or nil for change, got {}",
                other.type_name()
            )));
        }
    };

    let mut target_id: Option<ObjectId> = None;
    if let Some(arg) = args.get(1) {
        target_id = parse_object_reference_argument(arg, "DoCon", "target")?;
    }

    if args.len() > 2 {
        return Err(RuntimeError::new(
            "DoCon: additional arguments are not supported",
        ));
    }

    // FnDoCon invokes the native method on its optional object parameter;
    // it does not dispatch a target-local script function of the same name.
    let target = target_id.or_else(active_object_id);
    let Some(target) = target else {
        return Ok(Value::Bool(false));
    };
    let delta = construction_delta_from_percent(change_percent);
    Ok(Value::Bool(do_con_live(target, delta)?))
}

/// Synchronous host-context `C4Object::DoCon(..., fInitial=false)`. The
/// low-level construction primitive is also used by NewObject's initial
/// pass, so all non-initial side arms live here instead of in that primitive.
fn do_con_live(target: ObjectId, delta: i32) -> Result<bool, RuntimeError> {
    let staged = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut()?;
        if !context.ensure_object_scope(target) {
            return None;
        }
        let metadata = context
            .object_effective_definition_id(target)
            .and_then(|definition_id| context.definition_metadata(&definition_id).cloned())
            .unwrap_or_default();
        let before = context.object_scope(target)?.construction();
        let entry_position = context.object_scope(target)?.effective_position();
        let entry_shape = live_object_shape(context, target);
        let previous_step = before / (FULL_CON / 100);
        let was_full = before >= FULL_CON;
        let after = context.stage_live_docon_construction(target, delta)?;
        let step_diff = after / (FULL_CON / 100) - previous_step;
        let refresh = crate::docon_refreshes_construction(before, after);
        let _ = refresh_live_object_ocf(context, target);
        if refresh {
            if let Some(scope) = context.object_scope_mut(target) {
                if metadata.line == 0 {
                    scope.pending_update.shape_override = Some(None);
                }
                scope.refresh_shape_preview(&metadata);
            }
            // UpdateFace(true) recreates/puts the mask before contents
            // ejection and SetAction(Idle), so callbacks fired by either
            // path must already see the new landscape (C4Object.cpp:
            // 1450-1472).
            context.update_live_solid_mask(target, false);
        }
        Some((
            metadata,
            entry_position,
            entry_shape,
            previous_step,
            step_diff,
            was_full,
            after,
            refresh,
        ))
    });
    let Some((
        metadata,
        entry_position,
        entry_shape,
        previous_step,
        step_diff,
        was_full,
        after,
        refresh,
    )) = staged
    else {
        return Ok(false);
    };

    if refresh && after < FULL_CON {
        if !metadata.fire.incomplete_activity {
            loop {
                let next = HOST_CONTEXT.with(|cell| {
                    let borrow = cell.borrow();
                    let context = borrow.as_ref()?;
                    let object = context.get_world_object(target)?;
                    Some((first_retained_content(context, target)?, object.container()))
                });
                let Some((child, destination)) = next else {
                    break;
                };
                let moved = if let Some(destination) = destination {
                    enter_object_live(child, destination)?
                } else {
                    exit_object_at_current_position(child)?
                };
                if !moved {
                    // A callback can remove/reparent the head while the
                    // requested transfer itself reports false. Re-read like
                    // C4ObjectList::GetObject; stop only if no progress was
                    // made and the exact same child is still first.
                    let same_head = HOST_CONTEXT.with(|cell| {
                        cell.borrow()
                            .as_ref()
                            .and_then(|context| first_retained_content(context, target))
                            == Some(child)
                    });
                    if same_head {
                        break;
                    }
                }
            }
        }
        HOST_CONTEXT.with(|cell| {
            if let Some(scope) = cell
                .borrow_mut()
                .as_mut()
                .and_then(|context| context.object_scope_mut(target))
            {
                scope.set_need_energy(false);
            }
        });
    }

    if refresh && was_full {
        let should_idle = HOST_CONTEXT
            .with(|cell| {
                let borrow = cell.borrow();
                let context = borrow.as_ref()?;
                let scope = context.object_scope(target)?;
                let definition = context.object_effective_definition_id(target)?;
                let incomplete_activity = context
                    .definition_metadata(&definition)
                    .is_some_and(|metadata| metadata.fire.incomplete_activity);
                Some(scope.construction() < FULL_CON && !incomplete_activity)
            })
            .unwrap_or(false);
        if should_idle {
            let _ = native_set_action_by_name(target, "Idle")?;
        }
    }

    if refresh {
        HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(context) = borrow.as_mut() else {
                return;
            };
            let Some(definition_id) = context.object_effective_definition_id(target) else {
                return;
            };
            let Some(current_metadata) = context.definition_metadata(&definition_id).cloned()
            else {
                return;
            };
            let current_shape = live_object_shape(context, target);
            let moved = {
                let Some(scope) = context.object_scope_mut(target) else {
                    return;
                };
                let current_position = scope.effective_position();
                let adjusted_y = crate::docon_adjusted_position_y(
                    entry_position.y,
                    entry_shape,
                    current_position.y,
                    current_shape,
                    scope.rotation(),
                    scope.category(),
                    previous_step,
                    step_diff,
                    current_metadata.shape.map_or(0, |shape| shape.height),
                );
                scope.current_position.y = adjusted_y;
                if let Some(position) = scope.pending_update.position.as_mut() {
                    position.y = adjusted_y;
                }
                scope.pending_update.resolved_docon_position = Some(scope.current_position);
                scope.pending_update.resolved_docon_fixed_position =
                    Some(scope.current_fixed_position);
                adjusted_y != current_position.y
            };
            // DoCon's keep-bottom/lift arm calls UpdateSolidMask again at
            // the adjusted position before Completion/Initialize.
            if moved {
                context.update_live_solid_mask(target, false);
            }
        });
    }

    let crossed_full = !was_full
        && HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.object_scope(target))
                .is_some_and(|scope| scope.construction() >= FULL_CON)
        });
    if crossed_full {
        call_object_own_fail_safe(target, "Completion", &[]);
        if object_has_status(target) {
            call_object_own_fail_safe(target, "Initialize", &[]);
        }
    }

    let reached_zero = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_scope(target))
            .is_some_and(|scope| scope.construction() <= 0)
    });
    if reached_zero && object_has_status(target) {
        let _ = assign_removal_live(target, false)?;
    }
    Ok(true)
}

/// FnGetDamage (C4Script.cpp:1366-1370): `pObj->Damage`, the optional
/// object parameter defaulting to the caller.
fn get_damage(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "GetDamage expects at most 1 argument: target",
        ));
    }

    let mut target_id: Option<ObjectId> = None;
    if let Some(arg) = args.first() {
        target_id = parse_object_reference_argument(arg, "GetDamage", "target")?;
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        if let Some(target) = target_id {
            if let Some(object) = context.object_context() {
                if object.id() == target {
                    return Ok(Value::Int(object.damage()));
                }
            }
            if let Some(other) = context.get_world_object(target) {
                return Ok(Value::Int(other.damage()));
            }
            return Ok(Value::Nil);
        }

        match context.object_context() {
            Some(object) => Ok(Value::Int(object.damage())),
            None => Ok(Value::Nil),
        }
    })
}

/// FnGetPlrColorDw (C4Script.cpp:3658-3666): the player's resolved
/// C4Player::ColorDw; a missing player reads nil.
fn get_plr_color_dw(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() != 1 {
        return Err(RuntimeError::new(
            "GetPlrColorDw expects exactly 1 argument: player",
        ));
    }
    let player_id = value_to_i32(&args[0], "GetPlrColorDw", "player")?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let Some(player) = context.player_state(player_id) else {
            return Ok(Value::Nil);
        };
        Ok(Value::Int(player.exact_color_dw() as i32))
    })
}

/// FnGetPlrControlName (C4Script.cpp:2568-2571): format the configured key
/// for the player's effective local control set. Configuration lookup
/// failures are a non-nil empty C4 string.
fn get_plr_control_name(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 3 {
        return Err(RuntimeError::new(
            "GetPlrControlName expects at most 3 arguments: player, control, short",
        ));
    }
    let player_id = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "GetPlrControlName",
        "player",
    )?;
    let control = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "GetPlrControlName",
        "control",
    )?;
    let short = args.get(2).map(Value::as_bool).unwrap_or(false);

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let name = borrow
            .as_ref()
            .and_then(|context| {
                let control_set = context.player_state(player_id)?.control_set;
                context.world.control_key_name(control_set, control, short)
            })
            .unwrap_or_default();
        Ok(Value::String(name.to_string().into()))
    })
}

/// FnGetPlrJumpAndRunControl (C4Script.cpp:2579-2583): the player's
/// ControlStyle (0 classic / 1 Jump'n'Run, C4Player.cpp:2373); an absent
/// player yields -1. The return type is C4ValueInt — there is no nil path.
fn get_plr_jump_and_run_control(args: &[Value]) -> Result<Value, RuntimeError> {
    // An unfilled iPlr slot is nil -> 0 (C4AulExec parameter filling).
    let player_id = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "GetPlrJumpAndRunControl",
        "player",
    )?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let control_style = borrow
            .as_ref()
            .and_then(|context| context.player_state(player_id))
            .map(|player| i32::from(player.control.control_style));
        Ok(Value::Int(control_style.unwrap_or(-1)))
    })
}

fn do_damage(args: &[Value]) -> Result<Value, RuntimeError> {
    do_damage_with_cause_override(args, None)
}

/// Internal counterpart to `do_damage` that bypasses the script ABI's
/// encoded-zero caller-controller default for explicit NO_OWNER.
fn do_damage_with_cause_override(
    args: &[Value],
    caused_by_override: Option<i32>,
) -> Result<Value, RuntimeError> {
    let change = match args.first().unwrap_or(&Value::Nil) {
        Value::Int(value) => *value,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "DoDamage: expected int or nil for change, got {}",
                other.type_name()
            )));
        }
    };

    let mut index = 1;
    let mut target_id: Option<ObjectId> = None;

    if let Some(arg) = args.get(index) {
        match arg {
            Value::Object(_) | Value::Proplist(_) => {
                target_id = object_id_from_value(arg);
                index += 1;
            }
            Value::Nil => {
                index += 1;
            }
            Value::Int(value) if *value == 0 => {
                index += 1;
            }
            Value::Int(value) if *value > 0 => {
                target_id = Some(ObjectId::new(*value as u64));
                index += 1;
            }
            _ => {}
        }
    }

    let mut damage_type = crate::C4FX_CALL_DMG_SCRIPT;
    if let Some(arg) = args.get(index) {
        match arg {
            Value::Int(value) => {
                damage_type = *value;
                index += 1;
            }
            Value::Nil => {
                index += 1;
            }
            other => {
                return Err(RuntimeError::new(format!(
                    "DoDamage: expected int or nil for damage type, got {}",
                    other.type_name()
                )));
            }
        }
    }

    let mut caused_by_plus_one = 0;
    if let Some(arg) = args.get(index) {
        match arg {
            Value::Int(value) => {
                caused_by_plus_one = *value;
                index += 1;
            }
            Value::Nil => {
                index += 1;
            }
            other => {
                return Err(RuntimeError::new(format!(
                    "DoDamage: expected int or nil for caused by, got {}",
                    other.type_name()
                )));
            }
        }
    }

    if index < args.len() {
        return Err(RuntimeError::new(
            "DoDamage: additional arguments are not supported",
        ));
    }

    let staged = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("DoDamage requires an active engine context"))?;
        // iCausedBy = iCausedByPlusOne - 1, else the CALLER's controller
        // (C4Script.cpp:511) — resolved in the caller's scope.
        let caused_by = caused_by_override.unwrap_or_else(|| {
            if caused_by_plus_one != 0 {
                caused_by_plus_one - 1
            } else {
                context
                    .object_context()
                    .map(|object| object.controller())
                    .unwrap_or(OWNER_NONE)
            }
        });
        // `if (!pObj) pObj = cthr->Obj` is only the local-call default
        // (C4Script.cpp:510) — a named target may be FOREIGN.
        let Some(target) = target_id.or_else(|| context.object_context().map(|o| o.id())) else {
            return Ok(None);
        };
        if !context.ensure_object_scope(target) {
            return Ok(None);
        }
        let Some(scope) = context.object_scope(target) else {
            return Ok(None);
        };
        Ok(Some((target, caused_by, scope.alive())))
    })?;
    let Some((target, caused_by, alive)) = staged else {
        return Ok(Value::Bool(false));
    };
    // Non-living: ask the effects first (C4Object.cpp:1282-1286); a zero
    // chain outcome returns BEFORE the damage write and the ~Damage call.
    let change = match (!alive)
        .then(|| dispatch_effects_do_damage(target, change, damage_type, caused_by))
        .flatten()
    {
        Some(0) => return Ok(Value::Bool(true)),
        Some(modified) => modified,
        None => change,
    };
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        if let Some(scope) = context.object_scope_mut(target) {
            // Damage = max(Damage + iChange, 0) (C4Object.cpp:1288).
            scope.adjust_damage(change);
        }
    });
    // The Damage engine call after the stat write (PSF_Damage "~Damage",
    // C4Object.cpp:1290 — fail-safe exec, errors log and continue).
    if let Some(Err(error)) = call_world_object_own_function(
        target,
        "Damage",
        &[Value::Int(change), Value::Int(caused_by)],
    ) {
        tracing::warn!(
            %error,
            "script error in Damage; continuing like the C++ fail-safe exec"
        );
    }
    Ok(Value::Bool(true))
}

/// C4Effect::DoDamage on the host seam (C4Effect.cpp:427-437): walks the
/// target's live effects asking each Fx*Damage hook (on the effect's
/// command target) to chain the damage value. The C++ walk is a do-while:
/// the FIRST effect is asked even for a zero change; afterwards the chain
/// continues only while the value stays nonzero, and a target removal
/// mid-chain aborts (`if (pObj && !pObj->Status) return`). A hook the
/// dispatch script does not define leaves the value untouched (the
/// pFnDamage existence gate); an erroring hook folds to 0 like an
/// fPassErrors=false Exec. `None` when the target has no effects at all
/// (pEffects nullptr — the caller must not early-return then).
fn dispatch_effects_do_damage(
    target: ObjectId,
    mut change: i32,
    cause: i32,
    caused_by: i32,
) -> Option<i32> {
    let effects: Vec<EffectState> = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Vec::new();
        };
        context
            .object_scope(target)
            .map(|scope| scope.effects.snapshot())
            .or_else(|| {
                context
                    .get_world_object(target)
                    .and_then(|object| object.full_state().map(|state| state.effects.clone()))
            })
            .unwrap_or_default()
    });
    if effects.is_empty() {
        return None;
    }
    let target_value = object_reference_value(target);
    for effect in effects {
        // IsDead: a zero priority marks a dead effect (C4Effect.h).
        if effect.priority != 0 {
            let function = format!("Fx{}Damage", effect.name);
            let call_args = [
                target_value.clone(),
                Value::Int(effect.number),
                Value::Int(change),
                Value::Int(cause),
                Value::Int(caused_by),
            ];
            match dispatch_effect_fx_callback(
                effect.command_target,
                effect.command_id.as_deref(),
                &function,
                &call_args,
            ) {
                // No such hook anywhere: the chained value stays
                // (pFnDamage existence gate, C4Effect.cpp:433).
                None => {}
                // C4Value::getInt() reads non-canonical Bool payloads too.
                Some(Ok(value)) => change = value_as_i32(&value),
                Some(Err(error)) => {
                    tracing::warn!(
                        %error,
                        "script error in {function}; the chained damage folds to 0"
                    );
                    change = 0;
                }
            }
        }
        // `if (pObj && !pObj->Status) return` (C4Effect.cpp:435).
        let target_gone = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .map(|context| {
                    context
                        .get_world_object(target)
                        .map(|object| object.status() == ObjectStatus::Deleted)
                        .unwrap_or(true)
                })
                .unwrap_or(true)
        });
        if target_gone || change == 0 {
            break;
        }
    }
    Some(change)
}

/// FnExplode (C4Script.cpp:238-243) snapshots the immediate container and
/// controller, removes the target, then lets C4Object::Explode read its final
/// position while the removed object is still allocated.
fn explode(args: &[Value]) -> Result<Value, RuntimeError> {
    let level = value_to_i32(args.first().unwrap_or(&Value::Nil), "Explode", "level")?;
    let explicit_target = parse_object_reference_argument(
        args.get(1).unwrap_or(&Value::Nil),
        "Explode",
        "object",
    )?;
    let effect_id = parse_native_c4id_argument(args.get(2), "Explode")?;
    // FnStringPar always passes a non-null pointer to Explosion: a null C4String
    // becomes "". Consequently an omitted string does not activate
    // Explosion's `else if (idEffect)` particle-suppression arm.
    let effect_name =
        parse_native_c4_string_argument(args.get(3), "Explode", "effect")?.unwrap_or_default();

    let target = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| explicit_target.or(context.script_object_context))
    });
    let Some(target) = target else {
        return Ok(Value::Bool(false));
    };

    let pre_removal = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let object = context.get_world_object(target)?;
        let scope = context.object_scope(target);
        Some((
            scope
                .map(ObjectScopeContext::container)
                .unwrap_or_else(|| object.container()),
            scope
                .map(ObjectScopeContext::controller)
                .unwrap_or_else(|| object.controller()),
        ))
    });
    let Some((in_object, caused_by)) = pre_removal else {
        return Ok(Value::Bool(false));
    };

    let _ = assign_removal_live(target, false)?;
    let position = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        context
            .object_scope(target)
            .map(ObjectScopeContext::effective_position)
            .or_else(|| context.get_world_object(target).map(|object| object.position()))
    });
    // A resolved C4Object pointer remains allocated after AssignRemoval. The
    // Rust scope normally remains as well; retain FnExplode's unconditional
    // true result if a synthetic fixture cannot expose that retired scope.
    if let Some(position) = position {
        native_explosion(
            position,
            level,
            in_object,
            caused_by,
            target,
            effect_id,
            &effect_name,
        )?;
    }
    Ok(Value::Bool(true))
}

fn native_explosion(
    position: Vector2,
    level: i32,
    in_object: Option<ObjectId>,
    caused_by: i32,
    by_object: ObjectId,
    effect_id: Option<String>,
    effect_name: &str,
) -> Result<(), RuntimeError> {
    let grade = (level / 10 - 1).clamp(1, 3);
    HOST_CONTEXT.with(|cell| {
        if let Some(context) = cell.borrow_mut().as_mut() {
            // The current C++ oracle's std::format receives the promoted int
            // value of '0' + grade, hence Blast49..Blast51.
            context.audio_mut().events.push(AudioCommand::PlaySoundAt {
                name: format!("Blast{}", i32::from(b'0') + grade),
                position,
            });
        }
    });

    // Resolve containment once, before any visual-effect callbacks, and keep
    // that pointer for the later second BlastObjects pass.
    let contain_blast = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let mut container = in_object;
        while let Some(candidate) = container {
            let definition = effective_definition_id(context, candidate);
            let contains = definition
                .as_deref()
                .and_then(|definition| context.definition_metadata(definition))
                .is_some_and(|metadata| metadata.fire.contain_blast != 0);
            if contains {
                break;
            }
            container = context
                .object_scope(candidate)
                .map(ObjectScopeContext::container)
                .unwrap_or_else(|| {
                    context
                        .get_world_object(candidate)
                        .and_then(|object| object.container())
                });
        }
        container
    });

    if contain_blast.is_none() {
        if !incinerate_landscape_at(position.x, position.y)?.as_bool()
            && !incinerate_landscape_at(position.x, position.y.wrapping_sub(10))?.as_bool()
            && !incinerate_landscape_at(
                position.x.wrapping_sub(5),
                position.y.wrapping_sub(5),
            )?
            .as_bool()
        {
            let _ = incinerate_landscape_at(
                position.x.wrapping_add(5),
                position.y.wrapping_sub(5),
            )?;
        }
        native_explosion_visual(position, level, caused_by, by_object, effect_id, effect_name)?;
    }

    native_blast_objects(position.x, position.y, level, in_object, caused_by, Some(by_object))?;
    if contain_blast != in_object {
        native_blast_objects(
            position.x,
            position.y,
            level,
            contain_blast,
            caused_by,
            Some(by_object),
        )?;
    }
    if contain_blast.is_none() {
        native_blast_free_absolute(position, level, Some(caused_by))?;
    }
    Ok(())
}

fn native_explosion_visual(
    position: Vector2,
    level: i32,
    caused_by: i32,
    by_object: ObjectId,
    effect_id: Option<String>,
    effect_name: &str,
) -> Result<(), RuntimeError> {
    let selected_particle = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let default = (context.particle_def_known("Blast") != Some(false))
            .then(|| "Blast".to_string());
        if !effect_name.is_empty()
            && context.particle_def_known(effect_name) != Some(false)
        {
            Some(effect_name.to_string())
        } else {
            default
        }
    });

    if let Some(definition_id) = selected_particle {
        HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(context) = borrow.as_mut() else {
                return;
            };
            context.register_particle(ParticleCommand::Create(ParticleConfig {
                definition_id: definition_id.clone(),
                position: FloatVector2::new(position.x as f32, position.y as f32),
                velocity: FloatVector2::new(0.0, 0.0),
                life: 0,
                parameter_a: level as f32,
                parameter_b: 0,
                layer: ParticleLayer::Global,
            }));
            if definition_id.starts_with("Blast")
                && context.particle_def_known("FSpark") != Some(false)
            {
                context.register_particle(ParticleCommand::Cast {
                    definition_id: "FSpark".to_string(),
                    amount: level / 5 + 1,
                    x: position.x as f32,
                    y: position.y as f32,
                    level,
                    a0: (level / 2) as f32 + 1.0,
                    b0: 0x00ef_0000,
                    a1: level as f32 + 1.0,
                    b1: 0xffff_1010,
                    layer: ParticleLayer::Global,
                });
            }
        });
        return Ok(());
    }

    let definition = effect_id.unwrap_or_else(|| "FXB1".to_string());
    let controller = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        context
            .object_scope(by_object)
            .map(ObjectScopeContext::controller)
            .or_else(|| {
                context
                    .get_world_object(by_object)
                    .map(|object| object.controller())
            })
    });
    let Some(controller) = controller else {
        return Ok(());
    };
    if let Some(effect) = create_native_object(NativeObjectCreation {
        definition,
        creator: Some(by_object),
        owner: caused_by,
        controller,
        construction: level.wrapping_mul(FULL_CON) / 20,
        position: Vector2::new(position.x, position.y.wrapping_add(level)),
        rotation: 0,
        velocity: FixedVec2::ZERO,
        rotation_velocity: C4Fixed::ZERO,
    })? {
        call_object_own_fail_safe(effect, "Activate", &[]);
    }
    Ok(())
}

/// FnBlastObjects (C4Script.cpp:2269-2273) -> C4Game::BlastObjects
/// (C4Game.cpp:1248-1296). Coordinates are already global. The calling
/// object's layer restricts both contained children and outside victims;
/// a null calling object selects the null layer.
fn blast_objects(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "BlastObjects", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "BlastObjects", "y")?;
    let level = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "BlastObjects", "level")?;
    let in_object = parse_object_reference_argument(
        args.get(3).unwrap_or(&Value::Nil),
        "BlastObjects",
        "container",
    )?;
    let caused_by_plus_one = value_to_i32(
        args.get(4).unwrap_or(&Value::Nil),
        "BlastObjects",
        "caused by",
    )?;

    // Resolve both values before any blast callback. FnBlastObjects passes
    // cthr->Obj as pByObj, and C4Game immediately replaces it with pLayer.
    let (caused_by, by_object) = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow
            .as_ref()
            .ok_or_else(|| RuntimeError::new("BlastObjects requires an active engine context"))?;
        let caller = context.script_object_context;
        let caused_by = if caused_by_plus_one != 0 {
            caused_by_plus_one.wrapping_sub(1)
        } else {
            caller
                .and_then(|caller| {
                    context
                        .object_scope(caller)
                        .map(ObjectScopeContext::controller)
                        .or_else(|| {
                            context
                                .get_world_object(caller)
                                .map(|object| object.controller())
                        })
                })
                .unwrap_or(OWNER_NONE)
        };
        Ok::<_, RuntimeError>((caused_by, caller))
    })?;

    native_blast_objects(x, y, level, in_object, caused_by, by_object)?;
    Ok(Value::Nil)
}

/// Absolute `C4Game::BlastObjects` entry used both by the script wrapper and
/// `C4Object::Explode`. The latter must retain the removed source object's
/// layer instead of inheriting the currently executing caller's layer. The
/// layer is read at each invocation, matching C4Game's live `pByObj->pLayer`.
fn native_blast_objects(
    x: i32,
    y: i32,
    level: i32,
    in_object: Option<ObjectId>,
    caused_by: i32,
    by_object: Option<ObjectId>,
) -> Result<(), RuntimeError> {
    let blast_layer = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        by_object.and_then(|object| context.object_layer(object))
    });

    // Blast the container before obtaining Objects.First: its callbacks can
    // change the children that the subsequent master-list scan observes.
    if let Some(container) = in_object {
        let _ = native_blast_object(container, level, caused_by)?;
        let ids = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .map(EffectHostContext::master_object_ids)
                .unwrap_or_default()
        });
        for id in ids {
            let eligible = HOST_CONTEXT.with(|cell| {
                let borrow = cell.borrow();
                let Some(context) = borrow.as_ref() else {
                    return false;
                };
                let Some(object) = context.get_world_object(id) else {
                    return false;
                };
                let current_container = context
                    .object_scope(id)
                    .map(ObjectScopeContext::container)
                    .unwrap_or_else(|| object.container());
                context.object_status_active(id)
                    && current_container == Some(container)
                    && context.object_layer(id) == blast_layer
            });
            if eligible {
                let _ = native_blast_object(id, level, caused_by)?;
            }
        }
        return Ok(());
    }

    let ids = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .map(EffectHostContext::master_object_ids)
            .unwrap_or_default()
    });
    for id in ids {
        // Status/containment/layer are the outer C++ if-chain and are tested
        // once. A direct Blast callback may mutate later shockwave inputs.
        let direct_hit = HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let context = borrow.as_ref()?;
            let object = context.get_world_object(id)?;
            let container = context
                .object_scope(id)
                .map(ObjectScopeContext::container)
                .unwrap_or_else(|| object.container());
            if !context.object_status_active(id)
                || container.is_some()
                || context.object_layer(id) != blast_layer
            {
                return None;
            }
            let position = context
                .object_scope(id)
                .map(ObjectScopeContext::effective_position)
                .unwrap_or_else(|| object.position());
            let shape = live_object_shape(context, id).unwrap_or_default();
            let relative_x = x.wrapping_sub(position.x.wrapping_add(shape.x));
            let relative_y = y.wrapping_sub(position.y.wrapping_add(shape.y));
            Some(
                relative_y >= -5
                    && relative_y <= shape.height.wrapping_sub(1).wrapping_add(10)
                    && relative_x >= -5
                    && relative_x <= shape.width.wrapping_sub(1).wrapping_add(10),
            )
        });
        let Some(direct_hit) = direct_hit else {
            continue;
        };
        if direct_hit {
            let _ = native_blast_object(id, level, caused_by)?;
        }

        // C++ stays inside the already-passed outer block but reads these
        // fields after the direct Blast callback.
        let living_shockwave = HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let context = borrow.as_ref()?;
            let object = context.get_world_object(id)?;
            let scope = context.object_scope(id);
            let category = scope
                .map(ObjectScopeContext::category)
                .unwrap_or_else(|| object.category());
            if category
                & (crate::CATEGORY_LIVING | crate::CATEGORY_OBJECT | crate::CATEGORY_VEHICLE)
                == 0
            {
                return None;
            }
            let definition = context.object_effective_definition_id(id)?;
            let metadata = context.definition_metadata(&definition)?;
            if metadata.fire.no_horizontal_move != 0 {
                return None;
            }
            let position = scope
                .map(ObjectScopeContext::effective_position)
                .unwrap_or_else(|| object.position());
            if y.wrapping_sub(position.y).wrapping_abs() > level
                || x.wrapping_sub(position.x).wrapping_abs() > level
            {
                return None;
            }
            let floating = scope
                .map(|scope| scope.effective_action_procedure() == ActionProcedure::Float)
                .unwrap_or_else(|| {
                    object
                        .procedure_name()
                        .map(ActionProcedure::from_name)
                        .is_some_and(|procedure| procedure == ActionProcedure::Float)
                });
            if metadata.fire.grab != 1
                && (category & crate::CATEGORY_VEHICLE != 0 || floating)
            {
                return None;
            }
            Some(category & crate::CATEGORY_LIVING != 0)
        });
        let Some(living_shockwave) = living_shockwave else {
            continue;
        };

        if living_shockwave {
            let target = object_reference_value(id);
            let _ = do_energy_with_cause_override(
                &[
                    Value::Int(level.wrapping_neg() / 2),
                    target.clone(),
                    Value::Bool(false),
                    Value::Int(crate::C4FX_CALL_ENG_BLAST),
                ],
                Some(caused_by),
            )?;
            let _ = do_damage_with_cause_override(
                &[
                    Value::Int(level / 2),
                    target,
                    Value::Int(crate::C4FX_CALL_DMG_BLAST),
                ],
                Some(caused_by),
            )?;
        }

        // Living damage callbacks precede both force calculations. p2 is
        // evaluated before p1, and p1 alone consumes one Rnd3 value.
        let force_state = HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let context = borrow.as_ref()?;
            let object = context.get_world_object(id)?;
            let scope = context.object_scope(id);
            Some((
                scope
                    .map(ObjectScopeContext::effective_position)
                    .unwrap_or_else(|| object.position()),
                scope
                    .map(ObjectScopeContext::category)
                    .unwrap_or_else(|| object.category()),
                reflected_object_mass(context, id, &mut HashSet::new()),
            ))
        });
        let Some((position, category, mass)) = force_state else {
            continue;
        };
        let max_mass_divisor = if category & crate::CATEGORY_LIVING != 0 {
            8
        } else {
            20
        };
        let mass_divisor = (mass / 10).clamp(4, max_mass_divisor);
        let distance_y = y.wrapping_sub(position.y).wrapping_abs();
        let y_force = itofix(distance_y.wrapping_sub(level)) / mass_divisor;
        let rnd3 = draw_context_rnd3()?;
        let distance_x = x.wrapping_sub(position.x).wrapping_abs();
        let direction = position.x.wrapping_sub(x).wrapping_add(rnd3).signum();
        let x_force = itofix(direction.wrapping_mul(level.wrapping_sub(distance_x)))
            / mass_divisor;
        native_fling(id, FixedVec2::new(x_force, y_force), true, caused_by)?;
    }
    Ok(())
}

/// FnBlastObject (C4Script.cpp:2281-2289) -> C4Object::Blast
/// (C4Object.cpp:1414-1424): DoDamage(level, ..., C4FxCall_DmgBlast) with
/// its synchronous ~Damage callback, then alive targets lose level/3
/// energy percent points (DoEnergy fExact=false, C4FxCall_EngBlast).
fn blast_object(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 3 {
        return Err(RuntimeError::new(
            "BlastObject expects at most 3 arguments: level, target, caused by",
        ));
    }
    let level = parse_optional_i32(args.first(), "BlastObject", "level")?.unwrap_or(0);
    let target_id = args
        .get(1)
        .map(|arg| parse_object_reference_argument(arg, "BlastObject", "target"))
        .transpose()?
        .flatten();
    let caused_by_plus_one =
        parse_optional_i32(args.get(2), "BlastObject", "caused by")?.unwrap_or(0);

    let target_and_cause = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow
            .as_ref()
            .ok_or_else(|| RuntimeError::new("BlastObject requires an active engine context"))?;
        // iCausedBy = iCausedByPlusOne - 1, else the CALLER's controller
        // (C4Script.cpp:2283) — resolved in the caller's scope.
        let caused_by = if caused_by_plus_one != 0 {
            caused_by_plus_one.wrapping_sub(1)
        } else {
            context
                .script_object_context
                .and_then(|caller| {
                    context
                        .object_scope(caller)
                        .map(ObjectScopeContext::controller)
                        .or_else(|| {
                            context
                                .get_world_object(caller)
                                .map(|object| object.controller())
                        })
                })
                .unwrap_or(OWNER_NONE)
        };
        // `if (!pObj) if (!(pObj = cthr->Obj)) return false` (C4Script.cpp:2284).
        Ok::<_, RuntimeError>(
            target_id
                .or(context.script_object_context)
                .map(|target| (target, caused_by)),
        )
    })?;
    let Some((target, caused_by)) = target_and_cause else {
        return Ok(Value::Bool(false));
    };
    // FnBlastObject owns the Status gate. C4Game::BlastObjects deliberately
    // calls its captured `inobj->Blast` without it, even when an earlier
    // callback assigned removal to that container.
    if !object_has_status(target) {
        return Ok(Value::Bool(false));
    }
    Ok(Value::Bool(native_blast_object(target, level, caused_by)?))
}

/// Raw exact-cause `C4Object::Blast` entry for engine helpers. The method has
/// no Status gate of its own; public FnBlastObject checks Status before this
/// call, while C4Game::BlastObjects intentionally does not. An already-decoded
/// `OWNER_NONE` must not be reinterpreted as encoded-zero caller fallback.
fn native_blast_object(target: ObjectId, level: i32, caused_by: i32) -> Result<bool, RuntimeError> {
    let alive = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("BlastObject requires an active engine context"))?;
        if !context.ensure_object_scope(target) {
            return Ok(None);
        }
        Ok(context.object_scope(target).map(ObjectScopeContext::alive))
    })?;
    let Some(alive) = alive else {
        return Ok(false);
    };
    // DoDamage leg (C4Object.cpp:1416): non-living targets ask their
    // effects first (C4Object.cpp:1282-1286); a zero chain outcome skips
    // the write and the ~Damage call but the Blast proceeds.
    let damage_change = match (!alive)
        .then(|| dispatch_effects_do_damage(target, level, crate::C4FX_CALL_DMG_BLAST, caused_by))
        .flatten()
    {
        Some(0) => None,
        Some(modified) => Some(modified),
        None => Some(level),
    };
    if let Some(damage_change) = damage_change {
        HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(context) = borrow.as_mut() else {
                return;
            };
            if let Some(scope) = context.object_scope_mut(target) {
                // Damage = max(Damage + iChange, 0) (C4Object.cpp:1288).
                scope.adjust_damage(damage_change);
            }
        });
        // The ~Damage engine call runs INSIDE DoDamage, before the energy
        // leg (C4Object.cpp:1290 — fail-safe exec, errors log and continue).
        // C4Object::DoDamage always mutates the native field, but its
        // C4Object::Call immediately returns on Status=0. This distinction
        // matters for C4Game::BlastObjects' raw captured-container call.
        if object_has_status(target) {
            if let Some(Err(error)) = call_world_object_own_function(
                target,
                "Damage",
                &[Value::Int(damage_change), Value::Int(caused_by)],
            ) {
                tracing::warn!(
                    %error,
                    "script error in Damage; continuing like the C++ fail-safe exec"
                );
            }
        }
    }
    // Energy leg (C4Object.cpp:1417-1418): only alive targets, reading
    // Alive AFTER the ~Damage callback like the live C4Object would; the
    // living Fx*Damage hook sees the SCALED change (C4Object.cpp:1347,
    // :1355-1359) and a zero chain outcome skips the write.
    let alive_now = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        let alive = context
            .object_scope(target)
            .map(|scope| scope.alive())
            .unwrap_or(false);
        if alive {
            stage_energy_loss_cause(
                context,
                target,
                -level / 3,
                crate::C4FX_CALL_ENG_BLAST,
                caused_by,
            );
        }
        alive
    });
    if alive_now {
        let scaled = (-level / 3).saturating_mul(LEGACY_MAX_PHYSICAL / 100);
        let scaled =
            match dispatch_effects_do_damage(target, scaled, crate::C4FX_CALL_ENG_BLAST, caused_by)
            {
                Some(0) => None,
                Some(modified) => Some(modified),
                None => Some(scaled),
            };
        if let Some(scaled) = scaled {
            let max_energy = resolve_object_physical(target, false)
                .map(|physical| physical.energy)
                .unwrap_or(0);
            HOST_CONTEXT.with(|cell| {
                let mut borrow = cell.borrow_mut();
                let Some(context) = borrow.as_mut() else {
                    return;
                };
                if let Some(scope) = context.object_scope_mut(target) {
                    scope.adjust_energy(scaled, true, max_energy);
                }
            });
        }
    }
    // Incinerate arm (C4Object.cpp:1420-1423): the LIVE Damage — staged
    // writes plus whatever the ~Damage callback changed — against
    // Def->BlastIncinerate (truthy in C++, so any nonzero value arms it).
    let incinerate = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        let blast_incinerate = effective_definition_id(context, target)
            .and_then(|id| context.world.definition_metadata(&id))
            .map(|metadata| metadata.fire.blast_incinerate)
            .unwrap_or(0);
        blast_incinerate != 0
            && context
                .object_scope(target)
                .map(|scope| scope.damage())
                .unwrap_or(0)
                >= blast_incinerate
    });
    if incinerate {
        incinerate_target_blasted(target, caused_by)?;
    }
    Ok(true)
}

/// The definition the world currently sees for `target`, honoring a
/// same-call staged ChangeDef (C++ reads the live C4Object::Def).
fn effective_definition_id(context: &EffectHostContext, target: ObjectId) -> Option<String> {
    context
        .object_scope(target)
        .and_then(|scope| scope.pending_update.change_def.clone())
        .or_else(|| {
            context
                .get_world_object(target)
                .map(|object| object.definition_id().to_string())
        })
}

/// `C4Object::Incinerate(iCausedBy, fBlasted=true)` on the host seam for
/// BlastObject's ignition arm. The shared constructor path below performs
/// the refusal checks and complete Fire effect negotiation/start sequence.
fn incinerate_target_blasted(target: ObjectId, caused_by: i32) -> Result<(), RuntimeError> {
    incinerate_target(target, caused_by, true, None).map(|_| ())
}

/// `C4Object::Incinerate(iCausedBy, fBlasted)` on the host seam
/// (C4Object.cpp:1257-1266): the refusal checks, the "Fire" C4Effect
/// constructor (:1263-1265), including its Fx*Effect check chain and the
/// script-overridable synchronous FxFireStart.
pub(crate) fn incinerate_target(
    target: ObjectId,
    caused_by: i32,
    blasted: bool,
    incinerating: Option<ObjectId>,
) -> Result<bool, RuntimeError> {
    let eligible = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        if !context.ensure_object_scope(target) {
            return false;
        }
        // Already on fire (C4Object.cpp:1259) — a same-call incinerate
        // shows through the staged fire channel.
        let already_burning = context
            .object_scope(target)
            .and_then(|scope| scope.pending_update.staged_on_fire())
            .unwrap_or_else(|| {
                context
                    .get_world_object(target)
                    .and_then(|object| object.full_state().map(|state| state.on_fire))
                    .unwrap_or(false)
            });
        if already_burning {
            return false;
        }
        // Dead living don't burn (C4Object.cpp:1261).
        let (category, alive) = context
            .object_scope(target)
            .map(|scope| (scope.current_category, scope.alive()))
            .unwrap_or((0, false));
        if category & crate::CATEGORY_LIVING != 0 && !alive {
            return false;
        }
        true
    });
    if !eligible {
        return Ok(false);
    }

    // Reuse the live-object C4Effect constructor path. Besides keeping the
    // pending node callback-visible, this runs all Fx*Effect checks, honors
    // annul/merge, brackets Start with upper temp calls, and resolves a
    // global script FxFireStart before the native engine fallback.
    let result = add_effect_constructor(
        &[
            Value::String(crate::C4FX_FIRE.into()),
            object_reference_value(target),
            Value::Int(crate::C4FX_FIRE_PRIORITY),
            Value::Int(crate::C4FX_FIRE_TIMER_INTERVAL),
            Value::Nil,
            Value::Nil,
            Value::Int(caused_by),
            Value::Bool(blasted),
            incinerating
                .map(object_reference_value)
                .unwrap_or(Value::Nil),
            Value::Nil,
        ],
        crate::C4FX_FIRE.to_string(),
        false,
        AddEffectCommandIdSlot::Native(None),
    )?;
    Ok(matches!(result, Value::Int(number) if number != 0))
}

/// The engine FnFxFireStart body (C4Effect.cpp:560-641; AddFunc
/// C4Script.cpp:6994) against an EXISTING fire effect entry: the
/// extinguisher gate (checked BEFORE the FirePhase draw), BurnTurnTo
/// changedef, burning contents ejection, the ~FireMode determination,
/// the effect-var writes [Mode, CausedBy, Blasted, IncineratingObj]
/// (:628-631), ONE FirePhase = Random(15) draw on the shared ledger
/// (:634) and the Incineration/IncinerationEx callback — in C++ ledger
/// order. Returns C4Fx_OK (0) or C4Fx_Start_Deny (-1).
fn fire_effect_start_core(
    target: ObjectId,
    fire_number: i32,
    caused_by: i32,
    blasted: bool,
    incinerating: Option<ObjectId>,
) -> Result<i32, RuntimeError> {
    enum FireStage {
        Deny,
        NoFire { blasted: bool },
        Ignite,
    }
    let (stage, burn_turn_to) = HOST_CONTEXT.with(
        |cell| -> Result<(FireStage, Option<String>), RuntimeError> {
            let mut borrow = cell.borrow_mut();
            let Some(context) = borrow.as_mut() else {
                return Ok((FireStage::Deny, None));
            };
            if !context.ensure_object_scope(target) {
                return Ok((FireStage::Deny, None));
            }
            // fail if already on fire (C4Effect.cpp:567)
            let already_burning = context
                .object_scope(target)
                .and_then(|scope| scope.pending_update.staged_on_fire())
                .unwrap_or_else(|| {
                    context
                        .get_world_object(target)
                        .and_then(|object| object.full_state().map(|state| state.on_fire))
                        .unwrap_or(false)
                });
            if already_burning {
                return Ok((FireStage::Deny, None));
            }
            // get associated effect (C4Effect.cpp:569-571)
            let entry_exists = context.object_scope(target).is_some_and(|scope| {
                scope
                    .effects
                    .snapshot()
                    .iter()
                    .any(|effect| effect.number == fire_number)
            });
            if !entry_exists {
                return Ok((FireStage::Deny, None));
            }
            // In extinguishing material: no fire caused, checked BEFORE the
            // FirePhase draw (C4Effect.cpp:574-583).
            let position = context
                .object_scope(target)
                .map(|scope| scope.effective_position())
                .unwrap_or(Vector2::ZERO);
            let in_extinguisher = context
                .landscape_ref()
                .and_then(|landscape| landscape.material_at(position.x, position.y))
                .zip(context.world.materials())
                .and_then(|(material_id, materials)| materials.get_by_id(material_id))
                .map(|material| material.extinguisher() != 0)
                .unwrap_or(false);
            let fire_caused = !in_extinguisher;
            let fire_meta = effective_definition_id(context, target)
                .and_then(|id| context.world.definition_metadata(&id))
                .map(|metadata| metadata.fire.clone())
                .unwrap_or_default();
            // BurnTurnTo: blasts changedef in water too (C4Effect.cpp:579-585).
            let turn_to = (fire_caused || blasted)
                .then(|| fire_meta.burn_turn_to)
                .flatten()
                .filter(|turn_to| context.world.definition_metadata(turn_to).is_some());
            if !fire_caused {
                return Ok((FireStage::NoFire { blasted }, turn_to));
            }
            Ok((FireStage::Ignite, turn_to))
        },
    )?;

    if matches!(&stage, FireStage::Deny) {
        return Ok(-1);
    }

    if let Some(turn_to) = burn_turn_to {
        let _ = change_def_live(target, &turn_to)?;
    }

    // ChangeDef above is immediately live in C++. Re-read the effective
    // definition before each guarded block so BurnTurnTo and callbacks can
    // change whether contents are ejected and attached objects detached.
    let eject_contents = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        effective_definition_id(context, target)
            .and_then(|id| context.world.definition_metadata(&id))
            .map(|metadata| !metadata.fire.incomplete_activity && !metadata.fire.no_burn_decay)
            .unwrap_or(true)
    });
    if eject_contents {
        // Snapshot the current contents order, then re-check every link after
        // the preceding callbacks. Controller is assigned before the real
        // Enter/Exit, so RejectEntrance/Ejection/Departure see iCausedBy.
        let contents = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.get_world_object(target))
                .map(|object| object.contents().to_vec())
                .unwrap_or_default()
        });
        for content in contents {
            let parent = HOST_CONTEXT.with(|cell| {
                let mut borrow = cell.borrow_mut();
                let context = borrow.as_mut()?;
                let target_object = context.get_world_object(target)?;
                let content_object = context.get_world_object(content)?;
                if !target_object.is_present()
                    || !content_object.is_present()
                    || content_object.container() != Some(target)
                    || !context.ensure_object_scope(content)
                {
                    return None;
                }
                context.object_scope_mut(content)?.set_controller(caused_by);
                Some(target_object.container())
            });
            let Some(parent) = parent else {
                continue;
            };
            match parent {
                Some(container) => {
                    let _ = enter_object_live(content, container)?;
                }
                None => {
                    let _ = exit_object_at_current_position(content)?;
                }
            }
        }
    }

    let detach_attached = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        effective_definition_id(context, target)
            .and_then(|id| context.world.definition_metadata(&id))
            .map(|metadata| !metadata.fire.incomplete_activity && !metadata.fire.no_burn_decay)
            .unwrap_or(true)
    });
    if detach_attached {
        // C++ performs a fresh FindObject(..., pFindNext) against the live
        // forward master list after every AbortCall. In particular, removing
        // pFindNext from Game.Objects makes the next search stop.
        let mut previous = None;
        loop {
            let candidate = HOST_CONTEXT.with(|cell| {
                let borrow = cell.borrow();
                let context = borrow.as_ref()?;
                let master_ids = context
                    .master_object_ids()
                    .into_iter()
                    .filter(|candidate| {
                        if let Some(scope) = context.object_scope(*candidate) {
                            return scope.status() != ObjectStatus::Inactive;
                        }
                        context
                            .get_world_object(*candidate)
                            .is_some_and(|object| object.status() != ObjectStatus::Inactive)
                    })
                    .collect::<Vec<_>>();
                let start = match previous {
                    Some(previous) => {
                        master_ids
                            .iter()
                            .position(|candidate| *candidate == previous)?
                            + 1
                    }
                    None => 0,
                };
                master_ids.into_iter().skip(start).find(|candidate| {
                    if let Some(scope) = context.object_scope(*candidate) {
                        return !scope.destroy
                            && scope.status().is_active()
                            && !scope
                                .action_library
                                .is_idle_entry(
                                    scope.effective_action_name(),
                                    scope.effective_action_index(),
                                )
                            && (scope.effective_action_target(0) == Some(target)
                                || scope.effective_action_target(1) == Some(target));
                    }
                    context.get_world_object(*candidate).is_some_and(|object| {
                        object.status().is_active()
                            && context
                                .world
                                .definition_metadata(object.definition_id())
                                .is_some_and(|metadata| {
                                    !metadata
                                        .action_library
                                        .is_idle_entry(object.action_name(), object.action_index)
                                })
                            && (object.action_target(0) == Some(target)
                                || object.action_target(1) == Some(target))
                    })
                })
            });
            let Some(candidate) = candidate else {
                break;
            };
            previous = Some(candidate);
            // Earlier SetAction callbacks may remove or retarget later
            // candidates; test the live state immediately before detaching.
            let attached = HOST_CONTEXT.with(|cell| {
                let borrow = cell.borrow();
                let Some(context) = borrow.as_ref() else {
                    return false;
                };
                if let Some(scope) = context.object_scope(candidate) {
                    return !scope.destroy
                        && scope.status().is_active()
                        && scope.effective_action_procedure() == ActionProcedure::Attach
                        && (scope.effective_action_target(0) == Some(target)
                            || scope.effective_action_target(1) == Some(target));
                }
                context.get_world_object(candidate).is_some_and(|object| {
                    object.is_present()
                        && object
                            .procedure_name()
                            .map(ActionProcedure::from_name)
                            .unwrap_or_default()
                            == ActionProcedure::Attach
                        && (object.action_target(0) == Some(target)
                            || object.action_target(1) == Some(target))
                })
            });
            if attached {
                // C++ calls C4Object::SetAction(ActIdle) directly. A script
                // function named SetAction must not intercept this detach.
                let _ = native_set_action_by_name(candidate, "Idle")?;
            }
        }
    }

    match stage {
        FireStage::Deny => unreachable!("denied fire start returned above"),
        FireStage::NoFire { blasted } => {
            // Blasted but not incinerated: IncinerationEx
            // (C4Effect.cpp:602-607) — fail-safe exec.
            if blasted {
                if let Some(Err(error)) = call_world_object_own_function(
                    target,
                    "IncinerationEx",
                    &[Value::Int(caused_by)],
                ) {
                    tracing::warn!(
                        %error,
                        "script error in IncinerationEx; continuing like the C++ fail-safe exec"
                    );
                }
            }
            return Ok(-1);
        }
        FireStage::Ignite => {}
    }
    let category = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return 0;
        };
        let Some(scope) = context.object_scope(target) else {
            return 0;
        };
        scope.pending_update.category.unwrap_or_else(|| {
            scope
                .pending_update
                .change_def
                .as_deref()
                .and_then(|id| context.world.definition_metadata(id))
                .map(|metadata| metadata.category)
                .unwrap_or(scope.current_category)
        })
    });
    // determine fire appearance (C4Effect.cpp:609-626): the ~FireMode
    // script answer wins; zero falls back to the category default; an
    // out-of-range answer degrades to Object mode.
    let mode_answer = match call_world_object_own_function(target, "FireMode", &[]) {
        Some(Ok(value)) => value_as_i32(&value),
        Some(Err(error)) => {
            tracing::warn!(
                %error,
                "script error in FireMode; continuing like the C++ fail-safe exec"
            );
            0
        }
        _ => 0,
    };
    let fire_mode = if mode_answer == 0 {
        if category & (crate::CATEGORY_LIVING | crate::CATEGORY_STATIC_BACK) != 0 {
            crate::C4FX_FIRE_MODE_LIVING_VEG
        } else if category & (crate::CATEGORY_STRUCTURE | crate::CATEGORY_VEHICLE) != 0 {
            crate::C4FX_FIRE_MODE_STRUCT_VEH
        } else {
            crate::C4FX_FIRE_MODE_OBJECT
        }
    } else if !(1..=crate::C4FX_FIRE_MODE_OBJECT).contains(&mode_answer) {
        tracing::warn!(
            mode = mode_answer,
            object = target.as_u64(),
            "FireMode is invalid; using Object mode like C++"
        );
        crate::C4FX_FIRE_MODE_OBJECT
    } else {
        mode_answer
    };
    HOST_CONTEXT.with(|cell| -> Result<(), RuntimeError> {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(());
        };
        // store causes in effect vars (C4Effect.cpp:628-631)
        if let Some(scope) = context.object_scope_mut(target) {
            let number = fire_number.max(0) as usize;
            scope
                .effects
                .effect_var(number, 0, Some(EffectVarValue::Int(fire_mode)));
            scope
                .effects
                .effect_var(number, 1, Some(EffectVarValue::Int(caused_by)));
            scope
                .effects
                .effect_var(number, 2, Some(EffectVarValue::Bool(blasted)));
            scope.effects.effect_var(
                number,
                3,
                Some(
                    incinerating
                        .map(|id| EffectVarValue::Object(id.as_u64()))
                        .unwrap_or(EffectVarValue::Nil),
                ),
            );
        }
        // Set values + FirePhase = Random(15), one synced draw
        // (C4Effect.cpp:632-634).
        let phase = draw_context_random(15)?;
        if let Some(scope) = context.object_scope_mut(target) {
            scope.pending_update.stage_ignite(caused_by, phase);
        }
        Ok(())
    })?;
    // Engine script call (C4Effect.cpp:638) — fail-safe exec.
    if let Some(Err(error)) =
        call_world_object_own_function(target, "Incineration", &[Value::Int(caused_by)])
    {
        tracing::warn!(
            %error,
            "script error in Incineration; continuing like the C++ fail-safe exec"
        );
    }
    Ok(0)
}

/// FnFxFireStart (C4Effect.cpp:560-641; AddFunc C4Script.cpp:6994) — the
/// engine-internal fire start, reachable from a script FxFireStart
/// overload's inherited(...) chain. A temp readd only re-arms the flag
/// (:563-565).
pub(crate) fn fx_fire_start(args: &[Value]) -> Result<Value, RuntimeError> {
    let target = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "FxFireStart",
        "object",
    )?;
    // safety (C4Effect.cpp:563)
    let Some(target) = target else {
        return Ok(Value::Int(-1));
    };
    let fire_number = parse_optional_i32(args.get(1), "FxFireStart", "number")?.unwrap_or(0);
    let temp = args.get(2).is_some_and(|value| value_as_i32(value) != 0);
    if temp {
        // temp readd: SetOnFire(true), return 1 (C4Effect.cpp:565)
        HOST_CONTEXT.with(|cell| {
            if let Some(context) = cell.borrow_mut().as_mut() {
                if context.ensure_object_scope(target) {
                    if let Some(scope) = context.object_scope_mut(target) {
                        scope.pending_update.stage_fire_flag(true);
                    }
                }
            }
        });
        return Ok(Value::Int(1));
    }
    let caused_by = parse_optional_i32(args.get(3), "FxFireStart", "caused by")?.unwrap_or(0);
    let blasted = args.get(4).map(extract_cpp_native_bool).unwrap_or(false);
    let incinerating = args
        .get(5)
        .map(|arg| parse_object_reference_argument(arg, "FxFireStart", "incinerating object"))
        .transpose()?
        .flatten();
    fire_effect_start_core(target, fire_number, caused_by, blasted, incinerating).map(Value::Int)
}

/// FnFxFireTimer (C4Effect.cpp:643-666; AddFunc C4Script.cpp:6995) →
/// C4Object::ExecFire (C4Object.cpp:766-810) through the staged seam —
/// a script FxFireTimer overload's inherited(...) chain lands here. The
/// deterministic arms (phase, decay, Tick10 damage, Tick5 energy,
/// extinguisher, the Random(3) inflame draw) run in C++ ledger order;
/// fire particles, SmokeRate smoke, and sounds are presentation-only.
fn fx_fire_timer(args: &[Value]) -> Result<Value, RuntimeError> {
    let target = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "FxFireTimer",
        "object",
    )?;
    // safety: no object → C4Fx_Execute_Kill (C4Effect.cpp:646)
    let Some(target) = target else {
        return Ok(Value::Int(-1));
    };
    let fire_number = parse_optional_i32(args.get(1), "FxFireTimer", "number")?.unwrap_or(0);
    let frame = ENVIRONMENT_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .map(|context| context.frame)
            .unwrap_or(0)
    });
    struct FireExecState {
        caused_by: i32,
        attribution_caused_by: i32,
        phase: i32,
        no_burn_decay: bool,
        no_burn_damage: bool,
        position: Vector2,
    }
    let state = HOST_CONTEXT.with(|cell| -> Option<FireExecState> {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut()?;
        if !context.ensure_object_scope(target) {
            return None;
        }
        let scope = context.object_scope(target)?;
        let burning = scope.pending_update.staged_on_fire().unwrap_or_else(|| {
            context
                .get_world_object(target)
                .and_then(|object| object.full_state().map(|state| state.on_fire))
                .unwrap_or(false)
        });
        if !burning {
            return None;
        }
        let world_fire = context.get_world_object(target).and_then(|object| {
            object
                .full_state()
                .map(|state| (state.fire_caused_by, state.fire_phase))
        });
        // staged ignite wins over the world snapshot
        let (caused_by, phase) = scope
            .pending_update
            .fire
            .or(world_fire)
            .unwrap_or((OWNER_NONE, 0));
        // FnFxFireTimer reads the cause from the effect variable every
        // time, then validates that local value without rewriting Var(1).
        let effect_caused_by = scope
            .effects
            .snapshot()
            .iter()
            .find(|effect| effect.number == fire_number)
            .and_then(|effect| effect.vars.get(1))
            .map(|value| match value {
                EffectVarValue::Int(value) => *value,
                EffectVarValue::Bool(value) => i32::from(*value),
                EffectVarValue::RawBool(value) => *value as u32 as i32,
                _ => 0,
            })
            .unwrap_or(caused_by);
        let attribution_caused_by = context
            .player_state(effect_caused_by)
            .map(|_| effect_caused_by)
            .unwrap_or(OWNER_NONE);
        let fire_meta = effective_definition_id(context, target)
            .and_then(|id| context.world.definition_metadata(&id))
            .map(|metadata| metadata.fire.clone())
            .unwrap_or_default();
        let scope = context.object_scope(target)?;
        Some(FireExecState {
            caused_by,
            attribution_caused_by,
            phase,
            no_burn_decay: fire_meta.no_burn_decay,
            no_burn_damage: fire_meta.no_burn_damage,
            position: scope.effective_position(),
        })
    });
    // fire already out: kill the effect (C4Effect.cpp:663-666)
    let Some(state) = state else {
        return Ok(Value::Int(-1));
    };
    // Fire Phase (C4Object.cpp:770)
    let next_phase = (state.phase + 1) % crate::MAX_FIRE_PHASE;
    HOST_CONTEXT.with(|cell| {
        if let Some(context) = cell.borrow_mut().as_mut() {
            if let Some(scope) = context.object_scope_mut(target) {
                scope
                    .pending_update
                    .stage_ignite(state.caused_by, next_phase);
            }
        }
    });
    // C4Object::ExecFire's Tick5 base arm runs immediately after the phase
    // advance and before decay/damage/energy. ValidPlr is only membership in
    // the live player list; the container need not belong to the victim.
    if frame % 5 == 0 {
        let extinguish_in_base = HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let Some(context) = borrow.as_ref() else {
                return false;
            };
            if !context.world.base_extinguish_enabled {
                return false;
            }
            let Some(scope) = context.object_scope(target) else {
                return false;
            };
            if scope.category() & crate::CATEGORY_LIVING == 0 {
                return false;
            }
            let Some(container) = scope.container() else {
                return false;
            };
            let base = context
                .object_scope(container)
                .and_then(|scope| scope.pending_update.base)
                .or_else(|| {
                    context
                        .get_world_object(container)
                        .and_then(|object| object.full_state().map(|state| state.base))
                });
            base.is_some_and(|base| context.player_state(base).is_some())
        });
        if extinguish_in_base {
            extinguish_effect_target(target, fire_number)?;
        }
    }
    // Decay: DoCon(-100) every frame; burned away at zero construction
    // (C4Object.cpp:779-781 + the engine-side burn loop).
    if !state.no_burn_decay {
        let _ = do_con_live(target, -100)?;
    }
    let target_value = object_reference_value(target);
    // Damage: Tick10 DoDamage(+2) by fire (C4Object.cpp:783)
    if frame % 10 == 0 && !state.no_burn_damage {
        do_damage_with_cause_override(
            &[
                Value::Int(2),
                target_value.clone(),
                Value::Int(crate::C4FX_CALL_DMG_FIRE),
                Value::Int(state.attribution_caused_by + 1),
            ],
            Some(state.attribution_caused_by),
        )?;
    }
    // Energy: Tick5 DoEnergy(-1) (C4Object.cpp:785)
    if frame % 5 == 0 {
        do_energy_with_cause_override(
            &[
                Value::Int(-1),
                target_value,
                Value::Bool(false),
                Value::Int(crate::C4FX_CALL_ENG_FIRE),
                Value::Int(state.attribution_caused_by + 1),
            ],
            Some(state.attribution_caused_by),
        )?;
    }
    // Background effects: Tick5 over valid landscape material — extinguish
    // in extinguisher material, then the unconditional Random(3) inflame
    // draw (C4Object.cpp:794-809).
    if frame % 5 == 0 {
        let material_extinguisher = HOST_CONTEXT.with(|cell| {
            cell.borrow().as_ref().and_then(|context| {
                context
                    .landscape_ref()
                    .and_then(|landscape| landscape.material_at(state.position.x, state.position.y))
                    .zip(context.world.materials())
                    .and_then(|(material_id, materials)| materials.get_by_id(material_id))
                    .map(|material| material.extinguisher() != 0)
            })
        });
        if let Some(extinguisher) = material_extinguisher {
            if extinguisher {
                // Extinguish(iFireNumber) — C4Object.cpp:801; the number
                // form kills exactly this effect.
                extinguish_effect_target(target, fire_number)?;
            }
            // Inflame (C4Object.cpp:803-804)
            if draw_context_random(3)? == 0 {
                incinerate_landscape_at(state.position.x, state.position.y)?;
            }
        }
    }
    // FnFxFireTimer returns C4Fx_Execute_Kill once the flag is gone
    // (C4Effect.cpp:663-666).
    let still_burning = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_scope(target))
            .and_then(|scope| scope.pending_update.staged_on_fire())
            .unwrap_or(true)
    });
    Ok(Value::Int(if still_burning { 0 } else { -1 }))
}

/// FnFxFireStop (C4Effect.cpp:775-792; AddFunc C4Script.cpp:6996): clear
/// the OnFire flag — real and temp removals alike; the Fire sound stop
/// is presentation-only.
fn fx_fire_stop(args: &[Value]) -> Result<Value, RuntimeError> {
    let target = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "FxFireStop",
        "object",
    )?;
    // safety (C4Effect.cpp:778)
    let Some(target) = target else {
        return Ok(Value::Bool(false));
    };
    HOST_CONTEXT.with(|cell| {
        if let Some(context) = cell.borrow_mut().as_mut() {
            if context.ensure_object_scope(target) {
                if let Some(scope) = context.object_scope_mut(target) {
                    scope.pending_update.stage_fire_flag(false);
                }
            }
        }
    });
    Ok(Value::Bool(true))
}

/// FnFxFireInfo (C4Effect.cpp:794-797; AddFunc C4Script.cpp:6997): the
/// burning status line (IDS_OBJ_BURNS).
fn fx_fire_info(_args: &[Value]) -> Result<Value, RuntimeError> {
    Ok(Value::String("{{FLAM}} The object burns.".into()))
}

/// FnIncinerate (C4Script.cpp:245-252): the target defaults to the
/// caller; iCausedBy is the CALLING object's controller (NO_OWNER
/// without one).
fn incinerate(args: &[Value]) -> Result<Value, RuntimeError> {
    let target_id = args
        .first()
        .map(|arg| parse_object_reference_argument(arg, "Incinerate", "target"))
        .transpose()?
        .flatten();
    let (active, caused_by) = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_context())
            .map(|object| (Some(object.id()), object.controller()))
            .unwrap_or((None, OWNER_NONE))
    });
    let Some(target) = target_id.or(active) else {
        return Ok(Value::Bool(false));
    };
    Ok(Value::Bool(incinerate_target(
        target, caused_by, false, None,
    )?))
}

/// FnExtinguish (C4Script.cpp:264-270) → C4Object::Extinguish(0)
/// (C4Object.cpp:1269-1301): kill every "*Fire*" effect, skipping the
/// engine-internal "Int*" names (C4Fx_AnyFire/C4Fx_Internal,
/// C4Effects.h:154-155).
fn extinguish(args: &[Value]) -> Result<Value, RuntimeError> {
    let target_id = args
        .first()
        .map(|arg| parse_object_reference_argument(arg, "Extinguish", "target"))
        .transpose()?
        .flatten();
    let active = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_context().map(|object| object.id()))
    });
    let Some(target) = target_id.or(active) else {
        return Ok(Value::Bool(false));
    };
    extinguish_target(target).map(Value::Bool)
}

/// The staged half of C4Object::Extinguish(0): the kill loop over
/// "*Fire*"-matching, non-"Int*" effects (C4Object.cpp:1281-1298). The
/// engine-internal FnFxFireStop clears the OnFire flag synchronously
/// (C4Effect.cpp:787) unless a script global shadows it; script Fx*Stop
/// callbacks ride the deferred Stopped dispatch of the staged removals.
fn extinguish_target(target: ObjectId) -> Result<bool, RuntimeError> {
    extinguish_effect_target(target, 0)
}

/// The numbered `C4Object::Extinguish(iFireNumber)` form used by ExecFire:
/// zero selects every public `*Fire*` effect, while a nonzero number kills
/// exactly that effect (C4Object.cpp:1276-1299).
fn extinguish_effect_target(target: ObjectId, fire_number: i32) -> Result<bool, RuntimeError> {
    let engine_fire_stop = !script_shadows_engine_fx("FxFireStop");
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(false);
        };
        if !context.ensure_object_scope(target) {
            return Ok(false);
        }
        let Some(scope) = context.object_scope_mut(target) else {
            return Ok(false);
        };
        let mut killed = 0usize;
        loop {
            let number = scope.effects.effects.iter().find_map(|effect| {
                (effect.priority != 0
                    && if fire_number != 0 {
                        effect.number == fire_number
                    } else {
                        effect.name.contains("Fire") && !effect.name.starts_with("Int")
                    })
                .then_some(effect.number)
            });
            let Some(number) = number else { break };
            let Some(removed) =
                scope
                    .effects
                    .remove_live_effect(None, number.max(0), false)
            else {
                break;
            };
            if removed.name == crate::C4FX_FIRE && engine_fire_stop {
                scope.pending_update.stage_fire_flag(false);
            }
            killed += 1;
            if fire_number != 0 {
                break;
            }
        }
        Ok(killed > 0)
    })
}

/// Whether a script global shadows an engine-registered Fx* function —
/// C4Effect callback resolution finds script functions before the
/// engine's own (GetFuncRecursive over AddFunc'd C++ functions,
/// C4Effect.cpp:30-56 + C4Script.cpp:6994-6997).
fn script_shadows_engine_fx(function: &str) -> bool {
    HOST_CONTEXT.with(|cell| {
        cell.borrow().as_ref().is_some_and(|context| {
            context
                .world
                .scenario_script()
                .is_some_and(|script| script.has_global_function(function))
                || context
                    .world
                    .definition_scripts()
                    .any(|script| script.has_global_function(function))
        })
    })
}

fn set_action(args: &[Value]) -> Result<Value, RuntimeError> {
    if std::env::var("LC_DEBUG_CHBM").is_ok() {
        tracing::warn!(?args, "OSA SetAction");
    }
    let action_name = match args.first().unwrap_or(&Value::Nil) {
        Value::String(name) if !name.is_empty() => Some(name.clone()),
        Value::String(_) | Value::Nil => None,
        other => {
            return Err(RuntimeError::new(format!(
                "SetAction: expected string or nil for action name, got {}",
                other.type_name()
            )));
        }
    };

    // FnSetAction (C4Script.cpp:747-753): (szAction, pTarget, pTarget2,
    // fDirect) — the objects are the ACTION's targets
    // (SetActionByName(..., pTarget, pTarget2)), while fDirect is passed as
    // SetAction's fForce and bypasses NoOtherAction.
    let target1 = args
        .get(1)
        .map(|arg| parse_object_reference_argument(arg, "SetAction", "target"))
        .transpose()?
        .flatten();
    let target2 = args
        .get(2)
        .map(|arg| parse_object_reference_argument(arg, "SetAction", "target2"))
        .transpose()?
        .flatten();
    if args.len() > 4 {
        return Err(RuntimeError::new(format!(
            "SetAction: expected at most 4 arguments, got {}",
            args.len()
        )));
    }
    let force = args
        .get(3)
        .map(|value| value_to_bool(value, "SetAction", "direct/force"))
        .transpose()?
        .unwrap_or(false);

    let name = match action_name {
        Some(name) => name,
        None => return Ok(Value::Bool(false)),
    };
    let name = clonk_script::c4_string_from_bytes(&clonk_script::c4_string_bytes(&name));
    let builtin_idle = crate::action::is_builtin_idle_name(&name);
    let name = if builtin_idle {
        crate::action::DEFAULT_ACTION_NAME.to_string()
    } else {
        name
    };

    let mut sync_callbacks: Option<(
        ObjectId,
        Option<ScriptCallbackTarget>,
        Option<ScriptCallbackTarget>,
        i32,
        Option<String>,
    )> = None;
    let staged = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetAction requires an active engine context"))?;
        // SetActionByName returns false without changing anything when the
        // requested name is absent from the ActMap (C4Object.cpp:4218-4234).
        // "Idle"/"ActIdle" are the one sentinel exception. ChangeDef swaps
        // Def inline in C++, so a later same-call SetAction resolves against
        // the pending NEW definition (the horse Death -> Dead path).
        let action_exists = context.object_context().is_some_and(|object| {
            name == "Idle"
                || object
                    .pending_update
                    .change_def
                    .as_deref()
                    .and_then(|definition| context.world.definition_metadata(definition))
                    .map(|metadata| metadata.action_library.contains(&name))
                    .unwrap_or_else(|| object.action_library.contains(&name))
        });
        if !action_exists {
            return Ok(Value::Bool(false));
        }
        let incomplete_activity = context
            .object_context()
            .and_then(|object| {
                object
                    .pending_update
                    .change_def
                    .as_deref()
                    .or(object.definition_id.as_deref())
            })
            .and_then(|definition| context.world.definition_metadata(definition))
            .is_some_and(|metadata| metadata.fire.incomplete_activity);
        let object = match context.object_context_mut() {
            Some(object) => object,
            None => return Ok(Value::Bool(false)),
        };

        let current_action = object.effective_action_name().to_string();
        let current_index = object.effective_action_index();
        let current_phase = object.action_phase();
        let callback_definition = object
            .pending_update
            .change_def
            .clone()
            .or_else(|| object.definition_id.clone());
        let requested_index = object.action_library.named_action_index(&name);
        let blocks_other_actions = object.effective_blocks_other_actions();
        let requested_action_changed =
            name != current_action || requested_index != current_index;
        if blocks_other_actions && requested_action_changed && !force {
            return Ok(Value::Bool(false));
        }

        // C4Object::SetAction validates the requested slot and applies the
        // old action's NoOtherAction gate first, then accepts the call but
        // coerces its resulting numeric action to ActIdle when the object is
        // incomplete and the live definition disallows incomplete activity
        // (C4Object.cpp:4111-4130).
        let actual_name = if object.construction() < FULL_CON && !incomplete_activity {
            crate::action::DEFAULT_ACTION_NAME
        } else {
            name.as_str()
        };
        let actual_index = object.action_library.named_action_index(actual_name);
        let changed_action =
            actual_name != current_action || actual_index != current_index;

        let update = object
            .pending_update
            .action
            .get_or_insert_with(ActionUpdate::default);
        update.set_name(actual_name.to_string());
        update.set_force(force);
        // C4Object::SetAction snaps fix_x/fix_y after changing the action
        // (C4Object.cpp:4144). If it follows DoCon in this staged call, that
        // later snap wins over DoCon's stale-fixed UpdatePos behavior.
        object.pending_update.construction_preserves_fixed_position = false;
        let position = object.effective_position();
        object.current_fixed_position = FixedVec2::from_ints(position.x, position.y);

        // SetActionByName carries the action targets, and C4Object::SetAction
        // assigns them ONLY when non-null (C4Object.cpp:4123-4125:
        // `if (pTarget) Action.Target = pTarget;`) — nil preserves. Its
        // Idle/ActIdle sentinel branch discards both supplied target args
        // before calling SetAction (C4Object.cpp:4225-4227).
        if !builtin_idle {
            if target1.is_some() {
                object.set_action_target(0, target1);
            }
            if target2.is_some() {
                object.set_action_target(1, target2);
            }
        }
        // SetAction always clears PhaseDelay, even when it selects the same
        // numeric slot and Phase was already zero (C4Object.cpp:4142-4146).
        // Action.Time resets only when the numeric slot changes.
        if changed_action {
            object.reset_action_ticks();
        } else {
            object.reset_action_phase_delay();
        }
        // `Action.Phase = Action.PhaseDelay = 0` runs UNCONDITIONALLY on
        // every successful SetAction (C4Object.cpp:4132, outside the
        // change guard) — a pre-change SetPhase must not leak into the
        // new action (the GoldRush FireRifle ph6 -> LoadRifle ph0 case).
        object.set_action_phase(0);

        let procedure_changed = object.update_effective_action(actual_name);
        if procedure_changed {
            object.reset_action_data();
        }
        // C4Object::SetAction fires the calls with NO same-action gate
        // (C4Object.cpp:4146-4183) — a same-name SetAction re-runs the
        // StartCall once. Marking the update dispatched keeps the fold
        // from ALSO queueing deferred Abort/Start events (C++ has no
        // such queue; leaving same-name staging to the queue made the
        // coach's Driving guard loop forever against stale state).
        if let Some(update) = object.pending_update.action.as_mut() {
            update.callbacks_dispatched = true;
        }
        sync_callbacks = Some((
            object.id(),
            (actual_name != crate::action::DEFAULT_ACTION_NAME)
                .then(|| {
                    object
                        .action_library
                        .start_callback_for_entry(actual_name, actual_index)
                })
                .flatten(),
            object
                .action_library
                .abort_callback_for_entry(&current_action, current_index)
                .filter(|_| !force),
            current_phase,
            callback_definition,
        ));
        let object_id = object.id();
        // SetAction calls SetOCF before Start/Abort callbacks. Use the full
        // live refresh so leaving an ObjectDisabled action can re-add
        // OCF_FightReady rather than only clearing stale bits.
        let _ = refresh_live_object_ocf(context, object_id);

        Ok(Value::Bool(true))
    })?;
    // C4Object::SetAction runs the StartCall for the NEW action and then the
    // AbortCall for the OLD one SYNCHRONOUSLY inside the call
    // (SetActionByName defaults SAC_StartCall|SAC_AbortCall) — the
    // coach's Drive0 StartCall reads the PRE-SetDir facing for its seat
    // vertex, so deferral changes the result.
    if let Some((
        id,
        start_call,
        abort_call,
        previous_phase,
        callback_definition,
    )) = sync_callbacks
    {
        // C++ has no SetAction-specific recursion guard. Nested callbacks
        // keep dispatching synchronously until they terminate or the shared
        // script VM reports its native-equivalent stack/value limit.
        let callbacks = [
            start_call.map(|callback| (callback, Vec::new())),
            abort_call.map(|callback| (callback, vec![Value::Int(previous_phase)])),
        ];
        for (callback, args) in callbacks.into_iter().flatten() {
            if let Some(Err(error)) = call_world_object_script_callback(id, &callback, &args) {
                tracing::warn!(
                    %error,
                    callback = callback.function_name(),
                    "SetAction callback error; continuing like the C++ fail-safe exec"
                );
            }
            let receiver_is_live = HOST_CONTEXT.with(|cell| {
                cell.borrow().as_ref().is_some_and(|context| {
                    context.object_status_present(id)
                        && callback_definition.as_deref().is_none_or(|expected| {
                            context.object_effective_definition_id(id).as_deref()
                                == Some(expected)
                        })
                })
            });
            if !receiver_is_live {
                break;
            }
        }
    }
    Ok(staged)
}

/// C++ always has `Game.Material`; `None` only occurs in legacy Rust host
/// fixtures. Keep their previous byte clamp while making both bridge-data
/// entry points share one conversion.
fn clamp_bridge_material(material: i32, materials: Option<&MaterialSet>) -> i32 {
    match materials {
        Some(materials) if materials.is_empty() => -1,
        Some(materials) => material.min(materials.len().saturating_sub(1) as i32),
        None if material < 0 => -1,
        None => material.min(0xFF),
    }
}

fn set_bridge_action_data(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 5 {
        return Err(RuntimeError::new(
            "SetBridgeActionData expects at most 5 arguments: length, move flag, wall flag, material, object",
        ));
    }
    let param_count = args.len().min(4);
    let target_id = args
        .get(4)
        .map(|value| parse_object_reference_argument(value, "SetBridgeActionData", "object"))
        .transpose()?
        .flatten();

    let length = if param_count > 0 {
        value_to_i32(&args[0], "SetBridgeActionData", "length")?
    } else {
        // Unfilled iBridgeLength is nil -> 0 (C4Script.cpp:756).
        0
    };
    let move_clonk = if param_count > 1 {
        value_to_bool(&args[1], "SetBridgeActionData", "move_clonk")?
    } else {
        false
    };
    let wall = if param_count > 2 {
        value_to_bool(&args[2], "SetBridgeActionData", "wall")?
    } else {
        false
    };
    let material = if param_count > 3 {
        match &args[3] {
            Value::Nil => -1,
            other => value_to_i32(other, "SetBridgeActionData", "material")?,
        }
    } else {
        -1
    };

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut().ok_or_else(|| {
            RuntimeError::new("SetBridgeActionData requires an active engine context")
        })?;

        // C4Action::SetBridgeData clamps to the last loaded material before
        // packing the low byte (C4Object.cpp:54-62). A loaded empty table has
        // Num-1 == -1 and therefore stores the no-material sentinel 0xff.
        let material = clamp_bridge_material(material, context.world.materials());
        let encoded = encode_bridge_action_data(length, move_clonk, wall, material);

        // FnSetBridgeActionData defaults pObj to cthr->Obj, but an explicit
        // object may be foreign (C4Script.cpp:757-765). LOAM::StartBridge
        // runs in the loam's scope after ObjectSetAction staged "Bridge" on
        // the Clonk, so read and write that target's live nested scope.
        let Some(target) = target_id.or(context.script_object_context) else {
            return Ok(Value::Bool(false));
        };
        if !context.object_status_present(target) || !context.ensure_object_scope(target) {
            return Ok(Value::Bool(false));
        }
        let Some(object) = context.object_scope_mut(target) else {
            return Ok(Value::Bool(false));
        };

        if object.effective_action_procedure() != ActionProcedure::Bridge {
            return Ok(Value::Bool(false));
        }

        object.set_action_data(encoded);
        Ok(Value::Bool(true))
    })
}

fn set_action_data(args: &[Value]) -> Result<Value, RuntimeError> {
    // Unfilled iData is nil -> 0 (FnSetActionData, C4Script.cpp:767).
    let data = value_to_i32(args.first().unwrap_or(&Value::Nil), "SetActionData", "data")?;
    let mut index = 1;
    let mut target_id: Option<ObjectId> = None;

    if let Some(arg) = args.get(index) {
        target_id = parse_object_reference_argument(arg, "SetActionData", "target")?;
        index += 1;
    }

    if index < args.len() {
        return Err(RuntimeError::new(
            "SetActionData: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetActionData requires an active engine context"))?;
        let bridge_material = clamp_bridge_material(data, context.world.materials());
        let Some(target) = target_id.or(context.script_object_context) else {
            return Ok(Value::Bool(false));
        };
        if !context.object_status_present(target) || !context.ensure_object_scope(target) {
            return Ok(Value::Bool(false));
        }
        let Some(object) = context.object_scope_mut(target) else {
            return Ok(Value::Bool(false));
        };

        let procedure = object.effective_action_procedure();
        let mut next_data = data;
        match procedure {
            ActionProcedure::Bridge => {
                next_data = encode_bridge_action_data(0, false, false, bridge_material);
            }
            ActionProcedure::Attach => {
                let primary_vertex = (data & 0xFF) as i32;
                let secondary_vertex = data >> 8;
                if primary_vertex >= MAX_VERTEX_COUNT || secondary_vertex >= MAX_VERTEX_COUNT {
                    return Ok(Value::Bool(false));
                }
            }
            _ => {}
        }

        object.set_action_data(next_data);
        Ok(Value::Bool(true))
    })
}

fn set_action_targets(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut index = 0;

    // FnSetActionTargets assigns BOTH targets unconditionally
    // (C4Script.cpp:1108-1116): unfilled parameter slots are nil, so a
    // bare `SetActionTargets()` clears them (the horse's DisconnectWagon,
    // Horse.c4d Script.c:398).
    let target1 = if let Some(arg) = args.get(index) {
        let target = parse_object_reference_argument(arg, "SetActionTargets", "target1")?;
        index += 1;
        target
    } else {
        None
    };

    let target2 = if let Some(arg) = args.get(index) {
        let target = parse_object_reference_argument(arg, "SetActionTargets", "target2")?;
        index += 1;
        target
    } else {
        None
    };

    let mut object_id: Option<ObjectId> = None;
    if let Some(arg) = args.get(index) {
        object_id = parse_object_reference_argument(arg, "SetActionTargets", "object")?;
        index += 1;
    }

    if index < args.len() {
        return Err(RuntimeError::new(
            "SetActionTargets: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut().ok_or_else(|| {
            RuntimeError::new("SetActionTargets requires an active engine context")
        })?;
        let Some(target) = object_id.or(context.script_object_context) else {
            return Ok(Value::Bool(false));
        };
        if !context.ensure_object_scope(target) {
            return Ok(Value::Bool(false));
        }
        let Some(object) = context.object_scope_mut(target) else {
            return Ok(Value::Bool(false));
        };

        object.set_action_target(0, target1);
        object.set_action_target(1, target2);

        Ok(Value::Bool(true))
    })
}

/// FnScrollContents (C4Script.cpp:1793-1805): move the raw first contents
/// link to the back and return the new first object. Unlike ShiftContents,
/// this always advances exactly one link, including within a uniform stack.
fn scroll_contents(args: &[Value]) -> Result<Value, RuntimeError> {
    let target_object =
        parse_native_object_argument(args.first(), "ScrollContents", "target")?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Nil);
        };
        let Some(target) = target_object.or(context.script_object_context) else {
            return Ok(Value::Nil);
        };
        let Some(container) = context.get_world_object(target) else {
            return Ok(Value::Nil);
        };
        let contents: Vec<ObjectId> = container
            .contents()
            .iter()
            .copied()
            .filter(|child| {
                context
                    .get_world_object(*child)
                    .is_some_and(|object| object.is_present())
            })
            .collect();
        let Some(front) = contents.first().copied() else {
            return Ok(Value::Nil);
        };
        let Some(new_front) = contents.get(1).copied() else {
            return Ok(object_reference_value(front));
        };
        if !context.ensure_object_scope(target) {
            return Ok(Value::Nil);
        }
        let Some(container) = context.object_scope_mut(target) else {
            return Ok(Value::Nil);
        };
        container.shift_contents_front(new_front);
        Ok(object_reference_value(new_front))
    })
}

/// FnShiftContents (C4Script.cpp:1784-1797): rotate the contents list so a
/// different item comes first (C4Object::ShiftContents,
/// C4Object.cpp:5728-5752) or bring the first idTarget content to the
/// front (DirectComContents, :5754-5775). The rotation itself is the C++
/// cyclic relink (C4ObjectList.cpp:815-833), applied via
/// ObjectUpdate.contents_front; with fDoCalls the container's
/// ~ControlContents(id) may veto and the new front gets
/// ~Selection(container) with the Grab sound on a falsy return
/// (C4Object.cpp:5760-5767); the menu Refill (:5769-5772) is
/// presentation-only and unmodeled. Unfiltered shifts reuse the same live
/// CanConcatPictureWith predicate as internal menu grouping, including
/// same-call appearance writes. Contents include same-call CreateContents/
/// Enter scopes, matching the live C4ObjectList.
fn shift_contents(args: &[Value]) -> Result<Value, RuntimeError> {
    let target_object = match args.first() {
        None | Some(Value::Nil | Value::Int(0)) => None,
        Some(value @ (Value::Object(_) | Value::Proplist(_))) => {
            parse_object_reference_argument(value, "ShiftContents", "target")?
        }
        // C++ par conversion nils a non-object slot -> local call.
        Some(_) => None,
    };
    let shift_back = args
        .get(1)
        .map(|value| value_to_bool(value, "ShiftContents", "shift back"))
        .transpose()?
        .unwrap_or(false);
    let id_target = parse_native_c4id_argument(args.get(2), "ShiftContents")?;
    let do_calls = args
        .get(3)
        .map(|value| value_to_bool(value, "ShiftContents", "do calls"))
        .transpose()?
        .unwrap_or(false);

    // FnShiftContents' pObj may name ANOTHER container (C4Script.cpp:1786
    // only defaults nil to cthr->Obj) — re-enter through the nested seam so
    // the target's own scope runs the shift (the ObjectSetAction pattern).
    let active = active_object_id();
    if let Some(target) = target_object {
        if Some(target) != active {
            let forwarded = vec![
                Value::Nil,
                Value::Bool(shift_back),
                id_target.map(Value::C4Id).unwrap_or(Value::Nil),
                Value::Bool(do_calls),
            ];
            return match call_world_object_function(target, "ShiftContents", &forwarded) {
                Some(result) => result,
                None => Ok(Value::Bool(false)),
            };
        }
    }
    // Phase 1 (borrowed): resolve the frame-start contents view and pick
    // the new front — released before the DirectComContents calls re-enter.
    enum Picked {
        Done(Value),
        Shift {
            container: ObjectId,
            new_front: ObjectId,
            new_front_id: String,
        },
    }
    let picked = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Picked::Done(Value::Bool(false));
        };
        let Some(self_id) = context.object_context().map(|object| object.id()) else {
            return Picked::Done(Value::Bool(false));
        };
        let contents: Vec<(ObjectId, String)> = match context.get_world_object(self_id) {
            Some(container) => container
                .contents()
                .iter()
                .filter_map(|child_id| {
                    context
                        .get_world_object(*child_id)
                        .filter(|child| child.is_present())
                        .map(|child| (*child_id, child.definition_id().to_string()))
                })
                .collect(),
            None => return Picked::Done(Value::Bool(false)),
        };
        let Some((front_id, _)) = contents.first().cloned() else {
            return Picked::Done(Value::Bool(false));
        };
        let new_front = if let Some(id_target) = id_target {
            // Check if the ID is present within the container
            // (C4Script.cpp:1790-1793).
            let Some((found, _)) = contents
                .iter()
                .find(|(_, definition)| *definition == id_target)
            else {
                return Picked::Done(Value::Bool(false));
            };
            // Desired object already at front? (DirectComContents :5759.)
            if *found == front_id {
                return Picked::Done(Value::Bool(true));
            }
            *found
        } else {
            // Walk next (or prev from the back with fShiftBack) for the
            // first DIFFERENT item (C4Object.cpp:5734-5750).
            let candidate = if shift_back {
                contents
                    .iter()
                    .skip(1)
                    .rev()
                    .find(|(id, _)| !context.object_can_concat_picture_with(front_id, *id))
            } else {
                contents
                    .iter()
                    .skip(1)
                    .find(|(id, _)| !context.object_can_concat_picture_with(front_id, *id))
            };
            match candidate {
                Some((id, _)) => *id,
                None => return Picked::Done(Value::Bool(false)),
            }
        };
        let new_front_id = contents
            .iter()
            .find(|(id, _)| *id == new_front)
            .map(|(_, definition)| definition.clone())
            .unwrap_or_default();
        Picked::Shift {
            container: self_id,
            new_front,
            new_front_id,
        }
    });
    let (container, new_front, new_front_id) = match picked {
        Picked::Done(value) => return Ok(value),
        Picked::Shift {
            container,
            new_front,
            new_front_id,
        } => (container, new_front, new_front_id),
    };
    // DirectComContents (C4Object.cpp:5760-5763): with fDoCalls the
    // container's ~ControlContents(idNewFront) runs first — a truthy
    // return takes over the selection (fail-safe exec, errors read false).
    if do_calls {
        let veto = match call_world_object_own_function(
            container,
            "ControlContents",
            &[Value::C4Id(new_front_id)],
        ) {
            Some(Ok(value)) => value.as_bool(),
            Some(Err(error)) => {
                tracing::warn!(
                    %error,
                    "script error in ControlContents; continuing like the C++ fail-safe exec"
                );
                false
            }
            None => false,
        };
        if veto {
            return Ok(Value::Bool(true));
        }
    }
    // The cyclic relink (C4ObjectList::ShiftContents, C4ObjectList.cpp:
    // 815-833) via ObjectUpdate.contents_front.
    let shifted = HOST_CONTEXT.with(|cell| {
        cell.borrow_mut()
            .as_mut()
            .and_then(|context| context.object_context_mut())
            .map(|object| object.shift_contents_front(new_front))
            .is_some()
    });
    if !shifted {
        return Ok(Value::Bool(false));
    }
    // ~Selection(container) on the new front; a falsy return plays the
    // Grab sound at the container (C4Object.cpp:5767).
    if do_calls {
        let selected = match call_world_object_own_function(
            new_front,
            "Selection",
            &[object_reference_value(container)],
        ) {
            Some(Ok(value)) => value.as_bool(),
            Some(Err(error)) => {
                tracing::warn!(
                    %error,
                    "script error in Selection; continuing like the C++ fail-safe exec"
                );
                false
            }
            None => false,
        };
        if !selected {
            HOST_CONTEXT.with(|cell| {
                if let Some(context) = cell.borrow_mut().as_mut() {
                    context.audio_mut().play_sound(
                        "Grab",
                        Some(container),
                        100,
                        false,
                        false,
                        None,
                    );
                }
            });
        }
    }
    Ok(Value::Bool(true))
}

/// FnGetCommand (C4Script.cpp:918-945): walk the command stack to entry
/// iCommandNum and return the requested element. Reads use the staged live
/// stack when script has changed or executed commands in this call.
fn get_command(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut index = 0;
    let mut target_id: Option<ObjectId> = None;
    if let Some(arg) = args.get(index) {
        if matches!(
            arg,
            Value::Object(_) | Value::Proplist(_) | Value::Nil | Value::Int(0)
        ) {
            target_id = parse_object_reference_argument(arg, "GetCommand", "target")?;
            index += 1;
        }
    }
    let element = args
        .get(index)
        .map(|value| value_to_i32(value, "GetCommand", "element"))
        .transpose()?
        .unwrap_or(0);
    index += 1;
    let command_num = args
        .get(index)
        .map(|value| value_to_i32(value, "GetCommand", "command number"))
        .transpose()?
        .unwrap_or(0);

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let resolved = target_id.or_else(|| context.object_context().map(|object| object.id()));
        let Some(resolved) = resolved else {
            return Ok(Value::Nil);
        };
        // `while (Command && iCommandNum--)` (C4Script.cpp:924): a negative
        // count walks off the list end -> nil.
        if command_num < 0 {
            return Ok(Value::Nil);
        }
        let view = context
            .object_scope(resolved)
            .and_then(|scope| {
                scope
                    .live_commands
                    .command_views()
                    .get(command_num as usize)
                    .cloned()
            })
            .or_else(|| {
                context
                    .get_world_object(resolved)
                    .and_then(|object| object.commands.get(command_num as usize).cloned())
            });
        let Some(view) = view else {
            return Ok(Value::Nil);
        };
        // Element map (C4Script.cpp:926-945): 0 name, 1 Target, 2 Tx,
        // 3 C4VInt(Ty), 4 Target2, 5 C4Value(Data, C4V_Any) — a zero
        // int Data reads nil in C++.
        match element {
            0 => Ok(Value::String(view.name.clone().into())),
            1 => Ok(view
                .target
                .map(object_reference_value)
                .unwrap_or(Value::Nil)),
            2 => Ok(view
                .tx_value
                .or_else(|| view.tx_definition.map(Value::C4Id))
                .or_else(|| view.tx.map(Value::Int))
                .unwrap_or(Value::Nil)),
            3 => Ok(Value::Int(view.ty.unwrap_or(0))),
            4 => Ok(view
                .target2
                .map(object_reference_value)
                .unwrap_or(Value::Nil)),
            5 => Ok(view
                .legacy_data
                .or_else(|| match view.data {
                    CommandData::Integer(data) => Some(data),
                    CommandData::Text(_) | CommandData::None => None,
                })
                .map(command_data_any_value)
                .unwrap_or(Value::Nil)),
            _ => Ok(Value::Nil),
        }
    })
}

fn get_action(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut index = 0;
    let target_id =
        consume_optional_object_reference_argument(args, &mut index, "GetAction", "target")?;

    if index < args.len() {
        return Err(RuntimeError::new(
            "GetAction: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        if let Some(target) = target_id {
            if let Some(object) = context.object_context() {
                if target == object.id() {
                    let action_name = object.effective_action_name();
                    let resolved = if action_name.is_empty() {
                        "Idle"
                    } else {
                        action_name
                    };
                    return Ok(Value::String(resolved.to_string().into()));
                }
            }

            if let Some(other) = context.get_world_object(target) {
                let resolved = if other.action_name.is_empty() {
                    "Idle"
                } else {
                    other.action_name.as_str()
                };
                return Ok(Value::String(resolved.to_string().into()));
            }

            return Ok(Value::Nil);
        }

        let object = match context.object_context() {
            Some(object) => object,
            None => return Ok(Value::Nil),
        };

        let action_name = object.effective_action_name();
        let resolved = if action_name.is_empty() {
            "Idle"
        } else {
            action_name
        };
        Ok(Value::String(resolved.to_string().into()))
    })
}

