fn get_action_target(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut index = 0;
    let mut target_index = 0;

    if let Some(arg) = args.get(index) {
        match arg {
            Value::Int(value) => {
                target_index = *value;
                index += 1;
            }
            Value::Nil => {
                index += 1;
            }
            _ => {}
        }
    }

    let mut object_id: Option<ObjectId> = None;
    if let Some(arg) = args.get(index) {
        object_id = parse_object_reference_argument(arg, "GetActionTarget", "object")?;
        index += 1;
    }

    if index < args.len() {
        return Err(RuntimeError::new(
            "GetActionTarget: additional arguments are not supported",
        ));
    }

    if target_index < 0 {
        return Ok(Value::Nil);
    }

    let slot = target_index as usize;
    if slot > 1 {
        return Ok(Value::Nil);
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        if let Some(target) = object_id {
            if let Some(object) = context.object_context() {
                if target == object.id() {
                    let target_value = object.effective_action_target(slot);
                    return Ok(target_value.map_or(Value::Nil, object_reference_value));
                }
            }

            if let Some(other) = context.get_world_object(target) {
                let target_value = other.action_target(slot);
                return Ok(target_value.map_or(Value::Nil, object_reference_value));
            }

            return Ok(Value::Nil);
        }

        let object = match context.object_context() {
            Some(object) => object,
            None => return Ok(Value::Nil),
        };

        let target_value = object.effective_action_target(slot);
        Ok(target_value.map_or(Value::Nil, object_reference_value))
    })
}

fn get_vertex_num(args: &[Value]) -> Result<Value, RuntimeError> {
    let target_id = args
        .first()
        .map(|arg| parse_object_reference_argument(arg, "GetVertexNum", "object"))
        .transpose()?
        .flatten();

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        match resolve_vertices(context, target_id) {
            Some((_position, vertices)) => Ok(Value::Int(truncate_to_i32(vertices.len() as u64))),
            None => Ok(Value::Nil),
        }
    })
}

fn get_vertex(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.is_empty() {
        return Err(RuntimeError::new(
            "GetVertex: requires at least an index argument",
        ));
    }

    let index_value = value_to_i32(&args[0], "GetVertex", "index")?;
    // FnGetVertex's fixed C4ValueInt slot converts both an omitted value and
    // a legacy zero literal (nil) to VTX_X == 0.
    let attribute = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "GetVertex", "attribute")?;

    let mut target_id: Option<ObjectId> = None;
    let mut arg_index = 2;
    if let Some(arg) = args.get(2) {
        target_id = parse_object_reference_argument(arg, "GetVertex", "object")?;
        arg_index += 1;
    }

    if arg_index < args.len() {
        return Err(RuntimeError::new(
            "GetVertex: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        let (_position, vertices) = match resolve_vertices(context, target_id) {
            Some(value) => value,
            None => return Ok(Value::Nil),
        };

        if vertices.is_empty() {
            return Ok(Value::Nil);
        }

        let limit = vertices.len() as i32 - 1;
        let mut clamped = index_value;
        if clamped < 0 {
            clamped = 0;
        } else if clamped > limit {
            clamped = limit;
        }
        let vertex = &vertices[clamped as usize];
        let result = match attribute {
            0 => vertex.x,
            1 => vertex.y,
            2 => truncate_to_i32(vertex.cnat as u64),
            3 => vertex.friction,
            _ => vertex.y,
        };
        Ok(Value::Int(result))
    })
}

/// FnInside (C4Script.cpp:3350-3353): value within [lo, hi] inclusive.
fn inside(args: &[Value]) -> Result<Value, RuntimeError> {
    let value = value_to_i32(args.first().unwrap_or(&Value::Nil), "Inside", "value")?;
    let lo = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "Inside", "lo")?;
    let hi = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "Inside", "hi")?;
    Ok(Value::Bool(value >= lo && value <= hi))
}

/// FnGetVisibility (C4Script.cpp:3871-3877): return the target object's raw
/// visibility mask; a null target defaults to the calling object.
fn get_visibility(args: &[Value]) -> Result<Value, RuntimeError> {
    let target = args
        .first()
        .map(|arg| parse_object_reference_argument(arg, "GetVisibility", "obj"))
        .transpose()?
        .flatten();
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let Some(target) = target.or_else(|| context.object_context().map(|object| object.id()))
        else {
            return Ok(Value::Nil);
        };
        Ok(context
            .object_visibility(target)
            .map(Value::Int)
            .unwrap_or(Value::Nil))
    })
}

/// FnGetColor (C4Script.cpp:3629-3633): deprecated oldgfx stub.
fn get_color(args: &[Value]) -> Result<Value, RuntimeError> {
    if let Some(target) = args.first() {
        let _ = parse_object_reference_argument(target, "GetColor", "obj")?;
    }
    Ok(Value::Int(0))
}

/// FnSetCrewEnabled (C4Script.cpp:4814-4836): CrewDisabled = !enabled;
/// disabling also deselects (the cursor re-adjust runs on the engine
/// selection refresh).
/// FnGetColorDw (C4Script.cpp:3652-3656): the object's dword color;
/// nil without an object.
fn get_color_dw(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut index = 0;
    let target = consume_optional_object_reference_argument(args, &mut index, "GetColorDw", "obj")?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let active = context.object_context().map(|object| object.id());
        let Some(target) = target.or(active) else {
            return Ok(Value::Nil);
        };
        // A same-call SetColorDw staged the value on the scope.
        if Some(target) == active {
            if let Some(color) = context
                .object_context()
                .and_then(|object| object.pending_update.color)
            {
                return Ok(Value::Int(color as i32));
            }
        }
        match context.get_world_object(target) {
            Some(object) => Ok(Value::Int(
                object
                    .full_state()
                    .map(|state| state.color as i32)
                    .unwrap_or(0),
            )),
            None => Ok(Value::Nil),
        }
    })
}

/// FnGetChar (C4Script.cpp:4361-4370): the unsigned native byte at the index,
/// 0 past the end, and nil without a string. C++'s forward loop leaves every
/// negative index at offset zero.
fn get_char(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some(Value::String(text)) = args.first() else {
        return Ok(Value::Nil);
    };
    let index = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "GetChar", "index")?;
    if index < 0 {
        return Ok(Value::Int(
            clonk_script::c4_string_byte(text, 0)
                .map(i32::from)
                .unwrap_or(0),
        ));
    }
    Ok(Value::Int(
        clonk_script::c4_string_byte(text, index as usize)
            .map(i32::from)
            .unwrap_or(0),
    ))
}

/// FnGetCrewEnabled (C4Script.cpp:4813-4819): !CrewDisabled; nil/// FnGetCrewEnabled (C4Script.cpp:4813-4819): !CrewDisabled; nil
/// without an object.
fn get_crew_enabled(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut index = 0;
    let target =
        consume_optional_object_reference_argument(args, &mut index, "GetCrewEnabled", "obj")?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let active = context.object_context().map(|object| object.id());
        let target = target.or(active);
        let Some(target) = target else {
            return Ok(Value::Nil);
        };
        // A same-call SetCrewEnabled staged the flag on the scope.
        if Some(target) == active {
            if let Some(disabled) = context
                .object_context()
                .and_then(|object| object.pending_update.crew_disabled)
            {
                return Ok(Value::Bool(!disabled));
            }
        }
        match context.get_world_object(target) {
            Some(object) => Ok(Value::Bool(
                !object
                    .full_state()
                    .map(|state| state.crew_disabled)
                    .unwrap_or(false),
            )),
            None => Ok(Value::Nil),
        }
    })
}

/// C4Object::Call(PSF_CrewSelection) is fail-safe: callback errors abort the
/// callback but retain prior mutations and never abort the selecting script
/// (C4Object.cpp:5815-5832; C4AulExec.cpp:1318-1342).
fn call_crew_selection_callback(target: ObjectId, unselect: bool, cursor: bool) {
    if let Some(Err(error)) = call_world_object_own_function(
        target,
        "CrewSelection",
        &[Value::Bool(unselect), Value::Bool(cursor)],
    ) {
        tracing::warn!(
            object = %target,
            error = %error,
            "script error in crew selection callback; continuing like the C++ fail-safe exec"
        );
    }
}

/// C4Object::DoSelect (C4Object.cpp:5815-5824). Returns false only for an
/// unknown target; CrewDisabled is a successful callback-less no-op.
fn do_select_host_object(target: ObjectId, cursor: bool) -> bool {
    let disposition = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut()?;
        context.get_world_object(target)?;
        if context.object_crew_disabled(target).unwrap_or(false) {
            return Some(false);
        }
        if !cursor && !context.set_object_selected(target, true) {
            return None;
        }
        Some(true)
    });
    match disposition {
        None => false,
        Some(false) => true,
        Some(true) => {
            call_crew_selection_callback(target, false, cursor);
            true
        }
    }
}

/// C4Object::UnSelect (C4Object.cpp:5827-5832): unlike DoSelect it always
/// invokes the callback, including on CrewDisabled objects.
fn unselect_host_object(target: ObjectId, cursor: bool) -> bool {
    let known = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        if context.get_world_object(target).is_none() {
            return false;
        }
        cursor || context.set_object_selected(target, false)
    });
    if !known {
        return false;
    }
    call_crew_selection_callback(target, true, cursor);
    true
}

fn hi_rank_active_crew(
    context: &EffectHostContext,
    player: &PlayerState,
    selected: bool,
) -> Option<ObjectId> {
    let mut best = None;
    let mut highest_rank = -2;
    for &id in &player.crew {
        let Some(object) = context.get_world_object(id) else {
            continue;
        };
        let is_selected = context
            .object_scope(id)
            .map(ObjectScopeContext::selected)
            .unwrap_or(object.selected);
        if context.object_crew_disabled(id).unwrap_or(false) || (selected && !is_selected) {
            continue;
        }
        let rank = match context.object_scope(id) {
            Some(scope) => scope.info_rank(),
            None => context.world.crew_rank(id.as_u64()),
        }
        .unwrap_or(-1);
        if best.is_none() || rank > highest_rank {
            best = Some(id);
            highest_rank = rank;
        }
    }
    best
}

fn record_cursor_state(context: &mut EffectHostContext, player_id: i32) {
    let Some((object, control)) = context
        .player_state(player_id)
        .map(|player| (player.cursor, player.control))
    else {
        return;
    };
    context.record_player_command(PlayerCommand::SetCursor {
        player_id,
        object,
        control,
    });
}

/// C4PlayerList::ClearPointers in player-list order. Cursor replacement and
/// its selection callbacks run before the next player's pointers are cleared,
/// exactly as the C++ loop does.
fn clear_player_object_pointers_host(target: ObjectId) {
    let players = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Vec::new();
        };
        context.player_ids().to_vec()
    });
    for player_id in players {
        let removed_cursor = HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(context) = borrow.as_mut() else {
                return false;
            };
            let removed_cursor = context
                .player_state(player_id)
                .is_some_and(|player| player.cursor == Some(target));
            if let Some(player) = context.player_state_mut(player_id) {
                player.clear_object_pointers(target);
            }
            context.record_player_command(PlayerCommand::ClearPlayerObjectPointersWithoutAdjust {
                player_id,
                object: target,
            });
            removed_cursor
        });
        if removed_cursor {
            adjust_cursor_host(player_id);
        }
    }
}

/// C4Player::AdjustCursorCommand (C4Player.cpp:1235-1258).
fn adjust_cursor_host(player_id: i32) -> bool {
    let Some((previous, next)) = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut()?;
        let player = context.player_state(player_id)?.clone();
        let next = hi_rank_active_crew(context, &player, true)
            .or_else(|| hi_rank_active_crew(context, &player, false));
        let previous = player.cursor;
        context.player_state_mut(player_id)?.cursor = next;
        Some((previous, next))
    }) else {
        return false;
    };

    if previous != next {
        if let Some(previous) = previous {
            unselect_host_object(previous, true);
        }
    }
    // A callback above may itself have changed Cursor. C++ reads the live
    // field again for the final DoSelect call.
    let cursor = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.player_state(player_id))
            .and_then(|player| player.cursor)
    });
    if let Some(cursor) = cursor {
        do_select_host_object(cursor, false);
    }
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        if let Some(player) = context.player_state_mut(player_id) {
            player.control.cursor_flash = 30;
        }
        record_cursor_state(context, player_id);
    });
    true
}

fn select_crew_host_impl(
    player_id: i32,
    target: ObjectId,
    select: bool,
    no_cursor_adjust: bool,
) -> bool {
    let valid_player = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .is_some_and(|context| context.player_state(player_id).is_some())
    });
    if !valid_player {
        return false;
    }
    if no_cursor_adjust {
        return if select {
            do_select_host_object(target, false)
        } else {
            unselect_host_object(target, false)
        };
    }

    let is_crew = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.player_state(player_id))
            .is_some_and(|player| player.crew.contains(&target))
    });
    // C4Player::SelectCrew returns early for a target outside Crew, while
    // FnSelectCrew itself still reports success.
    if !is_crew {
        return true;
    }
    if select {
        do_select_host_object(target, false);
    } else {
        unselect_host_object(target, false);
    }
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        if let Some(player) = context.player_state_mut(player_id) {
            player.control.select_flash = 30;
            player.control.cursor_selection = 0;
            player.control.cursor_toggled = 0;
        }
    });
    adjust_cursor_host(player_id)
}

fn select_crew_host(args: &[Value]) -> Result<Value, RuntimeError> {
    let player_id = value_to_i32(args.first().unwrap_or(&Value::Nil), "SelectCrew", "player")?;
    let target = args
        .get(1)
        .map(|value| parse_object_reference_argument(value, "SelectCrew", "object"))
        .transpose()?
        .flatten();
    let select = value_to_bool(args.get(2).unwrap_or(&Value::Nil), "SelectCrew", "select")?;
    let no_cursor_adjust = value_to_bool(
        args.get(3).unwrap_or(&Value::Nil),
        "SelectCrew",
        "no cursor adjust",
    )?;
    Ok(Value::Bool(target.is_some_and(|target| {
        select_crew_host_impl(player_id, target, select, no_cursor_adjust)
    })))
}

/// FnSetCrewStatus (C4Script.cpp:2984-2993) delegates to
/// C4Player::SetObjectCrewStatus (C4Player.cpp:2107-2136). Crew membership
/// is an ordered per-player list independent of Owner; the return type is
/// C4ValueInt, so expose exact integer 0/1 rather than a script bool.
fn set_crew_status(args: &[Value]) -> Result<Value, RuntimeError> {
    let player_id = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "SetCrewStatus",
        "player",
    )?;
    let in_crew = value_to_bool(
        args.get(1).unwrap_or(&Value::Nil),
        "SetCrewStatus",
        "in crew",
    )?;
    let explicit = parse_object_reference_argument(
        args.get(2).unwrap_or(&Value::Nil),
        "SetCrewStatus",
        "object",
    )?;

    let target = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        borrow
            .as_ref()
            .and_then(|context| explicit.or(context.script_object_context))
    });
    let Some(target) = target else {
        return Ok(Value::Int(0));
    };

    if in_crew {
        let added = HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(context) = borrow.as_mut() else {
                return None;
            };
            let Some(player) = context.player_state(player_id) else {
                return None;
            };
            // SetObjectCrewStatus's idempotent fast path has no controller,
            // view-range or Recruitment side effects.
            if player.crew.contains(&target) {
                return Some(false);
            }
            if !context.ensure_object_scope(target)
                || !context.object_status_present(target)
                || !context
                    .object_effective_definition_id(target)
                    .and_then(|definition| context.definition_metadata(&definition))
                    .is_some_and(|metadata| metadata.crew_member)
            {
                return None;
            }
            if let Some(scope) = context.object_scope_mut(target) {
                scope.set_crew_status_member(true);
                // MakeCrewMember(pObj, false): Controller changes; Owner and
                // Info do not (C4Player.cpp:1167-1215).
                scope.set_controller(player_id);
                if scope.plr_view_range() == 0 {
                    scope.set_plr_view_range(500);
                }
            }
            if !context.insert_player_crew(player_id, target) {
                return None;
            }
            context.record_crew_rosters();
            Some(true)
        });
        let Some(added) = added else {
            return Ok(Value::Int(0));
        };

        if added {
            call_recruitment_callback(target, player_id);
            HOST_CONTEXT.with(|cell| {
                let mut borrow = cell.borrow_mut();
                if let Some(context) = borrow.as_mut() {
                    let still_member = context.object_in_any_crew(target);
                    if let Some(scope) = context.object_scope_mut(target) {
                        scope.set_crew_status_member(still_member);
                    }
                    context.record_crew_rosters();
                }
            });
        }
        return Ok(Value::Int(1));
    }

    let removal = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return None;
        };
        let player = context.player_state(player_id)?;
        if !player.crew.contains(&target) {
            // Already absent is a successful side-effect-free no-op.
            return Some((false, false));
        }
        if let Some(player) = context.player_state_mut(player_id) {
            player.crew.retain(|member| *member != target);
        }
        context.record_crew_rosters();
        Some((
            true,
            context
                .object_scope(target)
                .map(ObjectScopeContext::selected)
                .or_else(|| {
                    context
                        .get_world_object(target)
                        .map(|object| object.selected)
                })
                .unwrap_or(false),
        ))
    });
    let Some((was_present, selected)) = removal else {
        return Ok(Value::Int(0));
    };
    if !was_present {
        return Ok(Value::Int(1));
    }

    // Crew.Remove happens before UnSelect; Info remains attached while the
    // fail-safe CrewSelection(true,false) callback runs.
    if selected {
        unselect_host_object(target, false);
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        if !context.ensure_object_scope(target) {
            return;
        }
        // A live explicit None must NOT fall back to the immutable entry
        // snapshot: CrewSelection may have moved/cleared Info synchronously.
        let info_link = match context.object_scope(target) {
            Some(scope) => scope.info_link(),
            None => context.world.crew_info_link(target),
        };
        if info_link.is_some_and(|link| link.player_id == player_id) {
            let link = info_link.expect("checked above");
            if retire_host_crew_info(context, link) {
                if let Some(scope) = context.object_scope_mut(target) {
                    scope.set_info_rank(None);
                    scope.set_info_link(None);
                    scope.set_info_core(None);
                    scope.info_physical = None;
                    scope.record_physicals();
                }
                context.record_player_command(PlayerCommand::RetireCrewInfo {
                    object_id: target,
                    link,
                });
            }
        }
        let still_member = context.object_in_any_crew(target);
        if let Some(scope) = context.object_scope_mut(target) {
            scope.set_crew_status_member(still_member);
        }
        // A CrewSelection callback may have re-entered SetCrewStatus. The
        // outer removal preserves that final roster but still performs the
        // Info retirement above, matching C++ ordering.
        context.record_crew_rosters();
    });
    Ok(Value::Int(1))
}

fn unselect_crew_host(args: &[Value]) -> Result<Value, RuntimeError> {
    let player_id = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "UnselectCrew",
        "player",
    )?;
    let Some((crew, cursor)) = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let player = context.player_state(player_id)?;
        Some((player.crew.clone(), player.cursor))
    }) else {
        return Ok(Value::Bool(false));
    };
    for &id in &crew {
        let present = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .is_some_and(|context| context.object_status_present(id))
        });
        if present {
            unselect_host_object(id, false);
        }
    }
    if let Some(cursor) = cursor.filter(|cursor| !crew.contains(cursor)) {
        unselect_host_object(cursor, false);
    }
    Ok(Value::Bool(true))
}

/// FnSetCursor (C4Script.cpp:2951-2958): set the player cursor (and
/// crew selection unless fNoSelectCrew).
fn set_cursor_host(args: &[Value]) -> Result<Value, RuntimeError> {
    let player_id = value_to_i32(args.first().unwrap_or(&Value::Nil), "SetCursor", "player")?;
    let object = args
        .get(1)
        .map(|arg| parse_object_reference_argument(arg, "SetCursor", "obj"))
        .transpose()?
        .flatten();
    let no_select_mark = value_to_bool(
        args.get(2).unwrap_or(&Value::Nil),
        "SetCursor",
        "no select mark",
    )?;
    let no_select_arrow = value_to_bool(
        args.get(3).unwrap_or(&Value::Nil),
        "SetCursor",
        "no select arrow",
    )?;
    let no_select_crew = value_to_bool(
        args.get(4).unwrap_or(&Value::Nil),
        "SetCursor",
        "no select crew",
    )?;
    let Some((previous, disabled)) = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut()?;
        if context.world.player(player_id).is_none() {
            return None;
        }
        if object.is_some_and(|id| {
            !context.object_status_present(id)
        }) {
            return None;
        }
        let previous = context.player_state(player_id)?.cursor;
        let disabled = object.is_some_and(|id| context.object_crew_disabled(id).unwrap_or(false));
        if !disabled {
            context.player_state_mut(player_id)?.cursor = object;
        }
        Some((previous, disabled))
    }) else {
        return Ok(Value::Bool(false));
    };

    if !disabled {
        if previous != object {
            if let Some(previous) = previous {
                unselect_host_object(previous, true);
            }
        }
        // Like C++ SetCursor, read the live Cursor after the old callback.
        let current = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.player_state(player_id))
                .and_then(|player| player.cursor)
        });
        if let Some(current) = current {
            do_select_host_object(current, true);
        }
        HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(context) = borrow.as_mut() else {
                return;
            };
            if let Some(player) = context.player_state_mut(player_id) {
                if !no_select_arrow {
                    player.control.cursor_flash = 30;
                }
                if !no_select_mark {
                    player.control.select_flash = 30;
                }
            }
            record_cursor_state(context, player_id);
        });
    }

    if !no_select_crew {
        if let Some(object) = object {
            select_crew_host_impl(player_id, object, true, false);
        }
    }
    Ok(Value::Bool(true))
}

fn set_crew_enabled(args: &[Value]) -> Result<Value, RuntimeError> {
    let enabled = value_to_bool(
        args.first().unwrap_or(&Value::Nil),
        "SetCrewEnabled",
        "enabled",
    )?;
    let target = args
        .get(1)
        .map(|arg| parse_object_reference_argument(arg, "SetCrewEnabled", "obj"))
        .transpose()?
        .flatten();
    let active = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_context().map(|object| object.id()))
    });
    if let Some(target) = target {
        if Some(target) != active {
            return match call_world_object_function(
                target,
                "SetCrewEnabled",
                &[Value::Bool(enabled)],
            ) {
                Some(result) => result,
                None => Ok(Value::Bool(false)),
            };
        }
    }
    let adjust_owner = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return None;
        };
        let Some((id, owner)) = context.object_context_mut().map(|object| {
            object.pending_update.crew_disabled = Some(!enabled);
            if !enabled {
                // FnSetCrewEnabled clears Select silently; only a subsequent
                // cursor adjustment may emit cursor callbacks
                // (C4Script.cpp:4814-4836).
                object.set_selected(false);
            }
            (object.id(), object.owner())
        }) else {
            return None;
        };
        (!enabled
            && context
                .player_state(owner)
                .is_some_and(|player| player.cursor == Some(id)))
        .then_some(owner)
    });
    if let Some(owner) = adjust_owner {
        adjust_cursor_host(owner);
    }
    Ok(Value::Bool(adjust_owner.is_some() || active.is_some()))
}

/// FnFinishCommand (C4Script.cpp:947-957): mark the iCommandNum-th
/// command of the target finished (success) or bump its failures.
fn finish_command(args: &[Value]) -> Result<Value, RuntimeError> {
    let target = args
        .first()
        .map(|arg| parse_object_reference_argument(arg, "FinishCommand", "obj"))
        .transpose()?
        .flatten();
    let success = value_to_bool(
        args.get(1).unwrap_or(&Value::Nil),
        "FinishCommand",
        "success",
    )?;
    let index = parse_optional_i32(args.get(2), "FinishCommand", "command")?.unwrap_or(0);
    let active = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_context().map(|object| object.id()))
    });
    if let Some(target) = target {
        if Some(target) != active {
            return match call_world_object_function(
                target,
                "FinishCommand",
                &[Value::Int(0), Value::Bool(success), Value::Int(index)],
            ) {
                Some(result) => result,
                None => Ok(Value::Bool(false)),
            };
        }
    }
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let Some(object) = context.object_context_mut() else {
            return Ok(Value::Bool(false));
        };
        if !object.live_commands.finish_entry_public(index, success) {
            return Ok(Value::Bool(false));
        }
        object
            .command_operations
            .push(CommandOperation::Finish { index, success });
        Ok(Value::Bool(true))
    })
}

/// FnFling (C4Script.cpp:347-356) -> C4Object::Fling
/// (C4Object.cpp:1612-1624): optional half-speed add, then the Tumble
/// action if the ActMap has one, else the Jump action (after the
/// OnActionJump script hook), else raw velocity; the action-callback
/// bottom attach is cleared either way.
fn fling(args: &[Value]) -> Result<Value, RuntimeError> {
    let target = args
        .first()
        .map(|arg| parse_object_reference_argument(arg, "Fling", "obj"))
        .transpose()?
        .flatten();
    let xdir = parse_optional_i32(args.get(1), "Fling", "xdir")?.unwrap_or(0);
    let ydir = parse_optional_i32(args.get(2), "Fling", "ydir")?.unwrap_or(0);
    let prec = parse_optional_i32(args.get(3), "Fling", "precision")?
        .filter(|&prec| prec != 0)
        .unwrap_or(1);
    let add_speed = value_to_bool(
        args.get(4).unwrap_or(&Value::Nil),
        "Fling",
        "add speed",
    )?;
    // FnFling requires an explicit target — `if (!pObj) return false;`
    // (C4Script.cpp:347-349), NO caller fallback (unlike FnJump, :358).
    // The horse/wipf `Fling(GetRider(), ...)` with no rider is a no-op.
    let Some(target) = target else {
        return Ok(Value::Bool(false));
    };
    let caused_by = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_context())
            .map(ObjectScopeContext::controller)
            .unwrap_or(OWNER_NONE)
    });
    native_fling(
        target,
        FixedVec2::new(itofix_prec(xdir, prec), itofix_prec(ydir, prec)),
        add_speed,
        caused_by,
    )?;
    HOST_CONTEXT.with(|cell| {
        if let Some(object) = cell
            .borrow_mut()
            .as_mut()
            .and_then(|context| context.object_scope_mut(target))
        {
            // FnFling clears the WHOLE t_attach value after C4Object::Fling
            // (C4Script.cpp:353-355), unlike ShakeObjects' direct call.
            object.set_t_attach(0);
        }
    });
    Ok(Value::Bool(true))
}

/// The `SimFlightHitsLiquid` probe used by `ObjectComJump`
/// (C4Movement.cpp:657-670; C4ObjectCom.cpp:297-305).
fn script_jump_hits_liquid(
    context: &EffectHostContext,
    object: &ObjectScopeContext,
    launch: FixedVec2,
    gravity: C4Fixed,
) -> bool {
    // The scope carries the live C4Shape field, including a preceding
    // SetContactDensity in this same script call (C4Script.cpp:1286-1291).
    if object.contact_density() <= 25 {
        return false;
    }
    let mut position = object.fixed_position();
    if let Some(bottom) = object
        .vertices()
        .iter()
        .filter(|vertex| vertex.cnat & CNAT_BOTTOM != 0)
        .min_by_key(|vertex| vertex.y)
    {
        // C4Shape::GetBottomVertex (C4Shape.cpp:445-455).
        position.x += bottom.x;
        position.y += bottom.y;
    }
    let mut velocity = launch;
    let Some(landscape) = context.world.landscape_ref() else {
        return false;
    };
    let density_at = |x, y| context.world.movement_density_at(x, y).unwrap_or(0);
    let liquid = |density| (25..50).contains(&density);
    if liquid(density_at(fixtoi(position.x), fixtoi(position.y)))
        && !crate::direct_com::sim_flight_to_density(
            &mut position,
            &mut velocity,
            0,
            24,
            10,
            gravity,
            landscape.width() as i32,
            landscape.estimated_height(),
            &density_at,
        )
    {
        return false;
    }
    if !crate::direct_com::sim_flight_to_density(
        &mut position,
        &mut velocity,
        25,
        100,
        -1,
        gravity,
        landscape.width() as i32,
        landscape.estimated_height(),
        &density_at,
    ) {
        return false;
    }
    let x = fixtoi(position.x);
    let y = fixtoi(position.y);
    liquid(density_at(x, y)) && liquid(density_at(x, y + 9))
}

/// FnJump (C4Script.cpp:358-363): synchronous `ObjectComJump`.
fn jump(args: &[Value]) -> Result<Value, RuntimeError> {
    let target = args
        .first()
        .map(|arg| parse_object_reference_argument(arg, "Jump", "obj"))
        .transpose()?
        .flatten();
    let active = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_context().map(|object| object.id()))
    });
    if let Some(target) = target {
        if Some(target) != active {
            return match call_world_object_function(target, "Jump", &[]) {
                Some(result) => result,
                None => Ok(Value::Bool(false)),
            };
        }
    }
    // FnJump → ObjectComJump runs SYNCHRONOUSLY (C4Script.cpp:358-363,
    // C4ObjectCom.cpp:280-312): the snake's Activity jump takes effect
    // THIS frame, before its movement — a queued command would lag one
    // frame. Gates: only while the WALK procedure runs.
    let jump_target = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return None;
        };
        let object = context.object_context()?;
        let action_name = object.effective_action_name().to_string();
        if !matches!(
            object
                .action_library
                .procedure_for_entry(&action_name, object.effective_action_index()),
            crate::action::ActionProcedure::Walk
        ) {
            return None;
        }
        Some(object.id())
    });
    let Some(object_id) = jump_target else {
        return Ok(Value::Bool(false));
    };
    let Some(physical) = resolve_object_physical(object_id, false) else {
        return Ok(Value::Bool(false));
    };
    // SimFlightHitsLiquid reads the current global gravity after
    // GetPhysical; a fair-crew hook may have changed it synchronously.
    let gravity = PHYSICS_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .map(|context| fixed100(context.gravity()) / 5)
    });
    let launch = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let object = context.object_scope(object_id)?;
        let walk = physical.walk;
        let jump_physical = physical.jump;
        let con_scale = itofix_prec(object.construction(), crate::FULL_CON);
        let physical_walk = crate::math::val_by_physical(280, walk) * con_scale;
        let physical_jump = crate::math::val_by_physical(1000, jump_physical) * con_scale;
        let txdir = match object.command_direction() {
            CommandDirection::Left | CommandDirection::UpLeft => -physical_walk,
            CommandDirection::Right | CommandDirection::UpRight => physical_walk,
            _ => match object.direction() {
                Direction::Left => -physical_walk,
                Direction::Right => physical_walk,
                _ => C4Fixed::ZERO,
            },
        };
        let launch = FixedVec2::new(txdir, -physical_jump);
        let dive = gravity
            .is_some_and(|gravity| script_jump_hits_liquid(context, object, launch, gravity));
        Some((txdir, -physical_jump, dive))
    });
    let Some((txdir, tydir, dive)) = launch else {
        return Ok(Value::Bool(false));
    };
    if dive {
        let set = set_action(&[Value::String("Dive".into())])?;
        if matches!(set, Value::Bool(true)) {
            HOST_CONTEXT.with(|cell| {
                if let Some(object) = cell
                    .borrow_mut()
                    .as_mut()
                    .and_then(EffectHostContext::object_context_mut)
                {
                    object.set_fixed_velocity(FixedVec2::new(txdir, tydir));
                    object.set_mobile(true);
                    object.set_t_attach(object.t_attach() & !CNAT_BOTTOM);
                }
            });
            return Ok(Value::Bool(true));
        }
    }
    let jump_handled = match call_world_object_own_function(
        object_id,
        "OnActionJump",
        &[
            Value::Int(fixtoi_prec(txdir, 100)),
            Value::Int(fixtoi_prec(tydir, 100)),
            Value::Bool(true),
        ],
    ) {
        Some(Ok(value)) => value_raw_truthy(&value),
        Some(Err(error)) => {
            tracing::warn!(
                %error,
                "OnActionJump error; continuing like the C++ fail-safe exec"
            );
            false
        }
        None => false,
    };
    if jump_handled {
        return Ok(Value::Bool(true));
    }
    // ObjectActionJump (C4ObjectCom.cpp:48-61): SetActionByName("Jump")
    // with its Abort/Start calls, then the launch velocities. A failed
    // SetAction (no Jump in the ActMap) returns false without touching
    // the dirs.
    let set = set_action(&[Value::String("Jump".into())])?;
    if !matches!(set, Value::Bool(true)) {
        return Ok(Value::Bool(false));
    }
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(true));
        };
        if let Some(object) = context.object_context_mut() {
            object.set_fixed_velocity(FixedVec2::new(txdir, tydir));
            object.set_mobile(true);
            object.set_t_attach(object.t_attach() & !CNAT_BOTTOM);
        }
        Ok(Value::Bool(true))
    })
}

/// `CheckEnergyNeedChain` (C4Script.cpp:185-207): visit each object once,
/// test power consumers' `NeedEnergy`, then follow active PWRL objects in
/// master-list order from `Action.Target` to `Action.Target2`.
fn energy_chain_needs_power(
    context: &EffectHostContext,
    target: ObjectId,
    checked: &mut HashSet<ObjectId>,
) -> bool {
    if !checked.insert(target) {
        return false;
    }
    let world_object = context.get_world_object(target);
    let scope = context.object_scope(target);
    let definition = scope
        .and_then(|scope| scope.definition_id.as_deref())
        .map(ToOwned::to_owned)
        .or_else(|| {
            world_object
                .as_ref()
                .map(|object| object.definition_id().to_string())
        });
    let need_energy = scope
        .map(ObjectScopeContext::need_energy)
        .or_else(|| world_object.as_ref().map(|object| object.need_energy));
    let (Some(definition), Some(need_energy)) = (definition, need_energy) else {
        return false;
    };
    let is_consumer = context
        .definition_metadata(&definition)
        .is_some_and(|metadata| metadata.line_connect & crate::LINE_CONNECT_POWER_CONSUMER != 0);
    if is_consumer && need_energy {
        return true;
    }
    context.world_object_ids().into_iter().any(|line_id| {
        let Some(line) = context.get_world_object(line_id) else {
            return false;
        };
        line.status().is_active()
            && line.definition_id() == "PWRL"
            && line.action_target(0) == Some(target)
            && line
                .action_target(1)
                .is_some_and(|next| energy_chain_needs_power(context, next, checked))
    })
}

/// FnCheckEnergyNeedChain (C4Script.cpp:1832-1837): nil/default target means
/// the calling object; no object context returns nil.
fn check_energy_need_chain(args: &[Value]) -> Result<Value, RuntimeError> {
    let target = args
        .first()
        .map(|arg| match arg {
            // CheckConvertFunctionParameters Set0s every falsy parameter
            // before converting to C4Object* (C4AulExec.cpp:1370-1396).
            Value::Bool(false) => Ok(None),
            _ => parse_object_reference_argument(arg, "CheckEnergyNeedChain", "object"),
        })
        .transpose()?
        .flatten();
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let target = target.or_else(|| context.object_context().map(ObjectScopeContext::id));
        let Some(target) = target else {
            return Ok(Value::Nil);
        };
        Ok(Value::Bool(energy_chain_needs_power(
            context,
            target,
            &mut HashSet::new(),
        )))
    })
}

/// FnEnergyCheck (C4Script.cpp:1839-1849): true when the
/// StructuresNeedEnergy rule is off, the object has enough energy, or
/// the def is not a power consumer; update `NeedEnergy` on every branch.
fn energy_check(args: &[Value]) -> Result<Value, RuntimeError> {
    let energy = value_to_i32(args.first().unwrap_or(&Value::Nil), "EnergyCheck", "energy")?;
    let target = args
        .get(1)
        .map(|arg| match arg {
            Value::Bool(false) => Ok(None),
            _ => parse_object_reference_argument(arg, "EnergyCheck", "obj"),
        })
        .transpose()?
        .flatten();
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Nil);
        };
        let target = target.or_else(|| context.object_context().map(|object| object.id()));
        let Some(target) = target else {
            return Ok(Value::Nil);
        };
        let scope_values = context.object_scope(target).map(|scope| {
            (
                scope.energy(),
                scope.definition_id.as_deref().map(ToOwned::to_owned),
            )
        });
        let world_object = context.get_world_object(target);
        let current_energy = scope_values
            .as_ref()
            .map(|(energy, _)| *energy)
            .or_else(|| world_object.as_ref().map(HostWorldObject::energy));
        let definition = scope_values
            .and_then(|(_, definition)| definition)
            .or_else(|| {
                world_object
                    .as_ref()
                    .map(|object| object.definition_id().to_string())
            });
        let (Some(current_energy), Some(definition)) = (current_energy, definition) else {
            return Ok(Value::Nil);
        };
        let is_consumer = context
            .world
            .definition_metadata(&definition)
            .map(|metadata| metadata.line_connect & crate::LINE_CONNECT_POWER_CONSUMER != 0)
            .unwrap_or(false);
        let need_energy =
            context.world.structures_need_energy() && current_energy < energy && is_consumer;
        if context.object_scope(target).is_none() && !context.ensure_object_scope(target) {
            return Ok(Value::Nil);
        }
        if let Some(object) = context.object_scope_mut(target) {
            object.set_need_energy(need_energy);
        }
        Ok(Value::Bool(!need_energy))
    })
}

/// FnStuck (C4Script.cpp:1858-1862): Shape.CheckContact(x, y) — is any
/// shape vertex inside solid at the current position (C4Shape.cpp
/// CheckContact probes GBackSolid per vertex).
fn stuck(args: &[Value]) -> Result<Value, RuntimeError> {
    let target_id = args
        .first()
        .map(|arg| parse_object_reference_argument(arg, "Stuck", "obj"))
        .transpose()?
        .flatten();
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let Some((position, vertices)) = resolve_vertices(context, target_id) else {
            return Ok(Value::Nil);
        };
        if context.landscape_ref().is_none() {
            return Ok(Value::Bool(false));
        }
        let resolved_target =
            target_id.or_else(|| context.object_context().map(|object| object.id()));
        let contact_density = resolved_target
            .and_then(|target| {
                context
                    .object_scope(target)
                    .map(ObjectScopeContext::contact_density)
                    .or_else(|| {
                        context
                            .get_world_object(target)
                            .map(|object| object.contact_density())
                    })
            })
            .unwrap_or(crate::CONTACT_DENSITY_SOLID);
        let pending_masks = context.pending_solid_masks();
        let stuck = vertices.iter().any(|vertex| {
            if vertex.cnat & CNAT_NO_COLLISION != 0 {
                return false;
            }
            context
                .movement_density_at(&pending_masks, position.x + vertex.x, position.y + vertex.y)
                .is_some_and(|density| density >= contact_density)
        });
        Ok(Value::Bool(stuck))
    })
}

fn get_vertex_contact(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.is_empty() {
        return Err(RuntimeError::new(
            "GetVertexContact: requires a vertex index argument",
        ));
    }

    let vertex_index = value_to_i32(&args[0], "GetVertexContact", "index")?;
    let mut arg_index = 1;
    let mut mask: u32 = 0;

    if let Some(arg) = args.get(arg_index) {
        match arg {
            Value::Int(value) => {
                if *value > 0 {
                    mask = *value as u32;
                }
                arg_index += 1;
            }
            Value::Nil => {
                arg_index += 1;
            }
            _ => {}
        }
    }

    let mut target_id: Option<ObjectId> = None;
    if let Some(arg) = args.get(arg_index) {
        target_id = parse_object_reference_argument(arg, "GetVertexContact", "object")?;
        arg_index += 1;
    }

    if arg_index < args.len() {
        return Err(RuntimeError::new(
            "GetVertexContact: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        let (position, vertices) = match resolve_vertices(context, target_id) {
            Some(value) => value,
            None => return Ok(Value::Nil),
        };

        if vertex_index < 0 || (vertex_index as usize) >= vertices.len() {
            return Ok(Value::Nil);
        }

        let contact_density = resolve_contact_density(context, target_id);
        let pending_masks = context.pending_solid_masks();
        let contact = compute_vertex_contact(
            position,
            &vertices[vertex_index as usize],
            mask,
            contact_density,
            |x, y| context.movement_density_at(&pending_masks, x, y),
        );
        Ok(Value::Int(contact as i32))
    })
}

fn get_contact(args: &[Value]) -> Result<Value, RuntimeError> {
    // FnGetContact(pObj, iVertex, dwCheck) — C4Script.cpp:5611-5626:
    // the OBJECT comes first; iVertex -1 ORs all vertex contacts. A
    // non-object in the pObj slot coerces to nil (self) like C4Value.
    let target_id = match args.first() {
        Some(value @ (Value::Object(_) | Value::Proplist(_))) => {
            parse_object_reference_argument(value, "GetContact", "obj")?
        }
        _ => None,
    };
    let vertex_index = match args.get(1) {
        None | Some(Value::Nil) => 0,
        Some(value) => value_to_i32(value, "GetContact", "vertex")?,
    };
    let mask = match args.get(2) {
        None | Some(Value::Nil) => 0u32,
        Some(value) => {
            let raw = value_to_i32(value, "GetContact", "mask")?;
            if raw > 0 { raw as u32 } else { 0 }
        }
    };

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        let (position, vertices) = match resolve_vertices(context, target_id) {
            Some(value) => value,
            None => return Ok(Value::Nil),
        };

        let contact_density = resolve_contact_density(context, target_id);
        let pending_masks = context.pending_solid_masks();

        if vertex_index == -1 {
            if vertices.is_empty() {
                return Ok(Value::Int(0));
            }
            let mut result = 0u32;
            for vertex in &vertices {
                result |= compute_vertex_contact(
                    position,
                    vertex,
                    mask,
                    contact_density,
                    |x, y| context.movement_density_at(&pending_masks, x, y),
                );
            }
            return Ok(Value::Int(result as i32));
        }

        if vertex_index < 0 || (vertex_index as usize) >= vertices.len() {
            return Ok(Value::Nil);
        }

        let contact = compute_vertex_contact(
            position,
            &vertices[vertex_index as usize],
            mask,
            contact_density,
            |x, y| context.movement_density_at(&pending_masks, x, y),
        );
        Ok(Value::Int(contact as i32))
    })
}

fn path_free(args: &[Value]) -> Result<Value, RuntimeError> {
    let x1 = value_to_i32(args.first().unwrap_or(&Value::Nil), "PathFree", "x1")?;
    let y1 = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "PathFree", "y1")?;
    let x2 = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "PathFree", "x2")?;
    let y2 = value_to_i32(args.get(3).unwrap_or(&Value::Nil), "PathFree", "y2")?;

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Bool(true)),
        };

        let Some(landscape) = context.landscape_ref() else {
            return Ok(Value::Bool(true));
        };

        // FnPathFree → ::PathFree = the ForLine per-pixel Bresenham with
        // GBackSolid blocking (C4Landscape.cpp:1683-1738, 2052-2055) —
        // its exact stepping decides script branches (the Bison's
        // EnemyNearby flee gate). GBackSolid sees C4SolidMask's baked
        // MCVehic pixels — the plane carries them (put_solid_mask).
        let clear = match context.world.materials() {
            Some(materials) => crate::path_free_exact(landscape, materials, &[], x1, y1, x2, y2),
            None => landscape.path_is_clear(Vector2::new(x1, y1), Vector2::new(x2, y2)),
        };
        Ok(Value::Bool(clear))
    })
}

fn path_free2_native_int(value: &Value, parameter: &str) -> Result<i32, RuntimeError> {
    // Native dispatch eagerly resets falsy typed arguments to nil for callers
    // below #strict 3 before converting the C4ValueInt slots.
    let eager_falsy_conversion = match clonk_script::caller_origin_strictness() {
        clonk_script::HostCallerStrictness::NoCaller => false,
        clonk_script::HostCallerStrictness::NonStrict => true,
        clonk_script::HostCallerStrictness::Strict(level) => level < 3,
    };
    if eager_falsy_conversion && !value.as_bool() {
        return Ok(0);
    }
    value_to_i32(value, "PathFree2", parameter)
}

/// FnPathFree2 (C4Script.cpp:3132-3146): PathFree with native reference
/// parameters for the start point and blocked-pixel writeback.
fn path_free2(args: &[HostCallArg]) -> Result<Value, RuntimeError> {
    let x_arg = args.first().ok_or_else(|| {
        RuntimeError::new(
            "call to \"PathFree2\" parameter 1: got \"nil\", but expected \"&\"!",
        )
    })?;
    if !x_arg.is_reference() {
        return Err(RuntimeError::new(format!(
            "call to \"PathFree2\" parameter 1: got \"{}\", but expected \"&\"!",
            x_arg.read()?.type_name()
        )));
    }
    let y_arg = args.get(1).ok_or_else(|| {
        RuntimeError::new(
            "call to \"PathFree2\" parameter 2: got \"nil\", but expected \"&\"!",
        )
    })?;
    if !y_arg.is_reference() {
        return Err(RuntimeError::new(format!(
            "call to \"PathFree2\" parameter 2: got \"{}\", but expected \"&\"!",
            y_arg.read()?.type_name()
        )));
    }

    let x2_value = args
        .get(2)
        .map(HostCallArg::read)
        .transpose()?
        .unwrap_or(Value::Nil);
    let y2_value = args
        .get(3)
        .map(HostCallArg::read)
        .transpose()?
        .unwrap_or(Value::Nil);
    let x2 = path_free2_native_int(&x2_value, "x2")?;
    let y2 = path_free2_native_int(&y2_value, "y2")?;

    // Native dispatch converts x2/y2 before FnPathFree2 runs. The body then
    // uses GetRefVal().getInt(), preserving each reference while an
    // unconvertible referent contributes zero.
    let x1 = x_arg.read()?.as_c4_int().unwrap_or(0);
    let y1 = y_arg.read()?.as_c4_int().unwrap_or(0);

    let hit = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let landscape = context.landscape_ref()?;
        Some(match context.world.materials() {
            Some(materials) => {
                crate::path_free_exact_hit(landscape, materials, &[], x1, y1, x2, y2)
            }
            None => crate::for_line_first_blocker(x1, y1, x2, y2, |x, y| {
                landscape.is_solid_at(x, y)
            }),
        })
    });
    let hit = hit.flatten();

    if let Some(hit) = hit {
        let wrote_x = x_arg.write(Value::Int(hit.x))?;
        let wrote_y = y_arg.write(Value::Int(hit.y))?;
        debug_assert!(wrote_x && wrote_y, "validated PathFree2 reference disappeared");
        Ok(Value::Bool(false))
    } else {
        Ok(Value::Bool(true))
    }
}

fn get_path(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() != 4 {
        return Err(RuntimeError::new(
            "GetPath expects 4 arguments: from_x, from_y, to_x, to_y",
        ));
    }

    let from_x = value_to_i32(&args[0], "GetPath", "from_x")?;
    let from_y = value_to_i32(&args[1], "GetPath", "from_y")?;
    let to_x = value_to_i32(&args[2], "GetPath", "to_x")?;
    let to_y = value_to_i32(&args[3], "GetPath", "to_y")?;

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };
        let landscape = match context.landscape_ref() {
            Some(landscape) => landscape,
            None => return Ok(Value::Nil),
        };
        let mut finder = PathFinder::new(landscape, context.world.transfer_zones());
        let (level, transfer_zones_enabled) = context.world.pathfinder_settings();
        finder.set_level(level);
        finder.enable_transfer_zones(transfer_zones_enabled);
        let path = finder.find(Vector2::new(from_x, from_y), Vector2::new(to_x, to_y));
        *context.world.pathfinder_debug.borrow_mut() = finder.debug_snapshot().clone();
        let path = match path {
            Some(path) => path,
            None => return Ok(Value::Nil),
        };
        let mut result = ValueMap::new();
        result.insert("Length".into(), Value::Int(path.length));
        let mut waypoints = Vec::with_capacity(path.waypoints.len());
        for waypoint in path.waypoints {
            let mut map = ValueMap::new();
            map.insert("X".into(), Value::Int(waypoint.x));
            map.insert("Y".into(), Value::Int(waypoint.y));
            if let Some(target) = waypoint.transfer_target {
                map.insert("TransferTarget".into(), object_reference_value(target));
            }
            waypoints.push(Value::Proplist(map));
        }
        result.insert("Waypoints".into(), Value::Array(waypoints));
        Ok(Value::Proplist(result))
    })
}

fn set_transfer_zone(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 5 {
        return Err(RuntimeError::new(
            "SetTransferZone expects at most 5 arguments: x, y, width, height, [object]",
        ));
    }

    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "SetTransferZone", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "SetTransferZone", "y")?;
    let width = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "SetTransferZone",
        "width",
    )?;
    let height = value_to_i32(
        args.get(3).unwrap_or(&Value::Nil),
        "SetTransferZone",
        "height",
    )?;
    let explicit_object = args
        .get(4)
        .map(|value| parse_object_reference_argument(value, "SetTransferZone", "object"))
        .transpose()?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut().ok_or_else(|| {
            RuntimeError::new("SetTransferZone requires an active engine context")
        })?;

        let owner = match explicit_object.flatten() {
            Some(id) => id,
            None => context
                .object_context()
                .map(|ctx| ctx.id())
                .ok_or_else(|| {
                    RuntimeError::new(
                        "SetTransferZone requires an object argument or active object context",
                    )
                })?,
        };

        // pObj->x/y off the LIVE object (C4Script.cpp:3154): the executing
        // scope resolves the object even while its own Initialize runs
        // before the world snapshot knows it (C4Object::Init fires the
        // callbacks on the constructed object, C4Object.cpp:215+ — the
        // WZKP homebase placed at player join).
        let position = context
            .object_context()
            .filter(|object| object.id() == owner)
            .map(|object| object.effective_position())
            .or_else(|| {
                context
                    .get_world_object(owner)
                    .map(|object| object.position())
            })
            .ok_or_else(|| {
                RuntimeError::new(format!(
                    "SetTransferZone: object {} not found in current engine context",
                    owner
                ))
            })?;

        if width == 0 || height == 0 {
            context.register_transfer_zone_command(TransferZoneCommand::clear(owner));
            return Ok(Value::Bool(true));
        }

        let abs_x = position.x.saturating_add(x);
        let abs_y = position.y.saturating_add(y);
        let rect = TransferZoneRect {
            x: abs_x,
            y: abs_y,
            width,
            height,
        };
        context.register_transfer_zone_command(TransferZoneCommand::set(owner, rect));
        Ok(Value::Bool(true))
    })
}

#[derive(Clone, Copy)]
enum LandscapeQuery {
    Solid,
    SemiSolid,
    Liquid,
    Sky,
}

fn g_back_solid(args: &[Value]) -> Result<Value, RuntimeError> {
    g_back_common(args, "GBackSolid", LandscapeQuery::Solid)
}

fn g_back_semi_solid(args: &[Value]) -> Result<Value, RuntimeError> {
    g_back_common(args, "GBackSemiSolid", LandscapeQuery::SemiSolid)
}

fn g_back_liquid(args: &[Value]) -> Result<Value, RuntimeError> {
    g_back_common(args, "GBackLiquid", LandscapeQuery::Liquid)
}

fn g_back_sky(args: &[Value]) -> Result<Value, RuntimeError> {
    g_back_common(args, "GBackSky", LandscapeQuery::Sky)
}

fn g_back_common(
    args: &[Value],
    function: &str,
    query: LandscapeQuery,
) -> Result<Value, RuntimeError> {
    // Unfilled parameter slots are nil -> 0 (C4Aul.h:104-121,
    // C4AulExec.cpp:1364-1396): GBackSolid() queries the object's position.
    let local_x = value_to_i32(args.first().unwrap_or(&Value::Nil), function, "x")?;
    let local_y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), function, "y")?;

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Bool(fallback_without_context(query))),
        };

        let mut global_x = local_x;
        let mut global_y = local_y;
        if let Some(object) = context.object_context() {
            let position = object.effective_position();
            global_x = global_x.saturating_add(position.x);
            global_y = global_y.saturating_add(position.y);
        }

        let landscape = context.landscape_ref();
        let result = evaluate_landscape_query(landscape, query, global_x, global_y);
        Ok(Value::Bool(result))
    })
}

fn evaluate_landscape_query(
    landscape: Option<&Landscape>,
    query: LandscapeQuery,
    x: i32,
    y: i32,
) -> bool {
    match landscape {
        Some(landscape) => match query {
            LandscapeQuery::Solid => landscape.is_solid_at(x, y),
            // GBackSemiSolid = density >= C4M_SemiSolid(25), which liquids
            // satisfy (C4Wrappers.h:73-76, C4Material.h:202).
            LandscapeQuery::SemiSolid => landscape.is_semi_solid_at(x, y),
            LandscapeQuery::Liquid => landscape.is_liquid_at(x, y),
            // FnGBackSky is the historical background query: sky means the
            // pixel is not marked IFT, independent of material density
            // (C4Script.cpp:2252-2256).
            LandscapeQuery::Sky => !landscape.is_ift_at(x, y),
        },
        None => fallback_without_context(query),
    }
}

fn fallback_without_context(query: LandscapeQuery) -> bool {
    match query {
        LandscapeQuery::Sky => true,
        LandscapeQuery::Solid | LandscapeQuery::SemiSolid | LandscapeQuery::Liquid => false,
    }
}

fn get_material(args: &[Value]) -> Result<Value, RuntimeError> {
    // C++ pads missing script args with zero (FnGetMaterial(x, y),
    // C4Script.cpp:2216-2220): GetMaterial() probes the object center.
    let local_x = match args.first() {
        None | Some(Value::Nil) => 0,
        Some(value) => value_to_i32(value, "GetMaterial", "x")?,
    };
    let local_y = match args.get(1) {
        None | Some(Value::Nil) => 0,
        Some(value) => value_to_i32(value, "GetMaterial", "y")?,
    };

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Int(MATERIAL_NONE)),
        };

        let mut global_x = local_x;
        let mut global_y = local_y;
        if let Some(object) = context.object_context() {
            let position = object.effective_position();
            global_x = global_x.saturating_add(position.x);
            global_y = global_y.saturating_add(position.y);
        }

        let material = context
            .landscape_ref()
            // FnGetMaterial -> GBackMat -> Landscape.GetMat includes the
            // GetPix sky/MCVehic border mapping (C4Script.cpp:2216-2220;
            // C4Wrappers.h:164-167; C4Landscape.h:144-175).
            .and_then(|landscape| landscape.border_material_at(global_x, global_y));
        let result = material
            .map(|material_id| material_id.index() as i32)
            .unwrap_or(MATERIAL_NONE);
        Ok(Value::Int(result))
    })
}

/// FnGetTexture (C4Script.cpp:2222-2232): unlike GetMaterial/GBack*, x/y
/// are GLOBAL even with an object context. PixCol2Tex strips IFT, then the
/// live callback TextureMap supplies the raw entry texture name (presentation
/// may resolve liquid Smooth through the Liquid image). Parser-time allocations
/// and callback-COW terrain writes are both immediately visible.
fn get_texture(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "GetTexture", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "GetTexture", "y")?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let texture_index = context
            .landscape_ref()
            .and_then(|landscape| landscape.grid_byte_at(x, y))
            .map(|pixel| usize::from(pixel & 0x7f))
            .unwrap_or(0);
        if texture_index == 0 {
            return Ok(Value::Nil);
        }
        let Some(texmap) = context.runtime_texmap() else {
            return Ok(Value::Nil);
        };
        if texmap
            .material_names
            .get(texture_index)
            .and_then(Option::as_ref)
            .is_none()
        {
            return Ok(Value::Nil);
        }
        let texture = texmap
            .match_texture_names
            .get(texture_index)
            .and_then(Option::as_deref)
            .unwrap_or_default();
        Ok(Value::String(texture.to_string().into()))
    })
}

/// FnSetTextureIndex/C4Landscape::SetTextureIndex (C4Script.cpp:5071-5075;
/// C4Landscape.cpp:2733-2808). The wrapper admits 0..=255, then the landscape
/// applies its narrower texture-slot rules. MoveIndex is synchronously visible
/// through the live TextureMap even though Surface8 and Pix2* caches stay put.
fn set_texture_index(args: &[Value]) -> Result<Value, RuntimeError> {
    let material_texture =
        parse_optional_string(args.first(), "SetTextureIndex", "material-texture")?
            .unwrap_or_default();
    let new_index = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "SetTextureIndex",
        "new-index",
    )?;
    let insert = value_to_bool(
        args.get(2).unwrap_or(&Value::Nil),
        "SetTextureIndex",
        "insert",
    )?;
    if !(0..=255).contains(&new_index) {
        return Ok(Value::Int(0));
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Int(0));
        };
        let Some(texmap) = context.runtime_texmap_mut() else {
            return Ok(Value::Int(0));
        };
        let (succeeded, moved_indices) = texmap.set_texture_index(
            &material_texture,
            new_index as u8,
            insert,
        );
        let texmap = texmap.clone();

        if let Some((old_index, new_index)) = moved_indices {
            let operation = LandscapeOperation::SetTextureIndex {
                texmap,
                old_index,
                new_index,
            };
            // C++ changes the live TextureMap before returning. Keep this
            // callback's COW world coherent and carry the captured state to
            // later effect callbacks and the authoritative fold.
            context.world.preview_runtime_landscape_operation(&operation);
            context.register_landscape_operation(operation);
        }
        Ok(Value::Int(i32::from(succeeded)))
    })
}

/// FnRemoveUnusedTexMapEntries/C4Landscape::RemoveUnusedTexMapEntries
/// (C4Script.cpp:5077-5080; C4Landscape.cpp:2983-3007). Usage comes from the
/// full-resolution Surface8 plane plus CrossMapMaterials' retained numeric
/// references. Entry removal is live, but the native deliberately leaves the
/// byte plane and its Pix2* lookup caches untouched.
fn remove_unused_texmap_entries(_args: &[Value]) -> Result<Value, RuntimeError> {
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Nil);
        };
        let Some(texture_usage) = context
            .world
            .landscape_ref()
            .and_then(Landscape::texture_index_usage)
        else {
            return Ok(Value::Nil);
        };
        let Some(texmap) = context.runtime_texmap_mut() else {
            return Ok(Value::Nil);
        };
        let cleared_slots = texmap.remove_unused_entries(texture_usage);
        let operation = LandscapeOperation::RemoveUnusedTexMapEntries { cleared_slots };
        // Queue even an empty preview. Earlier deferred terrain operations
        // can make entries newly used or unused before the authoritative
        // fold reaches this point.
        context.world.preview_runtime_landscape_operation(&operation);
        context.register_landscape_operation(operation);
        Ok(Value::Nil)
    })
}

fn blast_free(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut x = value_to_i32(args.first().unwrap_or(&Value::Nil), "BlastFree", "x")?;
    let mut y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "BlastFree", "y")?;
    let level = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "BlastFree", "level")?;
    let caused_by_plus_one =
        value_to_i32(args.get(3).unwrap_or(&Value::Nil), "BlastFree", "caused by")?;

    let (center, controller) = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow
            .as_ref()
            .ok_or_else(|| RuntimeError::new("BlastFree requires an active engine context"))?;

        let mut controller = if caused_by_plus_one != 0 {
            Some(caused_by_plus_one.wrapping_sub(1))
        } else {
            None
        };

        if caused_by_plus_one == 0 {
            if let Some(object) = context.object_context() {
                let position = object.effective_position();
                x = x.saturating_add(position.x);
                y = y.saturating_add(position.y);
                controller = Some(object.controller());
            }
        }

        Ok((Vector2::new(x, y), controller))
    })?;
    native_blast_free_absolute(center, level, controller)?;
    // FnBlastFree is a void engine function; C4AulEngineFunc maps void to
    // C4VNull after performing the landscape side effect.
    Ok(Value::Nil)
}

/// Absolute C4Landscape::BlastFree entry for native engine operations.
/// Unlike the public wrapper, `OWNER_NONE` is already decoded and the point
/// must never be offset through the active script object.
fn native_blast_free_absolute(
    center: Vector2,
    level: i32,
    controller: Option<i32>,
) -> Result<(), RuntimeError> {
    let counts = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("BlastFree requires an active engine context"))?;
        let preview = context.preview_blast_circle(center, level);
        let counts = preview
            .as_ref()
            .map(|(_, counts)| counts.clone())
            .unwrap_or_default();
        let replay = preview.map(|(replay, _)| replay);
        let operation = match replay {
            Some(replay) => LandscapeOperation::BlastCirclePreviewed {
                center,
                radius: level,
                replay,
            },
            None => LandscapeOperation::BlastCircle {
                center,
                radius: level,
                controller,
            },
        };
        context.register_landscape_operation(operation);
        Ok(counts)
    })?;
    process_preview_blast_reactions(center, controller, &counts)?;
    Ok(())
}

/// The post-pixel evaluate loop of C4Landscape::BlastFree. Object creation
/// and its lifecycle callbacks happen between consecutive groups of four
/// random draws; PXS draws follow that material's objects before the next
/// material. Keeping this in the live host context makes callbacks and the
/// outer script observe the same order as C++ while the queued operations
/// only commit already-previewed terrain/PXS storage.
fn process_preview_blast_reactions(
    center: Vector2,
    controller: Option<i32>,
    counts: &HashMap<crate::MaterialId, i32>,
) -> Result<(), RuntimeError> {
    let materials = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref().ok_or_else(|| {
            RuntimeError::new("BlastFree requires an active engine context")
        })?;
        Ok::<_, RuntimeError>(
            context
                .world
                .materials()
                .map(|materials| {
                    materials
                        .iter()
                        .map(|material| {
                            (
                                material.id(),
                                material.blast_to_object_name().map(str::to_string),
                                material.blast_to_object_ratio(),
                                material.blast_to_pxs_ratio(),
                            )
                        })
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default(),
        )
    })?;

    for (material, definition, object_ratio, pxs_ratio) in materials {
        let count = counts.get(&material).copied().unwrap_or(0);
        if count == 0 {
            continue;
        }
        if let (Some(definition), Some(ratio)) = (definition, object_ratio) {
            if ratio != 0 {
                for _ in 0..count / ratio {
                    let rotation_velocity = itofix(draw_context_random(3)? + 1);
                    let ydir = fixed10(draw_context_random(61)? - 40);
                    let xdir = fixed10(draw_context_random(61)? - 30);
                    let rotation = draw_context_random(360)?;
                    let _ = create_native_object(NativeObjectCreation {
                        definition: definition.clone(),
                        creator: None,
                        owner: OWNER_NONE,
                        controller: controller.unwrap_or(OWNER_NONE),
                        construction: FULL_CON,
                        position: center,
                        rotation,
                        velocity: FixedVec2::new(xdir, ydir),
                        rotation_velocity,
                    })?;
                }
            }
        }
        if let Some(ratio) = pxs_ratio {
            if ratio != 0 {
                let velocities = RANDOM_CONTEXT.with(|cell| {
                    let random = cell
                        .borrow()
                        .as_ref()
                        .ok_or_else(|| RuntimeError::new("random context unavailable"))?
                        .clone();
                    let mut rng = random.rng.borrow_mut();
                    Ok::<_, RuntimeError>(
                        (0..count / ratio)
                            .map(|_| crate::pxs::PxsSystem::sample_cast_velocity(&mut rng, 60))
                            .collect::<Vec<_>>(),
                    )
                })?;
                HOST_CONTEXT.with(|cell| {
                    let mut borrow = cell.borrow_mut();
                    let context = borrow.as_mut().ok_or_else(|| {
                        RuntimeError::new("BlastFree requires an active engine context")
                    })?;
                    context.register_landscape_operation(LandscapeOperation::CastPxs {
                        material,
                        position: center,
                        velocities,
                    });
                    Ok::<_, RuntimeError>(())
                })?;
            }
        }
    }
    Ok(())
}

/// C4Object::DigOutMaterialCast at the end of DigFree/DigFreeRect. The
/// creator's MaterialContents stay live through each spawned object's
/// lifecycle callbacks and reset only after CreateObject returns.
fn process_preview_dig_reactions(
    by_object: Option<ObjectId>,
    counts: &HashMap<crate::MaterialId, i32>,
    requested: bool,
) -> Result<(), RuntimeError> {
    let Some(target) = by_object else {
        return Ok(());
    };
    let (frame, materials) = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut().ok_or_else(|| {
            RuntimeError::new("DigFree requires an active engine context")
        })?;
        if !context.add_dig_material_counts(target, counts) {
            return Ok((context.world.frame, Vec::new()));
        }
        let materials = context
            .world
            .materials()
            .map(|materials| {
                materials
                    .iter()
                    .map(|material| {
                        (
                            material.id(),
                            material.dig_to_object_name().map(str::to_string),
                            material.dig_to_object_ratio(),
                            material.dig_to_object_on_request_only(),
                        )
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        Ok::<_, RuntimeError>((context.world.frame, materials))
    })?;
    if frame % 5 != 0 {
        return Ok(());
    }

    for (material, definition, ratio, on_request_only) in materials {
        let (Some(definition), Some(ratio)) = (definition, ratio) else {
            continue;
        };
        if ratio == 0 || (on_request_only && !requested) {
            continue;
        }
        let position = HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let context = borrow.as_mut()?;
            let content = context.dig_material_content(target, material);
            if content == 0 || content < ratio {
                return None;
            }
            let object = context.get_world_object(target)?;
            let position = context
                .object_scope(target)
                .map(ObjectScopeContext::effective_position)
                .unwrap_or(object.position);
            let bottom = live_object_shape(context, target).map_or(position.y, |shape| {
                position
                    .y
                    .saturating_add(shape.y)
                    .saturating_add(shape.height)
            });
            Some(Vector2::new(position.x, bottom))
        });
        let Some(position) = position else {
            continue;
        };
        let rotation = draw_context_random(360)?;
        let _ = create_native_object(NativeObjectCreation {
            definition,
            creator: Some(target),
            owner: OWNER_NONE,
            controller: OWNER_NONE,
            construction: FULL_CON,
            position,
            rotation,
            velocity: FixedVec2::ZERO,
            rotation_velocity: C4Fixed::ZERO,
        })?;
        HOST_CONTEXT.with(|cell| {
            if let Some(context) = cell.borrow_mut().as_mut() {
                context.reset_dig_material_content(target, material);
            }
        });
    }
    Ok(())
}

fn shake_free(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 3 {
        return Err(RuntimeError::new(
            "ShakeFree expects exactly 3 arguments: x, y, radius",
        ));
    }

    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "ShakeFree", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "ShakeFree", "y")?;
    let radius = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "ShakeFree", "radius")?;
    if radius <= 0 {
        return Ok(Value::Nil);
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("ShakeFree requires an active engine context"))?;
        let operation = LandscapeOperation::ShakeCircle {
            center: Vector2::new(x, y),
            radius,
        };
        context.world.preview_runtime_landscape_operation(&operation);
        context.register_landscape_operation(operation);
        Ok(Value::Nil)
    })
}

/// FnFightWith (C4Script.cpp:5117-5132): require both cached
/// OCF_FightReady flags, run target/clonk RejectFight in that order, then
/// start the native Fight action on both objects with mutual targets.
fn fight_with(args: &[Value]) -> Result<Value, RuntimeError> {
    let target = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "FightWith",
        "target",
    )?;
    let clonk =
        parse_object_reference_argument(args.get(1).unwrap_or(&Value::Nil), "FightWith", "clonk")?;
    let Some(target) = target else {
        return Ok(Value::Bool(false));
    };
    let clonk = clonk.or_else(|| {
        HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.script_object_context)
        })
    });
    let Some(clonk) = clonk else {
        return Ok(Value::Bool(false));
    };

    let both_ready = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        [target, clonk].into_iter().all(|object| {
            context
                .get_world_object(object)
                .is_some_and(|object| object.ocf() & ocf::FIGHT_READY != 0)
        })
    });
    if !both_ready {
        return Ok(Value::Bool(false));
    }

    // C4Object::Call silently skips an object that was deleted by the
    // preceding callback, but fPassErrors=true propagates callback errors.
    for object in [target, clonk] {
        let present = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .is_some_and(|context| context.object_status_present(object))
        });
        if !present {
            continue;
        }
        let rejected = match call_world_object_own_function(
            object,
            "RejectFight",
            &[object_reference_value(object)],
        ) {
            Some(result) => result?.as_bool(),
            None => false,
        };
        if rejected {
            return Ok(Value::Bool(false));
        }
    }

    // ObjectActionFight calls SetActionByName directly. Its return value is
    // deliberately ignored by FnFightWith, which still returns true.
    let _ = native_set_action_by_name_with_target(clonk, "Fight", Some(target))?;
    let _ = native_set_action_by_name_with_target(target, "Fight", Some(clonk))?;
    Ok(Value::Bool(true))
}

/// Native `C4Object::SetActionByName` staging for engine helpers such as
/// `C4Object::Fling`. This deliberately bypasses script-level function
/// resolution: C++ calls the object method directly.
fn native_set_action_by_name(target: ObjectId, name: &str) -> Result<bool, RuntimeError> {
    native_set_action_by_name_with_target(target, name, None)
}

fn native_set_action_by_name_with_target(
    target: ObjectId,
    name: &str,
    action_target: Option<ObjectId>,
) -> Result<bool, RuntimeError> {
    let builtin_idle = crate::action::is_builtin_idle_name(name);
    let name = if builtin_idle {
        crate::action::DEFAULT_ACTION_NAME
    } else {
        name
    };
    let callbacks = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("native action requires an active engine context"))?;
        if !context.ensure_object_scope(target) {
            return Ok(None);
        }
        let incomplete_activity = context
            .object_scope(target)
            .and_then(|object| {
                object
                    .pending_update
                    .change_def
                    .as_deref()
                    .or(object.definition_id.as_deref())
            })
            .and_then(|definition| context.world.definition_metadata(definition))
            .is_some_and(|metadata| metadata.fire.incomplete_activity);
        let Some(object) = context.object_scope_mut(target) else {
            return Ok(None);
        };
        // ActIdle is the built-in action slot before ActMap and is always a
        // valid SetAction target even when no action named "Idle" exists.
        if name != "Idle" && !object.action_library.contains(name) {
            return Ok(None);
        }
        let current = object.effective_action_name().to_string();
        let current_index = object.effective_action_index();
        let requested_index = object.action_library.named_action_index(name);
        let previous_phase = object.action_phase();
        let definition = object
            .pending_update
            .change_def
            .clone()
            .or_else(|| object.definition_id.clone());
        if object.effective_blocks_other_actions()
            && (current != name || current_index != requested_index)
        {
            return Ok(None);
        }
        // C4Object::SetAction accepts the requested ActMap entry but coerces
        // the resulting action to ActIdle for incomplete objects whose
        // definition does not allow incomplete activity (:4127-4130).
        let actual_name = if object.construction() < FULL_CON && !incomplete_activity {
            "Idle"
        } else {
            name
        };
        let actual_index = object.action_library.named_action_index(actual_name);

        let changed = current != actual_name || current_index != actual_index;
        let update = object
            .pending_update
            .action
            .get_or_insert_with(ActionUpdate::default);
        update.set_name(actual_name.to_string());
        update.set_force(false);
        update.callbacks_dispatched = true;
        if changed {
            object.reset_action_ticks();
        } else {
            object.reset_action_phase_delay();
        }
        object.set_action_phase(0);
        if object.update_effective_action(actual_name) {
            object.reset_action_data();
        }
        if !builtin_idle {
            if let Some(action_target) = action_target {
                object.set_action_target(0, Some(action_target));
            }
        }
        let position = object.effective_position();
        object.current_fixed_position = FixedVec2::from_ints(position.x, position.y);
        object.refresh_cached_ocf();

        let callbacks = (
            (actual_name != "Idle")
                .then(|| {
                    object
                        .action_library
                        .start_callback_for_entry(actual_name, actual_index)
                })
                .flatten(),
            object
                .action_library
                .abort_callback_for_entry(&current, current_index),
            previous_phase,
            definition,
        );
        let _ = refresh_live_object_ocf(context, target);
        Ok(Some(callbacks))
    })?;
    let Some((start_call, abort_call, previous_phase, definition)) = callbacks else {
        return Ok(false);
    };
    if let Some(callback) = start_call {
        if let Some(Err(error)) = call_world_object_script_callback(target, &callback, &[]) {
            tracing::warn!(
                %error,
                callback = callback.function_name(),
                "native SetAction callback error; continuing like the C++ fail-safe exec"
            );
        }
    }
    let callbacks_continue = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_scope(target))
            .is_some_and(|object| {
                !object.destroy
                    && object.status != ObjectStatus::Deleted
                    && object
                        .pending_update
                        .change_def
                        .as_deref()
                        .or(object.definition_id.as_deref())
                        == definition.as_deref()
            })
    });
    if callbacks_continue {
        if let Some(callback) = abort_call {
            if let Some(Err(error)) = call_world_object_script_callback(
                target,
                &callback,
                &[Value::Int(previous_phase)],
            )
            {
                tracing::warn!(
                    %error,
                    callback = callback.function_name(),
                    "native SetAction callback error; continuing like the C++ fail-safe exec"
                );
            }
        }
    }
    Ok(true)
}

/// Target-aware `C4Object::SetDir` used by native action helpers.
fn native_set_dir(target: ObjectId, direction: Direction) -> Result<(), RuntimeError> {
    let turn_action = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetDir requires an active engine context"))?;
        if !context.ensure_object_scope(target) {
            return Ok(None);
        }
        let Some(object) = context.object_scope(target) else {
            return Ok(None);
        };
        let action = object.effective_action_name();
        let action_index = object.effective_action_index();
        let directions = object
            .action_library
            .directions_for_entry(action, action_index);
        let raw_direction = direction.to_script_value();
        if object
            .action_library
            .is_idle_entry(action, action_index)
            || raw_direction < 0
            || raw_direction >= directions as i32
        {
            return Ok(None);
        }
        Ok(Some(
            (object.direction() != direction)
                .then(|| {
                    object
                        .action_library
                        .turn_action_for_entry(action, action_index)
                        .map(str::to_string)
                })
                .flatten(),
        ))
    })?;
    let Some(turn_action) = turn_action else {
        return Ok(());
    };
    if let Some(turn_action) = turn_action {
        let _ = native_set_action_by_name(target, &turn_action)?;
    }
    HOST_CONTEXT.with(|cell| {
        if let Some(object) = cell
            .borrow_mut()
            .as_mut()
            .and_then(|context| context.object_scope_mut(target))
        {
            object.set_direction(direction);
        }
    });
    Ok(())
}

/// `C4Object::Fling(..., false, caused_by)` as used by ShakeObjects.
fn native_fling(
    target: ObjectId,
    mut velocity: FixedVec2,
    add_speed: bool,
    caused_by: i32,
) -> Result<(), RuntimeError> {
    let available = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("Fling requires an active engine context"))?;
        let Some(snapshot) = context.get_world_object(target) else {
            return Ok(false);
        };
        if !context.ensure_object_scope(target) {
            return Ok(false);
        }
        let staged_ocf = context
            .object_scope(target)
            .map(|object| object.staged_ocf(snapshot.ocf()))
            .unwrap_or_else(|| snapshot.ocf());
        if staged_ocf & ocf::ALIVE != 0 {
            stage_energy_loss_cause(context, target, -1, crate::C4FX_CALL_ENG_SCRIPT, caused_by);
        } else if context
            .object_scope(target)
            .and_then(ObjectScopeContext::container)
            .is_none()
        {
            if let Some(object) = context.object_scope_mut(target) {
                object.set_controller(caused_by);
            }
        }
        if add_speed {
            if let Some(object) = context.object_scope(target) {
                let current = object.fixed_velocity();
                velocity.x += current.x / 2;
                velocity.y += current.y / 2;
            }
        }
        Ok(true)
    })?;
    if !available {
        return Ok(());
    }

    if native_set_action_by_name(target, "Tumble")? {
        native_set_dir(
            target,
            if velocity.x < C4Fixed::ZERO {
                Direction::Right
            } else {
                Direction::Left
            },
        )?;
        HOST_CONTEXT.with(|cell| {
            if let Some(object) = cell
                .borrow_mut()
                .as_mut()
                .and_then(|context| context.object_scope_mut(target))
            {
                // ObjectActionTumble assigns xdir/ydir directly and therefore
                // preserves C4Object::Mobile. Counteract ObjectDelta's generic
                // script-velocity mobilization with the live post-callback value.
                let mobile = object.mobile();
                object.set_fixed_velocity(velocity);
                object.set_mobile(mobile);
            }
        });
        return Ok(());
    }

    let jump_handled = match call_world_object_own_function(
        target,
        "OnActionJump",
        &[
            Value::Int(fixtoi_prec(velocity.x, 100)),
            Value::Int(fixtoi_prec(velocity.y, 100)),
            Value::Bool(false),
        ],
    ) {
        Some(Ok(value)) => value.as_bool(),
        Some(Err(error)) => {
            tracing::warn!(
                %error,
                "OnActionJump error; continuing like the C++ fail-safe exec"
            );
            false
        }
        None => false,
    };
    if jump_handled {
        return Ok(());
    }

    let _ = native_set_action_by_name(target, "Jump")?;
    HOST_CONTEXT.with(|cell| {
        if let Some(object) = cell
            .borrow_mut()
            .as_mut()
            .and_then(|context| context.object_scope_mut(target))
        {
            object.set_fixed_velocity(velocity);
            object.set_mobile(true);
            object.set_t_attach(object.t_attach() & !CNAT_BOTTOM);
        }
    });
    Ok(())
}

/// FnShakeObjects -> C4Game::ShakeObjects (C4Script.cpp:3104-3106;
/// C4Game.cpp:1300-1314). Selection and random draws follow master-list
/// order; Random(3) precedes both attachment gates, while Rnd3 is consumed
/// only for objects that are actually flung.
fn shake_objects(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 3 {
        return Err(RuntimeError::new(
            "ShakeObjects expects exactly 3 arguments: x, y, radius",
        ));
    }
    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "ShakeObjects", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "ShakeObjects", "y")?;
    let radius = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "ShakeObjects", "radius")?;
    let (ids, caused_by) = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow
            .as_ref()
            .ok_or_else(|| RuntimeError::new("ShakeObjects requires an active engine context"))?;
        Ok::<_, RuntimeError>((
            context.master_object_ids(),
            context
                .object_context()
                .map(ObjectScopeContext::controller)
                .unwrap_or(OWNER_NONE),
        ))
    })?;

    for id in ids {
        let candidate = HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let context = borrow.as_ref()?;
            let object = context.get_world_object(id)?;
            let category = context
                .object_scope(id)
                .map(ObjectScopeContext::category)
                .unwrap_or_else(|| object.category());
            Some((object, category))
        });
        let Some((candidate, category)) = candidate else {
            continue;
        };
        let position = candidate.position();
        // C4OS_INACTIVE objects live in InactiveObjects rather than the
        // Game.Objects list traversed by C4Game::ShakeObjects
        // (C4GameObjects.cpp:54-67).
        let inside = candidate.status() == ObjectStatus::Normal
            && candidate.container().is_none()
            && category & crate::CATEGORY_LIVING != 0
            && (i64::from(y) - i64::from(position.y)).abs() <= i64::from(radius)
            && (i64::from(x) - i64::from(position.x)).abs() <= i64::from(radius);
        if !inside || draw_context_random(3)? != 0 {
            continue;
        }
        let attached_to_world = HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let context = borrow.as_ref()?;
            let t_attach = context
                .object_scope(id)
                .map(ObjectScopeContext::t_attach)
                .or_else(|| candidate.full_state().map(|state| state.t_attach))?;
            Some(
                t_attach != 0
                    && candidate
                        .full_state()
                        .is_some_and(|state| !state.shape_attach.mat_vehicle),
            )
        });
        if attached_to_world != Some(true) {
            continue;
        }
        native_fling(
            id,
            FixedVec2::new(itofix(draw_context_rnd3()?), C4Fixed::ZERO),
            false,
            caused_by,
        )?;
    }
    Ok(Value::Nil)
}

/// FnSetGamma (C4Script.cpp:4998-5006) -> C4GraphicsSystem::SetGamma
/// (C4GraphicsSystem.cpp:772-784). Missing arguments are C4Aul integer zero;
/// in particular, an omitted ramp index selects the script/user slot 0.
/// Remaining app-config gap: Rust does not yet pass
/// `Config.Graphics.DisableGamma` into an engine callback. C++ skips even the
/// stored write when that flag is set (C4GraphicsSystem.cpp:774-776); until
/// that boundary exists, every otherwise-valid Rust write is retained.
fn set_gamma(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut points = [0_u32; 3];
    for (slot, point) in points.iter_mut().enumerate() {
        *point = value_to_i32(
            args.get(slot).unwrap_or(&Value::Nil),
            "SetGamma",
            "control point",
        )? as u32;
    }
    let index = value_to_i32(args.get(3).unwrap_or(&Value::Nil), "SetGamma", "ramp index")?;

    // C4GraphicsSystem::SetGamma silently returns for every index outside
    // [0,C4MaxGammaRamps), before touching the stored controls.
    if !(0..crate::GAMMA_RAMP_COUNT as i32).contains(&index) {
        return Ok(Value::Nil);
    }
    HOST_CONTEXT.with(|cell| {
        if let Some(context) = cell.borrow_mut().as_mut() {
            context.register_landscape_operation(LandscapeOperation::GammaRamp { index, points });
        }
    });
    Ok(Value::Nil)
}

/// FnResetGamma (C4Script.cpp:5004-5006): restore the selected ramp to the
/// C4GraphicsSystem default 0x000000/0x808080/0xffffff control points.
fn reset_gamma(args: &[Value]) -> Result<Value, RuntimeError> {
    let index = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "ResetGamma",
        "ramp index",
    )?;
    if !(0..crate::GAMMA_RAMP_COUNT as i32).contains(&index) {
        return Ok(Value::Nil);
    }
    HOST_CONTEXT.with(|cell| {
        if let Some(context) = cell.borrow_mut().as_mut() {
            context.register_landscape_operation(LandscapeOperation::GammaRamp {
                index,
                points: crate::GammaControlState::DEFAULT_RAMP,
            });
        }
    });
    Ok(Value::Nil)
}

/// FnSetSkyAdjust (C4Script.cpp:4620-4624) -> C4Sky::SetModulation: sky
/// blit modulation plus the alpha-gated background fill color.
fn set_sky_adjust(args: &[Value]) -> Result<Value, RuntimeError> {
    let modulation = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "SetSkyAdjust",
        "adjust",
    )? as u32;
    let back_color = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "SetSkyAdjust",
        "back color",
    )? as u32;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetSkyAdjust requires an active engine context"))?;
        context.sky_adjustment = SkyAdjustment {
            modulation,
            back_color,
        };
        context.register_landscape_operation(LandscapeOperation::SkyAdjust {
            modulation,
            back_color,
        });
        Ok(Value::Nil)
    })
}

fn apply_sky_color_modulation(
    function: &str,
    target: RgbColor,
) -> Result<Value, RuntimeError> {
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| {
                RuntimeError::new(format!("{function} requires an active engine context"))
            })?;
        let adjustment =
            SkyAdjustment::from_color_modulation(context.world.sky_fade[0], target);
        context.sky_adjustment = adjustment;
        context.register_landscape_operation(LandscapeOperation::SkyAdjust {
            modulation: adjustment.modulation,
            back_color: adjustment.back_color,
        });
        Ok(Value::Nil)
    })
}

/// FnSetSkyFade (C4Script.cpp:3039-3044): NewGfx maps only the first RGB
/// triple onto FadeClr1. The legacy destination triple remains a typed but
/// otherwise ignored compatibility parameter.
fn set_sky_fade(args: &[Value]) -> Result<Value, RuntimeError> {
    let target = RgbColor::new(
        value_to_i32(
            args.first().unwrap_or(&Value::Nil),
            "SetSkyFade",
            "from red",
        )? as u8,
        value_to_i32(
            args.get(1).unwrap_or(&Value::Nil),
            "SetSkyFade",
            "from green",
        )? as u8,
        value_to_i32(
            args.get(2).unwrap_or(&Value::Nil),
            "SetSkyFade",
            "from blue",
        )? as u8,
    );
    for (offset, parameter) in [(3, "to red"), (4, "to green"), (5, "to blue")] {
        value_to_i32(
            args.get(offset).unwrap_or(&Value::Nil),
            "SetSkyFade",
            parameter,
        )?;
    }
    apply_sky_color_modulation("SetSkyFade", target)
}

/// FnSetSkyColor (C4Script.cpp:3046-3054): index zero maps the requested
/// OldGfx RGB color onto FadeClr1 via GetClrModulation; other indices are
/// silent no-ops.
fn set_sky_color(args: &[Value]) -> Result<Value, RuntimeError> {
    let index = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "SetSkyColor",
        "index",
    )?;
    let target = RgbColor::new(
        value_to_i32(args.get(1).unwrap_or(&Value::Nil), "SetSkyColor", "red")? as u8,
        value_to_i32(
            args.get(2).unwrap_or(&Value::Nil),
            "SetSkyColor",
            "green",
        )? as u8,
        value_to_i32(
            args.get(3).unwrap_or(&Value::Nil),
            "SetSkyColor",
            "blue",
        )? as u8,
    );
    if index != 0 {
        return Ok(Value::Nil);
    }
    apply_sky_color_modulation("SetSkyColor", target)
}

/// FnGetSkyAdjust (C4Script.cpp:4632-4636) returns the raw sky modulation,
/// or the raw background color when its bool argument is truthy. The latter
/// is independent of `BackClrEnabled` (C4Sky.h:43-46).
fn get_sky_adjust(args: &[Value]) -> Result<Value, RuntimeError> {
    let back_color = args.first().is_some_and(Value::as_bool);
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow
            .as_ref()
            .ok_or_else(|| RuntimeError::new("GetSkyAdjust requires an active engine context"))?;
        let raw = if back_color {
            context.sky_adjustment.back_color
        } else {
            context.sky_adjustment.modulation
        };
        Ok(Value::Int(raw as i32))
    })
}

/// FnGetSkyColor (C4Script.cpp:3056-3069), retained for OldGfx scripts.
/// Only palette index zero exists. Its alpha is zero, so C++ BltAlpha's
/// inverted-alpha `/ 256` blend returns each nonzero FadeClr2 channel minus
/// one; FadeClr1 contributes nothing.
fn get_sky_color(args: &[Value]) -> Result<Value, RuntimeError> {
    let index = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "GetSkyColor",
        "index",
    )?;
    let channel = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "GetSkyColor",
        "channel",
    )?;
    if index != 0 || !(0..=2).contains(&channel) {
        return Ok(Value::Int(0));
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow
            .as_ref()
            .ok_or_else(|| RuntimeError::new("GetSkyColor requires an active engine context"))?;
        let color = context.world.sky_fade[1];
        let component = match channel {
            0 => color.r,
            1 => color.g,
            2 => color.b,
            _ => unreachable!(),
        };
        Ok(Value::Int(i32::from(component.saturating_sub(1))))
    })
}

/// FnSetMatAdjust (C4Script.cpp:4626-4630): overwrite the raw landscape
/// blit modulation. Zero restores normal drawing.
fn set_mat_adjust(args: &[Value]) -> Result<Value, RuntimeError> {
    let modulation = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "SetMatAdjust",
        "adjust",
    )? as u32;
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetMatAdjust requires an active engine context"))?;
        if let Some(landscape) = context.world.landscape_mut() {
            landscape.set_modulation(modulation);
        }
        context.register_landscape_operation(LandscapeOperation::MatAdjust { modulation });
        Ok(Value::Nil)
    })
}

/// FnGetMatAdjust (C4Script.cpp:4638-4642): return the raw landscape blit
/// modulation. C4Landscape::Default initializes this to zero.
fn get_mat_adjust(_args: &[Value]) -> Result<Value, RuntimeError> {
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow
            .as_ref()
            .ok_or_else(|| RuntimeError::new("GetMatAdjust requires an active engine context"))?;
        let modulation = context
            .world
            .landscape_ref()
            .map_or(0, |landscape| landscape.modulation());
        Ok(Value::Int(modulation as i32))
    })
}

/// FnSetLandscapePixel (C4Script.cpp:5082-5088): offset by the current
/// script object and write only the packed-color Surface32 pixel. The native
/// is void and ignores out-of-bounds or surface-lock failure.
fn set_landscape_pixel(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "SetLandscapePixel",
        "x",
    )?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "SetLandscapePixel", "y")?;
    let color = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "SetLandscapePixel",
        "color",
    )? as u32;
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut().ok_or_else(|| {
            RuntimeError::new("SetLandscapePixel requires an active engine context")
        })?;
        let position = context
            .caller_scope()
            .map_or(Vector2::new(x, y), |(_, base)| {
                Vector2::new(base.x.saturating_add(x), base.y.saturating_add(y))
            });
        context.register_landscape_operation(LandscapeOperation::SetLandscapePixel {
            position,
            color,
        });
        Ok(Value::Nil)
    })
}

/// FnSetSkyParallax (C4Script.cpp:4955-4970): seven plain ints; nil and
/// missing args are 0 at the C4Aul boundary (zeroing the scroll slots) —
/// only the explicit SkyPar_KEEP magic preserves a slot.
fn set_sky_parallax(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut slots = [0i32; 7];
    for (index, slot) in slots.iter_mut().enumerate() {
        *slot = value_to_i32(
            args.get(index).unwrap_or(&Value::Nil),
            "SetSkyParallax",
            "parameter",
        )?;
    }
    let [mode, par_x, par_y, xdir, ydir, x, y] = slots;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetSkyParallax requires an active engine context"))?;
        context.register_landscape_operation(LandscapeOperation::SkyParallax {
            mode,
            par_x,
            par_y,
            xdir,
            ydir,
            x,
            y,
        });
        Ok(Value::Nil)
    })
}

fn dig_free(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "DigFree", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "DigFree", "y")?;
    let radius = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "DigFree", "radius")?;
    if radius < 0 {
        return Ok(Value::Nil);
    }

    let requested = if let Some(arg) = args.get(3) {
        value_to_bool(arg, "DigFree", "requested")?
    } else {
        false
    };

    let (by_object, counts) = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("DigFree requires an active engine context"))?;
        let by_object = context.object_context().map(|object| object.id());
        let center = Vector2::new(x, y);
        let counts = context.preview_dig_circle(center, radius);
        context.register_landscape_operation(LandscapeOperation::DigCirclePreviewed {
            center,
            radius,
        });
        Ok((by_object, counts))
    })?;
    process_preview_dig_reactions(by_object, &counts, requested)?;
    Ok(Value::Nil)
}

/// FnFreeRect (C4Script.cpp:3125-3131): clears the landscape rect in
/// GLOBAL coordinates (no caller offset, unlike DigFree*) without
/// producing dug-out material. A nonzero fifth argument selects C++'s
/// density-filtered ClearRectDensity arm.
/// FnScriptGo (C4Script.cpp:2782-2786): switches the scenario script
/// counter gate (Game.Script.Go) that drives the timed Script%d
/// sections (C4GameScriptHost::Execute, C4ScriptHost.cpp:222-232).
fn script_go(args: &[Value]) -> Result<Value, RuntimeError> {
    let go = match args.first() {
        Some(Value::Bool(flag)) => *flag,
        Some(Value::Int(value)) => *value != 0,
        _ => false,
    };
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Nil);
        };
        context.script_go_request = Some(go);
        Ok(Value::Nil)
    })
}

/// FnScriptCounter (C4Script.cpp:3616-3619): zero-argument getter for the
/// live scenario counter. C4GameScriptHost::Execute has already incremented
/// it before entering ScriptN (C4ScriptHost.cpp:222-232), and a preceding
/// goto() in this same VM call is immediately visible.
fn script_counter(_args: &[Value]) -> Result<Value, RuntimeError> {
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Int(0));
        };
        Ok(Value::Int(
            context
                .script_counter_request
                .unwrap_or(context.scenario_script_counter),
        ))
    })
}

/// Fn_goto (C4Script.cpp:225-229): synchronously replaces
/// `Game.Script.Counter` and returns the assigned integer. The current
/// C4GameScriptHost pulse has already post-incremented the counter before it
/// calls Script%d (C4ScriptHost.cpp:222-232), so this redirects the next pulse.
fn script_goto(args: &[Value]) -> Result<Value, RuntimeError> {
    let counter = value_to_i32(args.first().unwrap_or(&Value::Nil), "goto", "counter")?;
    HOST_CONTEXT.with(|cell| {
        if let Some(context) = cell.borrow_mut().as_mut() {
            context.script_counter_request = Some(counter);
        }
        Ok(Value::Int(counter))
    })
}

/// FnDrawMatChunks/C4Landscape::DrawChunks (C4Script.cpp:4802-4805;
/// C4Landscape.cpp:2419-2445): resolve the separate material/texture pair,
/// then sample one synchronized Random(1000) value per chunk in x-major,
/// y-minor order. The resulting offsets are carried to the deferred fold so
/// authoritative drawing cannot consume the global RNG a second time.
fn draw_mat_chunks(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "DrawMatChunks", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "DrawMatChunks", "y")?;
    let width = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "DrawMatChunks", "wdt")?;
    let height = value_to_i32(args.get(3).unwrap_or(&Value::Nil), "DrawMatChunks", "hgt")?;
    let count_x = value_to_i32(
        args.get(4).unwrap_or(&Value::Nil),
        "DrawMatChunks",
        "count-x",
    )?;
    let count_y = value_to_i32(
        args.get(5).unwrap_or(&Value::Nil),
        "DrawMatChunks",
        "count-y",
    )?;
    // FnStringPar maps null string parameters to "". Passing None to
    // get_index would instead wildcard-match the first material slot.
    let material =
        parse_optional_string(args.get(6), "DrawMatChunks", "material")?.unwrap_or_default();
    let texture =
        parse_optional_string(args.get(7), "DrawMatChunks", "texture")?.unwrap_or_default();
    let ift = value_to_bool(args.get(8).unwrap_or(&Value::Nil), "DrawMatChunks", "ift")?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Int(0));
        };
        let Some(map_seed) = context
            .world
            .landscape_ref()
            .and_then(Landscape::raster_state)
            .map(crate::landscape::LandscapeRasterState::map_seed)
        else {
            return Ok(Value::Int(0));
        };
        let Some(texmap) = context.runtime_texmap_mut() else {
            return Ok(Value::Int(0));
        };

        // GetMapColorIndex special-cases exact-case "Sky" to byte zero,
        // then DrawChunks still performs the independent material lookup.
        let slot = if material == "Sky" {
            0
        } else {
            texmap.get_index(&material, Some(&texture), true)
        };
        if (material != "Sky" && slot == 0) || texmap.material(&material).is_none() {
            return Ok(Value::Int(0));
        }
        let byte = if material == "Sky" {
            0
        } else {
            slot | if ift { 0x80 } else { 0 }
        };

        let mut random_offsets = Vec::new();
        for _ in 0..count_x {
            for _ in 0..count_y {
                random_offsets.push(draw_context_random(1_000)?);
            }
        }
        let texmap = texmap.clone();
        let operation = LandscapeOperation::DrawMatChunks {
            origin: Vector2::new(x, y),
            width,
            height,
            count_x,
            count_y,
            material,
            byte,
            map_seed,
            random_offsets,
            texmap,
        };
        context.preview_draw_mat_chunks(&operation);
        context.register_landscape_operation(operation);
        Ok(Value::Int(1))
    })
}

/// FnDrawVolcanoBranch (C4Script.cpp:2500-2509): draw the numeric material's
/// DefaultMatTex through raw, GLOBAL SetPix calls. The callback captures the
/// live default byte and previews the synchronous Surface8 mutation; the
/// authoritative fold repeats only the deterministic pixel loop.
fn draw_volcano_branch(args: &[Value]) -> Result<Value, RuntimeError> {
    let material = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "DrawVolcanoBranch",
        "material",
    )?;
    let from_x = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "DrawVolcanoBranch",
        "from-x",
    )?;
    let from_y = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "DrawVolcanoBranch",
        "from-y",
    )?;
    let to_x = value_to_i32(
        args.get(3).unwrap_or(&Value::Nil),
        "DrawVolcanoBranch",
        "to-x",
    )?;
    let to_y = value_to_i32(
        args.get(4).unwrap_or(&Value::Nil),
        "DrawVolcanoBranch",
        "to-y",
    )?;
    let size = value_to_i32(
        args.get(5).unwrap_or(&Value::Nil),
        "DrawVolcanoBranch",
        "size",
    )?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Nil);
        };
        let Some(material_byte) = context
            .runtime_texmap()
            .and_then(|texmap| texmap.default_material_entry_by_index(material))
        else {
            // C++'s direct material-map indexing is undefined for an invalid
            // index. Keep script execution safe without inventing a success
            // or failure value: the native is void in every case.
            return Ok(Value::Nil);
        };
        let operation = LandscapeOperation::DrawVolcanoBranch {
            from: Vector2::new(from_x, from_y),
            to: Vector2::new(to_x, to_y),
            size,
            material_byte,
        };
        context.preview_draw_volcano_branch(&operation);
        context.register_landscape_operation(operation);
        Ok(Value::Nil)
    })
}

/// FnDrawMaterialQuad (C4Script.cpp:5111-5115): all coordinates are GLOBAL
/// (there is no cthr->Obj offset), and the bool is the Surface8 IFT bit.
/// GetIndexMatTex runs synchronously so an unresolved material returns false
/// without queuing a landscape change (C4Landscape.cpp:2448-2452).
fn draw_material_quad(args: &[Value]) -> Result<Value, RuntimeError> {
    let material_texture =
        parse_optional_string(args.first(), "DrawMaterialQuad", "material-texture")?
            .unwrap_or_default();
    let coordinate_names = ["x1", "y1", "x2", "y2", "x3", "y3", "x4", "y4"];
    let mut coordinates = [0; 8];
    for (index, coordinate) in coordinates.iter_mut().enumerate() {
        *coordinate = value_to_i32(
            args.get(index + 1).unwrap_or(&Value::Nil),
            "DrawMaterialQuad",
            coordinate_names[index],
        )?;
    }
    let ift = value_to_bool(
        args.get(9).unwrap_or(&Value::Nil),
        "DrawMaterialQuad",
        "sub",
    )?;
    let vertices = [
        Vector2::new(coordinates[0], coordinates[1]),
        Vector2::new(coordinates[2], coordinates[3]),
        Vector2::new(coordinates[4], coordinates[5]),
        Vector2::new(coordinates[6], coordinates[7]),
    ];

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        if !context.resolve_runtime_material_texture(&material_texture) {
            return Ok(Value::Bool(false));
        }
        let operation = LandscapeOperation::DrawMaterialQuad {
            material_texture,
            vertices,
            ift,
        };
        context.preview_draw_material_quad(&operation);
        context.register_landscape_operation(operation);
        Ok(Value::Bool(true))
    })
}

fn runtime_map_random_context(function: &str) -> Result<Rc<RandomContext>, RuntimeError> {
    RANDOM_CONTEXT
        .with(|cell| cell.borrow().as_ref().cloned())
        .ok_or_else(|| RuntimeError::new(format!("{function}: random context unavailable")))
}

/// Run one AlgoScript callback without retaining either thread-local borrow.
/// The map renderer owns a detached copy of the live RANDOM_CONTEXT ledger;
/// publish it immediately before entering the nested scenario VM, then pull
/// back every Random() draw before continuing the native pixel traversal.
fn call_runtime_map_script_algo(
    random_context: &Rc<RandomContext>,
    scenario_script: Option<&Arc<ScriptEngine>>,
    rng: &mut LcgRng,
    function: &str,
    args: [i32; 4],
) -> bool {
    *random_context.rng.borrow_mut() = rng.clone();
    let args = args.map(Value::Int);
    let result = scenario_script
        .and_then(|script| {
            call_scoped_scenario_function(Arc::clone(script), function, &args)
        })
        .and_then(Result::ok)
        .is_some_and(|value| value.as_bool());
    *rng = random_context.rng.borrow().clone();
    result
}

/// FnDrawMap/C4Landscape::DrawMap (C4Script.cpp:4851-4855;
/// C4Landscape.cpp:2636-2668): clip the GLOBAL destination first, then make
/// an exact-size temporary S2 map through the callback's live synced RNG.
/// The resulting indexed bytes are queued verbatim so the later engine fold
/// cannot consume the map's size/range/seed draws a second time.
fn draw_map(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "DrawMap", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "DrawMap", "y")?;
    let width = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "DrawMap", "wdt")?;
    let height = value_to_i32(args.get(3).unwrap_or(&Value::Nil), "DrawMap", "hgt")?;
    let Some(source) = parse_optional_string(args.get(4), "DrawMap", "map-definition")? else {
        return Ok(Value::Int(0));
    };

    let preflight = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut()?;
        let Some((landscape_width, landscape_height, map_zoom, retained_creator)) =
            context.world.landscape_ref().and_then(|landscape| {
                let (landscape_width, landscape_height) = landscape.grid_dimensions()?;
                let raster = landscape.raster_state()?;
                Some((
                    landscape_width,
                    landscape_height,
                    raster.map_zoom(),
                    raster.map_creator().cloned(),
                ))
            })
        else {
            return None;
        };
        if map_zoom <= 0 {
            return None;
        }

        // C4Landscape::ClipRect (C4Landscape.cpp:2698-2707) is the half-open
        // intersection with the landscape. i64 intermediates retain those
        // semantics without overflowing on hostile script integers.
        let left = i64::from(x).max(0);
        let top = i64::from(y).max(0);
        let right = (i64::from(x) + i64::from(width)).min(i64::from(landscape_width));
        let bottom = (i64::from(y) + i64::from(height)).min(i64::from(landscape_height));
        if right <= left || bottom <= top {
            return None;
        }
        let clipped_x = left as i32;
        let clipped_y = top as i32;
        let clipped_width = (right - left) as i32;
        let clipped_height = (bottom - top) as i32;
        let map_width = (clipped_width - 1) / map_zoom + 1;
        let map_height = (clipped_height - 1) / map_zoom + 1;

        let texmap = context.runtime_texmap()?.clone();
        let scenario_script = context.world.scenario_script().cloned();
        Some((
            clipped_x,
            clipped_y,
            map_width,
            map_height,
            retained_creator,
            texmap,
            scenario_script,
        ))
    });
    let Some((
        clipped_x,
        clipped_y,
        map_width,
        map_height,
        mut retained_creator,
        texmap,
        scenario_script,
    )) = preflight
    else {
        return Ok(Value::Int(0));
    };

    let texmap_before = texmap.clone();
    let mut classifier = crate::scenario::MapPixelClassifier::from_runtime_state(texmap);
    let script_functions = scenario_script
        .as_ref()
        .map(|script| {
            script
                .functions()
                .keys()
                .filter(|name| script.has_local_function(name))
                .cloned()
                .collect::<HashSet<_>>()
        })
        .unwrap_or_default();
    let random_context = runtime_map_random_context("DrawMap")?;
    let mut rng = random_context.rng.borrow().clone();
    let rendered = {
        let mut script_algo = |rng: &mut LcgRng, function: &str, args: [i32; 4]| {
            call_runtime_map_script_algo(
                &random_context,
                scenario_script.as_ref(),
                rng,
                function,
                args,
            )
        };
        crate::map_creator_s2::render_runtime_s2_map_with_script_algo(
            retained_creator.as_mut(),
            &source,
            &mut classifier,
            map_width,
            map_height,
            &mut rng,
            &script_functions,
            &mut script_algo,
        )
    };
    // Parsing/evaluation draws also precede the caller's next script opcode,
    // even when no ScriptAlgo function exists or Render finds no map.
    *random_context.rng.borrow_mut() = rng;

    let texmap = classifier.into_runtime_state();
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Int(0));
        };
        // Parser-side texture allocations are live to later calls in this
        // VM session even if Render found no map.
        context.set_runtime_texmap(texmap.clone());
        let Some(bitmap) = rendered else {
            if texmap != texmap_before {
                let operation = LandscapeOperation::SyncRuntimeTexMap { texmap };
                context.world.preview_runtime_landscape_operation(&operation);
                context.register_landscape_operation(operation);
            }
            return Ok(Value::Int(0));
        };
        let map_creator = retained_creator.map(RetainedMapCreatorUpdate);
        let operation = LandscapeOperation::DrawMap {
            origin: Vector2::new(clipped_x, clipped_y),
            bitmap,
            map_width,
            map_height,
            texmap,
            map_creator,
        };
        context.preview_draw_indexed_map(&operation);
        context.register_landscape_operation(operation);
        Ok(Value::Int(1))
    })
}

/// FnDrawDefMap/C4Landscape::DrawDefMap (C4Script.cpp:4857-4861;
/// C4Landscape.cpp:2672-2696): clip the GLOBAL destination, resize the named
/// map in the retained scenario creator, re-evaluate that complete creator
/// through the live synced RNG, and queue the rendered indexed bytes.
fn draw_def_map(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "DrawDefMap", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "DrawDefMap", "y")?;
    let width = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "DrawDefMap", "wdt")?;
    let height = value_to_i32(args.get(3).unwrap_or(&Value::Nil), "DrawDefMap", "hgt")?;
    let Some(map_name) = parse_optional_string(args.get(4), "DrawDefMap", "map-definition")? else {
        return Ok(Value::Int(0));
    };

    let preflight = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut()?;
        let Some((landscape_width, landscape_height, map_zoom, map_creator)) =
            context.world.landscape_ref().and_then(|landscape| {
                let (landscape_width, landscape_height) = landscape.grid_dimensions()?;
                let raster = landscape.raster_state()?;
                Some((
                    landscape_width,
                    landscape_height,
                    raster.map_zoom(),
                    raster.map_creator()?.clone(),
                ))
            })
        else {
            return None;
        };
        if map_zoom <= 0 {
            return None;
        }

        // C4Landscape::ClipRect runs before GetMap/SetSize. In particular,
        // an empty clipped destination cannot re-evaluate the retained tree.
        let left = i64::from(x).max(0);
        let top = i64::from(y).max(0);
        let right = (i64::from(x) + i64::from(width)).min(i64::from(landscape_width));
        let bottom = (i64::from(y) + i64::from(height)).min(i64::from(landscape_height));
        if right <= left || bottom <= top {
            return None;
        }
        let clipped_x = left as i32;
        let clipped_y = top as i32;
        let clipped_width = (right - left) as i32;
        let clipped_height = (bottom - top) as i32;
        let map_width = (clipped_width - 1) / map_zoom + 1;
        let map_height = (clipped_height - 1) / map_zoom + 1;

        let texmap = context.runtime_texmap()?.clone();
        let scenario_script = context.world.scenario_script().cloned();
        Some((
            clipped_x,
            clipped_y,
            map_width,
            map_height,
            map_creator,
            texmap,
            scenario_script,
        ))
    });
    let Some((
        clipped_x,
        clipped_y,
        map_width,
        map_height,
        mut map_creator,
        texmap,
        scenario_script,
    )) = preflight
    else {
        return Ok(Value::Int(0));
    };

    let mut classifier = crate::scenario::MapPixelClassifier::from_runtime_state(texmap);
    let random_context = runtime_map_random_context("DrawDefMap")?;
    let mut rng = random_context.rng.borrow().clone();
    let rendered = {
        let mut script_algo = |rng: &mut LcgRng, function: &str, args: [i32; 4]| {
            call_runtime_map_script_algo(
                &random_context,
                scenario_script.as_ref(),
                rng,
                function,
                args,
            )
        };
        crate::map_creator_s2::render_named_s2_map_with_script_algo(
            &mut map_creator,
            &map_name,
            &mut classifier,
            map_width,
            map_height,
            &mut rng,
            &mut script_algo,
        )
    };
    *random_context.rng.borrow_mut() = rng;

    let texmap = classifier.into_runtime_state();
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Int(0));
        };
        context.set_runtime_texmap(texmap.clone());
        let Some(bitmap) = rendered else {
            return Ok(Value::Int(0));
        };

        // C++ mutates pMapCreator synchronously. Update the callback's COW
        // world now so a later DrawDefMap/DrawMap in this same VM call sees
        // the resized and re-evaluated tree; the operation carries the same
        // state into the authoritative engine fold.
        context.preview_runtime_map_creator(map_creator.clone());
        let operation = LandscapeOperation::DrawDefMap {
            origin: Vector2::new(clipped_x, clipped_y),
            bitmap,
            map_width,
            map_height,
            texmap,
            map_creator: RetainedMapCreatorUpdate(map_creator),
        };
        context.preview_draw_indexed_map(&operation);
        context.register_landscape_operation(operation);
        Ok(Value::Int(1))
    })
}

fn free_rect(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "FreeRect", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "FreeRect", "y")?;
    let width = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "FreeRect", "wdt")?;
    let height = value_to_i32(args.get(3).unwrap_or(&Value::Nil), "FreeRect", "hgt")?;
    let density = value_to_i32(
        args.get(4).unwrap_or(&Value::Nil),
        "FreeRect",
        "free_density",
    )?;
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Nil);
        };
        context.preview_clear_rect(
            Vector2::new(x, y),
            width,
            height,
            (density != 0).then_some(density),
        )?;
        Ok(Value::Nil)
    })
}

fn dig_free_rect(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "DigFreeRect", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "DigFreeRect", "y")?;
    let width = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "DigFreeRect", "width")?;
    let height = value_to_i32(args.get(3).unwrap_or(&Value::Nil), "DigFreeRect", "height")?;
    if width <= 0 || height <= 0 {
        return Ok(Value::Nil);
    }

    let requested = if let Some(arg) = args.get(4) {
        value_to_bool(arg, "DigFreeRect", "requested")?
    } else {
        false
    };

    let (by_object, counts) = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("DigFreeRect requires an active engine context"))?;
        let by_object = context.object_context().map(|object| object.id());
        let origin = Vector2::new(x, y);
        let counts = context.preview_dig_rect(origin, width, height);
        context.register_landscape_operation(LandscapeOperation::DigRectPreviewed {
            origin,
            width,
            height,
        });
        Ok((by_object, counts))
    })?;
    process_preview_dig_reactions(by_object, &counts, requested)?;
    Ok(Value::Nil)
}

// ── C4FindObject / C4SortObject condition trees (C4FindObject.{h,cpp}) ──────

/// C4FO_* constants (C4FindObject.h:27-50) as a parsed condition tree.
/// Known divergences: `Layer` is unmodeled on host objects (never
/// matches); shape tests use the vertices bounding box.
#[derive(Debug, Clone)]
enum FindCondition {
    Not(Box<FindCondition>),
    And(Vec<FindCondition>),
    Or(Vec<FindCondition>),
    Exclude(Option<ObjectId>),
    Id(usize),
    InRect(DefinitionRect),
    AtPoint(i32, i32),
    AtRect(DefinitionRect),
    OnLine(i32, i32, i32, i32),
    Distance {
        x: i32,
        y: i32,
        r2: i64,
        /// The enclosing square the C++ constructor precomputes for
        /// GetBounds (C4FindObject.h:253).
        bounds: DefinitionRect,
    },
    Ocf(u32),
    Category(i32),
    Action(String),
    ActionTarget {
        target: Option<ObjectId>,
        index: usize,
    },
    Container(Option<ObjectId>),
    AnyContainer,
    Owner(i32),
    Controller(i32),
    /// C4FindObjectFunc (C4FindObject.cpp:124-136): calls `name` on each
    /// candidate via the nested-call seam.
    Func {
        name: String,
        pars: Vec<Value>,
    },
    /// C4FindObjectLayer (C4FindObject.cpp:671-674): `pObj->pLayer ==
    /// pLayer` — None matches every unlayered object.
    Layer(Option<ObjectId>),
}

/// C4SO_* constants (C4FindObject.h:53-62) as a parsed sort tree.
#[derive(Debug, Clone)]
enum SortCriterion {
    Reverse(Box<SortCriterion>),
    Multiple(Vec<SortCriterion>),
    Distance {
        x: i32,
        y: i32,
    },
    Random,
    Speed,
    Mass,
    Value,
    /// C4SortObjectFunc (C4FindObject.h:521-533): evaluates the named
    /// callback for each candidate and compares its integer result.
    Func {
        name: String,
        pars: Vec<Value>,
    },
}

enum ParsedCriterion {
    Condition(FindCondition),
    Sort(SortCriterion),
    None,
}

fn value_as_object_id(value: &Value) -> Option<ObjectId> {
    match value {
        Value::Object(id) => Some(ObjectId::new(*id)),
        _ => object_id_from_value(value),
    }
}

/// `C4Value::getInt()` reads the shared low `Data.Int` word for Int and Bool
/// values. `RawBool` preserves the non-canonical Bool payload that script
/// casts can produce; every other C4V type yields zero.
pub(crate) fn value_as_i32(value: &Value) -> i32 {
    match value {
        Value::Int(value) => *value,
        Value::Bool(value) => i32::from(*value),
        Value::RawBool(value) => *value as u32 as i32,
        _ => 0,
    }
}

/// C4FindObjectFunc/C4SortObjectFunc store their arguments in C4Value cells.
/// AssignRemoval clears registered object references synchronously, so a
/// later candidate must receive nil even though Rust's parsed criterion tree
/// owns an ordinary Value clone.
fn live_find_callback_parameters(pars: &[Value]) -> Vec<Value> {
    let mut live = pars.to_vec();
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return;
        };
        for value in &mut live {
            clear_removed_object_references(value, &context.removed_object_references);
        }
    });
    live
}

impl FindCondition {
    /// `C4FindObject::CreateByValue` (C4FindObject.cpp:37-162): arrays whose
    /// first element is in C4SO_First..=C4SO_Last parse as sort criteria
    /// instead.
    fn parse(value: &Value) -> ParsedCriterion {
        // Must be an array (C4FindObject.cpp:40-41)
        let Value::Array(data) = value else {
            return ParsedCriterion::None;
        };
        let kind = data.first().map(value_as_i32).unwrap_or(0);
        if (100..=200).contains(&kind) {
            return SortCriterion::parse_typed(kind, data)
                .map(ParsedCriterion::Sort)
                .unwrap_or(ParsedCriterion::None);
        }
        let arg_i32 = |index: usize| data.get(index).map(value_as_i32).unwrap_or(0);
        let condition = match kind {
            // C4FO_Not
            1 => match data.get(1).map(Self::parse) {
                Some(ParsedCriterion::Condition(child)) => FindCondition::Not(Box::new(child)),
                _ => return ParsedCriterion::None,
            },
            // C4FO_And / C4FO_Or: trivial single-condition unwrap, dropped
            // null children (C4FindObject.cpp:67-87)
            2 | 3 => {
                let children: Vec<FindCondition> = data[1..]
                    .iter()
                    .filter_map(|entry| match Self::parse(entry) {
                        ParsedCriterion::Condition(child) => Some(child),
                        _ => None,
                    })
                    .collect();
                if data.len() == 2 {
                    match children.into_iter().next() {
                        Some(child) => child,
                        None => return ParsedCriterion::None,
                    }
                } else if kind == 2 {
                    FindCondition::And(children)
                } else {
                    FindCondition::Or(children)
                }
            }
            // C4FO_Exclude
            5 => FindCondition::Exclude(data.get(1).and_then(value_as_object_id)),
            // C4FO_InRect
            10 => FindCondition::InRect(DefinitionRect::new(
                arg_i32(1),
                arg_i32(2),
                arg_i32(3),
                arg_i32(4),
            )),
            // C4FO_AtPoint
            11 => FindCondition::AtPoint(arg_i32(1), arg_i32(2)),
            // C4FO_AtRect
            12 => FindCondition::AtRect(DefinitionRect::new(
                arg_i32(1),
                arg_i32(2),
                arg_i32(3),
                arg_i32(4),
            )),
            // C4FO_OnLine
            13 => FindCondition::OnLine(arg_i32(1), arg_i32(2), arg_i32(3), arg_i32(4)),
            // C4FO_Distance
            14 => {
                let r = arg_i32(3);
                let (x, y) = (arg_i32(1), arg_i32(2));
                FindCondition::Distance {
                    x,
                    y,
                    r2: i64::from(r) * i64::from(r),
                    // (x - r, y - r, 2r + 1, 2r + 1), C4FindObject.h:253 —
                    // wrapping like the C++ int32 arithmetic.
                    bounds: DefinitionRect::new(
                        x.wrapping_sub(r),
                        y.wrapping_sub(r),
                        r.wrapping_mul(2).wrapping_add(1),
                        r.wrapping_mul(2).wrapping_add(1),
                    ),
                }
            }
            // C4FO_ID
            20 => match data.get(1) {
                Some(Value::C4Id(id)) => FindCondition::Id(cast_c4id_payload(id)),
                Some(Value::String(id)) => FindCondition::Id(clonk_script::c4_id_parse(id)),
                _ => return ParsedCriterion::None,
            },
            // C4FO_OCF
            21 => FindCondition::Ocf(arg_i32(1) as u32),
            // C4FO_Category
            22 => FindCondition::Category(arg_i32(1)),
            // C4FO_Action
            30 => match data.get(1) {
                Some(Value::String(name)) => {
                    FindCondition::Action(name.as_ref().to_owned())
                }
                _ => return ParsedCriterion::None,
            },
            // C4FO_ActionTarget (index clamped to 0..=1, C4FindObject.cpp:138-144)
            31 => FindCondition::ActionTarget {
                target: data.get(1).and_then(value_as_object_id),
                index: arg_i32(2).clamp(0, 1) as usize,
            },
            // C4FO_Container
            40 => FindCondition::Container(data.get(1).and_then(value_as_object_id)),
            // C4FO_AnyContainer
            41 => FindCondition::AnyContainer,
            // C4FO_Owner
            50 => FindCondition::Owner(arg_i32(1)),
            // C4FO_Controller
            51 => FindCondition::Controller(arg_i32(1)),
            // C4FO_Func: Data[1] must convert to a string, else the whole
            // criterion is dropped (C4FindObject.cpp:127-128); Data[2] →
            // par 0, capped at 10 pars (SetPar, C4FindObject.cpp:645-651)
            60 => match data.get(1) {
                Some(Value::String(name)) => FindCondition::Func {
                    name: name.as_ref().to_owned(),
                    pars: data.iter().skip(2).take(10).cloned().collect(),
                },
                _ => return ParsedCriterion::None,
            },
            // C4FO_Layer: Data[1].getObj(), nil = the unlayered world
            // (C4FindObject.cpp:157-159).
            70 => FindCondition::Layer(data.get(1).and_then(value_as_object_id)),
            _ => return ParsedCriterion::None,
        };
        ParsedCriterion::Condition(condition)
    }

    /// Per-condition Check (C4FindObject.cpp:390-679). Fallible because a
    /// `Func` callback error passes through (`fPassErrors=true`,
    /// C4FindObject.cpp:661); And/Or evaluate children in array order with
    /// short-circuit, so Func side effects land in C++ order.
    fn check(
        &self,
        world: &impl WorldAccessor,
        object: &HostWorldObject,
    ) -> Result<bool, RuntimeError> {
        // Every C++ node dereferences the same live C4Object pointer. An
        // earlier Func sibling (or an earlier candidate's callback) may
        // have changed any field, so never retain the driver's clone across
        // a condition boundary. A vanished pending preview falls back to the
        // pointer-equivalent clone for the remainder of the current Check.
        let refreshed = world.get_object(object.id);
        let object = refreshed.as_ref().unwrap_or(object);
        Ok(match self {
            FindCondition::Not(child) => !child.check(world, object)?,
            FindCondition::And(children) => {
                for child in children {
                    if !child.check(world, object)? {
                        return Ok(false);
                    }
                }
                true
            }
            FindCondition::Or(children) => {
                for child in children {
                    if child.check(world, object)? {
                        return Ok(true);
                    }
                }
                false
            }
            FindCondition::Exclude(excluded) => Some(object.id) != *excluded,
            FindCondition::Id(id) => clonk_script::c4_id_parse(object.definition_id()) == *id,
            FindCondition::InRect(rect) => {
                // C4FindObjectInRect::Check is a plain point-in-rect on the
                // object CENTER (C4FindObject.cpp) — the old
                // contains_offset(pos - rect.xy) clause double-subtracted
                // the origin and matched far-away objects whose offset
                // happened to land back inside (the 597 NoDmg class).
                let position = object.position();
                position.x >= rect.x
                    && position.x < rect.x + rect.width
                    && position.y >= rect.y
                    && position.y < rect.y + rect.height
            }
            FindCondition::AtPoint(x, y) => {
                rect_contains_point_cpp(world.object_live_shape_rect(object), *x, *y)
            }
            FindCondition::AtRect(rect) => {
                rects_overlap_cpp(world.object_live_shape_rect(object), *rect)
            }
            FindCondition::OnLine(x1, y1, x2, y2) => {
                rect_intersects_line_cpp(world.object_live_shape_rect(object), *x1, *y1, *x2, *y2)
            }
            FindCondition::Distance { x, y, r2, .. } => {
                let position = object.position();
                let dx = i64::from(position.x - x);
                let dy = i64::from(position.y - y);
                dx * dx + dy * dy <= *r2
            }
            FindCondition::Ocf(mask) => object.ocf() & mask != 0,
            FindCondition::Category(category) => object.category() & category != 0,
            FindCondition::Action(name) => object.action_name() == name,
            FindCondition::ActionTarget { target, index } => {
                object.action_target(*index) == *target
            }
            FindCondition::Container(container) => object.container() == *container,
            FindCondition::AnyContainer => object.container().is_some(),
            FindCondition::Owner(owner) => object.owner() == *owner,
            // C4FindObjectController::Check (C4FindObject.cpp:628-631).
            FindCondition::Controller(controller) => object.controller() == *controller,
            // C4FindObjectFunc::Check (C4FindObject.cpp:653-662): no
            // overload visible to the object's def → silently false; the
            // result converts with raw C4Value truthiness, not getBool.
            FindCondition::Func { name, pars } => {
                let pars = live_find_callback_parameters(pars);
                match call_world_object_function(object.id, name, &pars) {
                    None => false,
                    Some(result) => value_raw_truthy(&result?),
                }
            }
            // C4FindObjectLayer::Check (C4FindObject.cpp:671-674).
            FindCondition::Layer(layer) => {
                object.full_state().and_then(|state| state.layer) == *layer
            }
        })
    }

    /// IsImpossible/IsEnsured pruning (C4FindObject.cpp:453-590). `Func` is
    /// impossible only when the name is unknown to every script
    /// (GetFirstFunc miss at construction, C4FindObject.cpp:640-643,
    /// 664-667); Not swaps the two (C4FindObject.h:116-117).
    fn is_impossible(&self, world: &impl WorldAccessor) -> bool {
        match self {
            FindCondition::Not(child) => child.is_ensured(world),
            FindCondition::And(children) => children.iter().any(|child| child.is_impossible(world)),
            FindCondition::Or(children) => {
                !children.iter().any(|child| !child.is_impossible(world))
            }
            FindCondition::InRect(rect) => rect.width == 0 || rect.height == 0,
            FindCondition::Ocf(mask) => *mask == 0,
            FindCondition::Func { name, .. } => !world.script_function_known(name),
            _ => false,
        }
    }

    fn is_ensured(&self, world: &impl WorldAccessor) -> bool {
        match self {
            FindCondition::Not(child) => child.is_impossible(world),
            // C4FindObjectAnd::IsEnsured is `!iCnt` AFTER the constructor
            // filtered ensured children (C4FindObject.h:135) — recursively:
            // ensured iff every child is.
            FindCondition::And(children) => children.iter().all(|child| child.is_ensured(world)),
            // C4FindObjectOr::IsEnsured (C4FindObject.cpp:514-520)
            FindCondition::Or(children) => children.iter().any(|child| child.is_ensured(world)),
            FindCondition::Category(category) => *category == 0,
            _ => false,
        }
    }

    /// The construction-time pruning of C4FindObjectAnd/Or
    /// (C4FindObject.cpp:400-410, 466-476), bottom-up like CreateByValue:
    /// And drops ensured children (whose Check may still be false —
    /// Category(0), C4FindObject.cpp:582-590), Or drops impossible ones
    /// (which would otherwise kill the sibling bounds). The drivers prune
    /// once before Check/bounds/IsImpossible run, matching the C++ tree.
    fn pruned(self, world: &impl WorldAccessor) -> FindCondition {
        match self {
            FindCondition::Not(child) => FindCondition::Not(Box::new(child.pruned(world))),
            FindCondition::And(children) => FindCondition::And(
                children
                    .into_iter()
                    .map(|child| child.pruned(world))
                    .filter(|child| !child.is_ensured(world))
                    .collect(),
            ),
            FindCondition::Or(children) => FindCondition::Or(
                children
                    .into_iter()
                    .map(|child| child.pruned(world))
                    .filter(|child| !child.is_impossible(world))
                    .collect(),
            ),
            other => other,
        }
    }

    /// GetBounds + UseShapes (C4FindObject.h:93-94): `Some((rect, shapes))`
    /// when the criteria bound the search area — the drivers then walk the
    /// sector lists (shape lists when `shapes`) instead of the master list.
    fn bounds(&self) -> Option<(DefinitionRect, bool)> {
        match self {
            // C4FindObjectAnd constructor (C4FindObject.cpp:411-434): a
            // bounded shapes child wins outright ("some objects might be in
            // an rect and at a point not in that rect"); otherwise all
            // bounded children intersect.
            FindCondition::And(children) => {
                let mut bounds: Option<DefinitionRect> = None;
                for child in children {
                    if let Some((child_bounds, child_shapes)) = child.bounds() {
                        if child_shapes {
                            return Some((child_bounds, true));
                        }
                        bounds = Some(match bounds {
                            Some(rect) => rect_intersect_cpp(rect, child_bounds),
                            None => child_bounds,
                        });
                    }
                }
                bounds.map(|rect| (rect, false))
            }
            // C4FindObjectOr constructor (C4FindObject.cpp:477-496): the
            // union of all child bounds; a boundless or shapes child (which
            // could report an object twice) kills the bounds entirely.
            FindCondition::Or(children) => {
                let mut bounds: Option<DefinitionRect> = None;
                for child in children {
                    match child.bounds() {
                        None | Some((_, true)) => return None,
                        Some((child_bounds, false)) => {
                            bounds = Some(match bounds {
                                Some(rect) => rect_add_cpp(rect, child_bounds),
                                None => child_bounds,
                            });
                        }
                    }
                }
                bounds.map(|rect| (rect, false))
            }
            FindCondition::InRect(rect) => Some((*rect, false)),
            FindCondition::AtPoint(x, y) => Some((DefinitionRect::new(*x, *y, 1, 1), true)),
            FindCondition::AtRect(rect) => Some((*rect, true)),
            // bounds(x, y, 1, 1) + Add((x2, y2, 1, 1)), C4FindObject.h:234-237
            FindCondition::OnLine(x1, y1, x2, y2) => Some((
                rect_add_cpp(
                    DefinitionRect::new(*x1, *y1, 1, 1),
                    DefinitionRect::new(*x2, *y2, 1, 1),
                ),
                true,
            )),
            FindCondition::Distance { bounds, .. } => Some((*bounds, false)),
            _ => None,
        }
    }

    /// Whether any node needs the nested-call seam (drives the borrow-free
    /// live-view evaluation path in the drivers).
    fn uses_func(&self) -> bool {
        match self {
            FindCondition::Not(child) => child.uses_func(),
            FindCondition::And(children) | FindCondition::Or(children) => {
                children.iter().any(FindCondition::uses_func)
            }
            FindCondition::Func { .. } => true,
            _ => false,
        }
    }
}

/// C4Rect::Intersect (C4Rect.cpp:101-133): narrow `a` to the overlap with
/// `b`; a degenerated result clamps to zero size.
fn rect_intersect_cpp(a: DefinitionRect, b: DefinitionRect) -> DefinitionRect {
    let mut result = a;
    if b.x > result.x {
        if b.x + b.width < result.x + result.width {
            result.x = b.x;
            result.width = b.width;
        } else {
            result.width -= b.x - result.x;
            result.x = b.x;
        }
    } else if b.x + b.width < result.x + result.width {
        result.width = b.x + b.width - result.x;
    }
    if b.y > result.y {
        if b.y + b.height < result.y + result.height {
            result.y = b.y;
            result.height = b.height;
        } else {
            result.height -= b.y - result.y;
            result.y = b.y;
        }
    } else if b.y + b.height < result.y + result.height {
        result.height = b.y + b.height - result.y;
    }
    result.width = result.width.max(0);
    result.height = result.height.max(0);
    result
}

/// C4Rect::Add (C4Rect.cpp:153-185): expand `a` to cover `b`; a null rect
/// on either side leaves the other unchanged.
fn rect_add_cpp(a: DefinitionRect, b: DefinitionRect) -> DefinitionRect {
    if b.width == 0 || b.height == 0 {
        return a;
    }
    if a.width == 0 || a.height == 0 {
        return b;
    }
    let mut result = a;
    if b.x < result.x {
        if b.x + b.width > result.x + result.width {
            result.x = b.x;
            result.width = b.width;
        } else {
            result.width += result.x - b.x;
            result.x = b.x;
        }
    } else if b.x + b.width > result.x + result.width {
        result.width = b.x + b.width - result.x;
    }
    if b.y < result.y {
        if b.y + b.height > result.y + result.height {
            result.y = b.y;
            result.height = b.height;
        } else {
            result.height += result.y - b.y;
            result.y = b.y;
        }
    } else if b.y + b.height > result.y + result.height {
        result.height = b.y + b.height - result.y;
    }
    result
}

/// Raw `C4Rect::Contains`; unlike the convenience `DefinitionRect` methods,
/// this preserves C++ behavior for zero/negative dimensions accepted by
/// `SetShape` and its wrapping `int32_t` edge arithmetic.
fn rect_contains_point_cpp(rect: DefinitionRect, x: i32, y: i32) -> bool {
    x >= rect.x
        && x < rect.x.wrapping_add(rect.width)
        && y >= rect.y
        && y < rect.y.wrapping_add(rect.height)
}

/// Raw `C4Rect::Overlap` (C4Rect.cpp:92-99).
fn rects_overlap_cpp(a: DefinitionRect, b: DefinitionRect) -> bool {
    a.x.wrapping_add(a.width) > b.x
        && a.x < b.x.wrapping_add(b.width)
        && a.y.wrapping_add(a.height) > b.y
        && a.y < b.y.wrapping_add(b.height)
}

/// Literal integer-edge port of `C4Rect::IntersectsLine`
/// (C4Rect.cpp:131-155). In particular this is not a rasterized line walk:
/// the native two edge probes and truncating divisions can accept a segment
/// that never visits an integer point inside the rectangle.
fn rect_intersects_line_cpp(rect: DefinitionRect, x1: i32, y1: i32, x2: i32, y2: i32) -> bool {
    if rect_contains_point_cpp(rect, x1, y1) || rect_contains_point_cpp(rect, x2, y2) {
        return true;
    }
    let right = rect.x.wrapping_add(rect.width);
    let bottom = rect.y.wrapping_add(rect.height);
    if (x1 < rect.x && x2 < rect.x)
        || (y1 < rect.y && y2 < rect.y)
        || (x1 >= right && x2 >= right)
        || (y1 >= bottom && y2 >= bottom)
    {
        return false;
    }
    if x1 == x2 || y1 == y2 {
        return true;
    }

    let intersect_x = if x1 < rect.x { rect.x } else { right };
    let intersect_y = y1.wrapping_add(
        y2.wrapping_sub(y1)
            .wrapping_mul(intersect_x.wrapping_sub(x1))
            .wrapping_div(x2.wrapping_sub(x1)),
    );
    if intersect_y >= rect.y && intersect_y < bottom {
        return true;
    }

    let intersect_y = if y1 < rect.y { rect.y } else { bottom };
    let intersect_x = x1.wrapping_add(
        x2.wrapping_sub(x1)
            .wrapping_mul(intersect_y.wrapping_sub(y1))
            .wrapping_div(y2.wrapping_sub(y1)),
    );
    intersect_x >= rect.x && intersect_x < right
}

impl SortCriterion {
    /// `C4SortObject::CreateByValue` (C4FindObject.cpp:683-758).
    fn parse_typed(kind: i32, data: &[Value]) -> Option<SortCriterion> {
        let arg_i32 = |index: usize| data.get(index).map(value_as_i32).unwrap_or(0);
        Some(match kind {
            // C4SO_Reverse
            101 => SortCriterion::Reverse(Box::new(data.get(1).and_then(Self::parse)?)),
            // C4SO_Multiple (trivial single unwrap, C4FindObject.cpp:705-726)
            102 => {
                let children: Vec<SortCriterion> =
                    data[1..].iter().filter_map(Self::parse).collect();
                if data.len() == 2 {
                    children.into_iter().next()?
                } else {
                    SortCriterion::Multiple(children)
                }
            }
            // C4SO_Distance
            110 => SortCriterion::Distance {
                x: arg_i32(1),
                y: arg_i32(2),
            },
            // C4SO_Random
            120 => SortCriterion::Random,
            // C4SO_Speed
            130 => SortCriterion::Speed,
            // C4SO_Mass
            140 => SortCriterion::Mass,
            // C4SO_Value
            150 => SortCriterion::Value,
            // C4SO_Func: string name required, else nullptr
            // (C4FindObject.cpp:743-755); pars capped at 10
            160 => match data.get(1) {
                Some(Value::String(name)) => SortCriterion::Func {
                    name: name.as_ref().to_owned(),
                    pars: data.iter().skip(2).take(10).cloned().collect(),
                },
                _ => return None,
            },
            _ => return None,
        })
    }

    /// Whether any node needs the nested-call seam.
    fn uses_func(&self) -> bool {
        match self {
            SortCriterion::Reverse(child) => child.uses_func(),
            SortCriterion::Multiple(children) => children.iter().any(SortCriterion::uses_func),
            // C4SO_Value calls C4Object::GetValue, which may dispatch the
            // definition's CalcValue script just like C4SO_Func.
            SortCriterion::Value | SortCriterion::Func { .. } => true,
            _ => false,
        }
    }

    fn parse(value: &Value) -> Option<SortCriterion> {
        let Value::Array(data) = value else {
            return None;
        };
        Self::parse_typed(data.first().map(value_as_i32).unwrap_or(0), data)
    }

    /// `CompareGetValue` (C4FindObject.cpp:908-956). `Random` draws the
    /// synced `Random(1 << 16)` — exactly once per object, in collection
    /// order, via the cache (C4SortObjectByValue::PrepareCache). `Func`
    /// runs the nested call: no overload → 0 silently, the result converts
    /// with `getInt()` (bools 0/1, pointer types 0), and callback errors
    /// pass through (`fPassErrors=true`, C4FindObject.cpp:947-956).
    fn value_for(
        &self,
        world: &impl WorldAccessor,
        object: &HostWorldObject,
    ) -> Result<i64, RuntimeError> {
        // CompareGetValue dereferences the live pointer for every criterion.
        // In particular, Multiple prepares one complete cache at a time, so
        // a Func cache may mutate fields consumed by the next cache.
        let refreshed = world.get_object(object.id);
        let object = refreshed.as_ref().unwrap_or(object);
        Ok(match self {
            SortCriterion::Distance { x, y } => {
                let position = object.position();
                let dx = position.x.wrapping_sub(*x);
                let dy = position.y.wrapping_sub(*y);
                // int32 wrap like C4SortObjectDistance
                // (C4FindObject.cpp:908-911, CompareGetValue is int32_t).
                i64::from(dx.wrapping_mul(dx).wrapping_add(dy.wrapping_mul(dy)))
            }
            SortCriterion::Random => RANDOM_CONTEXT.with(|cell| {
                cell.borrow()
                    .as_ref()
                    .map(|context| i64::from(context.rng.borrow_mut().random(1 << 16)))
                    .unwrap_or(0)
            }),
            SortCriterion::Speed => {
                // C4SortObjectSpeed's C4Fixed sum reaches int32_t through
                // the IMPLICIT `operator bool` (Fixed.h:117, the only
                // conversion C4Fixed offers): the key is 0/1 "moving at
                // all". The fixed squares truncate (val²/65536), so raw
                // |dir| < 256 keys 0 too. Live fixed dirs come from the
                // script-call snapshot; the int-mirror fallback only
                // misses sub-1/256-px movers.
                let (vx, vy) = object
                    .full_state()
                    .and_then(|state| state.script_fixed_velocity)
                    .map(|fixed| (fixed.x.val(), fixed.y.val()))
                    .unwrap_or_else(|| {
                        let velocity = object.velocity();
                        (
                            velocity.x.wrapping_mul(1 << 16),
                            velocity.y.wrapping_mul(1 << 16),
                        )
                    });
                let square = |v: i32| ((i64::from(v) * i64::from(v)) / (1 << 16)) as i32;
                i64::from(square(vx).wrapping_add(square(vy)) != 0)
            }
            SortCriterion::Mass => {
                // pFor->Mass is the LIVE UpdateMass field, including
                // contents unless NoComponentMass (C4Object.cpp:497-505).
                i64::from(sort_object_mass(world, object.id))
            }
            SortCriterion::Value => i64::from(
                get_value(&[
                    object_reference_value(object.id),
                    Value::Nil,
                    Value::Nil,
                    Value::Int(OWNER_NONE),
                ])?
                .as_c4_int()
                .unwrap_or(0),
            ),
            SortCriterion::Func { name, pars } => {
                let pars = live_find_callback_parameters(pars);
                match call_world_object_function(object.id, name, &pars) {
                    None => 0,
                    Some(result) => i64::from(result?.as_c4_int().unwrap_or(0)),
                }
            }
            SortCriterion::Reverse(_) | SortCriterion::Multiple(_) => 0,
        })
    }

    /// `C4SortObject::SortObjects` (C4FindObject.cpp:784-812): per-criterion
    /// value caches computed in collection order, then a stable sort with
    /// `Compare > 0` ⇒ ascending by value (smallest first).
    fn sort(&self, world: &impl WorldAccessor, ids: &mut [ObjectId]) -> Result<(), RuntimeError> {
        let keys = self.cache_keys(world, ids)?;
        let mut order: Vec<usize> = (0..ids.len()).collect();
        order.sort_by(|&a, &b| Self::compare_keys(&keys[a], &keys[b]));
        let sorted: Vec<ObjectId> = order.iter().map(|&index| ids[index]).collect();
        ids.copy_from_slice(&sorted);
        Ok(())
    }

    /// Per-object key vectors: flattened (criterion, direction) values so
    /// Reverse/Multiple compose like the C++ Compare chain.
    fn cache_keys(
        &self,
        world: &impl WorldAccessor,
        ids: &[ObjectId],
    ) -> Result<Vec<Vec<i64>>, RuntimeError> {
        let mut keys = vec![Vec::new(); ids.len()];
        self.fill_keys(world, ids, &mut keys, false)?;
        Ok(keys)
    }

    fn fill_keys(
        &self,
        world: &impl WorldAccessor,
        ids: &[ObjectId],
        keys: &mut [Vec<i64>],
        reverse: bool,
    ) -> Result<(), RuntimeError> {
        match self {
            SortCriterion::Reverse(child) => child.fill_keys(world, ids, keys, !reverse)?,
            SortCriterion::Multiple(children) => {
                for child in children {
                    child.fill_keys(world, ids, keys, reverse)?;
                }
            }
            _ => {
                let sign = if reverse { -1 } else { 1 };
                for (index, id) in ids.iter().enumerate() {
                    let value = match world.get_object(*id) {
                        Some(object) => self.value_for(world, &object)?,
                        None => 0,
                    };
                    keys[index].push(sign * value);
                }
            }
        }
        Ok(())
    }

    fn compare_keys(a: &[i64], b: &[i64]) -> std::cmp::Ordering {
        for (lhs, rhs) in a.iter().zip(b.iter()) {
            match lhs.cmp(rhs) {
                std::cmp::Ordering::Equal => continue,
                other => return other,
            }
        }
        std::cmp::Ordering::Equal
    }

    /// The UNCACHED `Compare(obj1, obj2)` used by the single-result Find
    /// path (C4FindObject.cpp:834-842): `CompareGetValue` runs for obj1
    /// then obj2 in hardcoded order, returning `value2 - value1` (>0 ⇒
    /// obj1 sorts first). Reverse swaps the arguments
    /// (C4FindObject.cpp:856-859); Multiple returns the first nonzero
    /// child comparison (C4FindObject.cpp:885-895).
    fn compare_uncached(
        &self,
        world: &impl WorldAccessor,
        obj1: &HostWorldObject,
        obj2: &HostWorldObject,
    ) -> Result<i64, RuntimeError> {
        match self {
            SortCriterion::Reverse(child) => child.compare_uncached(world, obj2, obj1),
            SortCriterion::Multiple(children) => {
                for child in children {
                    let result = child.compare_uncached(world, obj1, obj2)?;
                    if result != 0 {
                        return Ok(result);
                    }
                }
                Ok(0)
            }
            _ => {
                let value1 = self.value_for(world, obj1)?;
                let value2 = self.value_for(world, obj2)?;
                Ok(value2 - value1)
            }
        }
    }

    fn compare_uncached_ids(
        &self,
        world: &impl WorldAccessor,
        obj1: ObjectId,
        obj2: ObjectId,
    ) -> Result<i64, RuntimeError> {
        let Some(obj1) = world.get_object(obj1) else {
            return Ok(0);
        };
        let Some(obj2) = world.get_object(obj2) else {
            return Ok(0);
        };
        self.compare_uncached(world, &obj1, &obj2)
    }
}

/// The single-result Find with a sort attached (C4FindObject.cpp:272-308).
/// Bounded criteria walk the per-sector lists: the inner
/// `Find(*pLst)` (C4FindObject.cpp:186-199) keeps a running best PER LIST
/// — replaced when the uncached `Compare(candidate, best)` is positive —
/// and only each list's winner meets the outer running best
/// (C4FindObject.cpp:287-293/299-305). The unbounded walk is the
/// single-list case. No PrepareCache — value functions (and `C4SO_Random`
/// draws) run per comparison, so the pairing is lockstep-relevant. The
/// UseShapes lists carry no Marker: a shape spanning sectors is compared
/// in every list holding it.
fn find_first_with_sort(
    world: &impl WorldAccessor,
    condition: &FindCondition,
    sort: &SortCriterion,
) -> Result<Option<ObjectId>, RuntimeError> {
    if condition.is_impossible(world) {
        return Ok(None);
    }
    let lists = condition
        .bounds()
        .and_then(|(rect, use_shapes)| {
            if use_shapes {
                world.shape_sector_id_lists_in_rect(rect)
            } else {
                world.object_sector_id_lists_in_rect(rect)
            }
        })
        .unwrap_or_else(|| vec![world.object_ids()]);
    let mut best: Option<ObjectId> = None;
    for ids in lists {
        // inner Find(*pLst): the per-list best
        let mut list_best: Option<ObjectId> = None;
        for object_id in ids {
            let Some(object) = world.get_object(object_id) else {
                continue;
            };
            if !object.status().is_active() {
                continue;
            }
            if !condition.check(world, &object)? {
                continue;
            }
            // C4FindObject::Find rechecks Status after Check. Inactive is
            // nonzero in C++ and therefore still eligible here; only a
            // completed AssignRemoval is rejected.
            if !object_present_after_callback(world, object_id) {
                continue;
            }
            list_best = match list_best {
                None => Some(object_id),
                Some(best_id) => {
                    if sort.compare_uncached_ids(world, object_id, best_id)? > 0
                        && object_present_after_callback(world, object_id)
                    {
                        Some(object_id)
                    } else {
                        Some(best_id)
                    }
                }
            };
        }
        // outer walk: the list winner vs the running best
        if let Some(list_id) = list_best {
            best = match best {
                None => object_present_after_callback(world, list_id).then_some(list_id),
                Some(best_id) => {
                    if sort.compare_uncached_ids(world, list_id, best_id)? > 0
                        && object_present_after_callback(world, list_id)
                    {
                        Some(list_id)
                    } else {
                        Some(best_id)
                    }
                }
            };
        }
    }
    Ok(best)
}

/// `CreateCriterionsFromPars` (C4Script.cpp:1985-2034): each argument array
/// parses as a condition or sort; conditions AND together, sorts merge into
/// a Multiple; no conditions at all is a script error.
fn parse_criterions(args: &[Value]) -> Option<(FindCondition, Option<SortCriterion>)> {
    let mut conditions = Vec::new();
    let mut sorts = Vec::new();
    for arg in args.iter().take(10) {
        // The first raw-falsy parameter ends the criteria list
        // (`if (!Data) break;`, C4Script.cpp:1996).
        if !arg.as_bool() {
            break;
        }
        match FindCondition::parse(arg) {
            ParsedCriterion::Condition(condition) => conditions.push(condition),
            ParsedCriterion::Sort(sort) => sorts.push(sort),
            ParsedCriterion::None => {}
        }
    }
    if conditions.is_empty() {
        return None;
    }
    let condition = if conditions.len() == 1 {
        conditions.into_iter().next().expect("one condition")
    } else {
        FindCondition::And(conditions)
    };
    let sort = match sorts.len() {
        0 => None,
        1 => sorts.into_iter().next(),
        _ => Some(SortCriterion::Multiple(sorts)),
    };
    Some((condition, sort))
}

/// FindObject2/ObjectCount2 declare all ten native parameters as C4V_Array.
/// C4Aul validates every slot before CreateCriterionsFromPars scans for its
/// first falsy terminator; pre-strict-3 callers first normalize falsy values
/// to nil, while strict-3 callers retain their concrete types.
fn validate_array_criterion_args(function: &str, args: &[Value]) -> Result<(), RuntimeError> {
    let strict_nil = matches!(
        clonk_script::caller_origin_strictness(),
        clonk_script::HostCallerStrictness::Strict(level) if level >= 3
    );
    for (index, arg) in args.iter().take(10).enumerate() {
        let canonical_nil = matches!(arg, Value::Nil | Value::Object(0))
            || matches!(arg, Value::C4Id(id) if cast_c4id_payload(id) == 0);
        let converted = if canonical_nil || (!strict_nil && !arg.as_bool()) {
            Value::Nil.convert_to(clonk_script::C4VType::Array, true)
        } else {
            arg.convert_to(clonk_script::C4VType::Array, true)
        };
        if !converted {
            return Err(RuntimeError::new(format!(
                "call to \"{function}\" parameter {}: got \"{}\", but expected \"array\"!",
                index + 1,
                arg.type_name()
            )));
        }
    }
    Ok(())
}

/// The C++ bounded-vs-full walk decision (C4FindObject.cpp:315-328):
/// criteria bounds pick the sector walk — the ObjectShapes lists (with
/// first-encounter dedup standing in for the Marker) when the criteria use
/// shapes, the per-sector point lists otherwise. Boundless criteria — or a
/// world without a sector map (legacy fixture contexts) — walk the master
/// list.
fn find_candidate_ids(world: &impl WorldAccessor, condition: &FindCondition) -> Vec<ObjectId> {
    condition
        .bounds()
        .and_then(|(rect, use_shapes)| {
            if use_shapes {
                world.shape_sector_ids_in_rect(rect)
            } else {
                world.object_sector_ids_in_rect(rect)
            }
        })
        .unwrap_or_else(|| world.object_ids())
}

/// Collect matches in C++ walk order (C4FindObject::FindMany,
/// C4FindObject.cpp:203-226 unbounded, :310-355 sector-bounded).
fn find_condition_matches(
    world: &impl WorldAccessor,
    condition: &FindCondition,
) -> Result<Vec<ObjectId>, RuntimeError> {
    if condition.is_impossible(world) {
        return Ok(Vec::new());
    }
    let mut matches = Vec::new();
    for object_id in find_candidate_ids(world, condition) {
        let Some(object) = world.get_object(object_id) else {
            continue;
        };
        if !object.status().is_active() {
            continue;
        }
        if condition.check(world, &object)? {
            matches.push(object_id);
        }
    }
    Ok(matches)
}

/// Unsorted `C4FindObject::Find` stops immediately after the first matching
/// object whose Status survived its callback. This is observably different
/// from collecting a FindMany result when later predicates have side effects.
fn find_first_condition_match(
    world: &impl WorldAccessor,
    condition: &FindCondition,
) -> Result<Option<ObjectId>, RuntimeError> {
    if condition.is_impossible(world) {
        return Ok(None);
    }
    for object_id in find_candidate_ids(world, condition) {
        let Some(object) = world.get_object(object_id) else {
            continue;
        };
        if !object.status().is_active() {
            continue;
        }
        if condition.check(world, &object)? && object_present_after_callback(world, object_id) {
            return Ok(Some(object_id));
        }
    }
    Ok(None)
}

/// Whether the criteria need the reentrant live-view evaluation path.
fn criterions_use_func(condition: &FindCondition, sort: Option<&SortCriterion>) -> bool {
    condition.uses_func() || sort.map(SortCriterion::uses_func).unwrap_or(false)
}

/// FnFindObject2 (C4Script.cpp:2052-2067).
fn find_object2(args: &[Value]) -> Result<Value, RuntimeError> {
    validate_array_criterion_args("FindObject2", args)?;
    let Some((condition, sort)) = parse_criterions(args) else {
        return Err(RuntimeError::new(
            "FindObject: No valid search criterions supplied!",
        ));
    };
    if criterions_use_func(&condition, sort.as_ref()) {
        let Some(view) = LiveFuncFindView::new() else {
            return Ok(Value::Nil);
        };
        let condition = condition.pruned(&view);
        if let Some(sort) = sort {
            return Ok(find_first_with_sort(&view, &condition, &sort)?
                .map(object_reference_value)
                .unwrap_or(Value::Nil));
        }
        return Ok(find_first_condition_match(&view, &condition)?
            .map(object_reference_value)
            .unwrap_or(Value::Nil));
    }
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let condition = condition.pruned(context);
        if let Some(sort) = sort {
            return Ok(find_first_with_sort(context, &condition, &sort)?
                .map(object_reference_value)
                .unwrap_or(Value::Nil));
        }
        Ok(find_first_condition_match(context, &condition)?
            .map(object_reference_value)
            .unwrap_or(Value::Nil))
    })
}

/// FnFindObjects array form (C4Script.cpp:2069-2084).
fn find_objects2(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some((condition, sort)) = parse_criterions(args) else {
        return Err(RuntimeError::new(
            "FindObjects: No valid search criterions supplied!",
        ));
    };
    if criterions_use_func(&condition, sort.as_ref()) {
        let Some(view) = LiveFuncFindView::new() else {
            return Ok(Value::Array(Vec::new()));
        };
        let condition = condition.pruned(&view);
        let mut matches = find_condition_matches(&view, &condition)?;
        // Pre-sort: erase objects deleted during Check
        // (C4FindObject.cpp:217-218).
        retain_present_after_callback(&view, &mut matches);
        if let Some(sort) = sort {
            sort.sort(&view, &mut matches)?;
            // Post-sort: objects deleted by sort callbacks keep their slot
            // as nil (CheckObjectStatusAfterSort, C4FindObject.cpp:223,
            // 372-375). Inactive remains a non-null object.
            return Ok(Value::Array(
                matches
                    .into_iter()
                    .map(|id| {
                        if object_present_after_callback(&view, id) {
                            object_reference_value(id)
                        } else {
                            Value::Nil
                        }
                    })
                    .collect(),
            ));
        }
        return Ok(Value::Array(
            matches.into_iter().map(object_reference_value).collect(),
        ));
    }
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Array(Vec::new()));
        };
        let condition = condition.pruned(context);
        let mut matches = find_condition_matches(context, &condition)?;
        if let Some(sort) = sort {
            sort.sort(context, &mut matches)?;
        }
        Ok(Value::Array(
            matches.into_iter().map(object_reference_value).collect(),
        ))
    })
}

/// FnObjectCount2 (C4Script.cpp:2036-2050).
fn object_count2(args: &[Value]) -> Result<Value, RuntimeError> {
    validate_array_criterion_args("ObjectCount2", args)?;
    let Some((condition, _)) = parse_criterions(args) else {
        return Err(RuntimeError::new(
            "ObjectCount: No valid search criterions supplied!",
        ));
    };
    if criterions_use_func(&condition, None) {
        let Some(view) = LiveFuncFindView::new() else {
            return Ok(Value::Int(0));
        };
        let condition = condition.pruned(&view);
        if condition.is_ensured(&view) {
            let count = view
                .master_object_ids()
                .into_iter()
                .filter(|id| {
                    view.get_object(*id)
                        .is_some_and(|object| object.status().is_active())
                })
                .count();
            return Ok(Value::Int(truncate_to_i32(count as u64)));
        }
        let matches = find_condition_matches(&view, &condition)?;
        return Ok(Value::Int(truncate_to_i32(matches.len() as u64)));
    }
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Int(0));
        };
        let condition = condition.pruned(context);
        if condition.is_ensured(context) {
            let count = context
                .master_object_ids()
                .into_iter()
                .filter(|id| {
                    context
                        .get_world_object(*id)
                        .is_some_and(|object| object.status().is_active())
                })
                .count();
            return Ok(Value::Int(truncate_to_i32(count as u64)));
        }
        Ok(Value::Int(truncate_to_i32(
            find_condition_matches(context, &condition)?.len() as u64,
        )))
    })
}

fn find_object(args: &[Value]) -> Result<Value, RuntimeError> {
    find_object_cpp(args, "FindObject", None)
}

/// FnFindBase/C4Game::FindBase (C4Script.cpp:1976-1979;
/// C4Game.cpp:3732-3744): validate the player, then walk the active object
/// master list and return the indexed object whose stored Base matches.
fn find_base(args: &[Value]) -> Result<Value, RuntimeError> {
    let player = value_to_i32(args.first().unwrap_or(&Value::Nil), "FindBase", "player")?;
    let mut index = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "FindBase", "index")?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        if context.player_state(player).is_none() || index < 0 {
            return Ok(Value::Nil);
        }
        for object_id in context.master_object_ids() {
            let Some(object) = context.get_world_object(object_id) else {
                continue;
            };
            if !object.status().is_active()
                || object.full_state().map(|state| state.base) != Some(player)
            {
                continue;
            }
            if index == 0 {
                return Ok(object_reference_value(object_id));
            }
            index -= 1;
        }
        Ok(Value::Nil)
    })
}

/// Shared FnFindObject search (C4Script.cpp:2113-2135) with an optional
/// owner filter injected by FindObjectOwner (C4Script.cpp:2137-2161).
fn find_object_cpp(
    args: &[Value],
    function: &str,
    owner_override: Option<i32>,
) -> Result<Value, RuntimeError> {
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };
        let mut params = FindObjectParams::parse_cpp_call(args, function, context.caller_scope())?;
        if let Some(owner) = owner_override {
            params.owner = owner;
        }
        let result = if params.is_closest_query() {
            find_object_closest(context, &params)
        } else {
            find_object_linear(context, &params)
        };
        Ok(match result {
            Some(id) => object_reference_value(id),
            None => Value::Nil,
        })
    })
}

fn find_object_owner(args: &[Value]) -> Result<Value, RuntimeError> {
    // FnFindObjectOwner (C4Script.cpp:2137-2161): FindObject with the
    // owner filter as the SECOND parameter; an owner that is neither a
    // valid player nor NO_OWNER returns nil before any search. The
    // remaining arguments shift by one; exclude/container are not
    // script-settable here (C++ passes caller-exclusion and null).
    if args.len() > 10 {
        return Err(RuntimeError::new(
            "FindObjectOwner: expected at most 10 arguments",
        ));
    }
    let definition = parse_native_c4id_argument(args.first(), "FindObjectOwner")?;
    let owner = parse_optional_i32(args.get(1), "FindObjectOwner", "owner")?.unwrap_or(0);
    let owner_valid = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        borrow
            .as_ref()
            .map(|context| owner == OWNER_NONE || context.player_state(owner).is_some())
            .unwrap_or(false)
    });
    if !owner_valid {
        return Ok(Value::Nil);
    }
    let mut remapped: Vec<Value> = Vec::with_capacity(10);
    remapped.push(definition.map(Value::C4Id).unwrap_or(Value::Nil)); // id
    for slot in 2..=5 {
        remapped.push(args.get(slot).cloned().unwrap_or(Value::Nil)); // x y wdt hgt
    }
    remapped.push(args.get(6).cloned().unwrap_or(Value::Nil)); // ocf
    remapped.push(args.get(7).cloned().unwrap_or(Value::Nil)); // action
    remapped.push(args.get(8).cloned().unwrap_or(Value::Nil)); // action target
    remapped.push(Value::Nil); // container (not script-settable here)
    remapped.push(args.get(9).cloned().unwrap_or(Value::Nil)); // find next
    find_object_cpp(&remapped, "FindObjectOwner", Some(owner))
}

/// C4Game::FindObject (C4Game.cpp:1334-1424): the legacy single-result
/// search scans the MASTER list for every query form — first master-order
/// match wins; sectors are never consulted (unlike the criteria form).
fn find_object_linear(world: &impl WorldAccessor, params: &FindObjectParams) -> Option<ObjectId> {
    let mut skip_until = params.find_next;
    for object_id in world.master_object_ids() {
        let Some(object) = world.get_object(object_id) else {
            continue;
        };
        if let Some(target) = skip_until {
            if object_id == target {
                skip_until = None;
            }
            continue;
        }
        if !params.matches_object(&object) {
            continue;
        }
        if params.matches_area(world, &object) {
            return Some(object_id);
        }
    }
    None
}

fn find_object_closest(world: &impl WorldAccessor, params: &FindObjectParams) -> Option<ObjectId> {
    let reference = params.reference_distance(world);
    let mut best: Option<(ObjectId, i64)> = None;
    for object_id in params.candidate_ids(world) {
        let Some(object) = world.get_object(object_id) else {
            continue;
        };
        if !params.matches_object(&object) {
            continue;
        }
        let distance = squared_distance(object.position(), params.x, params.y);
        if let Some(reference) = reference {
            if distance <= reference {
                continue;
            }
        }
        match best {
            None => best = Some((object_id, distance)),
            Some((_, best_distance)) if distance < best_distance => {
                best = Some((object_id, distance));
            }
            _ => {}
        }
    }
    best.map(|(id, _)| id)
}

/// C++ `FindObjects` is the array-criteria form (C4Script.cpp:7043); the
/// legacy fixed-parameter form predates it in this port and is kept for the
/// existing fixtures. Array first argument → C++ semantics.
fn find_objects_dispatch(args: &[Value]) -> Result<Value, RuntimeError> {
    if matches!(args.first(), Some(Value::Array(_))) {
        find_objects2(args)
    } else {
        find_objects(args)
    }
}

/// `System.c4g/FindObject.c`'s `Find_AtPoint` wrapper: its coordinates are
/// relative to the calling object, or to the world origin in global context.
fn find_at_point(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "Find_AtPoint", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "Find_AtPoint", "y")?;
    let origin = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(EffectHostContext::object_context)
            .map(ObjectScopeContext::effective_position)
            .unwrap_or(Vector2::ZERO)
    });
    Ok(Value::Array(vec![
        Value::Int(11),
        Value::Int(origin.x.wrapping_add(x)),
        Value::Int(origin.y.wrapping_add(y)),
    ]))
}

/// `System.c4g/FindObject.c`'s `Find_Category` wrapper: construct the
/// two-cell C4FO_Category criterion consumed by `FindObjects`.
fn find_category(args: &[Value]) -> Result<Value, RuntimeError> {
    let category = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "Find_Category",
        "category",
    )?;
    Ok(Value::Array(vec![Value::Int(22), Value::Int(category)]))
}

/// `System.c4g/FindObject.c`'s `Find_ID` wrapper: preserve the typed C4ID in
/// the two-cell criterion consumed by `FindObject2`/`FindObjects`.
fn find_id(args: &[Value]) -> Result<Value, RuntimeError> {
    let id = parse_native_c4id_argument(args.first(), "Find_ID")?
        .map(Value::C4Id)
        .unwrap_or(Value::Nil);
    Ok(Value::Array(vec![Value::Int(20), id]))
}

fn find_objects(args: &[Value]) -> Result<Value, RuntimeError> {
    let params = FindObjectParams::parse(args)?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Array(Vec::new())),
        };
        let ids = if params.is_closest_query() {
            collect_closest_matches(context, &params)
        } else {
            collect_linear_matches(context, &params)
        };
        let values = ids
            .into_iter()
            .map(object_reference_value)
            .collect::<Vec<_>>();
        Ok(Value::Array(values))
    })
}

fn object_count(args: &[Value]) -> Result<Value, RuntimeError> {
    // FnObjectCount (C4Script.cpp:2085-2111): the FindObject layout with
    // iOwner instead of pFindNext as the 10th parameter; an owner of 0
    // becomes ANY_OWNER ("incomplete useless implementation").
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Int(0)),
        };
        let mut params = FindObjectParams::parse_cpp_call(
            &args[..args.len().min(9)],
            "ObjectCount",
            context.caller_scope(),
        )?;
        let owner = parse_optional_i32(args.get(9), "ObjectCount", "owner")?.unwrap_or(0);
        params.owner = if owner == 0 { OWNER_ANY } else { owner };
        let matches_len = if params.is_closest_query() {
            collect_closest_matches(context, &params).len()
        } else {
            collect_linear_matches(context, &params).len()
        };
        Ok(Value::Int(truncate_to_i32(matches_len as u64)))
    })
}

/// FnObjectNumber (C4Script.cpp:3321-3325): return C4Object::Number, defaulting
/// a nil/omitted object to the current script object. Number is the immutable
/// C4Game::ObjectEnumerationIndex allocation, not an index into either object
/// list; therefore object status and list membership do not affect this read.
fn object_number(args: &[Value]) -> Result<Value, RuntimeError> {
    let explicit = match args.first() {
        Some(Value::Object(0)) | Some(Value::Nil) | None => None,
        Some(Value::Object(number)) => Some(*number),
        Some(other) => {
            return Err(RuntimeError::new(format!(
                "ObjectNumber: expected object or nil for object, got {}",
                other.type_name()
            )));
        }
    };
    let number = explicit.or_else(|| {
        HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(EffectHostContext::object_context)
                .map(|object| object.id().as_u64())
        })
    });

    Ok(number.map_or(Value::Nil, |number| Value::Int(truncate_to_i32(number))))
}

/// FnObject (C4Script.cpp:3327-3330): resolve an exact saved object Number.
/// SafeObjectPointer rejects only deleted status; inactive objects remain
/// addressable (C4ObjectList.cpp:544-557, C4GameObjects.cpp:270-276).
fn object_by_number(args: &[Value]) -> Result<Value, RuntimeError> {
    let number = value_to_i32(args.first().unwrap_or(&Value::Nil), "Object", "number")?;
    let Some(id) = (number > 0).then(|| ObjectId::new(number as u64)) else {
        return Ok(Value::Nil);
    };

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let status = context
            .get_world_object(id)
            .map(|object| object.status())
            .or_else(|| {
                context.object_scope(id).map(|scope| {
                    if scope.destroy {
                        ObjectStatus::Deleted
                    } else {
                        scope.status()
                    }
                })
            });
        Ok(
            if status.is_some_and(|status| status != ObjectStatus::Deleted) {
                object_reference_value(id)
            } else {
                Value::Nil
            },
        )
    })
}

fn collect_linear_matches(world: &impl WorldAccessor, params: &FindObjectParams) -> Vec<ObjectId> {
    let mut matches = Vec::new();
    let mut skip_until = params.find_next;
    for object_id in params.candidate_ids(world) {
        let Some(object) = world.get_object(object_id) else {
            continue;
        };
        if let Some(target) = skip_until {
            if object_id == target {
                skip_until = None;
            }
            continue;
        }
        if params.matches_object(&object) && params.matches_area(world, &object) {
            matches.push(object_id);
        }
    }
    matches
}

fn collect_closest_matches(world: &impl WorldAccessor, params: &FindObjectParams) -> Vec<ObjectId> {
    let reference = params.reference_distance(world);
    let mut matches = Vec::new();
    for (order_index, object_id) in params.candidate_ids(world).into_iter().enumerate() {
        let Some(object) = world.get_object(object_id) else {
            continue;
        };
        if !params.matches_object(&object) {
            continue;
        }
        let distance = squared_distance(object.position(), params.x, params.y);
        if let Some(reference) = reference {
            if distance <= reference {
                continue;
            }
        }
        matches.push((distance, order_index, object_id));
    }
    matches.sort_by(|a, b| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1)));
    matches.into_iter().map(|(_, _, id)| id).collect()
}

fn set_dir(args: &[Value]) -> Result<Value, RuntimeError> {
    if std::env::var("LC_DIRDBG").is_ok() && !matches!(args.first(), Some(Value::Int(_))) {
        eprintln!("DIRDBG SetDir args={args:?}");
    }
    // Unfilled ndir is nil -> 0 = DIR_Left; native int parameters also
    // accept C4Value bools through CheckConvertFunctionParameters
    // (C4AulExec.cpp:1364-1396; C4Value.cpp:514-518).
    let raw_direction = value_to_i32(args.first().unwrap_or(&Value::Nil), "SetDir", "direction")?;

    let direction = Direction::from_raw(raw_direction);

    let mut index = 1;
    let target_id =
        consume_optional_object_reference_argument(args, &mut index, "SetDir", "target")?;

    if index < args.len() {
        return Err(RuntimeError::new(
            "SetDir: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetDir requires an active engine context"))?;
        // FnSetDir works on ANY object (`if (!pObj) pObj = cthr->Obj`) —
        // GoldRush's init calls SetDir(1, pHorse) from the scenario
        // scope. Foreign writes stage into the target's nested scope.
        let active = context.object_context().map(|object| object.id());
        if let Some(target) = target_id {
            if Some(target) != active {
                if !context.nested_objects.contains_key(&target) {
                    let Some(world_object) = context.get_world_object(target) else {
                        return Ok(Value::Bool(false));
                    };
                    let Some((scope, local_vars)) = context.nested_scope_for(&world_object) else {
                        return Ok(Value::Bool(false));
                    };
                    context
                        .nested_objects
                        .insert(target, NestedScopeState { scope, local_vars });
                }
                if !context.nested_order.contains(&target) {
                    context.nested_order.push(target);
                }
                let state = context
                    .nested_objects
                    .get_mut(&target)
                    .expect("scope just ensured");
                let scope = &mut state.scope;
                // The same C4Object::SetDir gates as the self path; the
                // TurnAction fires through the staged action update.
                let action_name = scope.effective_action_name().to_string();
                let action_index = scope.effective_action_index();
                if scope
                    .action_library
                    .is_idle_entry(&action_name, action_index)
                {
                    return Ok(Value::Bool(true));
                }
                let directions = scope
                    .action_library
                    .directions_for_entry(&action_name, action_index)
                    as i32;
                if direction.to_script_value() < 0 || direction.to_script_value() >= directions {
                    return Ok(Value::Bool(true));
                }
                let turn_action = (scope.direction() != direction)
                    .then(|| {
                        scope
                        .action_library
                        .turn_action_for_entry(&action_name, action_index)
                        .map(str::to_string)
                    })
                    .flatten();
                drop(borrow);
                if let Some(turn_action) = turn_action {
                    let _ = native_set_action_by_name(target, &turn_action)?;
                }
                return HOST_CONTEXT.with(|cell| {
                    let mut borrow = cell.borrow_mut();
                    let context = borrow.as_mut().ok_or_else(|| {
                        RuntimeError::new("SetDir requires an active engine context")
                    })?;
                    if let Some(scope) = context.object_scope_mut(target) {
                        scope.set_direction(direction);
                    }
                    Ok(Value::Bool(true))
                });
            }
        }
        let object = match context.object_context_mut() {
            Some(object) => object,
            None => return Ok(Value::Bool(false)),
        };

        // C4Object::SetDir (C4Object.cpp:4225-4245): a no-op on idle
        // objects and out-of-range directions (Directions defaults 1 —
        // single-direction actions reject SetDir(1)); a CHANGE fires the
        // action's TurnAction through SetActionByName first.
        let action_name = object.effective_action_name().to_string();
        let action_index = object.effective_action_index();
        if object
            .action_library
            .is_idle_entry(&action_name, action_index)
        {
            return Ok(Value::Bool(true));
        }
        let directions = object
            .action_library
            .directions_for_entry(&action_name, action_index)
            as i32;
        if direction.to_script_value() < 0 || direction.to_script_value() >= directions {
            return Ok(Value::Bool(true));
        }
        let turn_action = (object.direction() != direction)
            .then(|| {
                object
                    .action_library
                    .turn_action_for_entry(&action_name, action_index)
                    .map(str::to_string)
            })
            .flatten();
        drop(borrow);
        if let Some(turn_action) = turn_action {
            let _ = set_action(&[Value::String(turn_action.into())])?;
        }
        HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let context = borrow
                .as_mut()
                .ok_or_else(|| RuntimeError::new("SetDir requires an active engine context"))?;
            if let Some(object) = context.object_context_mut() {
                object.set_direction(direction);
            }
            Ok(Value::Bool(true))
        })
    })
}

fn get_dir(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut index = 0;
    let target_id =
        consume_optional_object_reference_argument(args, &mut index, "GetDir", "target")?;

    if index < args.len() {
        return Err(RuntimeError::new(
            "GetDir: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };
        if let Some(target) = target_id {
            if let Some(object) = context.object_context() {
                if target == object.id() {
                    return Ok(Value::Int(object.direction().to_script_value()));
                }
            }
            // FnGetDir reads ANY pObj's Action.Dir (C4Script.cpp:1118-1122;
            // `if (!pObj) pObj = cthr->Obj` is only the local-call default —
            // an explicit target needs NO object context: GoldRush's
            // WINC->ActualizePhase(pClonk) reads GetDir(pClonk) from a
            // DEFINITION call, Winchester.c4d/Script.c:118-121). The CLNK
            // Riding() PhaseCall does SetDir(GetDir(GetActionTarget()))
            // on the ridden vehicle — a Nil here flipped riders Left.
            return Ok(context
                .get_world_object(target)
                .map(|other| Value::Int(other.direction))
                .unwrap_or(Value::Nil));
        }

        match context.object_context() {
            Some(object) => Ok(Value::Int(object.direction().to_script_value())),
            None => Ok(Value::Nil),
        }
    })
}

fn set_r(args: &[Value]) -> Result<Value, RuntimeError> {
    // Unfilled nr is nil -> 0 (FnSetR, C4Script.cpp:737).
    let rotation = value_to_i32(args.first().unwrap_or(&Value::Nil), "SetR", "rotation")?;

    let mut index = 1;
    let mut target_id: Option<ObjectId> = None;
    if let Some(arg) = args.get(index) {
        target_id = parse_object_reference_argument(arg, "SetR", "object")?;
        index += 1;
    }

    if index < args.len() {
        return Err(RuntimeError::new(
            "SetR: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetR requires an active engine context"))?;
        let target = target_id.or_else(|| context.object_context().map(ObjectScopeContext::id));
        let Some(target) = target else {
            return Ok(Value::Bool(false));
        };
        if !context.ensure_object_scope(target) {
            return Ok(Value::Bool(false));
        }
        let metadata = context
            .object_effective_definition_id(target)
            .and_then(|definition_id| context.definition_metadata(&definition_id).cloned())
            .unwrap_or_default();
        let Some(object) = context.object_scope_mut(target) else {
            return Ok(Value::Bool(false));
        };

        object.set_rotation(rotation, &metadata);
        context.update_live_solid_mask(target, false);
        Ok(Value::Bool(true))
    })
}

fn script_rotation(rotation: i32) -> i32 {
    let rotation = rotation % 360;
    if rotation > 180 {
        rotation - 360
    } else if rotation < -180 {
        rotation + 360
    } else {
        rotation
    }
}

fn get_r(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new("GetR expects at most 1 argument: target"));
    }

    let target_id =
        parse_object_reference_argument(args.first().unwrap_or(&Value::Nil), "GetR", "target")?;

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        if let Some(target) = target_id {
            if let Some(object) = context.object_scope(target) {
                return Ok(Value::Int(script_rotation(object.rotation())));
            }
            if let Some(other) = context.get_world_object(target) {
                return Ok(Value::Int(script_rotation(other.rotation)));
            }
            return Ok(Value::Nil);
        }

        let object = match context.object_context() {
            Some(object) => object,
            None => return Ok(Value::Nil),
        };

        Ok(Value::Int(script_rotation(object.rotation())))
    })
}

fn set_com_dir(args: &[Value]) -> Result<Value, RuntimeError> {
    // Unfilled ncomdir is nil -> 0 = COMD_Stop (FnSetComDir,
    // C4Script.cpp:791, C4Object.h:56-57).
    let raw_direction = match args.first().unwrap_or(&Value::Nil) {
        Value::Int(value) => *value,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "SetComDir: expected int or nil for command direction, got {}",
                other.type_name()
            )));
        }
    };

    let command_direction = CommandDirection::from_raw(raw_direction);

    let mut index = 1;
    let target_id =
        consume_optional_object_reference_argument(args, &mut index, "SetComDir", "target")?;

    if index < args.len() {
        return Err(RuntimeError::new(
            "SetComDir: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetComDir requires an active engine context"))?;
        let target = target_id.or_else(|| context.object_context().map(ObjectScopeContext::id));
        let Some(target) = target else {
            return Ok(Value::Bool(false));
        };
        if !context.ensure_object_scope(target) {
            return Ok(Value::Bool(false));
        }
        let Some(object) = context.object_scope_mut(target) else {
            return Ok(Value::Bool(false));
        };

        object.set_command_direction(command_direction);
        Ok(Value::Bool(true))
    })
}

fn get_com_dir(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut index = 0;
    let target_id =
        consume_optional_object_reference_argument(args, &mut index, "GetComDir", "target")?;

    if index < args.len() {
        return Err(RuntimeError::new(
            "GetComDir: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };
        if let Some(target) = target_id {
            if let Some(object) = context.object_scope(target) {
                return Ok(Value::Int(object.command_direction().to_script_value()));
            }
            return Ok(context
                .get_world_object(target)
                .map(|object| {
                    Value::Int(
                        object
                            .full_state()
                            .map(|state| state.command_direction)
                            .unwrap_or_default()
                            .to_script_value(),
                    )
                })
                .unwrap_or(Value::Nil));
        }

        match context.object_context() {
            Some(object) => Ok(Value::Int(object.command_direction().to_script_value())),
            None => Ok(Value::Nil),
        }
    })
}

pub(crate) fn command_data_any_value(value: i32) -> Value {
    if value == 0 {
        return Value::Nil;
    }
    // C4Value(Data, C4V_Any) lazily runs GuessType. Packed four-byte IDs
    // win over the integer fallback; 1..9999 deliberately stay integers
    // despite LooksLikeID accepting their decimal-ID representation.
    let raw = value as u32;
    if raw >= 10_000
        && raw
            .to_le_bytes()
            .iter()
            .all(|byte| byte.is_ascii_uppercase() || byte.is_ascii_digit() || *byte == b'_')
    {
        Value::C4Id(clonk_script::c4_id_from_raw(raw as usize))
    } else {
        Value::Int(value)
    }
}

fn command_data_value(data: &CommandData) -> Value {
    match data {
        CommandData::Integer(value) => command_data_any_value(*value),
        CommandData::Text(value) => Value::String(value.clone().into()),
        CommandData::None => Value::Nil,
    }
}

fn command_view_tx_value(command: &CommandView) -> Value {
    command
        .tx_value
        .clone()
        .or_else(|| command.tx_definition.clone().map(Value::C4Id))
        .or_else(|| command.tx.map(Value::Int))
        .unwrap_or(Value::Nil)
}

fn command_view_data_value(command: &CommandView) -> Value {
    match command.legacy_data {
        Some(value) => command_data_any_value(value),
        None => command_data_value(&command.data),
    }
}

/// Host-preview twin of C4Command::Fail's ExecFail tail. ExecuteCommand runs
/// inside a script VM call, so CallFailed/BuildNeedsMaterial and the ComDir
/// stop must be visible before the next script instruction and before
/// ControlCommandFinished.
fn preview_command_failure_feedback(
    actor: ObjectId,
    feedback: CommandFailureFeedback,
) -> Result<(), RuntimeError> {
    let crew = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        context
            .object_scope(actor)
            .map(|scope| scope.ocf() & ocf::CREW_MEMBER != 0)
            .or_else(|| {
                context
                    .get_world_object(actor)
                    .map(|object| object.ocf & ocf::CREW_MEMBER != 0)
            })
            .unwrap_or(false)
    });
    if !crew {
        return Ok(());
    }

    let failure_reason = feedback.reason;
    let fail_message = (failure_reason == Some(CommandFailureReason::CannotBuild))
        .then(|| {
            HOST_CONTEXT.with(|cell| {
                let borrow = cell.borrow();
                let context = borrow.as_ref()?;
                let name = context
                    .object_custom_name(actor)
                    .filter(|name| !name.is_empty())
                    .or_else(|| match context.object_scope(actor) {
                        Some(scope) => scope.info_core().map(|info| info.name.clone()),
                        None => context
                            .world
                            .crew_infos
                            .get(&actor)
                            .map(|info| info.name.clone()),
                    })
                    .or_else(|| {
                        context
                            .object_effective_definition_id(actor)
                            .and_then(|definition| {
                                context
                                    .definition_metadata(&definition)
                                    .map(|metadata| metadata.name.clone())
                                    .or(Some(definition))
                            })
                    })?;
                Some(format!("{name} can't build."))
            })
        })
        .flatten();
    let command = feedback.command;
    match command.name.as_str() {
        "Call" => {
            if let (Some(target), CommandData::Text(text)) = (command.target, &command.data) {
                if !text.is_empty() {
                    let args = [
                        object_reference_value(actor),
                        command_view_tx_value(&command),
                        Value::Int(command.ty.unwrap_or(0)),
                        command
                            .target2
                            .map(object_reference_value)
                            .unwrap_or(Value::Nil),
                    ];
                    let handled =
                        call_object_own_fail_safe(target, &format!("{text}Failed"), &args)
                            .as_bool();
                    if handled {
                        return Ok(());
                    }
                }
            }
        }
        "Build" => {
            if let Some(target) = command.target {
                let (component, count) = HOST_CONTEXT.with(|cell| {
                    let borrow = cell.borrow();
                    let Some(context) = borrow.as_ref() else {
                        return (None, 0);
                    };
                    let scope = context.object_scope(target);
                    let state = context
                        .get_world_object(target)
                        .and_then(|object| object.full_state().cloned());
                    let components = scope
                        .and_then(|scope| scope.pending_update.components.as_ref())
                        .or_else(|| state.as_deref().map(|state| &state.components));
                    let order = scope
                        .and_then(|scope| scope.pending_update.component_order.as_ref())
                        .or_else(|| state.as_deref().map(|state| &state.component_order));
                    let Some(id) = order.and_then(|order| order.first()).cloned() else {
                        return (None, 0);
                    };
                    let count = components
                        .and_then(|components| components.get(&id))
                        .copied()
                        .unwrap_or(0);
                    (Some(id), count)
                });
                // A truthy result suppresses only the generated material
                // message; the common Stop still runs.
                let handled = call_object_own_fail_safe(
                    actor,
                    "BuildNeedsMaterial",
                    &[
                        component.map(Value::C4Id).unwrap_or(Value::Nil),
                        Value::Int(count),
                    ],
                )
                .as_bool();
                if !handled && failure_reason.is_none() {
                    // Even when presentation is deferred, constructing the
                    // message runs target GetCustomComponents synchronously.
                    let _ = get_needed_mat_str(&[object_reference_value(target)])?;
                }
            }
        }
        _ => {}
    }

    if !object_has_status(actor) {
        return Ok(());
    }
    let silent_commands = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        context
            .object_effective_definition_id(actor)
            .and_then(|id| context.definition_metadata(&id))
            .is_some_and(|metadata| metadata.silent_commands)
    });
    if silent_commands {
        return Ok(());
    }
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        if context.ensure_object_scope(actor) {
            if let Some(scope) = context.object_scope_mut(actor) {
                scope.set_command_direction(CommandDirection::Stop);
            }
        }
        if let Some(text) = fail_message {
            context.register_message(MessageCommand::Add(MessageSpec {
                kind: MessageKind::Target,
                text,
                target: Some(actor),
                player: None,
                offset: Vector2::ZERO,
                color: 0xffff_ffff,
                flags: FLAG_MULTIPLE,
                width: None,
                decoration: None,
                frame_decoration: None,
                portrait: None,
            }));
        }
    });
    Ok(())
}

/// Host-preview form of ObjectActionJump used by C4Command::Grab's
/// scale/hangle let-go. ExecuteCommand runs inside the VM, so both the
/// OnActionJump hook and Jump action callbacks must complete before the
/// caller's next script instruction (C4ObjectCom.cpp:48-61,310-314).
fn preview_object_action_jump(target: ObjectId, velocity: FixedVec2) -> Result<bool, RuntimeError> {
    let handled = call_object_own_fail_safe(
        target,
        "OnActionJump",
        &[
            Value::Int(fixtoi_prec(velocity.x, 100)),
            Value::Int(fixtoi_prec(velocity.y, 100)),
            Value::Bool(true),
        ],
    );
    if value_raw_truthy(&handled) {
        return Ok(true);
    }
    if !native_set_action_by_name(target, "Jump")? {
        return Ok(false);
    }
    HOST_CONTEXT.with(|cell| {
        if let Some(object) = cell
            .borrow_mut()
            .as_mut()
            .and_then(|context| context.object_scope_mut(target))
        {
            object.set_fixed_velocity(velocity);
            object.set_mobile(true);
            object.set_t_attach(object.t_attach() & !CNAT_BOTTOM);
        }
    });
    Ok(true)
}

/// Synchronous host twin of ObjectComUnGrab. ObjectComDrop invokes this
/// after its Exit callbacks and NoCollectDelay update, before ExecuteCommand
/// may run ControlCommandFinished (C4ObjectCom.cpp:261-278,640-676).
fn preview_object_com_ungrab(
    actor: ObjectId,
    restore_fight_ready: bool,
) -> Result<bool, RuntimeError> {
    let target = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut()?;
        if !context.ensure_object_scope(actor) {
            return None;
        }
        let scope = context.object_scope_mut(actor)?;
        if scope.effective_action_procedure() != ActionProcedure::Push {
            return None;
        }
        let target = scope.effective_action_target(0);
        scope.set_command_direction(CommandDirection::Stop);
        Some(target)
    });
    let Some(target) = target else {
        return Ok(false);
    };

    // SetActionByName("Walk") performs a full SetOCF before its action
    // callbacks. Preserve the pre-Drop FightReady capability underneath a
    // callback-installed ObjectDisabled Push action so changing to Walk can
    // expose it again; NoCollectDelay still keeps Collection disabled.
    let cached_ocf_before = HOST_CONTEXT.with(|cell| {
        let mut cached_before = None;
        if let Some(scope) = cell
            .borrow_mut()
            .as_mut()
            .and_then(|context| context.object_scope_mut(actor))
        {
            cached_before = scope.cached_ocf;
            if restore_fight_ready && scope.ocf() & ocf::ALIVE != 0 {
                let cached = scope.cached_ocf.unwrap_or_else(|| scope.ocf());
                scope.cached_ocf = Some(cached | ocf::FIGHT_READY);
            }
        }
        cached_before
    });
    if !native_set_action_by_name(actor, "Walk")? {
        HOST_CONTEXT.with(|cell| {
            if let Some(scope) = cell
                .borrow_mut()
                .as_mut()
                .and_then(|context| context.object_scope_mut(actor))
            {
                scope.cached_ocf = cached_ocf_before;
            }
        });
        return Ok(false);
    }
    HOST_CONTEXT.with(|cell| {
        if let Some(scope) = cell
            .borrow_mut()
            .as_mut()
            .and_then(|context| context.object_scope_mut(actor))
        {
            scope.set_fixed_velocity(FixedVec2::ZERO);
        }
    });
    if !close_object_menu(actor, false) {
        return Ok(false);
    }
    let target_value = target.map(object_reference_value).unwrap_or(Value::Nil);
    let _ = call_object_own_fail_safe(actor, "Grab", &[target_value, Value::Bool(false)]);
    if object_has_status(actor) {
        if let Some(target) = target.filter(|target| object_has_status(*target)) {
            let _ = call_object_own_fail_safe(
                target,
                "Grabbed",
                &[object_reference_value(actor), Value::Bool(false)],
            );
        }
    }
    Ok(true)
}

/// Synchronous ObjectActionThrow twin for script ExecuteCommand. Force and
/// facing are frozen before SetAction callbacks; position/shape and the Exit
/// callbacks are observed afterward (C4ObjectCom.cpp:120-137).
fn preview_object_action_throw(actor: ObjectId, object: ObjectId) -> Result<bool, RuntimeError> {
    let physical = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut()?;
        if !context.ensure_object_scope(actor) || !context.ensure_object_scope(object) {
            return None;
        }
        let actor_state = context.get_world_object(actor)?;
        if !actor_state.is_present() {
            return None;
        }
        context.prepare_object_physical(actor, false)
    });
    let Some(physical) = physical else {
        return Ok(false);
    };
    let throw_force = crate::math::val_by_physical(400, physical.resolve().throw);
    let prepared = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let actor_scope = context.object_scope(actor)?;
        let direction = if actor_scope.current_direction == Direction::Left {
            -1
        } else {
            1
        };
        Some(direction)
    });
    let Some(direction) = prepared else {
        return Ok(false);
    };
    if !native_set_action_by_name(actor, "Throw")? {
        return Ok(false);
    }

    // ObjectActionThrow consumes the synced rotation only after SetAction
    // succeeds, even if callbacks removed the carried object before Exit.
    let rotation = draw_context_random(360)?;
    let exit = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let actor_position = context.object_scope(actor)?.effective_position();
        let shape_top = live_object_bounds_shape(context, actor)
            .map(|shape| shape.y)
            .unwrap_or(0);
        Some(Vector2::new(
            actor_position.x,
            actor_position.y.wrapping_add(shape_top).wrapping_sub(1),
        ))
    });
    if let Some(position) = exit {
        let _ = exit_object_at_position_with_full_motion_and_calls(
            object,
            position,
            rotation,
            FixedVec2::new(throw_force * direction, -throw_force),
            throw_force * direction,
            true,
        )?;
    }
    Ok(true)
}

/// Synchronous host preview of ObjectComDrop for script ExecuteCommand.
/// Item/actor state, callbacks, delay and cached OCF are staged here in C++
/// order before the outer script call folds back into the engine.
fn preview_object_com_drop(actor: ObjectId, object: ObjectId) -> Result<bool, RuntimeError> {
    let physical = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut()?;
        if !context.ensure_object_scope(actor) || !context.ensure_object_scope(object) {
            return None;
        }
        context.prepare_object_physical(actor, false)
    });
    let Some(physical) = physical else {
        return Ok(false);
    };
    let throw_force = crate::math::val_by_physical(400, physical.resolve().throw);
    let prepared = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let actor_scope = context.object_scope(actor)?;
        let procedure = actor_scope.effective_action_procedure();
        let command_direction = actor_scope.command_direction();
        let actor_xdir = actor_scope.fixed_velocity().x;
        let actor_position = actor_scope.effective_position();
        let actor_shape = live_object_shape(context, actor).unwrap_or_default();
        let object_shape = live_object_shape(context, object).unwrap_or_default();
        let restore_fight_ready = actor_scope.ocf() & ocf::FIGHT_READY != 0;
        Some((
            throw_force,
            procedure,
            command_direction,
            actor_xdir,
            actor_position,
            actor_shape,
            object_shape,
            restore_fight_ready,
        ))
    });
    let Some((
        throw_force,
        procedure,
        command_direction,
        actor_xdir,
        actor_position,
        actor_shape,
        object_shape,
        restore_fight_ready,
    )) = prepared
    else {
        return Ok(false);
    };

    let com_dir_like = |sample: CommandDirection| {
        let com = command_direction.to_script_value();
        let sample = sample.to_script_value();
        com == sample || com % 8 + 1 == sample || com == sample % 8 + 1
    };
    let hangling_or_swimming = matches!(procedure, ActionProcedure::Hang | ActionProcedure::Swim);
    let mut throw_direction = 0;
    let mut right = 0;
    let mut outpos_reduction = 1;
    if procedure != ActionProcedure::Scale {
        if com_dir_like(CommandDirection::Left) {
            throw_direction = -1;
            if actor_xdir < fixed10(15) && !hangling_or_swimming {
                outpos_reduction -= 1;
            }
        }
        if com_dir_like(CommandDirection::Right) {
            throw_direction = 1;
            right = 1;
            if actor_xdir > -fixed10(15) && !hangling_or_swimming {
                outpos_reduction -= 1;
            }
        }
    }
    let edge = actor_shape
        .x
        .wrapping_add(actor_shape.width.wrapping_mul(right));
    let exit_position = Vector2::new(
        actor_position.x.wrapping_add(
            edge.wrapping_mul(i32::from(throw_direction != 0))
                .wrapping_mul(outpos_reduction),
        ),
        actor_position
            .y
            .wrapping_add(actor_shape.y)
            .wrapping_add(actor_shape.height)
            .wrapping_sub(object_shape.y.wrapping_add(object_shape.height)),
    );
    let velocity = FixedVec2::new(throw_force * throw_direction, C4Fixed::ZERO);
    let _ = exit_object_at_position_with_motion_and_calls(
        object,
        exit_position,
        velocity,
        C4Fixed::ZERO,
        true,
    )?;

    // The first SetOCF happened in Exit before Ejection. This explicit
    // ObjectComDrop update happens after Departure and before UnGrab.
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        if !context.ensure_object_scope(actor) {
            return;
        }
        if let Some(scope) = context.object_scope_mut(actor) {
            scope.set_no_collect_delay(2);
        }
        let _ = refresh_live_object_ocf(context, actor);
        if let Some(scope) = context.object_scope_mut(actor) {
            scope.cached_ocf = Some(scope.ocf() & !ocf::COLLECTION);
            scope.record_no_collect_delay_assignment();
            scope.persist_final_ocf = true;
        }
    });
    let _ = preview_object_com_ungrab(actor, restore_fight_ready)?;
    Ok(true)
}

enum PreviewObjectComPutGate {
    Reject,
    Drop,
    Put,
}

/// Synchronous ObjectComPut twin for script ExecuteCommand. The Enter
/// callbacks and Put/Collection tail must be visible before the next script
/// instruction, and its result must not resolve an unrelated outer Put.
fn preview_object_com_put(
    actor: ObjectId,
    target: ObjectId,
    object: ObjectId,
) -> Result<bool, RuntimeError> {
    let gate = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return PreviewObjectComPutGate::Reject;
        };
        let Some(actor_state) = context.get_world_object(actor) else {
            return PreviewObjectComPutGate::Reject;
        };
        let Some(target_state) = context.get_world_object(target) else {
            return PreviewObjectComPutGate::Reject;
        };
        let Some(_object_state) = context.get_world_object(object) else {
            return PreviewObjectComPutGate::Reject;
        };
        let target_metadata = context
            .object_effective_definition_id(target)
            .and_then(|id| context.definition_metadata(&id));
        let actor_container = actor_state.container();
        let grab_put = target_metadata
            .is_some_and(|metadata| metadata.grab_put_get & crate::GRAB_PUT_GET_PUT != 0);
        if actor_container != Some(target) && !grab_put {
            let down_double = context
                .player_state(actor_state.owner)
                .is_some_and(|player| player.control.last_com_down_double != 0);
            return if down_double {
                PreviewObjectComPutGate::Drop
            } else {
                PreviewObjectComPutGate::Reject
            };
        }
        let target_ocf = context
            .object_scope(target)
            .map(ObjectScopeContext::ocf)
            .unwrap_or_else(|| target_state.ocf());
        if target_ocf & ocf::FULL_CON == 0 {
            return PreviewObjectComPutGate::Reject;
        }
        let collection_limit = target_metadata.map_or(0, |metadata| metadata.collection_limit);
        let contents_count = target_state
            .contents()
            .iter()
            .filter(|object_id| {
                context
                    .get_world_object(**object_id)
                    .is_some_and(|object| object.is_present())
            })
            .count();
        if crate::collection_limit_reached(collection_limit, contents_count) {
            return PreviewObjectComPutGate::Reject;
        }
        PreviewObjectComPutGate::Put
    });

    match gate {
        PreviewObjectComPutGate::Reject => Ok(false),
        PreviewObjectComPutGate::Drop => preview_object_com_drop(actor, object),
        PreviewObjectComPutGate::Put => {
            if !enter_object_live_with_reject_collect(object, target)? {
                return Ok(false);
            }
            let _ = call_object_own_fail_safe(actor, "Put", &[]);
            let _ = call_object_own_fail_safe(
                target,
                "Collection",
                &[object_reference_value(object), Value::Bool(true)],
            );
            Ok(true)
        }
    }
}

struct PreviewInternalObjectMenuSource;

impl crate::direct_com::InternalObjectMenuSource for PreviewInternalObjectMenuSource {
    type Error = RuntimeError;

    fn current_menu(&self, object: ObjectId) -> Option<crate::ObjectMenuState> {
        HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.object_menu(object))
        })
    }

    fn object(&self, object: ObjectId) -> Option<crate::direct_com::InternalObjectMenuObject> {
        HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let context = borrow.as_ref()?;
            let object_state = context.get_world_object(object)?;
            let definition_id = object_state.definition_id().to_string();
            let name = context
                .object_custom_name(object)
                .or_else(|| {
                    context
                        .object_scope(object)
                        .and_then(ObjectScopeContext::info_core)
                        .map(|info| info.name.clone())
                })
                .or_else(|| {
                    context
                        .world
                        .crew_infos
                        .get(&object)
                        .map(|info| info.name.clone())
                })
                .or_else(|| {
                    context
                        .definition_metadata(&definition_id)
                        .map(|definition| definition.name.clone())
                })
                .unwrap_or_else(|| definition_id.clone());
            let contents_link_generation = context
                .object_scope(object)
                .map(|scope| scope.current_contents_link_generation)
                .or_else(|| {
                    object_state
                        .full_state()
                        .map(|state| state.contents_link_generation)
                })
                .unwrap_or(0);
            Some(crate::direct_com::InternalObjectMenuObject {
                id: object,
                contents_link_generation,
                definition_id,
                name,
                category: object_state.category(),
                ocf: object_state.ocf(),
                contents: object_state.contents().to_vec(),
                active: object_state.status() != ObjectStatus::Deleted,
            })
        })
    }

    fn definition(
        &self,
        definition: &str,
    ) -> Option<crate::direct_com::InternalObjectMenuDefinition> {
        HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let context = borrow.as_ref()?;
            let metadata = context.definition_metadata(definition)?;
            Some(crate::direct_com::InternalObjectMenuDefinition {
                name: metadata.name.clone(),
                description: context
                    .world
                    .definition_description(definition)
                    .unwrap_or_default()
                    .to_string(),
                no_get: metadata.fire.no_get,
                collection_limit: metadata.collection_limit,
            })
        })
    }

    fn can_concat_picture_with(&self, object: ObjectId, other: ObjectId) -> bool {
        HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .is_some_and(|context| context.object_can_concat_picture_with(object, other))
        })
    }

    fn activate_value(
        &mut self,
        command_object: ObjectId,
        object: ObjectId,
        container: ObjectId,
        menu_before_value: &crate::ObjectMenuState,
    ) -> Result<i32, Self::Error> {
        HOST_CONTEXT.with(|cell| {
            if let Some(context) = cell.borrow_mut().as_mut() {
                context.set_object_menu(command_object, Some(menu_before_value.clone()));
            }
        });
        let value = get_value(&[
            object_reference_value(object),
            Value::Int(0),
            object_reference_value(container),
            Value::Int(OWNER_NONE),
        ]);
        match value {
            Ok(value) => Ok(value.as_c4_int().unwrap_or(0)),
            Err(error) => {
                tracing::error!(%error, "script error in Activate-menu GetValue; continuing");
                Ok(0)
            }
        }
    }

    fn reject_collection(
        &mut self,
        command_object: ObjectId,
        object: ObjectId,
        menu_before_call: &crate::ObjectMenuState,
    ) -> Result<bool, Self::Error> {
        HOST_CONTEXT.with(|cell| {
            if let Some(context) = cell.borrow_mut().as_mut() {
                context.set_object_menu(command_object, Some(menu_before_call.clone()));
            }
        });
        let definition_id = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.get_world_object(object))
                .map(|object| object.definition_id().to_string())
        });
        let Some(definition_id) = definition_id else {
            return Ok(false);
        };
        Ok(call_object_own_fail_safe(
            command_object,
            "RejectCollect",
            &[Value::C4Id(definition_id), object_reference_value(object)],
        )
        .as_bool())
    }
}

/// Run the callbackful half of an internal Activate/Get menu in the live VM
/// scope, including SetRefillObject's immediate full refill. No HOST_CONTEXT
/// borrow is held while the Activate builder calls GetValue/CalcValue.
fn preview_prepare_put_take_menu(request: MenuRequest) -> bool {
    let prepared = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let target = match &request.kind {
            MenuRequestKind::Activate => context
                .get_world_object(request.crew_id)
                .and_then(|object| object.container()),
            MenuRequestKind::Get { container } => Some(*container),
            _ => None,
        }?;
        let reused_menu_identity = context
            .object_menu(request.crew_id)
            .map(|menu| menu.internal_refill_token)
            .filter(|identity| *identity != 0);
        Some((
            target,
            if matches!(&request.kind, MenuRequestKind::Activate) {
                6
            } else {
                13
            },
            reused_menu_identity,
        ))
    });
    let Some((target, identification, reused_menu_identity)) = prepared else {
        return false;
    };
    let _ = close_object_menu(request.crew_id, true);
    if call_object_own_fail_safe(target, "RejectContents", &[]).as_bool() {
        return false;
    }
    let menu = match identification {
        6 => crate::direct_com::build_activate_menu_state(
            &mut PreviewInternalObjectMenuSource,
            request.crew_id,
            target,
            false,
            reused_menu_identity,
        ),
        13 => crate::direct_com::build_container_contents_menu_state(
            &mut PreviewInternalObjectMenuSource,
            request.crew_id,
            target,
            13,
            false,
            reused_menu_identity,
        ),
        _ => unreachable!("PutTake only opens Activate/Get menus"),
    };
    let Ok(Some(menu)) = menu else {
        return false;
    };
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        context.set_object_menu(request.crew_id, Some(menu))
    })
}

enum PreviewObjectComPutTakeOutcome {
    Finished,
    NeedsGet(ObjectId),
}

/// Synchronous script-host half of ObjectComPutTake. Item transfers run
/// entirely in the live VM scope. Internal menu construction continues
/// through the established menu-request fold, while command completion is
/// still resolved before ExecuteCommand returns.
fn preview_object_com_put_take(
    actor: ObjectId,
    target: ObjectId,
    requested_item: Option<ObjectId>,
) -> Result<PreviewObjectComPutTakeOutcome, RuntimeError> {
    let prepared = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let actor_state = context.get_world_object(actor)?;
        let _target_state = context.get_world_object(target)?;
        let is_resolved = |item| context.get_world_object(item).is_some();
        let (item, needs_get) = match requested_item {
            Some(item) if actor_state.contents().contains(&item) && is_resolved(item) => {
                (Some(item), None)
            }
            Some(item) if is_resolved(item) => {
                (None, Some(item))
            }
            Some(_) | None => (
                actor_state
                    .contents()
                    .iter()
                    .copied()
                    .find(|item| {
                        context
                            .get_world_object(*item)
                            .is_some_and(|object| object.is_present())
                    }),
                None,
            ),
        };
        let grab_get = context
            .object_effective_definition_id(target)
            .and_then(|id| context.definition_metadata(&id))
            .is_some_and(|metadata| metadata.grab_put_get & crate::GRAB_PUT_GET_GET != 0);
        Some((
            item,
            actor_state.container(),
            actor_state.controller(),
            actor_state.owner,
            grab_get,
            needs_get,
        ))
    });
    let Some((item, container, controller, owner, grab_get, needs_get)) = prepared else {
        return Ok(PreviewObjectComPutTakeOutcome::Finished);
    };
    if let Some(item) = needs_get {
        return Ok(PreviewObjectComPutTakeOutcome::NeedsGet(item));
    };
    if let Some(item) = item {
        let _ = preview_object_com_put(actor, target, item)?;
        return Ok(PreviewObjectComPutTakeOutcome::Finished);
    }

    let request = if container == Some(target) {
        Some(MenuRequest {
            crew_id: actor,
            owner: controller,
            kind: MenuRequestKind::Activate,
        })
    } else if grab_get {
        Some(MenuRequest {
            crew_id: actor,
            owner,
            kind: MenuRequestKind::Get { container: target },
        })
    } else {
        None
    };
    if let Some(request) = request {
        let _ = preview_prepare_put_take_menu(request);
    }
    Ok(PreviewObjectComPutTakeOutcome::Finished)
}

fn preview_object_com_stop(actor: ObjectId) -> Result<(), RuntimeError> {
    let _ = native_set_action_by_name(actor, "Idle")?;
    HOST_CONTEXT.with(|cell| {
        if let Some(scope) = cell
            .borrow_mut()
            .as_mut()
            .and_then(|context| context.object_scope_mut(actor))
        {
            scope.set_command_direction(CommandDirection::Stop);
        }
    });
    if native_set_action_by_name(actor, "Walk")? {
        HOST_CONTEXT.with(|cell| {
            if let Some(scope) = cell
                .borrow_mut()
                .as_mut()
                .and_then(|context| context.object_scope_mut(actor))
            {
                scope.set_fixed_velocity(FixedVec2::ZERO);
            }
        });
    }
    Ok(())
}

/// Synchronous host twin of ObjectComDig for script ExecuteCommand. The
/// physical gate, callbackful SetAction, localized GameMsgObject failure and
/// Action.Data reset all complete before the caller's next script instruction.
fn preview_object_com_dig(actor: ObjectId) -> Result<bool, RuntimeError> {
    let physical = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut()?;
        if !context.ensure_object_scope(actor) {
            return None;
        }
        context.prepare_object_physical(actor, false)
    });
    let can_dig = physical
        .map(PhysicalResolution::resolve)
        .map(|physical| physical.can_dig != 0);
    let succeeded = can_dig == Some(true) && native_set_action_by_name(actor, "Dig")?;
    if succeeded {
        HOST_CONTEXT.with(|cell| {
            if let Some(scope) = cell
                .borrow_mut()
                .as_mut()
                .and_then(|context| context.object_scope_mut(actor))
            {
                scope.reset_action_data();
            }
        });
        return Ok(true);
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        let name = context.object_effective_name(actor).unwrap_or_default();
        let text = if context
            .get_world_object(actor)
            .is_some_and(|object| object.is_present())
        {
            context
                .world
                .object_no_dig_resource_string
                .replacen("%s", &name, 1)
        } else {
            // An empty non-Multiple target message performs the native
            // replacement clear without leaving a message behind.
            String::new()
        };
        context.register_message(MessageCommand::Add(MessageSpec {
            kind: MessageKind::Target,
            text,
            target: Some(actor),
            player: None,
            offset: Vector2::ZERO,
            color: 0xffff_ffff,
            flags: 0,
            width: None,
            decoration: None,
            frame_decoration: None,
            portrait: None,
        }));
    });
    Ok(false)
}

type PreparedCommandRuntimeData = (
    HashMap<ObjectId, CommandObjectSnapshot>,
    HashMap<i32, CommandPlayerSnapshot>,
    HashMap<DefinitionId, CommandDefinitionSnapshot>,
    TransferZoneTable,
);

#[derive(Default)]
struct CommandPreviewOutcome {
    finished: Option<CommandView>,
    buy_attempts: Vec<(ObjectId, ObjectId, DefinitionId, i32, i32, i32)>,
    sell_attempts: Vec<(ObjectId, ObjectId, DefinitionId, Option<ObjectId>, i32)>,
    grab_attempts: Vec<(ObjectId, ObjectId)>,
    put_attempts: Vec<(ObjectId, ObjectId, ObjectId, bool, u64)>,
    drop_attempts: Vec<(ObjectId, ObjectId, u64)>,
    ungrab_attempts: Vec<(ObjectId, u64)>,
    put_take_attempts: Vec<(ObjectId, ObjectId, Option<ObjectId>, CommandId, u64)>,
    throw_attempts: Vec<(ObjectId, ObjectId, bool, u64)>,
    throw_preludes: Vec<CommandEvent>,
    entrance_attempts: Vec<(ObjectId, ObjectId, Option<CallResultAction>, u64)>,
    control_transfers: Vec<(ObjectId, ObjectId, Value, i32, u64)>,
    exit_attempts: Vec<CommandEvent>,
    failure_feedback: Vec<(ObjectId, CommandFailureFeedback)>,
    move_to_stops: Vec<ObjectId>,
    build_stops: Vec<(ObjectId, u64)>,
    build_actions: Vec<(ObjectId, ObjectId, bool)>,
    dig_attempts: Vec<(ObjectId, bool, Option<CommandDirection>, u64)>,
    physical_reads: Vec<(ObjectId, u8, u64)>,
}

impl CommandPreviewOutcome {
    fn append(&mut self, mut other: Self) {
        if other.finished.is_some() {
            self.finished = other.finished.take();
        }
        self.buy_attempts.append(&mut other.buy_attempts);
        self.sell_attempts.append(&mut other.sell_attempts);
        self.grab_attempts.append(&mut other.grab_attempts);
        self.put_attempts.append(&mut other.put_attempts);
        self.drop_attempts.append(&mut other.drop_attempts);
        self.ungrab_attempts.append(&mut other.ungrab_attempts);
        self.put_take_attempts.append(&mut other.put_take_attempts);
        self.throw_attempts.append(&mut other.throw_attempts);
        self.throw_preludes.append(&mut other.throw_preludes);
        self.entrance_attempts.append(&mut other.entrance_attempts);
        self.control_transfers.append(&mut other.control_transfers);
        self.exit_attempts.append(&mut other.exit_attempts);
        self.failure_feedback.append(&mut other.failure_feedback);
        self.move_to_stops.append(&mut other.move_to_stops);
        self.build_stops.append(&mut other.build_stops);
        self.build_actions.append(&mut other.build_actions);
        self.dig_attempts.append(&mut other.dig_attempts);
        self.physical_reads.append(&mut other.physical_reads);
    }

    fn had_live_attempt(&self) -> bool {
        !self.buy_attempts.is_empty()
            || !self.sell_attempts.is_empty()
            || !self.grab_attempts.is_empty()
            || !self.put_attempts.is_empty()
            || !self.drop_attempts.is_empty()
            || !self.ungrab_attempts.is_empty()
            || !self.put_take_attempts.is_empty()
            || !self.throw_attempts.is_empty()
            || !self.throw_preludes.is_empty()
            || !self.entrance_attempts.is_empty()
            || !self.control_transfers.is_empty()
            || !self.exit_attempts.is_empty()
            || !self.failure_feedback.is_empty()
            || !self.move_to_stops.is_empty()
            || !self.build_stops.is_empty()
            || !self.build_actions.is_empty()
            || !self.dig_attempts.is_empty()
    }
}

/// Structural command snapshots never read target physicals. Resolve at most
/// the executing actor. A missing FairCrew projection is deliberately left
/// unresolved and marked on that actor snapshot; the exact command branch
/// which reaches native GetPhysical will suspend and request the live fill.
fn prepare_command_runtime_data(
    physical_actor: Option<ObjectId>,
) -> Option<PreparedCommandRuntimeData> {
    let resolution = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        Some(physical_actor.and_then(|id| {
            context
                .prepare_object_physical(id, false)
                .map(|plan| (id, plan))
        }))
    })?;
    let (physicals, deferred_actor) = match resolution {
        Some((id, plan)) if plan.needs_fair_crew_fill() => (HashMap::new(), Some(id)),
        Some((id, plan)) => (HashMap::from([(id, plan.resolve())]), None),
        None => (HashMap::new(), None),
    };
    HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .map(|context| context.command_runtime_data(&physicals, deferred_actor))
    })
}

/// Rebuild command snapshots after a physical hook using the exact value
/// returned by its final GetPhysical call. The actor is no longer deferred:
/// this continuation must retain that pointer value even if the hook changed
/// other live state while the read was in flight.
fn prepare_command_runtime_data_with_physical(
    actor: ObjectId,
    physical: PhysicalInfo,
) -> Option<PreparedCommandRuntimeData> {
    let physicals = HashMap::from([(actor, physical)]);
    HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .map(|context| context.command_runtime_data(&physicals, None))
    })
}

fn preview_command_event_instance_id(
    actor: ObjectId,
    kind: CommandEventInstanceKind,
    supplied: u64,
) -> u64 {
    HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_scope(actor))
            .map(|scope| {
                scope
                    .live_commands
                    .resolve_event_instance_id(kind, supplied)
            })
            .unwrap_or(supplied)
    })
}

/// Execute callbackful GetPhysical reads without holding HOST_CONTEXT, then
/// resume the retained native command against a fresh structural snapshot.
/// The command identity is bound before the first hook because that hook may
/// replace the visible stack which originally emitted the event.
fn preview_resume_command_after_physical(
    actor: ObjectId,
    reads: u8,
    supplied_instance_id: u64,
    rng: Option<&RefCell<LcgRng>>,
) -> Option<(Vec<CommandEvent>, Option<CommandView>)> {
    let command_instance_id = preview_command_event_instance_id(
        actor,
        CommandEventInstanceKind::Physical,
        supplied_instance_id,
    );

    let mut physical = None;
    for _ in 0..reads {
        let Some(resolved) = resolve_object_physical(actor, false) else {
            break;
        };
        physical = Some(resolved);
    }
    let physical = physical?;
    let command_data = prepare_command_runtime_data_with_physical(actor, physical)?;
    HOST_CONTEXT.with(|cell| {
        cell.borrow_mut().as_mut().and_then(|context| {
            context.execute_pending_command_physical_preview(
                actor,
                command_instance_id,
                physical,
                rng,
                &command_data,
            )
        })
    })
}

/// Script-level ExecuteCommand twin of CommandEvent::ObjectComStopMoveTo.
/// ObjectComStop callbacks and the retained command continuation must both
/// complete before ExecuteCommand returns to its caller.
fn preview_move_to_stop(actor: ObjectId) -> Result<Vec<CommandEvent>, RuntimeError> {
    preview_object_com_stop(actor)?;

    let Some((objects, players, definitions, transfers)) =
        prepare_command_runtime_data(Some(actor))
    else {
        return Ok(Vec::new());
    };
    let events = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Vec::new();
        };
        let Some(object_snapshot) = objects.get(&actor) else {
            return Vec::new();
        };
        let landscape = context.world.landscape_shared();
        let runtime = CommandRuntimeContext {
            rng: None,
            frame: context.world.frame,
            position: object_snapshot.position,
            landscape: landscape.as_deref(),
            object: object_snapshot,
            objects: &objects,
            players: &players,
            definitions: &definitions,
            structures_need_energy: context.world.structures_need_energy,
            base_buy_enabled: context.world.base_buy_enabled,
            base_sell_enabled: context.world.base_sell_enabled,
            transfer_zones: &transfers,
        };
        let Some(mut result) = context
            .object_scope_mut(actor)
            .and_then(|scope| scope.live_commands.execute_pending_move_to_stop(&runtime))
        else {
            return Vec::new();
        };
        if let Some(scope) = context.object_scope_mut(actor) {
            scope.command_stack_replaced = true;
        }
        if let Some(update) = result.update.take() {
            context.stage_object_command_update(actor, update);
        }
        if let Some(scope) = context.object_scope_mut(actor) {
            scope.command_count = scope.live_commands.len();
        }
        result.events
    });

    Ok(events)
}

