    #[test]
    fn draw_mat_chunks_failure_and_zero_count_paths_do_not_draw_rng() {
        for (material, texture) in [("Missing", "Rough"), ("Earth", "Missing")] {
            let args = [
                Value::Int(0),
                Value::Int(0),
                Value::Int(8),
                Value::Int(6),
                Value::Int(2),
                Value::Int(2),
                Value::String(material.to_string().into()),
                Value::String(texture.to_string().into()),
                Value::Bool(false),
            ];
            let initial_rng = LcgRng::new(61);
            let guard = enter_random_context(initial_rng.clone());
            let (result, outcome) =
                with_effect_context(None, &[], draw_mat_chunks_world(), 1, || {
                    draw_mat_chunks(&args)
                });
            let final_rng = guard.finish();

            assert_eq!(
                result.expect("unresolved DrawMatChunks is not an error"),
                Value::Int(0)
            );
            assert!(outcome.landscape.is_empty());
            assert_eq!(final_rng, initial_rng);
        }

        let zero_count_args = [
            Value::Int(0),
            Value::Int(0),
            Value::Int(8),
            Value::Int(6),
            Value::Int(0),
            Value::Int(2),
            Value::String("Earth".to_string().into()),
            Value::String("Rough".to_string().into()),
            Value::Bool(false),
        ];
        let initial_rng = LcgRng::new(67);
        let guard = enter_random_context(initial_rng.clone());
        let (result, outcome) = with_effect_context(None, &[], draw_mat_chunks_world(), 1, || {
            draw_mat_chunks(&zero_count_args)
        });
        let final_rng = guard.finish();

        assert_eq!(result.expect("zero-count call succeeds"), Value::Int(1));
        assert_eq!(final_rng, initial_rng);
        assert_eq!(outcome.landscape.len(), 1);
        match &outcome.landscape[0] {
            LandscapeOperation::DrawMatChunks {
                random_offsets,
                texmap,
                ..
            } => {
                assert!(random_offsets.is_empty());
                assert_eq!(texmap.material_names[1].as_deref(), Some("Earth"));
            }
            other => panic!("unexpected landscape operation: {other:?}"),
        }
    }

    #[test]
    fn draw_volcano_branch_matches_cpp_pixels_ift_and_rng_order() {
        // The C++ loop starts at (tx,ty), excludes fy, truncates interpolation
        // toward zero, and draws [cx-size/2,cx+size/2). With these endpoints
        // the row centers are exactly 8,6,5,4,3. The default Earth byte is 5
        // even though slot 1 also carries Earth, and each destination's IFT
        // bit must survive independently.
        let args = [
            Value::Int(0),
            Value::Int(2),
            Value::Int(7),
            Value::Int(8),
            Value::Int(2),
            Value::Int(5),
        ];
        let mut world = draw_volcano_branch_world();
        assert!(
            world
                .landscape_mut()
                .is_some_and(|landscape| { landscape.set_surface32_pixel(6, 2, 0x0011_2233) })
        );
        let initial_landscape = world.landscape_ref().expect("landscape exists").clone();
        let object_context = HostObjectContext::new(
            ObjectId::new(91),
            None,
            ObjectStatus::Normal,
            100,
            OWNER_NONE,
            Vector2::new(30, 40),
            Vector2::ZERO,
            &[],
            "Idle",
            0,
            0,
            ActionLibrary::default(),
            Direction::Right,
            CommandDirection::Stop,
            0,
            None,
            None,
            &[],
            crate::FULL_CON,
        );
        let seed = 73;
        let mut expected_rng = LcgRng::new(seed);
        let expected_after = expected_rng.random(1_000);
        let guard = enter_random_context(LcgRng::new(seed));
        let (result, outcome) = with_effect_context(Some(object_context), &[], world, 92, || {
            let drew = draw_volcano_branch(&args)?;
            let texture = get_texture(&[Value::Int(6), Value::Int(2)])?;
            // GBackSky is caller-relative, unlike both natives above.
            let ift_pixel = g_back_sky(&[Value::Int(6 - 30), Value::Int(2 - 40)])?;
            let plain_pixel = g_back_sky(&[Value::Int(7 - 30), Value::Int(2 - 40)])?;
            let after = random(&[Value::Int(1_000)])?;
            Ok::<_, RuntimeError>((drew, texture, ift_pixel, plain_pixel, after))
        });
        let final_rng = guard.finish();

        assert_eq!(
            result.expect("DrawVolcanoBranch and queries succeed"),
            (
                Value::Nil,
                Value::String("Smooth".to_string().into()),
                Value::Bool(false),
                Value::Bool(true),
                Value::Int(expected_after),
            )
        );
        assert_eq!(final_rng, expected_rng, "the native consumes no RNG");
        assert_eq!(outcome.landscape.len(), 1);
        match &outcome.landscape[0] {
            LandscapeOperation::DrawVolcanoBranch {
                from,
                to,
                size,
                material_byte,
            } => {
                assert_eq!(*from, Vector2::new(2, 7));
                assert_eq!(*to, Vector2::new(8, 2));
                assert_eq!(*size, 5);
                assert_eq!(*material_byte, 5);
            }
            other => panic!("unexpected landscape operation: {other:?}"),
        }

        // Effect batches replay state-bearing operations between callbacks.
        let mut replay_world = draw_volcano_branch_world();
        replay_world.preview_runtime_landscape_operation(&outcome.landscape[0]);
        let (replayed, _) = with_effect_context(None, &[], replay_world, 1, || {
            Ok::<_, RuntimeError>((
                get_texture(&[Value::Int(6), Value::Int(2)])?,
                g_back_sky(&[Value::Int(6), Value::Int(2)])?,
            ))
        });
        assert_eq!(
            replayed.expect("replayed callback reads landscape"),
            (Value::String("Smooth".to_string().into()), Value::Bool(false))
        );

        let mut engine = crate::Engine::new();
        engine.set_landscape(initial_landscape);
        engine.apply_landscape_operations(outcome.landscape);
        let landscape = engine.landscape().expect("folded landscape exists");
        let centers = [(2, 8), (3, 6), (4, 5), (5, 4), (6, 3)];
        for y in 0..10 {
            for x in 0..12 {
                let initial = if (x + y) % 2 == 0 { 0x80 } else { 0 };
                let drawn = centers
                    .iter()
                    .any(|&(row, center)| row == y && x >= center - 2 && x < center + 2);
                let expected = if drawn { 5 | (initial & 0x80) } else { initial };
                assert_eq!(
                    landscape.grid_byte_at(x, y),
                    Some(expected),
                    "C++ branch pixel ({x},{y})"
                );
            }
        }
        assert_eq!(
            landscape.surface32_pixel_at(6, 2),
            None,
            "raw SetPix queues a relight over the old Surface32 override"
        );
    }

    #[test]
    fn draw_volcano_branch_empty_ranges_and_invalid_material_are_safe_noops() {
        // C++ enters no inner iteration for these shapes. In particular,
        // ty==fy must not divide by zero, and odd size 1 paints zero pixels.
        for (from_y, to_y, size) in [(4, 4, 6), (3, 7, 6), (7, 2, 1), (7, 2, -3)] {
            let world = draw_volcano_branch_world();
            let initial = world.landscape_ref().expect("landscape exists").clone();
            let args = [
                Value::Int(0),
                Value::Int(2),
                Value::Int(from_y),
                Value::Int(8),
                Value::Int(to_y),
                Value::Int(size),
            ];
            let (result, outcome) =
                with_effect_context(None, &[], world, 1, || draw_volcano_branch(&args));
            assert_eq!(result.expect("empty branch succeeds"), Value::Nil);
            assert_eq!(outcome.landscape.len(), 1);
            let mut engine = crate::Engine::new();
            engine.set_landscape(initial.clone());
            engine.apply_landscape_operations(outcome.landscape);
            let actual = engine.landscape().expect("landscape exists");
            for y in 0..10 {
                for x in 0..12 {
                    assert_eq!(actual.grid_byte_at(x, y), initial.grid_byte_at(x, y));
                }
            }
        }

        let args = [
            Value::Int(99),
            Value::Int(2),
            Value::Int(7),
            Value::Int(8),
            Value::Int(2),
            Value::Int(5),
        ];
        let (result, outcome) =
            with_effect_context(None, &[], draw_volcano_branch_world(), 1, || {
                draw_volcano_branch(&args)
            });
        assert_eq!(result.expect("invalid material is contained"), Value::Nil);
        assert!(outcome.landscape.is_empty());
    }

    #[test]
    fn draw_material_quad_resolves_and_queues_global_vertices() {
        // FnDrawMaterialQuad passes its material string, four GLOBAL points,
        // and fSub straight to C4Landscape::DrawQuad (C4Script.cpp:5111-5115).
        // DrawQuad resolves GetIndexMatTex before entering PrepareChange
        // (C4Landscape.cpp:2448-2466), so the host can return true now and
        // defer the same resolved operation to the engine fold.
        let args = [
            Value::String("Water".to_string().into()),
            Value::Int(1),
            Value::Int(2),
            Value::Int(4),
            Value::Int(2),
            Value::Int(4),
            Value::Int(5),
            Value::Int(1),
            Value::Int(5),
            Value::Bool(true),
        ];
        let (result, outcome) =
            with_effect_context(None, &[], draw_material_quad_world(), 1, || {
                draw_material_quad(&args)
            });

        assert_eq!(
            result.expect("DrawMaterialQuad succeeds"),
            Value::Bool(true)
        );
        assert_eq!(outcome.landscape.len(), 1);
        match &outcome.landscape[0] {
            LandscapeOperation::DrawMaterialQuad {
                material_texture,
                vertices,
                ift,
            } => {
                assert_eq!(material_texture, "Water");
                assert_eq!(
                    *vertices,
                    [
                        Vector2::new(1, 2),
                        Vector2::new(4, 2),
                        Vector2::new(4, 5),
                        Vector2::new(1, 5),
                    ]
                );
                assert!(*ift);
            }
            other => panic!("unexpected landscape operation: {other:?}"),
        }
    }

    #[test]
    fn draw_material_quad_returns_false_for_unresolved_material() {
        // After an explicit pair fails, GetIndexMatTex checks the ORIGINAL
        // full string as a material name (C4Texture.cpp:346-369), so
        // `Water-Missing` does not fall back to Water's DefaultMatTex.
        // DrawQuad returns false before PrepareChange (C4Landscape.cpp:
        // 2450-2452), so no deferred write may be queued.
        let args = [
            Value::String("Water-Missing".to_string().into()),
            Value::Int(0),
            Value::Int(0),
            Value::Int(1),
            Value::Int(0),
            Value::Int(1),
            Value::Int(1),
            Value::Int(0),
            Value::Int(1),
            Value::Bool(false),
        ];
        let (result, outcome) =
            with_effect_context(None, &[], draw_material_quad_world(), 1, || {
                draw_material_quad(&args)
            });

        assert_eq!(
            result.expect("invalid material is not an error"),
            Value::Bool(false)
        );
        assert!(outcome.landscape.is_empty());
    }

    #[test]
    fn void_host_functions_return_nil_while_preserving_side_effects() {
        // `C4AulEngineFunc<void>::Exec` returns C4VNull after invoking the
        // native (C4Script.cpp:6136-6166). Exercise the registered script
        // boundary so both the exposed nil and its falsiness stay pinned.
        let (result, outcome) = with_object_host_context(|| {
            let mut script = ScriptEngine::new();
            register_host_functions(&mut script);
            script
                .load_script(
                    r#"
                    #strict 3
                    func Probe() {
                        var debug = DebugLog("void host probe");
                        var sound = SoundLevel("Wind", 40);
                        var go = ScriptGo(true);
                        var shake = ShakeFree(10, 20, 3);
                        var dig = DigFree(30, 40, 5, true);
                        var rect = DigFreeRect(50, 60, 7, 8, false);
                        if (debug) return 1;
                        if (sound) return 2;
                        if (go) return 3;
                        if (shake) return 4;
                        if (dig) return 5;
                        if (rect) return 6;
                        return [debug, sound, go, shake, dig, rect];
                    }
                    "#,
                )
                .map_err(|error| RuntimeError::new(error.to_string()))?;
            script
                .call("Probe", &[])
                .map_err(|error| RuntimeError::new(error.to_string()))
        });

        assert_eq!(
            result.expect("void host probes succeed"),
            Value::Array(vec![Value::Nil; 6])
        );
        assert_eq!(outcome.script_go, Some(true));
        assert_eq!(
            outcome.audio.events,
            vec![AudioCommand::SetSoundVolume {
                name: "Wind".into(),
                target: None,
                volume: 40,
            }]
        );
        assert!(matches!(
            outcome.landscape.as_slice(),
            [
                LandscapeOperation::ShakeCircle {
                    center: Vector2 { x: 10, y: 20 },
                    radius: 3,
                },
                LandscapeOperation::DigCirclePreviewed {
                    center: Vector2 { x: 30, y: 40 },
                    radius: 5,
                },
                LandscapeOperation::DigRectPreviewed {
                    origin: Vector2 { x: 50, y: 60 },
                    width: 7,
                    height: 8,
                },
            ]
        ));

        let (no_op_result, no_op_outcome) = with_object_host_context(|| {
            let mut script = ScriptEngine::new();
            register_host_functions(&mut script);
            script
                .load_script(
                    r#"
                    #strict 3
                    func Probe() {
                        var sound = SoundLevel();
                        var go = ScriptGo();
                        var shake = ShakeFree();
                        var dig = DigFree(0, 0, -1);
                        var rect = DigFreeRect(0, 0, 0, 1);
                        if (sound) return 1;
                        if (go) return 2;
                        if (shake) return 3;
                        if (dig) return 4;
                        if (rect) return 5;
                        return [sound, go, shake, dig, rect];
                    }
                    "#,
                )
                .map_err(|error| RuntimeError::new(error.to_string()))?;
            script
                .call("Probe", &[])
                .map_err(|error| RuntimeError::new(error.to_string()))
        });

        assert_eq!(
            no_op_result.expect("void host no-op probes succeed"),
            Value::Array(vec![Value::Nil; 5])
        );
        assert_eq!(no_op_outcome.script_go, Some(false));
        assert!(no_op_outcome.audio.events.is_empty());
        assert!(no_op_outcome.landscape.is_empty());
    }

    #[test]
    fn terrain_mutators_are_visible_to_same_callback_gback_queries() {
        let library = clonk_resources::MaterialLibrary::parse(
            "[Material Earth]\nName=Earth\nDensity=100\nDigFree=1\nBlastFree=1\n",
        )
        .expect("terrain-query material builds");
        let materials = Rc::new(MaterialSet::from_resource_library(&library));
        let earth = materials.id_of("Earth").expect("Earth exists");
        let map_world = || {
            let mut world = draw_map_world(8, 7, 3, true);
            world
                .landscape_mut()
                .expect("landscape exists")
                .resolve_grid_materials(|name| materials.id_of(name));
            world.with_materials(Some(Rc::clone(&materials)))
        };
        let terrain_world = || {
            let mut world = map_world();
            let landscape = world.landscape_mut().expect("landscape exists");
            for y in 0..7 {
                for x in 0..8 {
                    landscape.grid_write_byte(x, y, 1);
                }
            }
            landscape.refresh_all_raster_columns();
            world
        };

        let mut script = clonk_script::Engine::new();
        register_host_functions(&mut script);
        script
            .load_script(
                r#"#strict 2
func TerrainState(x, y) { return [GBackSolid(x, y), GetMaterial(x, y), GetTexture(x, y)]; }
func ProbeBlast() {
    var before = TerrainState(3, 3);
    var changed = BlastFree(3, 3, 1, 1);
    return [before, changed, TerrainState(3, 3)];
}
func ProbeShake() {
    var before = TerrainState(3, 3);
    var changed = ShakeFree(3, 3, 1);
    return [before, changed, TerrainState(3, 3)];
}
func ProbeDig() {
    var before = TerrainState(3, 3);
    var changed = DigFree(3, 3, 1);
    return [before, changed, TerrainState(3, 3)];
}
func ProbeDigRect() {
    var before = TerrainState(3, 3);
    var changed = DigFreeRect(3, 3, 1, 1);
    return [before, changed, TerrainState(3, 3)];
}
func ProbeDrawMap() {
    var before = TerrainState(0, 1);
    var changed = DrawMap(-2, 1, 7, 5, "map Runtime { seed = 9; Named; };");
    return [before, changed, TerrainState(0, 1)];
}
func ProbeDrawDefMap() {
    var before = TerrainState(0, 1);
    var changed = DrawDefMap(-2, 1, 7, 5, "Requested");
    return [before, changed, TerrainState(0, 1)];
}
"#,
            )
            .expect("terrain visibility probes compile");

        let earth_state = Value::Array(vec![
            Value::Bool(true),
            Value::Int(earth.index() as i32),
            Value::String("Rough".to_string().into()),
        ]);
        let sky_state = Value::Array(vec![
            Value::Bool(false),
            Value::Int(MATERIAL_NONE),
            Value::Nil,
        ]);
        for probe in ["ProbeBlast", "ProbeShake", "ProbeDig", "ProbeDigRect"] {
            let random = enter_random_context(LcgRng::new(101));
            let (result, outcome) = with_effect_context(None, &[], terrain_world(), 1, || {
                script.call(probe, &[])
            });
            let _ = random.finish();
            assert_eq!(
                result.unwrap_or_else(|error| panic!("{probe} failed: {error}")),
                Value::Array(vec![earth_state.clone(), Value::Nil, sky_state.clone()]),
                "{probe} must expose its cleared pixel before returning from the callback"
            );
            assert_eq!(outcome.landscape.len(), 1, "{probe} queues one fold");
            assert!(
                matches!(
                    (probe, &outcome.landscape[0]),
                    ("ProbeBlast", LandscapeOperation::BlastCirclePreviewed { .. })
                        | ("ProbeShake", LandscapeOperation::ShakeCircle { .. })
                        | ("ProbeDig", LandscapeOperation::DigCirclePreviewed { .. })
                        | ("ProbeDigRect", LandscapeOperation::DigRectPreviewed { .. })
                ),
                "{probe} queued {:?}",
                outcome.landscape[0]
            );
        }

        for (probe, seed) in [("ProbeDrawMap", 17), ("ProbeDrawDefMap", 37)] {
            let random = enter_random_context(LcgRng::new(seed));
            let (result, outcome) =
                with_effect_context(None, &[], map_world(), 1, || script.call(probe, &[]));
            let _ = random.finish();
            assert_eq!(
                result.unwrap_or_else(|error| panic!("{probe} failed: {error}")),
                Value::Array(vec![
                    sky_state.clone(),
                    Value::Int(1),
                    earth_state.clone(),
                ]),
                "{probe} must expose its painted pixel before returning from the callback"
            );
            assert_eq!(outcome.landscape.len(), 1, "{probe} queues one fold");
            assert!(
                matches!(
                    (probe, &outcome.landscape[0]),
                    ("ProbeDrawMap", LandscapeOperation::DrawMap { .. })
                        | ("ProbeDrawDefMap", LandscapeOperation::DrawDefMap { .. })
                ),
                "{probe} queued {:?}",
                outcome.landscape[0]
            );
        }
    }

